window.MEB_PROGRAM = {"kaynak":"https://tymm.meb.gov.tr","erisim":"2026-09-28","siniflar":{"s4":[{"no":1,"ad":"Günlük Hayat ve Din","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/4","odak":"Bu ünitede günlük hayattaki dinî ifadeler, temizlik, şükür ve sağlıklı beslenme konuları ele alınmaktadır. Öğrencilerin günlük hayatta kullanılan dinî ifadeleri ayırt etmeleri, İslam’ın temizliğe verdiği önemi müşahede etmeleri, şükrün ve şükretmenin önemini kavrayarak bu değerleri günlük hayatlarına yansıtmaları, temiz ve sağlıklı beslenmenin İslam dinindeki önemi hakkında bilgi toplamaları hedeflenmektedir. Sübhaneke duasını ve bu duanın anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":16,"alanBecerileri":["DAB3. Tahkik (DAB3.1. Dinî Kavramları Ayırt Etme)","DAB4. Tefekkür (DAB4.1. Müşahede Etme)"],"kavramsalBeceriler":["KB2.6. Bilgi Toplama","KB2.14. Yorumlama","KB2.15. Yansıtma"],"egilimler":["E1.4. Kendine İnanma (Öz Yeterlilik)","E3.1 Muhakeme","E3.3. Yaratıcılık","E3.4. Gerçeği Arama","E3.5. Açık Fikirlilik","E3.7. Sistematiklik"],"sdb":["SDB1.1. Kendini Tanıma (Öz Farkındalık)","SDB2.1 İletişim"],"degerler":["D13. Sağlıklı Yaşam","D14. Saygı","D16. Sorumluluk","D18. Temizlik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık","OB4. Görsel Okuryazarlık"],"disiplinlerArasi":"Hayat Bilgisi","becerilerArasi":"DAB4. Tefekkür (DAB4.2. Dinî Meseleleri Anlama)","ogrenmeCiktilari":[{"kod":"DKAB.4.1.1","ad":"Günlük hayatta kullanılan dinî ifadeleri ayırt edebilme","surec":["a) Günlük hayatta kullanılan dinî ifadeleri tespit eder.","b) Günlük hayatta kullanılan dinî ifadelerin önemini araştırır.","c) Günlük hayatta kullanılan dinî ifadeleri ilişkili olduğu alana göre etiketler."]},{"kod":"DKAB.4.1.2","ad":"İslam’ın temizliğe verdiği önemi müşahede edebilme","surec":["a) İslam’ın temizliğe verdiği önemle ilgili merak ettiği konuları belirler.","b) İslam’ın temizliğe verdiği önemle ilgili belirlediği konular hakkında soru sorar.","c) İslam’ın temizliğe verdiği önemle ilgili konuları inceler.","ç) İslam’ın temizliğe verdiği önemle ilgili incelediği konular hakkında çıkarım yapar."]},{"kod":"DKAB.4.1.3","ad":"Allah’a (cc) şükrün önemini hayatına yansıtabilme","surec":["a) Allah’a (cc) şükür ile ilgili tecrübelerini gözden geçirir.","b) Allah’a (cc) şükür ile ilgili tecrübelerinden hareketle Allah’a (cc) şükrün önemi hakkında çıkarım yapar.","c) Allah’a (cc) şükrün önemi hakkında yaptığı çıkarımları değerlendirir."]},{"kod":"DKAB.4.1.4","ad":"İslam’a göre helal ve sağlıklı beslenmenin önemi konusunda bilgi toplayabilme","surec":["a) İslam’a göre helal ve sağlıklı beslenmenin önemi konusunu araştırır.","b) İslam’a göre helal ve sağlıklı beslenmenin önemi konusunda bilgiler bulur.","c) İslam’a göre helal ve sağlıklı beslenmenin önemi konusunda ulaştığı bilgileri öğretmen rehberliğinde doğrular.","ç) İslam’a göre helal ve sağlıklı beslenmenin önemi konusunda ulaştığı bilgileri kaydeder."]},{"kod":"DKAB.4.1.5","ad":"Sübhaneke duasını ve bu duanın anlamını okuyarak yorumlayabilme","surec":["a) Sübhaneke duasını ve bu duanın anlamını okur.","b) Sübhaneke duasının anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Sübhaneke duasının anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Günlük Hayatta Dinî İfadeler","Allah Temiz Olmamı İster","Allah Şükretmemi İster","Allah Sağlıklı Beslenmemi İster","Bir Dua Öğreniyorum: Sübhaneke Duası"],"anahtarKavramlar":["hamt","haram","helal","selam","şükür"],"olcmeDegerlendirme":["Bu ünitenin ölçme ve değerlendirme sürecinde kısa cevaplı sorular, boşluk doldurma soruları, eşleştirme soruları, anlam çözümleme tablosu, çıkış kartı, tanılayıcı dallanmış ağaç ve açık uçlu sorular kullanılabilir.","Performans Görevi: Öğrencilerden İslam’a göre temizlik, şükür ve sağlık konulu bir günlük hazırlamaları istenebilir. Bu ürünün değerlendirilmesinde, ölçülmesi amaçlanan öğrenme çıktılarına uygun ölçütlerle hazırlanmış dereceli puanlama anahtarları veya dereceleme ölçekleri kullanılabilir. Öğrencilerin değerlendirme sürecine aktif katılımı öz, akran ya da grup değerlendirme formları kullanılarak sağlanabilir."],"temelKabuller":["Öğrencilerin dinî ifadeleri günlük yaşamlarında duydukları, temizliğin sağlıkla ilişkisini bildikleri ve İslam’ın şükür, temizlik ve sağlıklı beslenmeye verdiği öneme dair temel farkındalıkları olduğu kabul edilmektedir."],"onDegerlendirme":["Öğrencilere günlük hayatta duydukları dinî ifadeler ile beslenme ve temizlik alışkanlıkları ile ilgili sorular sorularak ön bilgileri tespit edilebilir."],"kopruKurma":["Dinî ifadeler, şükür, temizlik ve sağlıklı beslenme konularının öğrencilerin yakın çevrelerinde sıkça karşılaştıkları söz ve davranışlarla ilişkisi kurulabilir. Bu konuların, hangi durumlarda ortaya çıktığı ve nasıl uygulandığı üzerinden günlük hayatla bağlantı kurulabilir."],"uygulamalar":[{"kod":"DKAB.4.1.1","metin":"Öğrencilere Eğitim Bilişim Ağı’ndan (EBA) günlük hayatta kullanılan dinî ifadelerin yer aldığı çeşitli içerikler gösterilebilir. Öğrencilerden bismillahirrahmanirrahîm, maşallah, inşallah, selamünaleyküm, aleykümselam, elhamdülillah, estağfirullah ve sübhanallah gibi dinî ifadeleri tespit etmeleri ve bunların önemini araştırmaları istenir (E3.4). Bu ifadeler besmele, hamt, selam, estağfirullah, sübhanallah başlıkları altında anlamlarıyla birlikte açıklanır. Öğrencilere bu ifadeleri hangi durumlarda ve ne amaçla kullandıkları, besmele çekmenin veya selamlaşmanın onlara ne hissettirdiği gibi sorular sorulur. Öğrencilerin bu ifadeleri kullanırken ortaya çıkan duygu, düşünce ve davranışlarını fark etmeleri sağlanır (SDB1.1). Öğrencilerden günlük hayatta kullanılan dini ifadeleri ilişkili olduğu alana göre etiketlemeleri istenir. Bunun için sınıflandırma tablosu kullanılabilir. Ölçme ve değerlendirme uygulamalarında kısa cevaplı sorular, eşleştirme soruları, anlam çözümleme tablosu ve açık uçlu sorular kullanılabilir."},{"kod":"DKAB.4.1.2","metin":"Öğrencilerden temizliğin önemi, gerekliliği ve sağlıkla ilişkisi hakkında düşünmeleri ve düşüncelerini paylaşmaları istenir (E3.5). İslam’ın temizliğe verdiği önemle ilgili öğrencilerin merak ettikleri konuları belirlemeleri istenir. Öğrenciler belirledikleri konular hakkında soru sorar. Eğitim Bilişim Ağı’ndan (EBA) konuyla ilgili uygun görseller gösterilebilir ve öğrencilerin bu görselleri yorumlaması sağlanabilir (OB4). Öğrencilerin konuyla ilgili şiir, hikâye vb. yazmaları istenebilir. Bedensel temizliğin anlamı, bedenimizi temiz tutma yolları, kişisel temizlik ve bakımın önemi ile Allah’ın (cc) temizliği emretmesi gibi konular incelenir (D18.1). Allah’ın (cc) temizlikle ilgili emirleri kapsamında abdest konusuna değinilir. Hz. Muhammed’in (sav) temizliğe verdiği önemle ilgili örneklere yer verilir. Öğrencilerin bedenin Allah’ın (cc) bir emaneti olduğunu fark etmesi ve Allah’ın (cc) temiz olmamızı istediği çıkarımına ulaşması sağlanır. Öğrencilerden yaşadığımız ortamın temiz olmasının sağlığımız ile ilişkisini anlatan özgün bir görsel çalışması yapması istenir (E3.3, OB4). Böylece öğrencilerin yaşadıkları çevreyi temiz tutmaya dikkat etmeleri sağlanır (D18.2, D18.3). Ölçme ve değerlendirme uygulamalarında çıkış kartı, kısa cevaplı sorular ve açık uçlu sorular kullanılabilir."},{"kod":"DKAB.4.1.3","metin":"Öğrencilere kendilerine yapılan iyiliklere nasıl karşılık verdikleri, teşekkür etmenin ne anlama geldiği; ne zaman, kime ve neden teşekkür edileceği sorulur. Bunun için soru-cevap tekniği kullanılır. Kendi hayatlarını düşünerek teşekkür kavramı ile ilgili duygu, düşünce ve tecrübelerini gözden geçirmeleri istenir. Teşekkür etmenin saygının gereği olduğuna vurgu yapılır (D14.1). Allah’ın (cc) bizlere verdiği nimetler anlatılarak bu nimetlerden ötürü Allah’a (cc) şükretme ifadelerini hatırlamaları istenir. Şükür ile teşekkür arasındaki ilişki ve şükrün insana katkıları konusunda farkındalık oluşturmak için öğrencilerin Allah’a (cc) şükrün önemiyle ilgili çıkarım ve değerlendirme yapması sağlanır. Öğrencilerden Allah’a (cc) şükür konusunu içeren bir hikâye yazmaları ve bunları sınıfta paylaşmaları istenir (OB1). Öğrencilerin yazdıkları hikâyeyi paylaşırken duygu ve düşüncelerini açık bir dille ifade etmeleri desteklenir (SDB2.1). Öğrenciler arkadaşlarından dinledikleri hikâyelerin konularını inceler ve içerdiği mesajları kendi cümleleriyle yeniden ifade eder. Ölçme ve değerlendirme uygulamalarında çıkış kartı ve açık uçlu sorular kullanılabilir."},{"kod":"DKAB.4.1.4","metin":"Sağlıklı beslenmenin önemi konusunda öğrencilere sorular sorulur. Öğrencilerden konu hakkında araştırma yapmaları istenir (E3.7). Öğrenciler, buldukları bilgileri kullanarak “Sağlıklı beslenirsek vücudumuzda neler olur?” sorusuyla ilgili çıkarımda bulunur (E1.4). Konuyla ilgili hayat bilgisi dersinden yararlanılır ve sağlıklı beslenmenin önemine dair farkındalık oluşturmak için drama çalışması yaptırılabilir. Öğrencilerin yeterli, dengeli ve sağlıklı beslenmenin, kişinin kendi bedenine karşı sorumluluğunu yerine getirmesi anlamına geldiğini fark etmesi sağlanır (D13.1, D16.1). Helal ve haram kavramları ele alınarak öğrencilerin bu kavramlara ilişkin farkındalık kazanmaları sağlanır (DAB4.2). Öğrencilerden İslam’ın helal ve sağlıklı beslenmeye verdiği önem hakkında araştırma yapmaları istenir. Öğrencilerin buldukları bilgiler öğretmen rehberliğinde doğrulanır. Öğrencilerin bunları yazarak kaydetmeleri sağlanır. İslam dininin insan sağlığına verdiği önemden yola çıkılarak İslam’a göre uygun beslenme ilkeleri ayet ve hadislerle ele alınır. İslam dininin israftan kaçınma, temiz ve helalinden beslenme konusuna verdiği önem kısaca açıklanır. Yemeğe başlarken ve yemeği bitirirken yapılacak dualara örnek verilir. Ölçme ve değerlendirme uygulamalarında kısa cevaplı sorular, eşleştirme soruları ve tanılayıcı dallanmış ağaç kullanılabilir. Öğrencilerden performans görevi olarak İslam’da temizlik, şükür ve sağlık konulu bir günlük hazırlamaları istenebilir. Hazırlanan günlük, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir."},{"kod":"DKAB.4.1.5","metin":"Öğrencilere “Sübhaneke duası hakkında neler biliyorsunuz?” sorusu yöneltilir. Bu duanın nerelerde okunduğuna dair bilgi verilir. Sübhaneke duasının doğru telaffuzunu öğretmek için öğrencilerin genel ağ araçlarını tanımaları ve kullanmaları sağlanır. Sübhaneke duasını dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak duanın doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır (OB2). Öğrencilerin bu duayı doğru telaffuz etmeleri için sesli okuma etkinliği yapılabilir. Duanın anlamı incelenir. Duanın anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılır. Öğrencilerin duanın anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır (E3.1). Öğrencilerin Sübhaneke duasının anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir. Öğrencilerin yaşadıkları toplumun manevi değerlerine saygı duymalarını sağlamak amacıyla röportaj yapmaları istenebilir. Ölçme ve değerlendirme uygulamalarında boşluk doldurma soruları, eşleştirme soruları ve açık uçlu sorular kullanılabilir."}],"zenginlestirme":["Öğrencilerden Allah’a (cc) şükretmenin insana kazandırdıkları hakkında afiş çalışması hazırlaması istenebilir. Sağlıklı beslenmenin önemini anlatan kısa film senaryosu yazması istenebilir. Bilişsel çıraklık yöntemi kullanılarak gönüllü öğrencilerin Sübhaneke duasını ezberlemesine rehberlik edilebilir."],"destekleme":["Dinî ifadeleri ve bu ifadelerin kullanıldığı yerleri içeren bir hikâye okunarak öğrencilerden hikâyede geçen dinî ifadeleri belirlemesi ve kendi hayatından bunlarla ilgili örnekler vermesi istenebilir.","Güncelleme tarihi: 27.07.2026"],"ogretmenYansitmalari":[]},
{"no":2,"ad":"Allah Sevgisi","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/6","odak":"Bu ünitede Allah’ın (cc) birliği ve yüceliği, Allah’ın (cc) kullarına olan sevgisi, dua, kelimeitevhit ve kelimeişehadet konuları ele alınmaktadır. Öğrencilerin Allah’ın (cc) birliği ve yüceliği hakkında bilgi sahibi olmaları ve öğrendikleri bilgileri yorumlamaları amaçlanmaktadır. Gözlemlerinden yola çıkarak Allah’ın (cc) insanlara olan sevgisini, merhametini ve iyiliğini fark etmeleri, dua etme ihtiyacı hakkında çıkarımda bulunmaları, kelimeitevhit ve kelimeişehadet hakkında bilgi toplamaları amaçlanmaktadır. Amentü duasını ve bu duanın anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.6. Bilgi Toplama","KB2.11. Gözleme Dayalı Tahmin Etme","KB2.14. Yorumlama","KB3.3. Eleştirel Düşünme"],"egilimler":["E1.5. Kendine Güvenme (Öz Güven)","E2.1. Empati","E3.8. Soru Sorma"],"sdb":["SDB1.3. Kendine Uyarlama (Öz Yansıtma)"],"degerler":["D14. Saygı","D15. Sevgi"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.4.2.1","ad":"Allah’ın (cc) birliğini ve yüceliğini kavrayabilme","surec":["a) Allah’ın (cc) birliğini ve yüceliğini içeren ayetleri inceler.","b) Allah’ın (cc) birliğini ve yüceliğini hayatı için anlamlı hâle getirir.","c) Allah’ın (cc) birliğini ve yüceliğini kendi cümleleri ile ifade eder."]},{"kod":"DKAB.4.2.2","ad":"Allah’ın (cc) kullarına olan sevgisini gözleme dayalı tahmin edebilme","surec":["a) Allah’ın (cc) kullarına olan sevgisini gözlemleriyle ilişkilendirir.","b) Allah’ın (cc) kullarına olan sevgisi hakkında çıkarım yapar.","c) Allah’ın (cc) kullarına olan sevgisi hakkında sonuç çıkarır."]},{"kod":"DKAB.4.2.3","ad":"Dua etme ihtiyacı hakkında düşünebilme","surec":["a) Duanın insan için bir ihtiyaç olduğunu fark eder.","b) Dua etmenin önemi hakkında sonuç çıkarır.","c) İhtiyaçları ve duyguları çerçevesinde dua örneklerini günlük hayatında ifadelerine yansıtır."]},{"kod":"DKAB.4.2.4","ad":"Kelimeitevhit ve kelimeişehadet hakkında bilgi toplayabilme","surec":["a) Kelimeitevhit ve kelimeişehadet konusunu araştırır.","b) Kelimeitevhit ve kelimeişehadet hakkında bilgi toplar.","c) Kelimeitevhit ve kelimeişehadet hakkında ulaştığı bilgileri öğretmen rehberliğinde doğrular.","d) Kelimeitevhit ve kelimeişehadet hakkında ulaştığı bilgileri kaydeder."]},{"kod":"DKAB.4.2.5","ad":"Amentü duasını ve bu duanın anlamını okuyarak yorumlayabilme","surec":["a) Amentü duasını ve bu duanın anlamını okur.","b) Amentü duasının anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Amentü duasının anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Allah’ı Tanıyorum","Allah Bizi Seviyor","Allah’a Dua Ediyorum","Kelimeitevhit ve Kelimeişehadet","Bir Dua Öğreniyorum: Amentü Duası"],"anahtarKavramlar":["dua","şehadet","tevhit"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Allah’ın (cc) birliği ve yüceliği hakkında çalışma yaprağı hazırlanabilir. Allah’ın (cc) kullarına olan sevgisi hakkında sunu hazırlanabilir. Dua etme ihtiyacıyla ilgili panel hazırlanabilir. Kelimeitevhit ve kelimeişehadet hakkında çalışma yaprağı hazırlanabilir. Amentü duası ve bu duanın anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur."],"temelKabuller":["Öğrencilerin sevmenin ve sevilmenin kişiye hissettirdikleri konusunda temel düzeyde bilgi sahibi oldukları kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Allah’a (cc) sevgimizi nasıl gösteririz?” sorusu sorularak öğrencilerin ön bilgileri harekete geçirilir ve bu soruya verdikleri cevaplara göre hazır bulunuşlukları kontrol edilir."],"kopruKurma":["Öğrencilere sevgilerini nasıl ifade ettikleri sorulur. Sevmenin ve sevilmenin ifade ediliş şekilleri örneklendirilerek günlük hayatla ilişki kurulur."],"uygulamalar":[{"kod":"DKAB.4.2.1","metin":"Evrendeki mükemmel düzen hakkında öğrencilere soru sorulur ve Allah’ın (cc) birliği vurgulanır. Allah’ın varlığına ve birliğine inanmanın, İslam’ın temel inanç esası olduğuna değinilir. İslam’ın altı inanç esası ayrıntıya girilmeden sıralanır. Allah’ın (cc) birliği ve yüceliğiyle ilgili ayetler belirlenir ve öğrencilerin bunları incelemesi istenir. Tüm varlıkların Allah (cc) tarafından yaratıldığına dair bilgilere yer verilerek Allah’ın (cc) kudret sıfatı vurgulanır. Öğrencilerin Allah’ın (cc) birliğini ve yüceliğini kendi cümleleri ile ifade etmeleri sağlanır."},{"kod":"DKAB.4.2.2","metin":"Merhamet kavramı tanımlanır. İnsanda bulunan sevme ve sevilme duygusunun Allah’ın (cc) merhametinin göstergesi olduğuna değinilir. Öğrencilerin, Allah’ın (cc) kullarına olan sevgisini ve verdiği nimetleri gözlemleyerek çıkarım yapması sağlanır. Konuyla ilgili görseller verilebilir. Allah’ın (cc) kullarına olan sevgisi ve merhameti dua ile ilişkilendirilir. Salih amel tanımlanır ve Allah’ın sevdiği amellerle ilgili örnekler verilir. Allah’ın (cc) kullarını sevdiği, kullarının da O’nu sevdiği ile ilgili öğrencilerin sonuç çıkarması sağlanır."},{"kod":"DKAB.4.2.3","metin":"Öğrencilerin dua etme ihtiyacı hakkında empati kurmalarını (E2.1) sağlamak için onlara “Dua ederken ne hissedersiniz?” sorusu yöneltilir. Dua etme ihtiyacı hakkında merak ettiklerini, soru sorarak (E3.8) bu ihtiyacı fark etmeleri sağlanır. Dua etmenin; ibadetin özü olduğu, Allah’a (cc) kulluk etmenin gereği olduğu, Allah (cc) ile iletişim ve bağ kurmanın bir yolu olduğu açıklanır. Kur’an-ı Kerim’de geçen dualara ve Hz. Muhammed’in (sav) yaptığı dualara örnekler verilir. Öğrencilerin bu dua örneklerini günlük hayatlarında kullandıkları ifadelere dönüştürmesi beklenir. Dua etmenin veya dua almanın insana neler hissettirdiği, kişinin duyguları üzerindeki etkisi ele alınır. Öğrencilerin kendi duygu, düşünce ve ihtiyaçlarının farkında olarak dua etmenin önemi hakkında sonuç çıkarması sağlanır. Öğrencilerin ihtiyaçları ve duyguları çerçevesinde öz değerlendirme yapmaları istenebilir (SDB1.3)."},{"kod":"DKAB.4.2.4","metin":"İslam’ın beş şartı ayrıntıya girilmeden sıralanır. Öğrencilerin kelimeitevhit ve kelimeişehadet hakkında bilgi toplamaları sağlanır. Kelimeitevhit ve kelimeişehadetin Allah’a (cc) olan sevgi (D15.3), saygı (D14.3) ve bağlılığın ifadesi olduğu açıklanır ve önemi vurgulanır. Öğrenciler; kelimeitevhit ve kelimeişehadet ile ilgili elde ettikleri bilgileri öğretmenleriyle birlikte değerlendirerek doğrular ve afiş, broşür, pano, duvar gazetesi gibi yollarla kaydeder."},{"kod":"DKAB.4.2.5","metin":"Öğrencilere “Amentü duası hakkında neler biliyorsunuz?” sorusu yöneltilir. Amentü kelimesinin anlamı açıklanır ve Amentü duası hakkında bilgi verilir. Amentü duasının doğru telaffuzunu öğretmek için öğrencilerin genel ağ araçlarını tanımaları ve kullanmaları sağlanır. Amentü duasını dinlemek ve bu dua hakkında bilgi sahibi olmak üzere Eğitim Bilişim Ağı’ndan (EBA) uygun içerikler belirlenir. Öğrencilerin bu platformu kullanmaları sağlanarak (OB2) duanın doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu duayı kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Duanın anlamı incelenir. Duanın anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak dua değerlendirilebilir. Öğrencilerin duanın anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Amentü duasının okunduğu yerler örneklendirilir. Öğrencilerin Amentü duasının anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Duanın insana kazandırdıkları hakkında öğrencilerin çevresindeki kişilerle röportaj yapması istenebilir. Öğrencilerden, insanın biyolojik mükemmelliği ile Allah’ın (cc) kullarına olan sevgisi arasındaki ilişkiyi araştırması istenebilir."],"destekleme":["Allah’ın (cc) varlığı ve birliği konusunun öğretiminde öğrencileri desteklemek için öğrencilerin ilgisini çekecek ve anlamlandırmayı kolaylaştıracak hikâyeler, görsel materyaller ve etkileşimli dijital uygulamalar kullanılabilir. Dualar konusunda sesli okuma ve tekrar etme etkinlikleri, görsel-işitsel materyaller ve etkileşimli dijital uygulamalarla öğrenciler desteklenebilir."],"ogretmenYansitmalari":[]},
{"no":3,"ad":"Peygamberlerin Sevgisi","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/7","odak":"Bu ünitede peygamberlerin çocuklarla ve toplumla ilişkisi, çevreyi ve çalışmayı sevmesi konuları ele alınmaktadır. Öğrencilerin peygamberlerin çocuk sevgisi hakkında örnekler üzerinden bilgi toplamaları, peygamberlerin toplumlarına olan sevgisini dua örneklerinden yola çıkarak yapılandırmaları, çevreye karşı duyarlılıklarıyla doğa ve hayvan sevgisi arasında ilişki kurmaları, peygamberlerin mesleklerinden yola çıkarak çalışmayı sevdiklerine dair çıkarım yapmaları amaçlanmaktadır. Salli ve Barik dualarını ve bu duaların anlamlarını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.6. Bilgi Toplama","KB2.10. Çıkarım Yapma","KB2.13. Yapılandırma","KB2.14. Yorumlama","KB2.16.2. Tümdengelime Dayalı Akıl Yürütme"],"egilimler":["E1.5. Kendine Güvenme (Öz Güven)","E3.8. Soru Sorma"],"sdb":["SDB1.3. Kendine Uyarlama (Öz Yansıtma)"],"degerler":["D1. Adalet","D2. Aile Bütünlüğü","D3. Çalışkanlık","D5. Duyarlılık","D9. Merhamet","D15. Sevgi","D18. Temizlik"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Fen Bilimleri, Hayat Bilgisi","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.4.3.1","ad":"Peygamberlerin çocuk sevgisiyle ilgili bilgi toplayabilme","surec":["a) Peygamberlerin çocuk sevgisi konusunu araştırır.","b) Peygamberlerin çocuk sevgisi hakkında bilgi toplar.","c) Peygamberlerin çocuk sevgisi hakkında ulaştığı bilgileri öğretmen rehberliğinde doğrular.","ç) Peygamberlerin çocuk sevgisi hakkındaki bilgileri kaydeder."]},{"kod":"DKAB.4.3.2","ad":"Peygamberlerin toplumlarına olan sevgisini yapılandırabilme","surec":["a) Peygamberlerin hayatlarını inceleyerek topluma karşı davranışları ve rehber olmaları arasında ilişki kurar.","b) Peygamberlerin toplumları için ettikleri dua örneklerinden yola çıkarak toplumlarına sevgiyle yaklaştıklarından hareketle uyumlu bir bakış açısı geliştirir."]},{"kod":"DKAB.4.3.3","ad":"Peygamberlerin çevre sevgisine ilişkin akıl yürütebilme","surec":["a) Peygamberlerin çevreye yaklaşımlarını inceler.","b) Peygamberlerin davranışlarıyla çevre sevgileri arasında ilişki kurar.","c) Peygamberlerin çevre sevgisi hakkında çıkarım yapar."]},{"kod":"DKAB.4.3.4","ad":"Peygamberlerin çalışmayı sevdiğine dair çıkarım yapabilme","surec":["a) Peygamberlerin çalışmayı sevdiğini farkeder.","b) Peygamberlerin geçimlerini sağlamak için yaptıkları işleri listeler.","c) Peygamberlerin mesleklerini karşılaştırır.","ç) Peygamberlerin çalışmaya ve üretmeye istekli olduklarına dair önerme sunar.","d) Peygamberlerin yaşantılarından hareketle emek vererek kazanç elde etmenin önemini değerlendirir."]},{"kod":"DKAB.4.3.5","ad":"Salli ve Barik dualarını ve bu duaların anlamlarını okuyarak yorumlayabilme","surec":["a) Salli ve Barik dualarını ve bu duaların anlamlarını okur.","b) Salli ve Barik dualarının anlamlarını kendi hayatı için anlamlı bir hâle getirir.","c) Salli ve Barik dualarının anlamlarını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Peygamberler Çocukları Sever","Peygamberler Toplumlarını Sever","Peygamberler Çevreyi Sever","Peygamberler Çalışmayı Sever","Bir Dua Öğreniyorum: Salli ve Barik Duaları"],"anahtarKavramlar":["peygamber","salavat"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, tanılayıcı dallanmış ağaç, sunu ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Peygamberlerin çocuklara olan sevgisi konusunda çalışma yaprağı hazırlanabilir. Peygamberlerin ailelerine ve toplumlarına olan sevgisiyle ilgili açık uçlu soruların yer aldığı çalışma yaprağı hazırlanabilir. Peygamberlerin çevre, doğa ve hayvan sevgisiyle ilgili çıkarımları içeren sunu veya pano hazırlama görevi verilebilir, drama yaptırılabilir. Peygamberlerin çalışmayı sevmesiyle ilgili metin okunabilir ve ilkeler çıkarılabilir. Salli ve Barik duaları ve bu duaların anlamlarıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur."],"temelKabuller":["Öğrencilerin peygamberlik hakkında temel düzeyde fikir sahibi olduğu kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Peygamber kime denir?” sorusu sorularak ön bilgileri tespit edilir."],"kopruKurma":["Peygamberlerin çocuklara, topluma ve çevreye verdikleri değer ile öğrencilerin hayat bilgisi dersinde öğrendikleri arasında bağlantı kurulur."],"uygulamalar":[{"kod":"DKAB.4.3.1","metin":"Peygamber kavramı açıklanır. Öğrencilerden, Hz. Muhammed (sav) günümüzde yaşasaydı bir dede olarak torunları ile neler yapabileceği üzerine düşünmeleri ve fikirlerini paylaşmaları istenir. Verilen cevaplardan hareketle peygamberlerin çocuklara şefkat ve anlayışla yaklaştıklarına dair çıkarımda bulunulur. Hz. Ali, Hz. Enes, Hz. Zeyd gibi çocuk sahabilerin Hz. Muhammed’le (sav) ilgili anlatılarına yer verilerek onun çocuklara gösterdiği özveri ve ilgi ele alınır (D15.4). Hz. Muhammed’in (sav) kız ve erkek çocuklar arasında ayrım yapmadığına dikkat çekilir (D1.1). Hz. Muhammed’in (sav) çocuklarla ilgili hadisleri belirlenir. Kur’an-ı Kerim’deki baba-oğul peygamberlerle ilgili ayetlere de dikkat çekilerek bu ayet ve hadisler ışığında öğrencilerin, peygamberlerin çocuk sevgisi hakkında bilgi toplamaları sağlanır. Öğrencilerin elde ettikleri bilgiler öğretmen tarafından değerlendirilir ve doğrulanır. Öğrencilerin bu bilgileri afiş, broşür, pano, duvar gazetesi gibi yollarla kaydetmesi sağlanır."},{"kod":"DKAB.4.3.2","metin":"Peygamberlerin toplumlarına olan sevgisi, aileleri ile ilişkilerinden yola çıkılarak ele alınır. Her peygamberin bir ailesi olduğuna ve bir toplum içinde yaşadığına dikkat çekilir. Hz. İbrahim’in oğlu Hz. İsmail ile olan sevgi dolu ilişkisine Saffat suresi 100 ve 101. ayetler bağlamında değinilir, Hz. Zekeriya ve Hz. Yahya’nın aile bağlarına (D2.1) vurgu yapılır. Peygamberlerin hayatları incelenerek topluma karşı davranışları ve rehber olmaları arasında ilişki kurulur. Peygamberlerin toplumlarına verdikleri değer (D5.1), Tevbe suresi 128. ayetten hareketle ele alınır. Peygamberlerin toplumları için yaptıkları dua örneklerinden yola çıkılarak gönderildikleri toplumlara sevgi ve merhametle (D9.2) yaklaştıklarına dair bir bakış açısı geliştirir."},{"kod":"DKAB.4.3.3","metin":"Öğrenciden çevresini gözlemlemesi istenir. Yaşadığımız çevrenin ve bu çevre içerisindeki canlıların Allah (cc) tarafından yaratıldığına dikkat çekilir. Doğanın ve hayvanların korunmasının önemi ile ilgili Eğitim Bilişim Ağı’ndan (EBA) uygun bir video izletilebilir. Böylece öğrencilerin fen bilimleri dersinden öğrendikleriyle konu ilişkilendirilebilir. Öğrencilere, onların diğer canlılara karşı davranışlarına dair kendilerini değerlendirmelerine yönelik sorular sorulabilir (SDB1.3). Konuyla ilgili bir öz değerlendirme formu hazırlanabilir. Peygamberlerin hayvanlara verdiği değer (D5.2) ve gösterdiği şefkatle (D9.3) ilgili örnek davranışları belirlenir. Çevre temizliği konusundaki uyarılarına değinilir (D18.3). Peygamberlerin bu davranışlarıyla doğa ve hayvan sevgileri arasında ilişki kurulur. Hz. Muhammed’in (sav) konuyla ilgili hadislerine yer verilir. İlgili hadisler yorumlanarak peygamberlerin çevre ve hayvan sevgisi hakkında çıkarım yapılır."},{"kod":"DKAB.4.3.4","metin":"Öğrencilere hangi mesleklere ilgi duydukları sorulur. Her insanın geçinmek için bir işle meşgul olduğuna dikkat çekilir ve öğrencilerden peygamberlerin geçimlerini nasıl sağlamış olabilecekleriyle ilgili akıl yürütmeleri istenir. Verilen cevaplardan hareketle peygamberlerin çalışmayı sevdikleri farkettirilir. Öğrenciler, peygamberlerin mesleklerinin neler olabileceği hakkında merak ettikleri soruları sormaları (E3.8) için teşvik edilir. Bazı peygamberlerin geçimlerini sağlamak için yaptıkları işler listelenir. Peygamberlerin meslekleri karşılaştırılarak her birinin yeteneklerine göre bir uzmanlık alanının olduğu fark ettirilir. Peygamberlerin çalışmaya ve üretmeye istekli olduklarına (D3.1) dair önermeler sunulur. Peygamberlerin yaşantılarından hareketle emek vererek kazanç elde etmenin önemini değerlendirir. Bunun için ilke çıkarma etkinliği yapılabilir."},{"kod":"DKAB.4.3.5","metin":"Eğitim Bilişim Ağı’ndan (EBA) salavat dinletilerek öğrencilerin dikkati çekilir. Hz. Muhammed’in (sav) ismini duyan veya söyleyen her Müslümanın onu dua ve selamla anarak ona olan sevgisini ve bağlılığını dile getirdiği belirtilir. Onun için yapılan bu dualara salavat duaları denildiği, Salli ve Barik dualarının da bu özel dualardan olduğu ifade edilir. Bu duaların nerelerde okunduğuna dair bilgi verilir. Hz. Peygamber’in ailesine “Ehlibeyt” adı verildiğine değinilerek bu dualarda onun ailesinden bahsedildiğine dikkat çekilir. Salli ve Barik dualarını dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) duaların doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu duaları kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Duaların anlamları incelenir. Duaların anlamlarından çıkarılacak mesajlarla ilgili etkinlikler yapılarak dualar değerlendirilebilir. Öğrencilerin duaların anlamlarını kendi hayatları için anlamlı hâle getirmeleri sağlanır. Öğrencilerin Salli ve Barik dualarının anlamlarını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Hz. Muhammed’in (sav) çocuklara karşı davranışları incelenerek öğrencilerden, çocuk haklarına dair ilkeler çıkarması istenebilir."],"destekleme":["Peygamberlerin çalışmayı sevmeleri hakkında öğrencilerin ilgisini çekecek etkileşimli ve görsel öğrenme materyalleri (bilgi kartları, oyunlar) kullanılarak öğrencilerin konuyu daha iyi kavramaları ve somutlaştırmaları sağlanabilir. Derste anlatılan peygamberlerin icra ettikleri mesleklerle ilgili görseller hazırlanabilir. Öğrencilerden görseldeki meslek ile o mesleği yapan peygamberin adını eşleştirmesi istenebilir."],"ogretmenYansitmalari":[]},
{"no":4,"ad":"Ahlaki Değerlerimiz","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/44","odak":"Bu ünitede adalet, sabır ve yardımseverlik değerleri ve bu değerlerin davranışlara yansımaları ele alınmaktadır. Öğrencilerin adaletli davranmayı sorgulamaları, sabrın önemini yapılandırmaları, gözlemlerinden yola çıkarak yardımseverliğin insan ilişkilerindeki rolünü ve önemini tahmin etmeleri amaçlanmaktadır. Fatiha suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":12,"alanBecerileri":[],"kavramsalBeceriler":["KB2.8. Sorgulama","KB2.11. Gözleme Dayalı Tahmin Etme","KB2.13. Yapılandırma","KB2.14. Yorumlama"],"egilimler":["E1.5. Kendine Güvenme (Öz Güven)","E3.8. Soru Sorma","E3.10. Eleştirel Bakma"],"sdb":[],"degerler":["D1. Adalet","D12. Sabır","D20. Yardımseverlik"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.4.4.1","ad":"Adaletli davranmayı sorgulayabilme","surec":["a) Adaleti kendi ifadeleri ile tanımlar.","b) Adaletle ilgili sorular sorar.","c) İslam’ın adalete verdiği önem hakkında bilgi toplar.","ç) İslam’ın adalete verdiği önem hakkında topladığı bilgilerin doğruluğunu öğretmen rehberliğinde değerlendirir.","d) İslam’ın adalete verdiği önem hakkında toplanan bilgiler üzerinde çıkarım yapar."]},{"kod":"DKAB.4.4.2","ad":"Sabır değerinin önemini yapılandırabilme","surec":["a) İnsan ilişkilerini inceleyerek sabır değerinin önemini içeren nedensel ilişkiler ortaya koyar.","b) Sabır değerinin önemi hakkında ortaya koyduğu ilişkilerden hareketle uyumlu bir bakış açısı geliştirir."]},{"kod":"DKAB.4.4.3","ad":"Yardımseverliğin insan ilişkilerindeki rolünü ve önemini gözleme dayalı tahmin edebilme","surec":["a) Yardımseverliğe ilişkin ön gözlem ve tecrübesini ilişkilendirir.","b) Yardımseverliğin önemine ilişkin çıkarım yapar.","c) Yardımseverliğin insan ilişkilerindeki rolü ve önemine ilişkin sonuç çıkarır."]},{"kod":"DKAB.4.4.4","ad":"Fatiha suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Fatiha suresini ve bu surenin anlamını okur.","b) Fatiha suresinin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Fatiha suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Adalet","Sabır","Yardımseverlik","Bir Sure Öğreniyorum: Fatiha Suresi"],"anahtarKavramlar":["adalet","ahlak","sabır","yardımseverlik"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Adaletli davranmakla ilgili drama yaptırılabilir. Sabırlı bir insanın özelliklerine dair hikâye tamamlama etkinliği yaptırılabilir. Yardımseverliğin önemi hakkında öğrencilerden öğrenme günlükleri tutmaları istenebilir. Fatiha suresi ve bu surenin anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur."],"temelKabuller":["Öğrencilerin ahlaki değerler hakkında temel düzeyde fikir sahibi oldukları kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Ahlaki değerlerden hangilerini biliyorsunuz?” sorusu sorularak onların ahlaki değerlerle ilgili ön bilgileri belirlenir."],"kopruKurma":["Ahlaki değerlerin insan ilişkilerindeki rolü ile günlük hayat arasında bağlantı kurulur."],"uygulamalar":[{"kod":"DKAB.4.4.1","metin":"Ahlak kavramı ele alınarak öğrencilere ayet ve hadisler çerçevesinde kısaca bilgi verilir. Öğrencilerin, adalet kavramını kendi ifadeleriyle tanımlamaları sağlanır. Adalet kavramı tanımlanır. Kavramın ölçülü ve dengeli olmak (D1.3) anlamlarını da içerdiğine değinilir. Ayet ve hadislerden yararlanarak öğrencilere adaletle ilgili bilgi verilir. Adalet ile ilgili örnekler verilerek öğrenmeler pekiştirilir. Öğrencilerin adaletle ilgili merak ettiği soruları (E3.8) not etmeleri istenir. Soracakları soruları belirledikten sonra küçük kağıtlara yazarak bir kutuya atmaları istenir. Sorular kutuda toplanır ve öğrencilere sırayla seçtirilir. Öğrencilerin seçtikleri soruları cevaplaması beklenir. Verilen cevapların doğruluğu, öğretmen tarafından değerlendirilerek öğrencilere dönütler verilir. Öğrencilerden, İslam’ın adalete verdiği önem hakkında bilgi toplamaları sağlanır. Toplanan bilgilerin doğruluğu öğretmen rehberliğinde değerlendirilir ve bu bilgiler üzerinden öğrencilerin çıkarım yapmaları sağlanır."},{"kod":"DKAB.4.4.2","metin":"Sabır kavramı tanımlanarak konu hakkında bilgi verilir. Sabrın duygu, düşünce ve davranışlarda kontrollü olmak anlamına geldiği öğrencilere fark ettirilir (D12.2). Sabırlı insanın özellikleri belirlenir. Müminlerin sabırlı olduğuna vurgu yapılır. Öğrencilerin insan ilişkilerinde sabrın önemini fark edebilmeleri için günlük hayattan örnekler verilerek kendi bilgi ve davranışlarına eleştirel bakmaları (E3.10) sağlanır. Böylece sabırlı olmanın önemini içeren nedensel ilişkiler ortaya konulur. Öğrencilere günlük hayatlarıyla özdeşleştirmeleri için aile ve arkadaşlık ilişkileri üzerinden sabırlı olmaya dair örnekler verilir. Karşılaştıkları zorluklar karşısında olumlu bakış açısına sahip olmaları (D12.1) gerektiği vurgulanır. Hz. Muhammed’in (sav) sabırlı oluşuna dair örnekler verilir. Sabır değeri hakkında verilen bilgiler doğrultusunda, bu değerin önemiyle ilgili ortaya konulan ilişkilerden hareketle uyumlu bir bakış açısı geliştirmesi sağlanır."},{"kod":"DKAB.4.4.3","metin":"Yardımseverlik tanımlanır. Öğrencilere yardımseverlikle ilgili ön bilgileri ve tecrübeleri sorulur. Kendi hayatlarından verdikleri örneklerden hareketle öğrencilerin tecrübeleri yardımseverlik kavramı ile ilişkilendirilir. Yardımsever insanın özellikleri ayetlerle açıklanır. Hz. Muhammed’in (sav) hayatından yardımseverliğe dair örnekler verilir. Cömert ve iyiliksever olmanın öneminden bahsedilir (D20.1, D20.3). Yardımlaşma örnekleri verilerek öğrencilerin konuyu pekiştirmeleri sağlanır. Ensar ve muhacir kardeşliğine değinilir. Öğrencilerin bu bilgilerden hareketle yardımseverliğin önemine ilişkin çıkarım yapmaları beklenir. Yardımsever olmanın insan ilişkilerindeki rolüne ve önemine dair sonuç çıkarmaları sağlanır. Konuyla ilgili olarak Kızılay Haftası’na değinilir."},{"kod":"DKAB.4.4.4","metin":"Öğrencilere “Fatiha suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Fatiha kelimesinin anlamı açıklanarak Fatiha suresinin içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Fatiha suresi hakkında bilgi verilirken surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Fatiha suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Fatiha suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilerden, ahlaki değerler arasından seçtikleri değerle ilgili kısa bir hikâye oluşturarak çocuk kitabı tasarlamaları istenebilir. Öğrencilerin, Kur’an’dan sabır içerikli kıssalara ulaşarak bu kıssalardan akıllarında kalanları öğretmen rehberliğinde arkadaşlarıyla sınıf ortamında paylaşmaları sağlanabilir. Yardımseverlik değeri için kermes düzenlenip gelirinin ihtiyaç sahibi insanlara ulaştırılması sağlanabilir."],"destekleme":["Öğrencilere adaletle ilgili hikâyeler sunularak öğrencilerin adalet kavramını somutlaştırmaları sağlanabilir."],"ogretmenYansitmalari":[]},
{"no":5,"ad":"Haklar ve Sorumluluklar","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/50","odak":"Bu ünitede hak ve sorumluluklar konusu ele alınmaktadır. Öğrencilerin toplumdaki herkesin temel hak ve özgürlüklere sahip olduğunu açıklamaları, kişisel hakları sentezleyerek bunlara saygı duymaları, temel bir hak olarak mahremiyeti sorgulamaları ve bu hakkın korunması gerektiğine dair farkındalık kazandırmaları amaçlanmaktadır. Allah’a (cc) karşı sorumluluklarını inanç ve ibadet açısından çözümlemeleri ve diğer insanlara karşı sorumluluklarını özetlemeleri amaçlanmaktadır. Rabbena dualarını ve bu duaların anlamlarını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":12,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.4. Çözümleme","KB2.8. Sorgulama","KB2.14. Yorumlama","KB2.20. Sentezleme"],"egilimler":["E1.5. Kendine Güvenme (Öz Güven)"],"sdb":["SDB1.2. Kendini Düzenleme (Öz Düzenleme)"],"degerler":["D5. Duyarlılık","D8. Mahremiyet","D9. Merhamet","D14. Saygı","D15. Sevgi","D16. Sorumluluk"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.4.5.1","ad":"Kişisel hakları sentezleyebilme","surec":["a) Kişisel hakları açıklar.","b) Kişisel haklar arasında ilişki kurar.","c) Kişisel hakları birleştirerek özgün bir bütün oluşturur."]},{"kod":"DKAB.4.5.2","ad":"Mahremiyet hakkını sorgulayabilme","surec":["a) Mahremiyet kavramını tanımlar.","b) Mahremiyet hakkında sorular sorar.","c) Mahremiyet hakkında bilgi toplar.","ç) Mahremiyet hakkında topladığı bilgilerin doğruluğunu öğretmen rehberliğinde değerlendirir.","d) Mahremiyet hakkında topladığı bilgiler üzerinden çıkarım yapar."]},{"kod":"DKAB.4.5.3","ad":"Allah’a (cc) karşı sorumluluklarını çözümleyebilme","surec":["a) Allah’a (cc) karşı inanç ve ibadet sorumluluklarını sıralar.","b) İnanç ve ibadetle ilgili sorumluluklar arasındaki ilişkileri inceler."]},{"kod":"DKAB.4.5.4","ad":"İnsanlara karşı sorumluluklarını özetleyebilme","surec":["a) İnsanlara karşı sorumluluklarını çözümler.","b) İnsanlara karşı sorumluluklarını sınıflandırır.","c) İnsanlara karşı sorumluluklarını yorumlar."]},{"kod":"DKAB.4.5.5","ad":"Rabbena dualarını ve bu duaların anlamlarını okuyarak yorumlayabilme","surec":["a) Rabbena dualarını ve bu duaların anlamlarını okur.","b) Rabbena dualarının anlamlarını kendi hayatı için anlamlı bir hâle getirir.","c) Rabbena dualarının anlamlarını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Kişisel Haklar ve Haklara Saygı","Mahremiyet","Allah’a Karşı Sorumluluklarım","İnsanlara Karşı Sorumluluklarım","Bir Dua Öğreniyorum: Rabbena Duaları"],"anahtarKavramlar":["hak","mahremiyet","sorumluluk"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu sorular, kelime ilişkilendirme, çalışma yaprağı, kavram haritası, soru kutusu ve öz değerlendirme formu kullanılabilir.","Performans görevi:","Ayet ve hadislerden örnekler içeren kişisel haklar konulu kitapçık hazırlanabilir. Mahremiyetin önemi konulu drama çalışması hazırlanabilir. Allah’a (cc) karşı sorumlulukları içeren bir sunu hazırlanabilir. İnsanlara karşı sorumlulukların konu edildiği bir pano hazırlanabilir. Rabbena duaları ve bu duaların anlamlarını eşleştirme çalışması yapılabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur."],"temelKabuller":["Öğrencilerin hak ve sorumluluklar konusunda temel düzeyde fikir sahibi oldukları kabul edilmektedir."],"onDegerlendirme":["Öğrencilere hak ve sorumluluklar konusunda neler bildikleri sorulur. Verilen cevaplardan hareketle öğrencilerin hazır bulunuşlukları tespit edilir."],"kopruKurma":["Öğrencilere, sahip olduğu haklar ve sorumluluklar hakkında bilgi verilerek Hayat Bilgisi dersi ile ilişki kurulur."],"uygulamalar":[{"kod":"DKAB.4.5.1","metin":"Öğrencilere “Kişisel haklar hakkında neler biliyorsunuz?” sorusu sorularak onların konuya olan ilgi ve öğrenme istekleri (E1.1) uyandırılır. Hak kavramı açıklanır ve kişisel hakların neler olduğu belirlenir. Herkesin temel kişisel hakları olduğu ve İslam’ın kişisel haklara önem verdiği belirtilir. Öğrencilere aile içindeki, okuldaki ve ülkedeki insanların hakları konusunda farkındalık kazandırılır. Toplumsal rollerin insanlara kazandırdığı haklara örnekler verilerek öğrencilerin bunlarla kişisel haklar arasında ilişki kurması sağlanır. Hz. Muhammed’in (sav) toplumsal rolleri üzerinden örnekliği çerçevesinde (bir baba, evlat, dede, arkadaş, eş olarak) haklara değinilir. Öğrencilerin hem kendisinin hem de başkalarının kişisel hakları olduğunu fark ederek bunları birleştirmesi (E2.1) ; insanlarla ilişkilerinde saygılı (D14.1), nazik, sabırlı ve anlayışlı olması (D5.1) sağlanır. Öğrenci, bu değerlere yer verdiği bir afiş, poster, pano vs. oluşturur."},{"kod":"DKAB.4.5.2","metin":"Öğrencilere günlük hayatta gizli kalması gereken konuların neler olduğu hakkında sorular sorulur. Verilen cevaplardan hareketle mahremiyet kavramı açıklanır ve öğrenciler mahremiyetle ilgili sorular sormaya teşvik edilir. Bunun için soru kutusu tekniği kullanılabilir. Öğrencilerin mahremiyetin temel bir hak olduğunu, bu hakka saygı gösterilmesi gerektiğini ve her ferdin değerli olduğunu fark etmesi (D14.1) sağlanır. Öğrencilere; mahremiyet hakkında bilgi toplamalarını sağlayacak ve tanımadıkları kişilere, arkadaşlarına ve ailelerine karşı sınırların ne olması gerektiğini fark ettirecek etkinlikler yaptırılır. Bu etkinliklerle toplananılan bilgilerin doğruluğu öğretmen rehberliğinde değerlendirilir ve öğrencilere kendi hayatlarında (D8.1) ve sosyal ilişkilerinde kişisel alanların korunması gerektiği (D8.4) açıklanır. Kişisel eşyaları korumaya (D8.4), başkalarını rahatsız edecek davranışlardan uzak durmaya ve özel hayatın gizliliğini ihlal edecek davranışlardan kaçınmaya (D8.4) dair öğrencilere farkındalık kazandırılır. Mahremiyete saygının İslam ahlakının temel ilkelerinden biri olduğu vurgulanır. Hz. Muhammed’in (sav) bu konuyla ilgili öğütlerine yer verilir. Böylece İslam’ın mahremiyet kavramına verdiği önem ve bu hakkın korunması gerekliliği hususunda öğrencilerin çıkarımda bulunması sağlanır."},{"kod":"DKAB.4.5.3","metin":"Sorumluluk kavramı açıklanır. Öğrencilere “kimlere/nelere karşı sorumluluklarımız var?” sorusu sorulur. Verilen cevaplardan hareketle insanın kendisine, ailesine, çevresine ve Allah’a (cc) karşı sorumlulukları olduğu sonucuna ulaşılarak bu maddeler sıralanır. İnsanın bedensel, ruhsal ve sosyal iyi oluşu için çaba göstermesinin ve kendini tehlikeye sokacak davranışlardan kaçınmasının (D16.1) kendisine olan sorumluluğu olduğu belirtilir. Verilen görevleri yerine getirmek (D16.3), ortak kullanım alanlarını korumak, temiz kullanmak, toplumsal hayatı düzenleyen kurallara uymak gibi (D16.2) sorumluluklarının da olduğu açıklanır. Öğrencilerin kişisel ve toplumsal sorumluluklarından hareketle kendisini yaratan ve her türlü nimeti bahşeden Allah’a (cc) karşı da sorumlulukları olduğunu fark etmesi sağlanır. Allah’a (cc) karşı inanç ve ibadet alanlarında sorumluluklarımızın olduğu öğrencilere ifade edilir. Allah’a (cc) duyulan sevginin ibadetlerle gösterildiği (D15.3) belirtilir. Öğrencilerin ibadet eden insanları izleyerek ibadetin insan üzerindeki etkilerini fark etmeleri sağlanır. Allah’a (cc) karşı sorumlulukları yerine getirmenin güzel ahlaka katkısı vurgulanır. Ahlaki değerlerin kazanılması ve korunmasının O’na karşı sorumlulukların yerine getirilmesiyle ilişkisi açıklanır."},{"kod":"DKAB.4.5.4","metin":"İnsanlara karşı sorumluluklarla ilgili görseller gösterilerek öğrencilerin bu sorumlulukları belirlemesi ve çözümlemesi sağlanır. Diğer insanlara karşı sorumluluklar tanımlanır. Bu sorumluluklar söz ve davranışlarda doğru olmak, yardımlaşmak ve dayanışmak, büyükleri saymak, küçükleri sevmek, komşuları ve akrabaları gözetmek şeklinde sınıflandırılır. İslam dininin bu sorumluluklara verdiği önem vurgulanır. Öğrencilerin bu sorumlulukların toplumsal hayata etkisini kendi cümleleriyle yorumlamaları sağlanır. Böylece insanlara karşı şefkatli, sevgi dolu (D9.2) ve duyarlı (D5.1) davranma konusunda öğrencilere bilinç kazandırılır. Öğrencilerin yeteneklerine güvenerek (E1.5) insanlara karşı sorumlulukların önemine dair yargıda bulunmaları ve bu konuda olumlu davranışlar ortaya koymaları (SDB1.2) beklenir."},{"kod":"DKAB.4.5.5","metin":"Öğrencilere “Rabbena duaları hakkında neler biliyorsunuz?” sorusu yöneltilir ve önceki bilgileri kontrol edilir. Rabbena duaları ve bu duaların anlamları açıklanarak içerdikleri mesajlar ve nerelerde okundukları hakkında bilgi verilir. Rabbena dualarını dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) duaların doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu duaları kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Duaların anlamı incelenir. Duaların anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin duaların anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Rabbena dualarının anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilerin çevreye karşı sorumluluklarını kendilerine benimsetmek için okul çevresinde fidan dikme, bitki sulama, çevreyi güzelleştirme (peyzaj çalışması vb.) gibi etkinliklere gönüllü olarak katılımları sağlanabilir.","Öğrencilerden sosyal medya kullanımının mahremiyeti nasıl etkilediğine ilişkin bir sınıf tartışması yapmaları istenebilir."],"destekleme":["Kişisel haklar hakkında öğrencilerin ilgisini çekecek etkileşimli ve görsel öğrenme materyalleri (bilgi kartları, oyunlar) kullanılarak öğrencilerin konuyu daha iyi kavramaları ve somutlaştırmaları sağlanabilir."],"ogretmenYansitmalari":[]}],"s5":[{"no":1,"ad":"Allah İnancı","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/53","odak":"Bu ünitenin teması inançtır. Ünitede İslam dininin temeli olan Allah (cc) inancı konusu ele alınmaktadır. Öğrencilerin evrendeki mükemmel düzene ilişkin akıl yürütmeleri, bu düzeni fark ederek Allah’ın (cc) varlığı ve birliği hakkında gözleme dayalı tahminde bulunmaları, tevhit kavramı ve Allah’ın (cc) güzel isimleri hakkında kaynaklardan bilgi toplamaları amaçlanmaktadır. İhlas suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.6. Bilgi Toplama","KB2.11. Gözleme Dayalı Tahmin Etme","KB2.14. Yorumlama","KB2.16.1. Tümevarıma Dayalı Akıl Yürütme"],"egilimler":["E1.1. Merak","E1.2. Bağımsızlık","E1.5. Kendine Güvenme (Öz Güven)","E2.1. Empati","E3.4. Gerçeği Arama","E3.7. Sistematik Olma","E3.8. Soru Sorma","E3.10. Eleştirel Bakma"],"sdb":["SDB1.1. Kendini Tanıma (Öz Farkındalık)"],"degerler":["D9. Merhamet","D11. Özgürlük"],"okuryazarlik":["OB2. Dijital Okuryazarlık","OB4. Görsel Okuryazarlık"],"disiplinlerArasi":"Fen Bilimleri","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.5.1.1","ad":"Evrendeki mükemmel düzene ilişkin akıl yürütebilme","surec":["a) Evrendeki mükemmel düzene ilişkin gözlem yapar.","b) Evrendeki mükemmel düzenle ilgili örüntüler bulur.","c) Evrendeki mükemmel düzene dair genellemeler yapar."]},{"kod":"DKAB.5.1.2","ad":"Evrendeki mükemmel düzeni gözlem yoluyla fark edip Allah’ın (cc) varlığı ve birliğini gözleme dayalı tahmin edebilme","surec":["a) Evrendeki mükemmel düzene ilişkin ön gözlem veya tecrübeyi Allah’ın (cc) varlığı ve birliği ile ilişkilendirir.","b) Bu ilişkilerden hareketle Allah’ın (cc) var ve bir olduğuna dair çıkarım yapar.","c) Tevhit inancına ilişkin sonuç çıkarır."]},{"kod":"DKAB.5.1.3","ad":"Allah’ın (cc) güzel isimleri hakkında bilgi toplayabilme","surec":["a) Allah’ın (cc) güzel isimleri konusunu araştırır.","b) Allah’ın (cc) güzel isimleri hakkında bilgi toplar.","c) Allah’ın (cc) güzel isimleri hakkında ulaştığı bilgileri doğrular.","ç) Allah’ın (cc) güzel isimleri hakkında ulaştığı bilgileri kaydeder."]},{"kod":"DKAB.5.1.4","ad":"İhlas suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) İhlas suresini ve bu surenin anlamını okur.","b) İhlas suresinin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) İhlas suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Evrendeki Mükemmel Düzen","Allah’ın Varlığı ve Birliği","Allah’ın Güzel İsimleri","Bir Sure Öğreniyorum: İhlas Suresi"],"anahtarKavramlar":["esmayıhüsna","ihlas","tevhit"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası, görsel inceleme formu ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Gözlemlerinden hareketle genellemeler yaparak evrendeki mükemmel düzenin oluşumunu anlattığı çıkış kartı hazırlanabilir. Evrendeki mükemmel düzen ile Allah’ın (cc) varlığı ve birliği arasındaki ilişkiyi belirlemek için kavram haritası hazırlanabilir.","Allah’ın (cc) güzel isimlerinin hayata yansımalarıyla ilgili pano hazırlanabilir. İhlas suresi ve bu surenin anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin İslam’ın inanç esasları hakkında temel düzeyde bilgi sahibi olduğu, çevresini gözlemleyebildiği, Kur’an-ı Kerim’de ve hadislerde inanç konusuyla ilgili bilgilerin yer aldığını bildiği kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Evrende ve vücudumuzda nasıl bir işleyiş vardır?” sorusu sorulur. Öğrencilerden konuyla ilgili beyin fırtınası yapmaları istenir. Dijital öğrenme platformları kullanılarak uygun görseller öğrencilere gösterilir ve çevremizdeki mükemmel düzene dikkat çekilir."],"kopruKurma":["Öğrencilerin fen bilimleri dersinde öğrendiği tabiat olaylarıyla ilgili (Dünya’nın hem kendi hem de Güneş etrafında dönüşü, mevsimlerin oluşumu, su döngüsü vb.) görseller ve kısa filmler aracılığıyla doğa yasalarına dikkat çekilir. Bu olaylar ile Allah’ın (cc) yaratıcılığı arasında ilişki kurulur."],"uygulamalar":[{"kod":"DKAB.5.1.1","metin":"Konuya başlamadan öğrencilerin önceki bilgileriyle ilişki kurmaları ve öğrenme stratejisi geliştirmeleri (SDB1.1) amacıyla çevrelerindeki düzen hakkında merak ettikleri soruları sormaları (E3.8) sağlanır. Konuyla ilgili sorular öğrencilerin defterlerine yazdırılır. Öğrencilerden evrendeki mükemmel düzene ilişkin gözlem yapması istenir. Derste öğrencilerin gözlemlerini özgür ve bağımsız olarak ifade etmelerine (D11.2) imkân tanınır. Bunun için öğretmen tarafından Eğitim Bilişim Ağı’ndan (EBA) gece gündüz, mevsimler, su döngüsü gibi tabiat olaylarıyla ilgili görseller belirlenir. Öğrencilerin bu görsellerdeki tabiat olaylarını algılamaları ve tanımaları sağlanır. Öğrenciler, bu görselleri yorumlar ve tabiat olayları hakkında akıl yürütür (OB4). Bu sayede sistematik olarak (E3.7) evrendeki düzeni kanıtlayan örüntüler bulması ve bu düzeni içeren genellemeler yapması sağlanır. Bunun için öğrencilerden kavram haritası hazırlamaları istenilebilir."},{"kod":"DKAB.5.1.2","metin":"Evrendeki mükemmel düzenin nasıl oluştuğu sorusu sorulur. Gerçek hayattan verilen örneklerden hareketle varlıkların mutlaka bir yaratıcıya ihtiyaç duyduğu vurgulanır. Öğrencilerden evrendeki mükemmel düzenle ilgili gözlemlerini Allah’ın (cc) varlığı ve birliği ile ilişkilendirmesi istenir. Öğrencilerin konuyla ilgili düşüncelerini değerlendirmesi (E3.10), kendisinden ve çevresinden hareket ederek insanların bir yaratıcıya ihtiyaç duyduğunu fark etmesi (SDB1.1) için öğretmen rehberliğinde bir tartışma ortamı oluşturulabilir (E3.4).Tevhit kavramı ele alınır. Öğrencilerin her şeyin Allah (cc) tarafından yaratıldığı bilgisine ulaşması sağlanır. Konuyla ilgili ayetlerden ve hadislerden öğrenci seviyesine uygun örnekler verilir.Tevhidin İslam’ın inanç esası olduğu yargısına öğrencilerin ulaşması için etkinlikler yapılabilir."},{"kod":"DKAB.5.1.3","metin":"Öğrencilere “Allah’ın (cc) güzel isimlerinden hangilerini duydunuz?” sorusu sorulur. Öğrenciler esmayıhüsnanın anlamını ve merak ettiği (E1.1, E.1.2) isimleri araştırır. Bu isimlerden başta Rahman ve Rahîm olmak üzere Alîm, Kadir, Semi ve Basir hakkında bilgi toplar. Ayetler ve hadisler yoluyla ulaştığı bilgileri doğrular ve defterine yazarak bunları kaydeder. Besmele açıklanır. Günlük hayatta besmelenin sıklıkla kullanıldığı yerler örneklendirilir. Rahman ve Rahîm isimlerinin Allah’ın (cc) yarattıklarına karşı merhametli olması anlamına geldiği vurgulanır. Etkinlikler yoluyla varlıklara şefkatli davranmanın (D9.2), insanı ve doğayı sevmenin (D9.3) gerektiğini öğrencilerin fark etmesi ve bunları davranışlarına yansıtması sağlanır (SDB1.1). Bunun için öz değerlendirme formu kullanılabilir."},{"kod":"DKAB.5.1.4","metin":"Öğrencilere “İhlas suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. İhlas kelimesinin anlamı açıklanarak İhlas suresinin içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. İhlas suresi hakkında bilgi verilirken surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. İhlas suresinin doğru telaffuzunu öğretmek için öğrencilerin genel ağ araçlarını tanımaları ve kullanmaları sağlanır. İhlas suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Günlük hayatta İhlas suresinin okunduğu yerler örneklendirilir. Öğrencilerin İhlas suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrenciler, insan vücudunun işleyişi ile Allah’ın (cc) her şeyi mükemmel şekilde yaratması arasındaki ilişkiyi araştırabilir. Allah’ın (cc) güzel isimlerinden merak edilenler belirlenerek bunlar hakkında bir sunu hazırlanabilir."],"destekleme":["Öğrencilerden Eğitim Bilişim Ağı’nda (EBA) yer alan görsel içerikleri kullanarak evrendeki mükemmel düzenle ilgili bir sınıf panosu hazırlanması istenebilir."],"ogretmenYansitmalari":[]},
{"no":2,"ad":"Namaz","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/59","odak":"Ünitenin teması ibadettir. Bu ünitede İslam’ın ibadet esasları içerisinde yer alan namaz konusu ele alınmaktadır. Öğrencilerin namaz ibadetini özetlemeleri, namaza hazırlık ve namazın kılınış şartlarını inceleyerek namazın kılınışını gözlemlemeleri, namaz ibadetinin insana kazandırdığı değerler hakkında düşünmeleri amaçlanmaktadır. Tahiyyat duasını ve bu duanın anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":18,"alanBecerileri":[],"kavramsalBeceriler":["KB2.2. Gözlemleme","KB2.3. Özetleme","KB2.14. Yorumlama","KB3.3. Eleştirel Düşünme"],"egilimler":["E1.4. Kendine İnanma (Öz Yeterlilik)","E1.5. Kendine Güvenme (Öz Güven)","E2.1. Empati","E3.2. Odaklanma","E3.7. Sistematik Olma"],"sdb":["SDB1.3. Kendine Uyarlama (Öz Yansıtma)","SDB3.2. Esneklik"],"degerler":["D3. Çalışkanlık","D12. Sabır","D15. Sevgi","D16. Sorumluluk","D18. Temizlik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık","OB4. Görsel Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.5.2.1","ad":"Namaz ibadetini özetleyebilme","surec":["a) Namaz ibadetiyle ilgili çözümleme yapar.","b) Namazı farz, vacip ve nafile olarak sınıflandırır.","c) Namaz ibadetinin önemini kendi cümleleri ile aktarır."]},{"kod":"DKAB.5.2.2","ad":"Namazın kılınışını gözlemleyebilme","surec":["a) Namazın kılınışını gözlemlemek için hazırlık ve kılınış şartlarını ölçüt olarak açıklar.","b) Namazın kılınışı hakkında öğretmen rehberliğinde bilgi toplar.","c) Namazın kılınışı hakkında topladığı bilgileri sınıflandırır ve kaydeder."]},{"kod":"DKAB.5.2.3","ad":"Namazın insan hayatına etkileri hakkında düşünebilme","surec":["a) Namazın insan hayatına etkilerini araştırır.","b) Namazın insana kazandırdıkları hakkında sonuç çıkarır.","c) Namazın insana kazandırdıkları hakkında ulaştığı çıkarımları davranışlarına yansıtır."]},{"kod":"DKAB.5.2.4","ad":"Tahiyyat duasını ve bu duanın anlamını okuyarak yorumlayabilme","surec":["a) Tahiyyat duasını ve bu duanın anlamını okur.","b) Tahiyyat duasının anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Tahiyyat duasının anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Allah’ın Huzurunda Olmak: Namaz","Namazın Kılınışı","Namazın İnsana Kazandırdıkları","Bir Dua Öğreniyorum: Tahiyyat Duası"],"anahtarKavramlar":["abdest","farz","gusül","nafile","teyemmüm","vacip"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritaları, bulmacalar (anagram, çengel, sözcük avı vb.) ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Namaz ibadeti hakkında broşür hazırlanabilir. Diyanet İşleri Başkanlığına","bağlı genel ağ adreslerinden “Namaz Kılıyorum” ve “Abdest Alıyorum” başlığı altında","yer alan kısa videolar izletilerek gözlem formu hazırlanabilir. Namazın insana kazandırdıkları","ile ilgili münazara yaptırılabilir. Tahiyyat duası ve bu duanın anlamıyla ilgili eşleştirme","etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla","değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin İslam’ın ibadet esasları hakkında bilgi sahibi olduğu, çevresinde namaz","ibadetini yerine getiren insanları gözlemleyebildiği, Kur’an-ı Kerim ve hadislerde namaz","ibadetinin açıklandığı bilgisine sahip olduğu kabul edilmektedir."],"onDegerlendirme":["Çevresindeki gözlemlerinden hareketle namaz ibadeti hakkında neler bildiği sorusu sorularak","öğrencilerin ön bilgileri harekete geçirilir ve bu soruya verdikleri cevaplara göre hazır","bulunuşlukları kontrol edilir."],"kopruKurma":["Öğrencilere “Yüce Allah’ı anmak, O’na olan sevgi ve saygımızı dile getirmek için neler yaparız?”","sorusu sorulur. Bu soru ekseninde İslam’ın ibadet esaslarına ve bu esaslar içerisinde","namaz ibadetine dikkat çekilir. Çevrelerinde namaz ibadetinin yerine getirildiğine dair gözlemleme","becerisini kullanmaları beklenir ve namaz ibadeti ile gerçek hayat arasında köprü","kurulur."],"uygulamalar":[{"kod":"DKAB.5.2.1","metin":"Öğrencilerin odaklanarak (E3.2) İslam’ın şartları arasında namazın yeri hakkında parça-bütün ilişkisini çözümlemesi istenir. Öğrencilerin Kur’an ve hadislerden yararlanarak namaz ibadetiyle ilgili bilgiler bulması ve namazın kimlere farz olduğunu araştırması sağlanır. Öğrenciler, namaz ibadetiyle ilgili elde ettikleri bilgileri öğretmenleriyle birlikte değerlendirerek doğrular ve afiş, broşür, pano, duvar gazetesi gibi yollarla kaydeder (OB1). Namaz çeşitleri; farz, vacip ve nafile şeklinde sınıflandırılarak tahtaya yazılır. Farz, vacip ve nafile namazların tanımları yapılır ve bu namaz çeşitlerine örnekler verilir. Farz, vacip ve nafile namazların kılınışı, rekât sayısı, vakti gibi ayrıntılara girilmeden bu namaz çeşitleri arasında hükümleri açısından ilişki kurulur. Namaz ibadetinin Allah’a (cc) duyulan sevgi (D15.3) ve bağlılığın göstergelerinden olduğu açıklanarak namaz hakkında bütüncül bir bakış açısı geliştirilir (OB1). Öğrencilerden namazın önemiyle ilgili duygu ve düşüncelerini kendi cümleleri ile aktarmaları istenir."},{"kod":"DKAB.5.2.2","metin":"Namazın kılınışını sistematik olarak (E3.7) gözlemlemeleri için öğrencilere “Namaz kılmaya niyetlenen bir kişi, namaza başlamadan önce neler yapar?” sorusu yöneltilir. Öğrencilerin namaz kılmak için abdest almanın bir gereklilik olduğunu fark etmeleri sağlanır (OB1). Abdestin farzları belirlenir ve alınış sırası görseller yardımıyla açıklanır. Öğrencilerin yeterliliklerinin farkında olarak (E1.4) abdest görsellerini incelemeleri, bağlamından koparmadan sözlü ifadelere dönüştürmeleri ve kişisel temizlik ve bakımına önem vermeleri (D18.1) beklenir (OB4). Konuyla ilgili ayrıntılı ilmihal bilgilerinden kaçınarak abdesti bozan durumlara örnekler verilir. Gusül ve teyemmüm konuları ise tanım ve farzlarıyla sınırlı tutularak açıklanır. Teyemmüm konusu anlatılırken öğrencilerin zor durumlara alternatif çözüm bulma ve yeni durumlara uyum sağlama becerilerini kazanmaları beklenir (SDB3.2). Öğrencilerin görev bilincine sahip olarak (D16.3) namaz ibadetinin nasıl yerine getirildiğini anlamaları için namazın hazırlık ve kılınış şartları açıklanır. Bu şartlar hakkında bilgi toplanır ve bunlar kısaca açıklanır. İki rekâtlı namazın kılınışı görseller yardımıyla anlatılır. Öğrencilerden görsellerde ifade edilen fiillerin anlamını değiştirmeyecek şekilde yeniden ifade etmeleri ve namazın kılınışını anlatmaları istenir (OB4). Beş vakit namazların rekât sayıları ve vakitleri hakkında toplanan bilgiler sınıflandırılır ve kaydedilir. Konuyla ilgili ayrıntılı ilmihal bilgilerinden kaçınarak namazı bozan durumlara örnekler verilir. Cemaatle namaz, cuma namazı, bayram namazı, teravih namazı ve cenaze namazı konularına ve bu namazların kılınışlarına ana hatlarıyla değinilir."},{"kod":"DKAB.5.2.3","metin":"Namazın insana kazandırdıkları hakkında empati kurarak (E2.1) düşünmeleri için öğrencilere “Niçin namaz kılınır?” sorusu yöneltilir ve namazın insan hayatına etkileri hakkında araştırma yapmaları sağlanır. Öğrencilerin verdiği cevaplar tahtaya yazılarak beyin fırtınası yapılır ve namaz ibadetinin insana kazandırdıklarıyla ilgili sonuçlar çıkarılır. Öğrencilerin namaz ibadetiyle ilgili duygu ve düşüncelerini değerlendirmeleri sağlanır (SDB1.3). Bu değerlendirme sonucunda öğrenciler namaz ibadetinin öz denetim sahibi (D3.2) ve istikrarlı olmayı (D12.3) sağladığı hakkında çıkarımda bulunur. Öğrencilerin bu değerleri davranışlarına yansıtmaları hedeflenir."},{"kod":"DKAB.5.2.4","metin":"Öğrencilere “Tahiyyat duası hakkında neler biliyorsunuz?” sorusu yöneltilir. Tahiyyat kelimesinin anlamı açıklanarak Tahiyyat duasının içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Tahiyyat duasının doğru telaffuzunu öğretmek için öğrencilerin genel ağ araçlarını tanımaları ve kullanmaları sağlanır. Tahiyyat duasını dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) duanın doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu duayı kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Duanın anlamı incelenir. Duanın anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak dua değerlendirilebilir. Öğrencilerin duanın anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Tahiyyat duasının anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrenciler, namaz vakitlerini belirten bir takvim veya zaman çizelgesi hazırlayabilir. İki rekâtlı bir namazın kılınışı simülasyon (benzetim) yöntemiyle sunabilir."],"destekleme":["Öğrencilerin namaz ve abdest konularını anlamalarını kolaylaştırmak amacıyla, basitleştirilmiş görsel rehberler ve adım adım izlenebilecek videolar kullanılabilir. Bu materyaller, öğrencilerin namaz kılma sürecini ve abdest alma adımlarını anlamlandırmalarına ve pratik yapmalarına yardımcı olur. Namazın anlamı ve önemi hakkında öğrencilere yönelik hikâyeler ve günlük hayattan alınan örnekler kullanılabilir."],"ogretmenYansitmalari":[]},
{"no":3,"ad":"Kur’an-ı Kerim","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/64","odak":"Ünitenin teması din ve hayattır. Bu ünitede Kur’an-ı Kerim’in tanımı, iç düzeni, temel özellikleri ve ana konuları ele alınmaktadır. Öğrencilerin Kur’an-ı Kerim’in iç düzenini çözümlemeleri, temel konuları hakkında bilgi toplamaları, ana konularını sınıflandırılmaları amaçlanmaktadır. Kevser suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.4. Çözümleme","KB2.5. Sınıflandırma","KB2.6. Bilgi Toplama","KB2.14. Yorumlama"],"egilimler":["E1.1. Merak","E1.5. Kendine Güvenme (Öz Güven)","E3.7. Sistematik Olma"],"sdb":[],"degerler":["D6. Dürüstlük","D9. Merhamet"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık","OB4. Görsel Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.5.3.1","ad":"Kur’an-ı Kerim’in iç düzenini çözümleyebilme","surec":["a) Kur’an-ı Kerim’in iç düzenini inceler.","b) Ayet, sure ve cüz arasındaki ilişkileri inceler."]},{"kod":"DKAB.5.3.2","ad":"Kur’an-ı Kerim’in temel özellikleri hakkında bilgi toplayabilme","surec":["a) Kur’an-ı Kerim’in temel özellikleri konusunu araştırır.","b) Kur’an-ı Kerim’in temel özellikleri hakkında bilgi toplar.","c) Kur’an-ı Kerim’in temel özellikleri hakkında ulaştığı bilgileri öğretmen rehberliğinde doğrular.","ç) Kur’an-ı Kerim’in temel özellikleri hakkında ulaştığı bilgileri kaydeder."]},{"kod":"DKAB.5.3.3","ad":"Kuran-ı Kerim’in ana konularını sınıflandırabilme","surec":["a) Kur’an-ı Kerim’i, hayatı tüm yönleriyle ele alan bir ölçüt olarak kabul eder.","b) Kur’an-ı Kerim’in ana konularını bölümlere ayırır.","c) Kur’an-ı Kerim’in ana konularını tasnif eder.","ç) Kur’an-ı Kerim’in ana konularını listeler."]},{"kod":"DKAB.5.3.4","ad":"Kevser suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Kevser suresini ve bu surenin anlamını okur.","b) Kevser suresinin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Kevser suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Kur’an-ı Kerim’in İç Düzeni","Kur’an-ı Kerim’in Temel Özellikleri","Kur’an-ı Kerim’in Ana Konuları","Bir Sure Öğreniyorum: Kevser Suresi"],"anahtarKavramlar":["ayet","cüz","kıssa","sure"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritaları, bulmacalar (anagram, çengel, sözcük avı vb.) ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Kur’an-ı Kerim’in iç düzeniyle ilgili poster hazırlanabilir. Kur’an-ı Kerim’in temel özellikleri hakkında çalışma yaprağı hazırlanabilir. Kur’an-ı Kerim’in ana konuları hakkında çalışma yaprağı hazırlanabilir. Kevser suresi ve bu surenin anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin çevrelerinde Kur’an-ı Kerim okuyan insanları gözlemledikleri kabul edilmektedir."],"onDegerlendirme":["Tahtaya “Kur’an-ı Kerim denildiği zaman aklınıza neler geliyor?” sorusu yazılarak öğrencilerin ön bilgileri harekete geçirilir ve bu soruya verdikleri cevaplara göre hazır bulunuşlukları kontrol edilir."],"kopruKurma":["Öğrencilere “Kur’an-ı Kerim’i birkaç cümleyle nasıl anlatırsınız?” sorusu sorulur. Bu soru ekseninde Kur’an-ı Kerim’in ilahi bir kitap olduğuna dikkat çekilerek öğrencilerin çıkarım yapma becerisini kullanmaları beklenir. Çevrelerinde Kur’an-ı Kerim okuyan insanları gözlemledikleri düşünülerek Kur’an-ı Kerim ile gerçek hayat arasında ilişki kurulur."],"uygulamalar":[{"kod":"DKAB.5.3.1","metin":"Öğrencilerin Kur’an-ı Kerim’in iç düzenini merak ederek (E1.1) çözümlemeleri için Kur’an-ı Kerim görseli verilir ve bu görseli tanımaları sağlanır (OB4). Kur’an-ı Kerim’in iç düzeniyle ilgili ayet, sure ve cüz kavramları belirlenir. Kur’an-ı Kerim’in iç sayfalarından görseller verilerek ayet, sure ve cüz kavramları hakkında bilgi verilir. Öğrencilerin ayet, sure ve cüz kavramları arasındaki parça-bütün ilişkisini belirlemeleri istenir."},{"kod":"DKAB.5.3.2","metin":"Öğrencilerin Kur’an-ı Kerim’in temel özellikleri hakkında sistematik olarak (E3.7) bilgi toplamaları için onlara “Kur’an-ı Kerim hakkında neler biliyorsunuz?” sorusu yöneltilir. Kur’an-ı Kerim’in temel özellikleri hakkında ayet ve hadisler belirlenir. Öğrencilerin belirlenen ayet ve hadislerden yararlanarak Kur’an-ı Kerim’in temel özellikleri hakkında bilgi toplaması sağlanır. “Kur’an-ı Kerim’in temel özellikleri çözümlenir ve bu özellikler; iyiye, doğruya ve güzele yönlendirmesi, kötülüklerden sakındırması, yol göstermesi, açıklayıcı olması, insanları düşünmeye ve aklını kullanmaya yöneltmesi şeklinde listelenir (OB1). Öğrencilere vicdanlı (D9.1), doğru ve güvenilir (D6.2) olmak hakkında bilinç kazandırılır. Dürüstlük ve merhametle ilişkili ayet örnekleri verilir. Bu ayetlerden hareketle örnek olaylar verilerek öğrencilerin sınıfta fikir paylaşımında bulunmaları sağlanır. Öğrenciler, Kur’an-ı Kerim’in temel özellikleriyle ilgili elde ettikleri bilgileri öğretmenleriyle birlikte değerlendirerek doğrular ve afiş, broşür, pano, duvar gazetesi gibi yollarla kaydeder."},{"kod":"DKAB.5.3.3","metin":"Öğrencilerin Kur’an-ı Kerim’in ana konularını sınıflandırmaları için onlara “Kur’an-ı Kerim’in ana konuları hakkında neler biliyorsunuz?” sorusu yöneltilir ve öğrencilerden Kur’an-ı Kerim’in ana konularını yorumlamaları istenir (OB1). Kur’an-ı Kerim’i bireysel ve toplumsal hayatı tüm yönleriyle ele alan ilahi bir kitap olarak açıklaması sağlanır. Kur’an-ı Kerim’in ana konuları bölümlere ayrılarak tasnif edilir. İnanç, ibadet, ahlak, sosyal hayat ve kıssalar olarak listelenir. İnanç, ibadet, ahlak, sosyal hayat ve kıssalar Kur’an’ın ana konuları olarak ayrıntıya girilmeksizin açıklanır."},{"kod":"DKAB.5.3.4","metin":"Öğrencilere “Kevser suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Kevser suresinin içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Kevser kelimesinin bolluk, bereket ve neslin çoğalması anlamlarına geldiğinden bahsedilir. Allah’ın (cc) Hz. Peygamber’e pek çok nimet verdiğine, bu nimetlerden birinin de Hz. Peygamber’in neslini devam ettiren Hz. Fatıma (ra) olduğuna değinilir. Kevser suresi hakkında bilgi verilirken surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Kevser suresinin doğru telaffuzunu öğretmek için öğrencilerin genel ağ araçlarını tanımaları ve kullanmaları sağlanır. Kevser suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Kevser suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrenciler, Kur’an-ı Kerim’in temel özellikleri ve ana konuları hakkında infografik (bilgi grafiği) hazırlayabilir. Ünitede öğrenilen konular bağlamında Kur’an-ı Kerim bülteni veya panosu hazırlayabilir."],"destekleme":["Öğrencilerin ilgisini çekecek ve konuyu anlamalarını kolaylaştıracak hikâyeler, görsel materyaller ve etkileşimli dijital uygulamalar kullanılabilir."],"ogretmenYansitmalari":[]},
{"no":4,"ad":"Peygamber Kıssaları","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/70","odak":"Bu ünitenin teması Kur’an ve peygamberdir. Ünitede peygamber kıssaları ele alınmaktadır. Öğrencilerin peygamberlik hakkında akıl yürütmeleri; Hz. Nuh, Hz. İbrahim, Hz. Musa ve Hz. İsa’nın kıssalarını sentezlemeleri amaçlanmaktadır. Kureyş suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":12,"alanBecerileri":[],"kavramsalBeceriler":["KB2.14. Yorumlama","KB2.16.2. Tümdengelime Dayalı Akıl Yürütme","KB2.20. Sentezleme"],"egilimler":["E1.5. Kendine Güvenme (Öz Güven)","E3.4. Gerçeği Arama"],"sdb":[],"degerler":["D3. Çalışkanlık","D11. Özgürlük","D12. Sabır","D16. Sorumluluk"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.5.4.1","ad":"Peygamberlik hakkında akıl yürütebilme","surec":["a) Peygamberlerin görevlerini araştırır.","b) Peygamberlerin görevleri ile örnek olmaları arasında parça - bütün ilişkisi kurar.","c) Peygamberlerin görevleriyle ilgili çıkarım yapar."]},{"kod":"DKAB.5.4.2","ad":"Peygamber kıssalarında verilen öğütleri sentezleyebilme","surec":["a) Peygamber kıssalarında verilen öğütleri inceler.","b) Peygamber kıssalarında verilen öğütler arasında ilişki kurar.","c) Peygamber kıssalarında verilen öğütleri birleştirerek bunlar hakkında özgün bir bütün oluşturur."]},{"kod":"DKAB.5.4.3","ad":"Kureyş suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Kureyş suresini ve bu surenin anlamını okur.","b) Kureyş suresinin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Kureyş suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Allah’ın Elçileri: Peygamberler","Kur’an-ı Kerim’den Öğütler: Peygamber Kıssaları","Bir Sure Öğreniyorum: Kureyş Suresi"],"anahtarKavramlar":["davet","ülülazm"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Peygamberler ve peygamberlerin görevleriyle ilgili farklı metinler okunarak ilkeler çıkarılabilir. Peygamber kıssaları ile ilgili çalışma yaprağı hazırlanabilir. Kureyş suresi ve bu surenin anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin Kuran-ı Kerim’de peygamber kıssalarına yer verildiğini bildikleri kabul edilmektedir."],"onDegerlendirme":["Öğrencilerin peygamber kıssalarıyla ilgili hazır bulunuşluklarını tespit etmek üzere hangi peygamberler hakkında bilgi sahibi oldukları sorulur."],"kopruKurma":["Geçmişte yaşamış insanların ve peygamberlerin hayatlarından ders çıkarılması bağlamında peygamber kıssalarıyla günümüzdeki örnekler arasında bağlantı kurulur."],"uygulamalar":[{"kod":"DKAB.5.4.1","metin":"Peygamberlere duyulan ihtiyacı fark etmeleri için öğrencilere “Allah (cc) peygamber göndermeseydi ne olurdu?” sorusu sorulur. Verilen cevaplardan hareketle peygamberlere niçin ihtiyaç duyulduğu açıklanır. Peygamberlerin, Allah’ın (cc) mesajlarını insanlara iletmek için gönderilen elçiler olduğu fark ettirilir. Peygamberlerin görevlerinin neler olabileceği sorularak beyin fırtınası yaptırılır ve öğrencilerden gerçeği bulma arzusuyla (E3.4) bilgilerini gözden geçirerek cevap vermeleri istenir. Verilen cevaplar doğrultusunda peygamberlerin görevleri belirlenir. Peygamberlerin görevleri ile örnek olmaları arasında ilişki kurulur. Peygamberlerin hangi konularda insanlara örnek olduğu ayrıntıya girilmeden açıklanır. Konuyla ilgili ayet veya hadislere yer verilir. Dünya ve ahiret mutluluğu için peygamberleri örnek almanın gerekliliğine değinilir. Öğrencilerden peygamberlerin niçin gönderildiğiyle ilgili çıkarım yapması istenir. Öğrencilerin çıkarımlarını kısa ve akılda kalıcı cümleler ile ifade etmeleri ve kaydetmeleri sağlanır."},{"kod":"DKAB.5.4.2","metin":"Öğrencilere “kıssadan hisse çıkarmak” tabirinin anlamı açıklanarak Kuran’daki peygamber kıssalarına dikkat çekilir. Kıssaların amacına kısaca değinilir. Davet kavramı açıklanarak kıssaların konusunun peygamberlerin İslam’a daveti olduğu vurgulanır. Tevhit mücadelesi esnasında gösterdikleri sabır nedeniyle Kuran’da övülen ülülazm peygamberlere değinilir. Hz. Nuh kıssası Yunus, Hud ve Nuh surelerindeki ilgili ayetler kapsamında; Hz. İbrahim kıssası Enbiya suresi çerçevesinde; Hz. Musa kıssası Araf, Taha ve Kasas surelerindeki ayetler bağlamında; Hz. İsa kıssası Al-i İmran, Maide ve Meryem surelerindeki ilgili ayetlerle ilişkilendirilerek öğrenci seviyesine uygun şekilde ele alınır. Bu kıssalardan çıkarılabilecek öğütler belirlenir. Peygamberlerin tevhide daveti, gösterdiği mucizeler, yaşadığı zorluklar, gönderildiği toplumlara yaptığı uyarılar bakımından kıssalar arasında ilişki kurulur. Hz. Nuh’un tevhit mücadelesindeki azim ve kararlılığına (D3.1) ; Hz. İbrahim’in içinde yaşadığı toplumu tevhide daveti esnasında gösterdiği cesaret ve kararlılığına (D11.1, D11.2) ; Hz. Musa’nın bir peygamber ve lider olarak görevini özveriyle yerine getirmesine (D16.3) ve Hz. İsa’nın toplumunu doğru yola davet ederken gösterdiği sabır ve sebata (D12.3) dikkat çekilir. Ayet ve hadislerden hareketle Hz. Meryem’in ahlaki yönüne değinilir. Öğrencilerin kıssalardaki öğüt ve değerleri dikkate alarak bir hikâye yazması veya afiş, poster gibi içerikler hazırlaması sağlanır."},{"kod":"DKAB.5.4.3","metin":"Öğrencilere “Kureyş suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Hz. Muhammed’in (sav) mensup olduğu kabilenin surede ismi geçen Kureyş kabilesi olduğuna dikkat çekilir. Kureyş hakkında ayrıntıya girilmeden bilgi verilir. Kureyş suresinin nerelerde okunduğuna değinilir ve içerdiği mesajlar açıklanır. Kureyş suresi hakkında bilgi verilirken surenin Mekki- Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Kureyş suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Kureyş suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilerden seçtiği bir peygamber kıssasını gerekli unsurları ekleyerek çocuk kitabına dönüştürmesi istenebilir."],"destekleme":["Derste anlatılan her bir peygamber kıssası için kıssada öne çıkan bir olayın resmedildiği görseller hazırlanır. Öğrencilerin görselle ilgili peygamber kıssasını eşleştirmesi istenebilir."],"ogretmenYansitmalari":[]},
{"no":5,"ad":"Mimarimizde Dinî Motifler","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/71","odak":"Bu ünitenin teması kültürdür. Ünitede mimarimizde dinî motifler ele alınmaktadır. Öğrencilerin dinin mimariye etkisini çözümlemeleri, camilerin iç ve dış bölümlerini sınıflandırmaları ve kültürümüzde yer alan cami örneklerini karşılaştırmaları amaçlanmaktadır.","dersSaati":10,"alanBecerileri":[],"kavramsalBeceriler":["KB2.4. Çözümleme","KB2.5. Sınıflandırma","KB2.7. Karşılaştırma"],"egilimler":["E3.4. Gerçeği Arama","E3.6. Analitik Düşünme"],"sdb":["SDB1.3. Kendine Uyarlama (Öz Yansıtma)"],"degerler":["D7. Estetik","D14. Saygı"],"okuryazarlik":["OB4. Görsel Okuryazarlık","OB5. Kültür Okuryazarlığı","OB9. Sanat Okuryazarlığı"],"disiplinlerArasi":"Görsel Sanatlar","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.5.5.1","ad":"Dinin mimarimize etkisini çözümleyebilme","surec":["a) Dinin mimariye etki ettiği hususları araştırır.","b) Dinin mimariye etki ettiği hususlar arasındaki ilişkiyi inceler."]},{"kod":"DKAB.5.5.2","ad":"Camilerin bölümlerini tanıyabilme","surec":["a) Camilerin bölümleri ile ilgili ölçüt belirler.","b) Camilerin bölümlerini ayrıştırır.","c) Camilerin bölümlerini iç ve dış olarak tasnif eder.","ç) Camilerin iç ve dış bölümlerini listeler."]},{"kod":"DKAB.5.5.3","ad":"Kültürümüzde yer alan cami örneklerini karşılaştırabilme","surec":["a) Kültürümüzde yer alan cami örneklerinin özelliklerini araştırır.","b) Kültürümüzde yer alan cami örneklerinin benzer özelliklerini listeler.","c) Kültürümüzde yer alan cami örneklerinin farklı özelliklerini listeler."]}],"icerikCercevesi":["Dinin Mimarimize Etkisi","Camileri Tanıyalım","Kültürümüzden Cami Örnekleri"],"anahtarKavramlar":["cami","mescit","mimari"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, bulmacalar (anagram, çengel, sözcük avı vb.), görsel eşleştirme kartları ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Dinin mimarimize etkisini örnek yapılar üzerinden ele alan poster, broşür, afiş vb. hazırlanabilir. Caminin bölümlerini içeren çalışma yaprağı hazırlanabilir. Kültürümüzden cami örnekleriyle ilgili görseller kullanılarak sunu hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin çevrelerindeki mimari eserleri gözlemlediği ve camilerde ibadet edildiğini bildiği kabul edilmektedir."],"onDegerlendirme":["Öğrencilerin kültürümüzde önemli yere sahip mimarları ve bunların eserlerini araştırmaları sağlanarak ön hazırlık yapılır."],"kopruKurma":["Öğrencilerin camileri gözlemlemeleri sağlanarak dinî mimari ile gerçek hayat arasında ilişki kurması sağlanır."],"uygulamalar":[{"kod":"DKAB.5.5.1","metin":"Dijital öğrenme platformları aracılığıyla çeşitli bölgelerden cami, çeşme, medrese, külliye, kervansaray gibi mimari eserler gösterilir. Mimarinin kültürel bir unsur olduğunu ve dinin mimarimize etkisini fark etmeleri için bu örneklerle ilgili öğrencilere sorular sorulur (E3.4, OB5). Öğretmen rehberliğinde öğrencilerin dinin mimariye etki ettiği hususları araştırması sağlanır. Öğrenciler bu hususlar arasında ilişki kurar. Bu eserlerde kullanılan hat, tezhip, çini, minyatür gibi sanatlar belirlenir. Bu eserlerin yapılış amaçları, sanatların hangi duygularla ortaya çıkarıldıkları anlatılarak din, sanat ve mimari arasında ilişki kurulur.Bu ilişkiden hareketle öğrencilerin konuyu tartışmaları sağlanır (E3.6)."},{"kod":"DKAB.5.5.2","metin":"Cami ve mescit kavramları çerçevesinde Müslümanlar açısından caminin önemine değinilir. Öğrencilerden konuyla ilgili özgün görseller oluşturmaları ve bunları sınıfta paylaşmaları istenir (OB4).Teravih, cuma, bayram ve cenaze namazlarının toplumsal hayattaki işlevi hatırlatılır. Cemaatle ibadet etmenin ve camide ibadet edenlere saygı duymanın önemi, etkinlikler yoluyla öğrencilere fark ettirilir (SDB1.3, D14.3). Öğrencilerin caminin iç ve dış bölümlerini gözlemlemesi sağlanır. Öğrencilerden mihrap, minber, vaaz kürsüsü, minare, şerefe, şadırvan, kubbe gibi mimari unsurları belirlemesi istenir. Öğrenciler belirledikleri bu unsurları caminin iç ve dış bölümleri olarak ayrıştırır ve bunları tasnif eder. Mihrap, minber, vaaz kürsüsünü caminin iç bölümü; şerefe, şadırvan, kubbeyi de caminin dış bölümü olarak listeler."},{"kod":"DKAB.5.5.3","metin":"İslam kültüründe öne çıkan cami örnekleri (Mescid-i Nebevi ve Mescid-i Aksa vb.) listelenir. Bunların özelliklerine ve Müslümanlar açısından önemine değinilir. Mescid-i Aksa anlatılırken ayrıntıya girilmeden Hz. Süleyman kıssasına yer verilir. Bu şekilde öğrencilerin kültürel mirasın önemini fark etmesi ve bunlara değer vermesi sağlanır. Kültürümüzde yer alan camilere örnekler verirken Türkiye’nin çeşitli bölgelerinden kültürel, sanatsal ve mimari açıdan öne çıkmış farklı camiler belirlenir. Öğrenciler, belirlenen cami örnekleri üzerine araştırma yapar. Öğretmen rehberliğinde bu camilerin benzer ve farklı özelliklerini listeler. Sanatsal ve görsel zevkleri hayatlarının bir parçası hâline getirmeleri için (D7.3) öğrencilere hat, ebru, çini, taş ve ahşap oymacılığı gibi sanatlarla ilgili örnekler gösterilir. Öğrencilerden bu sanatları içeren eserleri incelemeleri ve yorumlamaları istenir (OB9). Bunun için öğretmen rehberliğinde etkinlikler yapılabilir."}],"zenginlestirme":["Öğrencilerden farklı mimari eserleri inceleyerek bunlar hakkında belgesel hazırlaması istenebilir. Görsel sanatlar dersinde öğrendikleri bilgiler kullanılarak öğrencilere farklı cami tasarımları yaptırılabilir. Dijital platformlar aracılığıyla cami ziyareti yaptırılabilir."],"destekleme":["Öğrencilerden dinin etkisiyle yapılan mimari eserlerin görselleri inceleyerek bu eserlerin yapılış amaçlarının anlatıldığı bir sunu hazırlaması istenebilir."],"ogretmenYansitmalari":[]}],"s6":[{"no":1,"ad":"Peygamber ve İlahi Kitap İnancı","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/73","odak":"Bu ünitenin teması inançtır. Ünitede İslam’ın temel esaslarından peygamber ve ilahi kitap inancı konusu ele alınmaktadır. Öğrencilerin; peygamberlerin görevleri ve özellikleri hakkında bilgi toplamaları, peygamberlerin insanlara örnek olması ve vahyin gönderiliş amacı konularını yapılandırmaları, ilahi kitaplar ve bu kitapların indirildiği peygamberler hakkındaki bilgileri çözümlemeleri amaçlanmaktadır. Felak suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":16,"alanBecerileri":[],"kavramsalBeceriler":["KB2.4. Çözümleme","KB2.6. Bilgi Toplama","KB2.13. Yapılandırma","KB2.14. Yorumlama"],"egilimler":["E1.1. Merak","E1.5. Kendine Güvenme (Öz Güven)","E3.7. Sistematik Olma","E3.8. Soru Sorma"],"sdb":["SDB1.1. Kendini Tanıma (Öz Farkındalık)"],"degerler":["D14. Saygı"],"okuryazarlik":["OB2. Dijital okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.6.1.1","ad":"Peygamberlerin insanlara rehber olarak gönderilmesi hakkında bilgi toplayabilme","surec":["a) Peygamber inancı konusunu araştırır.","b) Peygamber inancıyla ilgili bilgileri bulur.","c) Peygamber inancıyla ilgili ulaştığı bilgileri öğretmen rehberliğinde doğrular.","ç) Peygamber inancıyla ilgili ulaştığı bilgileri kaydeder."]},{"kod":"DKAB.6.1.2","ad":"Vahiylerin insanlara ilettiği mesajları yapılandırabilme","surec":["a) Vahyin gönderiliş amacıyla ilgili nedensel ilişkiler ortaya koyar.","b) Vahyin gönderiliş amacıyla ilgili nedensel ilişkilere dayalı unsurlardan hareketle uyumlu bir bakış açısı geliştirir."]},{"kod":"DKAB.6.1.3","ad":"İlahi kitaplarla ilgili bilgileri çözümleyebilme","surec":["a) Temel İslam kaynaklarından hareketle ilahi kitapların Tevrat, Zebur, İncil ve Kur’an-ı Kerim olduğunu öğretmen rehberliğinde açıklar.","b) İlahi kitaplar arasındaki kronolojik ilişkiyi inceler."]},{"kod":"DKAB.6.1.4","ad":"Felak suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Felak suresini ve bu surenin anlamını okur.","b) Felak suresinin anlamını kendi hayatı için anlamlı hâle getirir.","c) Felak suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["İnsanlara Rehber: Peygamber","Peygamberlerin İlettiği Mesaj: Vahiy","İlahi Kitaplar","Bir Sure Öğreniyorum: Felak Suresi"],"anahtarKavramlar":["nübüvvet","risalet","tebliğ","vahiy"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Peygamberlerin insanlara rehber olarak gönderilmesiyle ilgili bir sunu hazırlanabilir. Vahyin hayata yansımalarıyla ilgili bir panel hazırlanabilir. İlahi kitapların isimlerinin ve hangi peygamberlere gönderildiğinin belirtildiği bir kavram haritasının oluşturulması istenebilir. Felak suresi ve bu surenin anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin İslam’ın inanç esasları hakkında temel düzeyde bilgi sahibi olduğu, Kur’an-ı Kerim’de ve hadislerde inanç konusuyla ilgili bilgilerin yer aldığını bildiği kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Hangi peygamberleri ve ilahi kitapları biliyorsunuz?” sorusu yöneltilerek hazır bulunuşlukları tespit edilir."],"kopruKurma":["Öğrencilerin 5. sınıf “Peygamber Kıssaları” ünitesinde öğrendiği bilgiler ile yeni öğreneceği bilgiler arasında bağlantı kurması sağlanır."],"uygulamalar":[{"kod":"DKAB.6.1.1","metin":"Öğrencilerin bilme ve anlama ihtiyacına yönelik keşfetme arzusu harekete geçirilerek peygamber ve ilahi kitap inancıyla ilgili sorular sormaları sağlanır (E3.8). Konuyla ilişkili sorular tahtaya yazılır ve öğrencilerin kendilerini ifade etmelerine imkân tanınır. Peygamber, vahiy, tebliğ, nübüvvet, risalet kavramları ele alınır. Öğrencilerin Kur’an-ı Kerim’de adı geçen peygamberlere örnekler vermesi, peygamberlerin görevlerini ve özelliklerini öğretmen rehberliğinde bulması sağlanır. Peygamberlerin insanlar için bir kılavuz olduğu açıklanarak peygamberliğin insanlık için bir gereklilik olduğuna vurgu yapılır. Öğrencilerin seviyeleri dikkate alınarak mucize konusuna kısaca yer verilir. Öğretmen rehberliğinde öğrencilerin konu ile ilgili kaynaklardan elde ettiği bilgileri ayet ve hadislerden yararlanarak doğrulamaları ve defterlerine yazmaları sağlanır."},{"kod":"DKAB.6.1.2","metin":"Öğrencilere, vahiy yoluyla insanlara iletilen mesajlarla ilgili merak uyandıracak sorular sorulur (E1.1). Peygamberlerin insanlar arasından seçilmesi, insanlara örnek olması ve vahyin gönderiliş amacı arasında nedensel ilişkiler kurulur. Öğrencilerin bunları kendi hayatına aktararak mantıksal bir bütün oluşturması ve bir yol göstericiye duyulan ihtiyacı fark etmesi sağlanır (SDB1.1). Bunun için öğretmen rehberliğinde etkinlikler yapılabilir."},{"kod":"DKAB.6.1.3","metin":"Öğrencilere ilahi kitapların önemi ve değeri açıklanır. Onların manevi değerlere saygılı (D14.3) olmaları sağlanır. Temel İslam kaynaklarından hareketle ilahi kitapların Tevrat, Zebur, İncil ve Kur’an-ı Kerim olduğu öğretmen rehberliğinde açıklanır. Bu kitapların gönderildiği peygamberler hakkında bilgi verilir. Kur’an-ı Kerim’in son ilahi kitap, Hz. Muhammed’in (sav) de son peygamber olduğu anlatılır. Bu sayede öğrencilerin sistematik olarak (E3.7) ilahi kitaplar arasında kronolojik ilişki kurması sağlanır."},{"kod":"DKAB.6.1.4","metin":"Öğrencilere “Felak suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Felak kelimesinin anlamı açıklanarak Felak suresinin içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Felak suresi hakkında bilgi verilirken surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Felak suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Felak suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilerden peygamberlerin özelliklerini ve görevlerini içeren bir bilgi grafiği hazırlamaları istenebilir.","Kutsal kitapların gönderildiği peygamberlerin karşılaştıkları güçlüklere çözümleri ile öğrencilerin yaşadıkları güçlüklere kendi çözüm yaklaşımlarını karşılaştırmalı olarak incelemeleri istenebilir."],"destekleme":["Öğrencilere peygamberler ve ilahi kitaplar hakkında görsel ve etkileşimli materyaller sunulabilir."],"ogretmenYansitmalari":[]},
{"no":2,"ad":"Ramazan ve Oruç","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/75","odak":"Bu ünitenin teması ibadettir. Ünitede, ramazan ayı ve oruç ibadeti ele alınmaktadır. Öğrencilerin ramazan ayının oruç ve Kur’an ayı olduğunu çözümlemeleri, oruç ibadeti ve önemi ile ilgili bilgi toplamaları, oruç ibadetinin bireye ve topluma kazandırdıklarını yapılandırmaları amaçlanmaktadır. İftar duasını ve bu duanın anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.4. Çözümleme","KB2.6. Bilgi Toplama","KB2.13. Yapılandırma","KB2.14. Yorumlama"],"egilimler":["E1.1. Merak","E1.5. Kendine Güvenme (Öz Güven)"],"sdb":["SDB1.3. Kendine Uyarlama (Öz Yansıtma)"],"degerler":["D12. Sabır","D20. Yardımseverlik"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Sosyal Bilgiler","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.6.2.1","ad":"Ramazan ayının oruç ve Kur’an ayı olduğunu çözümleyebilme","surec":["a) Temel İslam kaynaklarından hareketle ramazan ayını oruç ve Kur’an ayı olarak öğretmen rehberliğinde açıklar.","b) Ramazan ayı ile oruç ve Kur’an okuma ibadeti arasındaki ilişkiyi inceler."]},{"kod":"DKAB.6.2.2","ad":"Oruç ibadeti hakkında bilgi toplayabilme","surec":["a) Oruç ibadeti konusunu araştırır.","b) Oruç ibadeti hakkında bilgiler bulur.","c) Oruç ibadeti hakkında elde ettiği bilgileri öğretmen rehberliğinde doğrular.","ç) Oruç ibadeti hakkında elde ettiği bilgileri kaydeder."]},{"kod":"DKAB.6.2.3","ad":"Oruç ibadetinin insana kazandırdıklarını yapılandırabilme","surec":["a) Oruç ibadetinin insana kazandırdıklarını inceleyerek mantıksal ilişkiler kurar.","b) Oruç ibadetinin insana kazandırdıkları hakkında kendi elde ettiği bilgilerden hareketle uyumlu bir bakış açısı geliştirir."]},{"kod":"DKAB.6.2.4","ad":"İftar duasını ve bu duanın anlamını okuyarak yorumlayabilme","surec":["a) İftar duasını ve bu duanın anlamını okur.","b) İftar duasının anlamını kendi hayatı için anlamlı hâle getirir.","c) İftar duasının anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Oruç ve Kur’an Ayı Ramazan","Oruç İbadeti","Oruç İbadetinin İnsana Kazandırdıkları","Bir Dua Öğreniyorum: İftar Duası"],"anahtarKavramlar":["fitre","iftar","imsak","mukabele","oruç","ramazan","sahur","teravih"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası, öz değerlendirme formu kullanılabilir.","Performans Görevi:","Oruç ve Kur’an ayı olarak ramazan hakkında sunu hazırlanabilir. Ramazan ve oruç ibadetiyle ilgili kavramların yer aldığı kavram haritası hazırlanabilir. Oruç ibadetinin insana kazandırdıklarının değerlendirildiği bir panel hazırlanabilir. İftar duası ve bu duanın anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin ramazan ayında oruç ibadetini yerine getiren insanları gözlemledikleri, Kur’an-ı Kerim ve hadislerde oruç ibadetiyle ilgili bilgilerin yer aldığını bildikleri kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “İslam’ın ibadet esasları nelerdir?” sorusu yöneltilir. Verilen cevaplardan yola çıkılarak öğrencilerin ön bilgisi harekete geçirilir."],"kopruKurma":["Öğrencilerin ramazan ayında gözlemlediklerinden hareketle oruç ibadeti ile gerçek hayat arasında bağlantı kurulur."],"uygulamalar":[{"kod":"DKAB.6.2.1","metin":"Öğrencilerin konuyla ilgili merakını (E1.1) uyandıracak çeşitli etkinlikler planlanır. Bu kapsamda Eğitim Bilişim Ağı’ndan (EBA) ramazan ayı ile ilgili videolar izletilir. Öncelikle ramazan ayının Müslümanlar için önemine ve değerine yer verilir. Ramazan ayının oruç ayı olduğu ve Müslümanların bu ayda farz olan oruç ibadetini yerine getirdikleri anlatılır. Ramazan ayının Kur’an ayı olduğuna vurgu yapılır ve Kadir Gecesi’nin önemine değinilir. Temel İslam kaynaklarından hareketle öğrencilerin ramazan ayını oruç ve Kur’an ayı olarak öğretmen rehberliğinde açıklaması sağlanır. Öğrencilerden öğrendiklerini kendi cümleleriyle yorumlaması istenir (OB1). Ramazan ayı ile oruç ve Kur’an okuma ibadeti arasındaki ilişki incelenir. Böylece öğrenciler ramazan ayını diğer aylardan ayıran özellikler arasında ilişki kurar."},{"kod":"DKAB.6.2.2","metin":"İslam’ın ibadet esasları arasında oruç ibadetinin yeri ve önemi ile orucun kimlere farz olduğu hakkında öğrencilerin bilgi toplaması sağlanır. Sahur, imsak, iftar, teravih, mukabele ve fitre kavramları açıklanır. Konuyla ilgili ayrıntılı ilmihal bilgilerinden kaçınılarak oruçlunun dikkat etmesi gereken hususlara, orucu bozan ve bozmayan durumlara örnekler verilir. Öğrenci seviyesi göz önünde bulundurularak farz, vacip, sünnet olan oruç çeşitlerine kısaca değinilir. Öğrencilerden öğrendiği kavramlar arasındaki ilişkileri belirleyip bunlarla oruç ibadeti arasında ilişki kurmaları istenir. Oruçla ilgili kavramlar hakkında elde edilen bilgileri, öğrenciler öğretmen rehberliğinde doğrulayıp defterlerine kaydederler."},{"kod":"DKAB.6.2.3","metin":"Orucun insana kazandırdıkları konusunda öğrencilere “Niçin oruç tutulur?” sorusu sorularak beyin fırtınası yaptırılır. Verilen cevaplardan yola çıkılarak öğrencilerden oruç ibadetinin insana kazandırdıklarıyla ilgili mantıksal bir ilişki kurmaları istenir. Oruçlu insanın duygu, düşünce ve davranışlarını kontrol ederek sabırlı olması (D12.2) ve bu hususta istikrarlı olmasının (D12.3) önemi vurgulanır. İftar davetleri, fitre ve sadakanın yardımseverlik (D20.3), cömertlik (D20.1), dayanışma (D20.2) gibi ahlaki özelliklerin kazanılmasına katkıda bulunduğu fark ettirilir. Öğrencilerin oruç ibadetiyle ilgili duygu ve düşüncelerini değerlendirerek oruç ibadetinin insana kazandırdıkları hakkında çıkarımda bulunması sağlanır (SDB1.3)."},{"kod":"DKAB.6.2.4","metin":"Öğrencilere “İftar duası hakkında neler biliyorsunuz?” sorusu yöneltilir. İftar kelimesinin anlamı açıklanarak iftar duasının içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. İftar duasını dinlemek üzere Eğitim Bilişim Ağı’ndan (EBA) uygun içerikler belirlenir. Öğrencilerin bu adresi kullanmaları sağlanarak (OB2) duanın doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu duayı kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Duanın anlamı incelenir. Duanın anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak dua değerlendirilebilir. Öğrencilerin duanın anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin iftar duasının anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilerden oruç ibadetinin insana kazandırdıkları konulu bir röportaj yapmaları istenebilir. Ramazan ve oruçla ilgili kavramlar hakkında öğrencilerin oyun tasarlamaları istenebilir. Ramazan ayında diğer aylardan farklı olan şeylerle ilgili gözlem yaparak bununla ilgili bir ödev hazırlayabilir."],"destekleme":["Oruç ve ramazan ayı ile ilgili bilgileri gerçek hayat tecrübeleriyle ilişkilendirmeleri için öğrencilerden kendi tecrübelerini sınıfta paylaşmaları istenebilir."],"ogretmenYansitmalari":[]},
{"no":3,"ad":"Ahlaki Davranışlar","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/79","odak":"Bu ünitenin teması din ve hayattır. Ünitede ahlaki davranışlar ele alınmaktadır. Öğrencilerin; doğru sözlü olmayı kendi hayatlarına yansıtmaları, merhametli olmanın bireysel ve toplumsal faydalarını yorumlamaları, adap ve nezaket kurallarını özetlemeleri, vatanı sevmenin önemi hakkında çıkarım yapmaları amaçlanmaktadır. Kunut dualarını ve bu duaların anlamlarını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":12,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.10. Çıkarım Yapma","KB2.14. Yorumlama","KB2.15. Yansıtma"],"egilimler":["E1.5. Kendine Güvenme (Öz Güven)","E3.11. Özgün Düşünme"],"sdb":["SDB1.1. Kendini Tanıma (Öz Farkındalık)","SDB1.3. Kendine Uyarlama (Öz Yansıtma)"],"degerler":["D4. Dostluk","D6. Dürüstlük","D9. Merhamet","D14. Saygı","D15. Sevgi","D16. Sorumluluk","D19. Vatanseverlik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Sosyal Bilgiler","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.6.3.1","ad":"Doğru sözlü olmayı kendi hayatına yansıtabilme","surec":["a) Doğru sözlü olmanın önemini kendisinden ve çevresinden hareketle gözden geçirir.","b) Doğru sözlü olmanın bireysel ve toplumsal açıdan önemine dair çıkarımda bulunur.","c) Doğru sözlü olmanın önemiyle ilgili ulaştığı çıkarımları değerlendirir."]},{"kod":"DKAB.6.3.2","ad":"Merhametli olmayı yorumlayabilme","surec":["a) Merhametli olmanın bireysel ve toplumsal boyutlarını inceler.","b) Merhametli olmayı kendi hayatı için anlamlı hâle getirir.","c) Merhametli olmanın önemini kendi cümleleriyle yeniden ifade eder."]},{"kod":"DKAB.6.3.3","ad":"Adap ve nezaket kurallarını özetleyebilme","surec":["a) Adap ve nezaket kurallarını çözümler.","b) Adap ve nezaket kurallarını sınıflandırır.","c) Adap ve nezaket kurallarını yorumlar."]},{"kod":"DKAB.6.3.4","ad":"Vatanını sevmenin önemi hakkında çıkarım yapabilme","surec":["a) Vatanını sevmenin önemi hakkında mevcut bilgisi dâhilinde varsayımda bulunur.","b) Vatan sevgisiyle ilişkili kavramları listeler.","c) Vatan sevgisiyle ilişkili kavramları birbirleriyle ilişkisi açısından karşılaştırır.","ç) Vatan sevgisinin önemi hakkında önermeler sunar.","d) Vatan sevgisinin önemi hakkında önermelerle ilgili değerlendirmede bulunur."]},{"kod":"DKAB.6.3.5","ad":"Kunut dualarını ve bu duaların anlamlarını okuyarak yorumlayabilme","surec":["a) Kunut dualarını ve bu duaların anlamlarını okur.","b) Kunut dualarının anlamlarını kendi hayatı için anlamlı hâle getirir.","c) Kunut dualarının anlamlarını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Doğru Sözlü Olmak","Merhametli Olmak","Adap ve Nezaket Kurallarına Uymak","Vatanımızı Sevmek","Bir Dua Öğreniyorum: Kunut Duaları"],"anahtarKavramlar":["adap","dürüstlük","gazi","merhamet","şehit","vatan"],"olcmeDegerlendirme":["Bu ünitede ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, kelime ilişkilendirme, çalışma yaprağı, kavram haritası, neden sonuç diyagramı (balık kılçığı), yapılandırılmış grid ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Doğru sözlü olmanın önemi hakkında bir sunu hazırlanabilir. Merhametli olmanın bireysel ve toplumsal faydalarını anlatan bir drama-canlandırma etkinliği de yaptırılabilir. Toplumsal hayatta adap ve nezaket kurallarına uymanın önemiyle ilgili drama çalışması hazırlanabilir. Vatan sevgisi ile ilgili kavramları kullanarak örnek olay/kişi üzerinden sunu hazırlanabilir. Kunut duaları ve bu duaların anlamlarıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulabilir.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin, insanların birbirine karşı toplumsal sorumluluklarının olduğunu, ahlaki davranışların toplumdaki önemini ve değerini bildiği kabul edilmektedir."],"onDegerlendirme":["Öğrencilere, “Bir arada yaşamak için gereken ahlaki davranışlar nelerdir?” sorusu sorulur. Verilen cevaplar çerçevesinde, sınıfta bir tartışma ortamı oluşturularak öğrencilerin hazır bulunuşluk seviyeleri ölçülür."],"kopruKurma":["Öğrencilerin çevrelerinde gözlemlediği olumlu ve olumsuz davranışlar karşılaştırılarak ahlaki davranışlar ile günlük hayat arasında ilişki kurulur."],"uygulamalar":[{"kod":"DKAB.6.3.1","metin":"Öğrencilere doğru sözlü olmanın gerekliliği hakkında sorular sorulur. Verilen cevaplar listelenir. Doğru sözlü olmayı kendi hayatına yansıtabilmeleri için dürüstlük (D6.2) ve dostluk (D4.3) değerleri ele alınır.Davranışlar üzerinden bu değerler arasındaki ilişki açıklanır. Bu değerlerin İslam dinindeki yeri ve önemi ayet ve hadisler ışığında açıklanır. Bu konu hakkında öğrencilerin kendi görüşlerini ifade etmelerine fırsat verilir. Öğrencilerin doğru sözlü olmanın önemini kendisinden ve çevresinden hareketle gözden geçirmesi sağlanır. Öğrencilerden doğru sözlü olmanın bireysel ve toplumsal açıdan önemine dair çıkarımda bulunmak üzere grup çalışması yürütmeleri istenir. Her bir grubun ulaştığı sonuçlar, diğer gruplar tarafından değerlendirilir. Yapılan değerlendirmede ulaşılan sonuçlar öğretmen tarafından bir araya getirilir ve öğrenciler tarafından kaydedilir. Doğru sözlü olmanın insanlar arasındaki iletişim ve etkileşime katkıda bulunduğu sonucuna ulaşılarak öğrencilerin bu konudaki duygu, düşünce ve davranışlarını değerlendirmeleri beklenir (SDB1.3). Hz. Şuayb kıssası üzerinden öğrencilerin doğruluk ve dürüstlük değerlerini (D6.2) kavraması sağlanır. Kıssada yer alan hadiseler, ahlaki davranışlar kapsamında değerlendirilerek öğrencilere dürüstlük değeri kazandırılır."},{"kod":"DKAB.6.3.2","metin":"Öğrencilere Eğitim Bilişim Ağı’ndan (EBA) merhametli olmanın önemini anlatan dijital içerikler izletilir. Merhametli olmanın birey ve topluma yansımaları hakkında sorular sorularak öğrencilere beyin fırtınası yaptırılır. Vicdanlı ve şefkatli olmanın, insanı, doğayı ve hayvanları sevmenin merhametle bağlantısı vurgulanır (D9.3). Böylece merhamet ve sevgi (D15.1) arasında ilişki kurulur. Allah’ın (cc) adil, merhametli ve affedici olması ile Hz. Muhammed’in (sav) merhametli ve affedici oluşuna ayet ve hadislerden örnekler verilir. Öğrencilerden merhametli olmanın bireysel ve toplumsal boyutlarını fark edebilecekleri bir örnek olay bulmaları, özgün bir yaklaşımla (E3.11) bunu incelemeleri ve sınıfta sunmaları istenir. Öğrencilerden merhametli olmayı kendi yaşantılarında uyguladıklarına dair örnekler vermeleri istenir. Öğrencilerin merhametli olmanın önemini kendi cümleleriyle yeniden ifade edebildikleri bir afiş çalışması yapmaları sağlanır."},{"kod":"DKAB.6.3.3","metin":"Adap ve nezaket kurallarıyla ilgili günlük hayattan örnek olaylar incelenir. Örnek olaylardan hareketle toplumda bu kurallara neden ihtiyaç duyulduğu, nezaketli olmanın önemi (D14.1) ve bu kurallara uymanın her insanın sorumluluğu olduğu (D16.3) fark ettirilir. Adap ve nezaket kavramları tanımlanır. Günlük hayattan farklı örnekler verilerek bu kurallar çözümlenir. Toplumda bu kurallara uymanın neden önemli olduğuna dair beyin fırtınası yaptırılır. Öğrencilerin düşüncelerini kısa ve akılda kalıcı cümlelerle ifade etmeleri ve kaydetmeleri sağlanır. Adap ve nezaket kuralları selamlaşma adabı, iletişim ve konuşma adabı, sofra adabı olarak sınıflandırılır. Selamlaşmanın İslam dinindeki yeri, toplumsal birlik ve beraberliğe katkısı ayet ve hadislerle açıklanır. İletişim ve konuşma adabıyla ilgili olarak doğru sözlü olmak, açık ve anlaşılır ifadeler kullanmak, nazik bir üsluba sahip olmanın önemine dikkat çekilir. Sosyal medya ve internette de nezaket kurallarına uymak gerektiği ve mahremiyete dikkat etmenin önemi vurgulanır. Öğrencilere yemek yerken nelere dikkat ettikleri sorularak sofra adabıyla ilgili kurallar fark ettirilir. Sofra adabına dair Hz. Muhammed’in (sav) tavsiyelerine ve ayetlere yer verilir. Öğrencilerin selamlaşma, konuşma ve sofra adabıyla ilgili öğrendiklerinden hareketle nezaket kurallarını kendi cümleleriyle ifade edebileceği etkinlikler yapılır."},{"kod":"DKAB.6.3.4","metin":"Vatanını sevmenin (D19.1) önemi hakkında öğrencilerin vatanımıza, milletimize, bayrağımıza ve millî marşımıza karşı görev ve sorumluluklarımız olduğunu fark etmeleri sağlanır (OB1). Vatan sevgisiyle ilişkili vatan, millet, bayrak, şehitlik ve gazilik kavramları listelenir. Bu kavramlar Kuzey Kıbrıs Türk Cumhuriyeti bağlamında da özel olarak örneklendirilir ve vurgulanır. İlgili kavramların millî birlik ve beraberliğe katkısı karşılaştırılır. Konuyla ilgili olarak Çanakkale zaferine, İstiklal savaşına, 15 Temmuz Demokrasi ve Millî Birlik Günü’ne değinilir. Edindiği bilgilerden hareketle öğrencilerin vatan sevgisinin önemi hakkında önermeler sunmaları ve bunları değerlendirmeleri sağlanır. Vatanın bağımsızlığını korumak, vatanı geliştirmek ve güzelleştirmek için neler yapılabileceği bağlamında duygularını fark etmeleri sağlanır (SDB1.1). Bu amaçla savunma sanayinde yerli firmaların millî imkanlarla geliştirdiği ürün ve projelerin araştırılmasını içeren etkinlik yaptırılabilir."},{"kod":"DKAB.6.3.5","metin":"Öğrencilere “Kunut duaları hakkında neler biliyorsunuz?” sorusu yöneltilir. Kunut kelimesinin anlamı açıklanarak Kunut dualarının içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Kunut dualarını dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) duaların doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu duaları kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Duaların anlamı incelenir. Duaların anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak dualar değerlendirilebilir. Öğrencilerin duaların anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Kunut dualarının anlamlarını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilere şehit yakınlarıyla veya gazilerle vatan sevgisi hakkında röportaj yaptırılabilir. Doğru sözlü olmanın önemi hakkında hikâye yazdırılabilir. Ahlaki davranışlar sergileyen ve bunun aksi davranışlarda bulunan iki kişinin özelliklerini belirten drama hazırlatılabilir."],"destekleme":["Doğru sözlülük, merhamet, sorumluluk ve vatan sevgisi değerlerinin anlamını kavramaları için öğrencilere kısa animasyonlar izlettirilebilir."],"ogretmenYansitmalari":[]},
{"no":4,"ad":"Peygamberliğinden Önce Hz. Muhammed","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/88","odak":"Bu ünitenin teması Kur’an ve peygamberdir. Ünitede Hz. Muhammed’in (sav) doğduğu çevre, çocukluğu, gençliği ve ailesiyle ilgili konular tarihsel bağlamda ele alınmaktadır. Öğrencilerin; Hz. Muhammed’in (sav) doğumu ve çocukluk yıllarını yorumlamaları, Hz. Muhammed’in (sav) gençlik yıllarını yapılandırmaları amaçlanmaktadır. Fil suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":14,"alanBecerileri":["SBAB3. Tarihsel Empati (KB2.13. Yapılandırma","SBAB3.1. Tarihsel Bağlamsallaştırma","KB2.14. Yorumlama)"],"kavramsalBeceriler":["KB2.14. Yorumlama"],"egilimler":["E1.1. Merak","E1.5. Kendine Güvenme (Öz Güven)","E2.4. Güven","E3.1. Uzmanlaşma","E3.2. Odaklanma","E3.8. Soru Sorma"],"sdb":[],"degerler":["D1. Adalet","D6. Dürüstlük"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Sosyal Bilgiler","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.6.4.1","ad":"Hz. Muhammed’in (sav) doğduğu çevreyi tarihsel bağlamda değerlendirebilme","surec":["a) Hz. Muhammed’in (sav) doğduğu çevre hakkındaki bilgileri temel kaynaklardan hareketle farkeder.","b) Hz. Muhammed’in (sav) doğduğu çevreyi koşulları içerisinde açıklar.","c) Hz. Muhammed’in (sav) doğduğu çevrenin koşullarını analiz eder.","ç) Hz. Muhammed’in (sav) doğduğu çevrenin koşullarını günümüz koşullarıyla karşılaştırır."]},{"kod":"DKAB.6.4.2","ad":"Hz. Muhammed’in (sav) çocukluk yılları hakkında verilen bilgileri yorumlayabilme","surec":["a) Hz. Muhammed’in (sav) çocukluk yıllarında yaşadıklarını inceler.","b) Hz. Muhammed’in (sav) çocukluk yıllarında yaşadıklarını kendi ifadeleriyle, doğru ve bilgiyi değiştirmeyecek şekilde yeniden ifade eder."]},{"kod":"DKAB.6.4.3","ad":"Hz. Muhammed’in (sav) gençlik yılları hakkında verilen bilgileri yapılandırabilme","surec":["a) Hz. Muhammed’in (sav) gençlik yıllarında yaşadıklarından hareketle çıkarımda bulunur.","b) Hz. Muhammed’in (sav) gençlik yıllarına dair öğrendikleri üzerine düşüncelerini ifade eder."]},{"kod":"DKAB.6.4.4","ad":"Fil suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Fil suresini ve bu surenin anlamını okur.","b) Fil suresinin anlamını kendi hayatı için anlamlı hâle getirir.","c)Fil suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Hz. Muhammed’in (sav) Doğduğu Çevre","Hz. Muhammed’in (sav) Ailesi ve Çocukluğu","Hz. Muhammed’in (sav) Gençlik Yılları","Bir Sure Öğreniyorum: Fil Suresi"],"anahtarKavramlar":["Cahiliye Dönemi","emin","Kâbe","Hilfülfudul"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Hz. Muhammed’in (sav) doğduğu çevrenin şartları ile ilgili bir çalışma yaprağı hazırlanabilir. Hz. Muhammed’in (sav) çocukluk yıllarının anlatıldığı bir sunu hazırlanabilir. Hz. Muhammed’in (sav) gençlik yıllarında yaşadıkları ile ahlaki davranışlarını ele alan bir panel hazırlanabilir. Fil suresi ve bu surenin anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin temel tarih ve kronoloji algısına sahip olduğu kabul edilir. Peygamberlik ve peygamber inancı konularında bilgi sahibi olduğu kabul edilir."],"onDegerlendirme":["Öğrencilere “Hz. Muhammed’in (sav) hayatı hakkında neler biliyorsunuz?” sorusu yöneltilerek öğrencilerin ön bilgileri harekete geçirilir ve bu soruya verdikleri cevaplara göre hazır bulunuşlukları kontrol edilir."],"kopruKurma":["Öğrencilere “Hz. Muhammed’in (sav) hayatını öğrenmek neden önemlidir?” sorusu yöneltilir. Gelen cevaplardan hareketle Hz. Muhammed’in (sav) insanlara örneklik teşkil etmesi üzerinde durulur. Hz. Muhammed’in (sav) hayatındaki ahlaki davranışlar ile öğrencilerin gerçek hayatı arasında ilişki kurmaları sağlanır."],"uygulamalar":[{"kod":"DKAB.6.4.1","metin":"Öğrencilere “Hz. Muhammed’in (sav) doğduğu zaman ve mekâna gitseydiniz orada neler görürdünüz?” sorusu yöneltilerek öğrencilerin merakını (E1.1) uyandıracak sorular sorulur. Hz. Muhammed’in (sav) doğduğu çevreye dair dinî, siyasi, sosyal ve ekonomik ortam anlatılır. Öğrencilerden Hz. Muhammed’in (sav) doğduğu çevre hakkındaki bilgileri temel kaynaklardan fark etmesi sağlanır. Cahiliye Dönemi’nin özelliklerinden bahsedilerek Kâbe’nin toplumdaki konumu vurgulanır. Öğrencilerin Hz. Muhammed’in (sav) doğduğu çevreyi koşulları içerisinde açıklaması ve toplumdaki ahlaki yanlışları fark etmesi sağlanır. Öğrenciler Hz. Muhammed’in (sav) doğduğu çevrenin temel özelliklerine odaklanarak (E3.2) o dönemin koşullarını analiz eder. Öğrencilerin elde ettiği bilgiler çerçevesinde dönemin koşullarını dinî, siyasi, sosyal ve ekonomik açılardan uzmanlaşarak (E3.1) karşılaştırması için öğrencilere grup çalışması yaptırılabilir."},{"kod":"DKAB.6.4.2","metin":"Öğrenciler; Hz. Muhammed’in (sav) doğumu, sütanneye verilmesi ve aile büyükleriyle ilgili merak ettikleri soruları sormaları için teşvik edilir (E3.8). Hz. Muhammed’in (sav) doğumu ve çocukluk yılları anlatılır. Aile fertlerinden bahsedilir. Hz. Muhammed’in (sav) aile fertleriyle ilişkisi örnekler üzerinden ele alınır. Öğrencilerin Hz. Muhammed’in (sav) çevresine karşı saygılı, çalışkan ve yardımsever olduğunu doğru ve anlamı değiştirmeyecek şekilde yeniden ifade etmesi sağlanır. Bunun için öğretmen rehberliğinde yazma etkinliği yaptırılabilir."},{"kod":"DKAB.6.4.3","metin":"Hz. Muhammed’in (sav) gençlik dönemi incelenir. Hz. Muhammed’in (sav) Hilfülfudul’a katılması, Kâbe hakemliği ve Hz. Hatice ile evliliği hakkında bilgi verilir. Emin kavramı ele alınır. Güven (E2.4) eğilimini harekete geçirmek için öğrencilerin emin kavramıyla Hz. Muhammed’e (sav) “el-emin” denmesi arasındaki ilişki açıklanır. Hacerülesved’in yerleşimi konusunda genç yaşında olmasına rağmen Hz. Muhammed’e (sav) görev verilmesinin sebepleri üzerinde durulur. Hz. Muhammed’in (sav) gençlik yıllarında sahip olduğu ahlak anlatılırken onun adaletli (D1.2), doğru ve güvenilir (D6.2) olduğu vurgulanır. Öğrencilerin Hz. Muhammed’in (sav) gençlik yıllarından hareketle örnekliği hakkında çıkarımda bulunması istenir. Öğrenciler, Hz. Muhammed’in (sav) gençlik yılları hakkında yaptığı çıkarımları kendi cümleleri ile ifade ettikleri bir metin hazırlar. Öğrenciler oluşturdukları metni, öz güvenlerini pekiştirmek üzere (E1.5) gönüllülük esasına dayanarak sınıf içerisinde sunar. Böylece Hz. Muhammed’in (sav) gençlik yıllarında sahip olduğu ahlaki özelliklerle ön plana çıktığını fark eder. Öğrencilerden konuyla ilgili öz değerlendirme formu kullanmaları ve elde ettikleri çıkarımları paylaşmaları istenir. Ayrıca Hz. Muhammed’in örnek davranışlarıyla ilişki kurarak Hz. Muhammed (sav) ve Hz. Hatice’nin çocukları hakkında bilgi verilir. Hz. Muhammed’in (sav) aile içi iletişimine ve aile bireyleri arasındaki örnek davranışlarına değinilir."},{"kod":"DKAB.6.4.4","metin":"Öğrencilere “Fil suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Fil suresinin anlamı açıklanarak Fil suresinin içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Fil olayına kısaca değinilir. Fil suresi hakkında bilgi verilirken surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Fil suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Fil suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrenciler, Hz. Muhammed’in (sav) peygamberliğinden önce yaşadıkları hakkında panel düzenleyebilir."],"destekleme":["Hz. Muhammed’in (sav) doğumu, doğduğu çevre, çocukluk ve gençlik yıllarıyla ilgili görsel ve işitsel materyaller kullanılır."],"ogretmenYansitmalari":[]},
{"no":5,"ad":"Kültürümüzdeki Dinî Motifler","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/90","odak":"Bu ünitenin teması kültürdür. Ünitede dinin kültüre etkisi ele alınmaktadır. Öğrencilerin gelenek, edebiyat ve musikide dinin etkilerini özetlemeleri amaçlanmaktadır.","dersSaati":12,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme"],"egilimler":["E1.1. Merak","E1.5. Kendine Güvenme (Öz Güven)","E3.3. Özgün Düşünme"],"sdb":["SDB1.1. Kendini Tanıma (Öz Farkındalık)"],"degerler":["D7. Estetik","D16. Sorumluluk","D20. Yardımseverlik"],"okuryazarlik":["OB5. Kültür Okuryazarlığı","OB9. Sanat Okuryazarlığı"],"disiplinlerArasi":"Türkçe, Sosyal Bilgiler, Müzik","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.6.5.1","ad":"Geleneğimizde, edebiyatımızda ve musikimizde dinin izlerini özetleyebilme","surec":["a) Geleneğimizde, edebiyatımızda ve musikimizde dinin izleriyle ilgili çözümleme yapar.","b) Din ve kültür ilişkisini gelenek, edebiyat ve musiki örneklerinden hareketle sınıflandırır.","c) Dinin geleneğimiz, edebiyatımız ve musikimize etkisini yorumlar."]}],"icerikCercevesi":["Geleneğimizde Dinin İzleri","Edebiyatımızda Dinin İzleri","Musikimizde Dinin İzleri"],"anahtarKavramlar":["ezan","ilahi","kültür","mahya","mevlit","salavat"],"olcmeDegerlendirme":["Bu ünitede ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Geleneğimiz, edebiyatımız ve musikimizde dinin izlerini yansıtan örnekler hakkında sunu hazırlanabilir. İçinde dinî ögelerin yer aldığı geleneksel bir drama örneği hazırlatılabilir. Performans görevleri ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin dinin kültüre etki ettiğini bildiği kabul edilir."],"onDegerlendirme":["Öğrencilere “Geleneklerimiz hakkında neler biliyorsunuz?” gibi sorular sorularak ön bilgi düzeyleri kontrol edilir."],"kopruKurma":["“Kültürümüzde din, hangi alanları etkilemiştir?” sorusu sorularak 5. Sınıf “Mimarimizde Dinî Motifler” ünitesiyle bağlantı kurulur."],"uygulamalar":[{"kod":"DKAB.6.5.1","metin":"Öğrencilerin merak duygusunu (E1.1) harekete geçirmek için “Kültürü oluşturan kavramlar nelerdir?” sorusu yöneltilir ve onlardan öz güvenli (E1.5) olarak cevap vermesi beklenir. Örf, âdet, musiki ve edebiyat kavramları açıklanır, örnekler verilir. Öğrencilerin sosyal çevrelerinden, kaynak kitaplardan ya da dijital kaynaklardan yararlanarak dinin kültüre etkisini araştırmaları ve çeşitli örnekler bulmaları istenir. Dinin etkilediği unsurlar ve bu unsurlar arasındaki ilişkiler belirlenerek çözümlemeler yapılır. Dinî bayramlar, kandil geceleri, yardımlaşma gelenekleri, edebiyat ve musiki gibi konularda örnekler verilir. Öğrencilerin bu örnekleri alanlarına göre sınıflandırması beklenir. Hz. Muhammed (sav) ve Ehlibeyt sevgisinin toplumumuzu birleştirmedeki rolüne yer verilir. Konuyla ilgili örnekler içerisindeki dinî ögeler tespit edilerek din ve kültür etkileşimi vurgulanır. Kültürel unsurların toplumda çeşitli değerlerin pekiştirilmesine katkıda bulunduğuna değinilir. Öğrencilerin kültürel unsurlar içerisindeki dinî ögeleri inceleyerek toplumun kültürel mirasına değer vermenin önemini anlamaları ve bu mirasın korunması hususunda duyarlılık kazanmaları amaçlanır. Kültürü sürdürme amacıyla çeşitli etkinliklere katılmanın önemi vurgulanarak kültür okuryazarlığının kazandırılması (OB5) hedeflenir. Toplumumuzda yaygın olan dinî içeriğe sahip geleneklerden mevlit, isim koyma, kız isteme, sünnet, taziye, asker uğurlama örnekleri verilerek din ve kültür etkileşimi vurgulanır. Mukabele okuma, tekne orucu, diş kirası, mahya asma, Hırkayışerif ziyaretleri gibi ramazan geleneklerinin yanı sıra muharrem ayı ve aşure günü gibi oruçla ilgili diğer uygulamalara yer verilir. Sadaka taşı, zimem defteri ve vakıf faaliyetlerinden bahsedilerek dayanışmanın ve fedakârlık göstermenin önemi vurgulanır. Bu sayede öğrencilere yardımseverlik (D20.4) davranışının kazandırılması hedeflenir. Öğrenciler topluma karşı görevlerini yerine getirmek amacı ile sorumluluk (D16.2) davranışına sahip olur. Dinin geleneğimizdeki izlerinin aktarımında sosyal bilgiler dersinden yararlanılır. Öğrencilerin dinin edebiyat üzerindeki etkisini fark etmesi amacıyla Ahmed Yesevi, Mevlana, Hacı Bektaş Veli, Yunus Emre gibi kişilerin eserlerinden onların seviyesine uygun çeşitli örnekler verilir (OB9). Sınıf ortamında öğrencilerin dikkatlerini toplamak ve meraklarını (E1.1) uyandırmak amacıyla dijital platformlardan çeşitli dinî musiki parçaları dinletilir. Ezan, kamet, ilahi, salavat gibi musiki türlerinden bahsedilir. Bu türlerin işlediği ortak dinî temalar üzerinde durulur. Bu türler vasıtasıyla çeşitli duyguların ifade edildiği fark ettirilir. Öğrencilerin eserleri tecrübe etmesi esnasında hissettiği duyguları fark etmesine (SDB1.1) yönelik çalışmalar yapılır. Dinin edebiyatımızdaki izlerinin aktarımında Türkçe dersinden, musikimizdeki izlerinin aktarımında ise müzik dersinden yararlanılır. Dinî musiki ve edebiyat örneklerinin incelenmesi öğrencilere duyusal derinliği anlama (D7.1) kabiliyeti kazandırır. Sanatsal zevklerin hayatın bir parçası hâline getirilmesi (D7.3) hedeflenir. Böylece öğrencilerde estetik (D7.1) değerinin geliştirilmesine katkıda bulunulur. Öğrenciler; özgün düşünmeyi (E3.3) güçlendirmek amacıyla farklı türlerde edebî yazılar üretme, geleneğimizi yansıtan çeşitli drama etkinlikleri yapma ve dijital ortamlardan faydalanarak çeşitli dinî musiki örnekleri paylaşma konularında teşvik edilir. Öğrenciler bütün bu örneklerin ışığında dinin kültürümüze etkisini ve bu kültürü korumanın önemini kendi cümleleri ile ifade eder."}],"zenginlestirme":["Öğrencilerden bir dinî musiki örneğini sınıfta arkadaşlarına sunması istenebilir. Öğrencilere dinî bir tema örneği (tevhit, peygamber sevgisi vb.) verilerek öğrencilerden çeşitli edebî türlerde eser üretmeleri istenebilir. Dinî konuların yer aldığı şiirlerden bir dinleti hazırlanabilir. Bu dinleti dinî musiki ögeleriyle desteklenebilir."],"destekleme":["Küçük gruplara ayrılan öğrencilerin dinle ilişkilendirilmiş eserleri incelemeleri sağlanabilir. Dinin gelenek, edebiyat ve musikimizdeki izlerini aktarırken resimler, müzik örnekleri ve video gösterimleri gibi görsel ve işitsel materyaller kullanabilir."],"ogretmenYansitmalari":[]}],"s7":[{"no":1,"ad":"Melek ve Ahiret İnancı","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/119","odak":"Ünitenin teması inançtır. Bu ünitede İslam’ın inanç esasları arasında yer alan melek ve ahiret inancı ele alınmaktadır. Öğrencilerin; Allah’ın (cc) yarattığı varlıklar arasından melekleri sınıflandırmaları, ahiret hayatının aşamalarını çözümlemeleri, melek ve ahiret inancının insan davranışına etkisi hakkında düşünmeleri amaçlanmaktadır. Nâs suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":16,"alanBecerileri":[],"kavramsalBeceriler":["KB2.4. Çözümleme","KB2.5 Sınıflandırma","KB2.14. Yorumlama","KB3.3. Eleştirel Düşünme"],"egilimler":["E1.1. Merak","E1.5. Kendine Güvenme (Öz Güven)","E3.7. Sistematik Olma","E3.8. Soru Sorma"],"sdb":["SDB1.2.Kendini Düzenleme (Öz Düzenleme)"],"degerler":["D16. Sorumluluk"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.7.1.1","ad":"Melekleri sınıflandırabilme","surec":["a) Görülen ve görülemeyen varlıkları öğretmen rehberliğinde araştırır.","b) Temel İslam kaynaklarından hareketle meleklerin yaratılan diğer varlıklardan farklı özelliklerini ayrıştırır.","c) Melekleri ve onların görevlerini listeler."]},{"kod":"DKAB.7.1.2","ad":"Ahiret hayatının aşamalarını çözümleyebilme","surec":["a) Ahiret hayatının aşamalarına ilişkin unsurları inceler.","b) Ahiret hayatının aşamalarına ilişkin unsurlar arasındaki ilişkileri açıklar."]},{"kod":"DKAB.7.1.3","ad":"Melek ve ahiret inancının insan davranışına etkisi hakkında düşünebilme","surec":["a) Melek ve ahiret inancının insan davranışına etkisini inceler.","b) Melek ve ahiret inancının insan davranışına etkisiyle ilgili sonuç çıkarır.","c) Melek ve ahiret inancının insan davranışına etkisiyle ilgili ulaştığı çıkarımları davranışlarına yansıtır."]},{"kod":"DKAB.7.1.4","ad":"Nâs suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Nâs suresini ve bu surenin anlamını okur.","b) Nâs suresinin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Nâs suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Varlıklar Âlemi","Dünya ve Ahiret Hayatı","Melek ve Ahiret İnancının İnsan Davranışına Etkileri","Bir Sure Öğreniyorum: Nâs Suresi"],"anahtarKavramlar":["ahiret","âlem","gayb","kıyamet","melek"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası, sınıflandırma tablosu ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Melekleri özellikleri ve görevlerini içeren sınıflandırma tablosu hazırlanabilir. Ahiret hayatı hakkında çalışma yaprağı hazırlanabilir. Melek ve ahiret inancının insana kazandırdıklarıyla ilgili bir metin okutularak öğrencilerden ilkeler çıkarmaları istenebilir. Nâs suresi ve bu surenin anlamını içeren eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin İslam’ın inanç esasları hakkında bilgi sahibi olduğu kabul edilmektedir. Kur’an-ı Kerim’de ve hadislerde, öğrencilerin melek ve ahiret inancının yer aldığı bilgisine sahip olduğu kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “İslam’ın inanç esasları nelerdir?” sorusu sorularak onların ön bilgi düzeyleri kontrol edilir. Öğrencilerin verdiği cevaplar alınır. “Melekler hakkında neler biliyorsunuz?” ve “Ahiret hayatı hakkında neler biliyorsunuz?” soruları öğrencilere sorularak onların hazır bulunuşluk seviyeleri belirlenir."],"kopruKurma":["Öğrencilerde farkındalık oluşturmak için çevremizdeki bazı varlıkların duyularla algılanamayacağına dikkat çekilir ve bunlarla ilgili örnekler verilir. Yaratılmış bazı varlıkları göremediğimiz veya duyamadığımız vurgulanarak görülen ve görülemeyen varlıklar konusunda mevcut bilgiler ile yeni bilgiler ilişkilendirilir."],"uygulamalar":[{"kod":"DKAB.7.1.1","metin":"Öğrencilerden varlıklar âlemini, görülen ve görülemeyen şeklinde belirlemeleri istenir. Görülemeyen varlıklar melek, cin ve şeytan şeklinde ayrıştırılarak melek kavramı açıklanır ve özellikleri listelenir. Cin ve şeytan ayrıntıya girilmeden açıklanarak gaybın yalnızca Allah (cc) tarafından bilinebileceği belirtilir. Öğrencilerin meleklerin diğer görülemeyen varlıklardan ayrılan özelliklerini fark etmeleri sağlanır. Tahtada melekler ve görevlerini içeren bir sınıflandırma tablosu oluşturulur (E3.7). Ayet ve hadislerden hareketle melekler dört büyük melek, Kiramen Kâtibin (yazıcı melekler), Münker ve Nekir (sorgu melekleri) olarak sınıflandırılır ve bunların görevleri açıklanır. Öğrencilerden edindikleri bilgiler ışığında melekleri, görevlerine göre ayırarak listelemeleri beklenir. Bakara ve Araf surelerindeki ilgili ayetler çerçevesinde Hz. Âdem kıssasına değinilir."},{"kod":"DKAB.7.1.2","metin":"Öğrencilerde merak uyandırmak için (E1.1) öğrencilere “Ahiret denildiğinde aklınıza neler gelir?” sorusu sorulur. Ayet ve hadislerden yararlanarak ahiret hayatına ilişkin ömür, ecel, kıyamet, baas, mahşer, amel defteri, mizan, cennet ve cehennem kavramlarının incelenmesi sağlanır. Bahsi geçen kavramlar açıklanır ve konu İsrafil meleği ile ilişkilendirilerek anlatılır. Ahiret hayatının aşamaları açıklanarak öğrencilerden merak ettikleri soruları sormaları (E3.8) istenir. Ahiret hayatının aşamaları arasındaki ilişki açıklanır. Öğrencilerin sorumluluklarını yerine getirmelerini ve seçimlerini ahlaki açıdan değerlendirmelerini sağlamak amacıyla Rad suresinin 22-24. ayetlerinden yararlanılarak ahiret hayatının dünya hayatında yapılanların karşılığı olduğu bilgisi öğrencilere aktarılır (D16.3). Bu sayede öğrencilerin dünya hayatı ile cennet ve cehennem arasında bir ilişki olduğunu fark etmeleri, ahiret hayatının önemini kavramaları sağlanır. Ahiret inancı ile Allah’ın (cc) adil, merhametli ve affedici olması ilişkilendirilir. Öğrencilerin konuyla ilgili örnekler vermesi sağlanır."},{"kod":"DKAB.7.1.3","metin":"Öğrencilere “Meleklere iman eden bir insan nasıl davranmalıdır?” ve “Ahiret hayatında yaptıklarının hesabını Allah’a (cc) vereceğine inanan biri nasıl davranışlar sergilemelidir?” soruları yöneltilerek öğrencilerin konu ile ilgili düşünmeleri sağlanır. Bunun için öğrencilerden melek ve ahiret inancının insana kazandırdıkları konusunda çıkarımlarda bulunmaları istenir. Meleklerin varlığının insanların davranışlarını düzenleme konusunda motivasyon oluşturduğu bilgisi verilir. Ahiret inancının insanların hayatlarına anlam kattığı ve bu sayede davranışlarını düzenlemeleri konusunda teşvik edici olduğu aktarılır. Öğrencilerin görev ve sorumluluklarını yerine getirmesi ve davranışlarını olumlu yönde düzenlemesi gerektiği fark ettirilir (D16.3), böylece kendi davranışlarını değerlendirerek kendini yönetmesi sağlanır (SDB1.2)."},{"kod":"DKAB.7.1.4","metin":"Öğrencilere “Nâs suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Nâs kelimesinin anlamı açıklanarak Nâs suresinin içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Nâs suresi hakkında bilgi verilirken surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Nâs suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Nâs suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilerden melek ve ahiret inancının insana kazandırdıkları konulu röportaj, araştırma veya sunum yapmaları istenebilir."],"destekleme":["Öğrencilerden dört büyük meleği görevleriyle listelemesi istenebilir. Ahiret inancıyla ilgili kavramlardan oluşan sözcük avı hazırlanabilir."],"ogretmenYansitmalari":[]},
{"no":2,"ad":"Hac, Umre ve Kurban","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/120","odak":"Bu ünitenin teması ibadettir. Ünitede hac, umre ve kurban ibadetleri ele alınmaktadır. Öğrencilerin; hacla ilgili kavramlar ve mekânlar hakkında bilgi toplamaları, bu ibadetleri çözümlemeleri, kurbanı Allah’a (cc) yakınlaşma ve yardımlaşma ibadeti olarak tanımlamaları, bu ibadetin kazandırdığı değerleri yapılandırmaları, gözlemlerinden yola çıkarak haccın ve kurbanın kültürümüze yansımaları hakkında tahminde bulunmaları amaçlanmaktadır. Kâfirun suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.4. Çözümleme","KB2.11. Gözleme Dayalı Tahmin Etme","KB2.13. Yapılandırma","KB2.14. Yorumlama"],"egilimler":["E1.5. Kendine Güvenme (Öz Güven)","E2.1. Empati","E3.2. Odaklanma","E3.7. Sistematik Olma"],"sdb":["SDB1.1. Kendini Tanıma (Öz Farkındalık)","SDB1.3. Kendine Uyarlama (Öz Yansıtma)"],"degerler":["D4. Dostluk","D10. Mütevazılık","D12. Sabır","D16. Sorumluluk","D18. Temizlik","D20. Yardımseverlik"],"okuryazarlik":["OB2. Dijital Okuryazarlık","OB4. Görsel Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.7.2.1","ad":"Hac ve umre ibadetlerini inceleyebilme","surec":["a) Temel İslam kaynaklarından hareketle hac ve umre ibadetleriyle ilgili unsurları inceler.","b) Hac ve umre ibadetleriyle ilgili unsurlar arasındaki ilişkileri bulur."]},{"kod":"DKAB.7.2.2","ad":"Kurban ibadetini yapılandırabilme","surec":["a) Kurban ibadetiyle Hz. İsmail kıssası arasında nedensel ilişki ortaya koyar.","b) Kurban ibadeti hakkında temel İslam kaynaklarından elde ettiği bilgilerden hareketle uyumlu bir bakış açısı geliştirir."]},{"kod":"DKAB.7.2.3","ad":"Hac ve kurban ibadetinin kültürümüze yansımalarını gözleme dayalı tahmin edebilme","surec":["a) Hac ve kurban ibadetlerinin kültürümüze yansımasına ilişkin ön gözlem veya tecrübelerini ilişkilendirir.","b) Hac ve kurban ibadetlerinin kültürümüze yansımasına ilişkin çıkarımlar yapar.","c) Hac ve kurban ibadetlerinin kültürümüze yansımasına ilişkin sonuç çıkarır."]},{"kod":"DKAB.7.2.4","ad":"Kâfirun suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Kâfirun suresini ve bu surenin anlamını okur.","b) Kâfirun suresinin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Kâfirun suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Hac ve Umre İbadeti","Kurban İbadeti","Hac ve Kurban İbadetinin Kültürümüze Yansımaları","Bir Sure Öğreniyorum: Kâfirun Suresi"],"anahtarKavramlar":["hac","ihram","kurban","say","tavaf","umre"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası, tanılayıcı dallanmış ağaç, görsel inceleme formu ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Hacla ilgili mekânların ve kavramların belirlendiği bir kavram haritası hazırlanabilir. Kurban ibadetinin yardımlaşma ve paylaşmaya katkısını içeren çalışma yaprağı hazırlanabilir. Hac ve kurban ibadetlerine dair uygulama ve geleneklerin kültürümüze yansımasıyla ilgili panel yapılabilir. Kâfirun suresi ve bu surenin anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri ölçütlere göre oluşturulan puanlama anahtarı ve öz değerlendirme formu ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin İslam’ın ibadet esasları hakkında bilgi sahibi oldukları, çevrelerinde hac ibadetini yerine getirmek üzere kutsal mekânları ziyaret edenleri gözlemledikleri, Kur’an-ı Kerim ve hadislerde hac ibadetinin açıklandığı bilgisine sahip oldukları kabul edilmektedir."],"onDegerlendirme":["Öğrencilerin hac ibadetiyle ilgili ön bilgilerini tespit etmek üzere Eğitim Bilişim Ağı’ndan (EBA) faydalanılarak Kâbe ve diğer kutsal mekânların görsellerine başvurulur. Öğrencilere söz konusu mekânlar hakkında sorular sorularak onların bu mekânlara dair bilgilerini paylaşmaları istenir."],"kopruKurma":["6. sınıf “Kültürümüzdeki Dinî Motifler” ünitesinde öğrendiklerinden hareketle öğrencilere dinen önemli günlerin neler olduğu sorulur. Dinî bayramlara ve özellikle Kurban Bayramı’na dikkat çekilir. Öğrencilerin, gözlemlerinden yola çıkarak kurban ibadetinin bayram olarak kutlanması ile kültürümüze yansımaları arasında bağlantı kurmaları sağlanır."],"uygulamalar":[{"kod":"DKAB.7.2.1","metin":"Öğrencilerin konuyu odaklanarak (E3.2) dinlemeleri için Eğitim Bilişim Ağı’ndan (EBA) faydalanılarak Hz. İsmail kıssası izletilir. Konunun Saffat, Bakara, İbrahim ve Hac surelerindeki ilgili ayetler kapsamında; öğrenci düzeyine göre ele alınmasına dikkat edilir. Kıssada bahsi geçen Mekke, zemzem suyu, Safa ve Merve Tepeleri, tavaf, Kâbe gibi konuyla ilgili kavram ve isimler tahtaya yazılarak hac ibadetiyle ilişkilendirilir. Öğrencilerin hac ibadetinin Hz. İbrahim’e kadar dayanan bir ibadet olduğu çıkarımını yapmaları ve Hz. İsmail’in Kâbe’nin inşasındaki rolünü fark etmeleri sağlanır. Hac ibadetinin İslam’ın ibadet esaslarından olduğu vurgulanır. Hac kavramının anlamı incelenir. Haccın Müslümanlar için önemine ve değerine yer verilir. Haccın farz olması için bir Müslümanın taşıması gereken şartların neler olduğu, ayet ve hadislerden yola çıkılarak öğrencilere anlatılır. Hacla ilgili ihram, telbiye, vakfe, tavaf, şavt kavramları; hac esnasında ziyaret edilen mekânlar olan Kâbe, Arafat, Mina, Müzdelife, Safa ve Merve incelenir. Mekânlar ve kavramlar öğrenci düzeyi gözetilerek ve ayrıntıya girmeden görseller aracılığıyla açıklanır (OB4). Haccın yapılışı, sırası ile anlatılır. Haccın farzlarının neler olduğu belirlenir. Haccın çeşitlerine ayrıca yer verilmez. Hac ibadeti esnasında yerine getirilen uygulamalar, hikmetleri ve anlamlarıyla birlikte açıklanır. İhram ile duygu ve düşüncelerin kontrol edilerek sabırlı olma (D12.2), gösteriş ve övünmeden kaçınarak mütevazı olma (D10.2) değerlerinin, vakfe ile istikrarlı davranarak sabır göstermenin (D12.3), tavaf ile evrensel bağ kurmayı sağlayan dostluk (D4.5) değerinin, say ile olumlu bakış açısına sahip olarak sabretmenin (D12.1), şeytan taşlama ile öz düzenleme yaparak sorumluluk üstlenme bilincinin (D16.3) kazandırılmak istendiği öğrencilere fark ettirilir. Kavramlar arasındaki ilişkiler belirlenir. Umre ibadetinin Müslümanlar için anlam ve değerine değinilir, yapılışı tarif edilir. Verilen bilgilerden yola çıkılarak hac ve umre arasındaki farkların neler olabileceği sorusu yöneltilir. Cevaplar hac ve umre başlıkları altında kategorize edilerek tahtaya yazılır. Öğrencilerden empati kurarak (E2.1) hac ve umre ibadetlerinin insana neler kazandırabileceğine dair düşünmeleri istenir. Öğrencilerin hac ibadeti bağlamında duygu ve düşüncelerini değerlendirmeleri sağlanır. Bu ibadetin insanın ahlaki gelişimine, Müslümanlar arasındaki iletişim ve etkileşime katkıda bulunduğu sonucuna ulaşmaları beklenir (SDB1.3)."},{"kod":"DKAB.7.2.2","metin":"Öğrencilere sevdikleri için ne tür fedakârlıklar yapabilecekleri sorulur (SDB1.1). Verilen cevaplardan yola çıkılarak Hz. İsmail kıssası bağlamında fedakârlık davranışı ile kurban ibadeti arasında ilişki kurulur. Kurban kavramının anlamı incelenir. Kurban ibadetinin İslam dinindeki yeri ve önemi gözden geçirilir. Kurban ibadetinin zamanı belirtilerek kurban kesmekle yükümlü olmanın şartları açıklanır. Hangi hayvanların kurban edilebileceği hakkında bilgi verilerek öğrencilerin bu bilgileri sistematik şekilde (E3.7) ayrıntıya girmeden kategorize etmeleri beklenir. Kurban ibadeti yerine getirilirken çevreyi temiz tutmak (D18.2) gerektiğine dikkat çekilir. Kesilen kurbanın ihtiyaç sahipleriyle paylaşılmasının (D20.2) önemi vurgulanır. Alevilik Bektaşilikteki kurban tığlama duasına yer verilir. Kurban ibadetinin insanın ahlaki gelişimine nasıl katkı sağlayabileceğinin sorgulanması için öğrencilere “Niçin kurban kesilir?” sorusu yöneltilir. Verilen cevaplardan yola çıkılarak kurbanın hikmetine dair öğrencilerin çıkarımda bulunmaları sağlanır. Bu çıkarımlara dayanarak öğrenciler, kurban ibadetini Allah’a (cc) yaklaşma ibadeti olarak değerlendirir ve uyumlu bir bakış açısı geliştirir."},{"kod":"DKAB.7.2.3","metin":"Öğrencilere çevrelerinde hacca gitmiş birini ziyaret edip etmedikleri sorulur. Bu ziyaret esnasındaki gözlemlerini paylaşmaları istenir. Böylelikle öğrenciler, hac ibadetinin kültürümüz üzerindeki yansımalarını fark eder, kendi gözlem ve tecrübeleriyle ilişkilendirir. Öğrencilere “Kurban bayramında neler yaparsınız?” sorusu yöneltilerek kurban ibadetinin kültürümüze etkisini fark etmeleri sağlanır. Bu kapsamda bayram namazı ve teşrik tekbirleri konusuna değinilir. Akika, adak ve şükür kurbanları hakkında bilgi verilerek benzerlik ve farklılıkları ayırt edilir. Asker uğurlaması ve düğün gibi vesilelerle de kurban ibadetinin yerine getirildiği ifade edilerek gündelik hayattaki örnekler üzerinden kurbanın kültürümüze yansımasına ilişkin çıkarım yapılır. Kurban etini ihtiyaç sahipleriyle paylaşma ve gelen misafirlere ikram etme geleneğinin toplumda yardımseverliği ve cömertliği (D20.1) yaygınlaştırdığına dikkat çekilir. Öğrencilerin hac ve kurban ibadetinin kültürümüzün ve yaşantımızın ayrılmaz bir parçası olduğu sonucuna ulaşmaları sağlanır."},{"kod":"DKAB.7.2.4","metin":"Öğrencilere “Kâfirun suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Kâfirun suresinin içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Kâfirun suresi hakkında bilgi verilirken surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Kâfirun suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Kâfirun suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilerden hacla ilgili kavramlardan oluşan bir sözlük tasarlanması istenebilir. Hac ibadetinin aşamalarının simülasyon (benzetim) yöntemiyle sunulması istenebilir. Kurban ibadetinin kültürümüze yansımalarının edebî bir tür içinde (hikâye, anı) sunulması istenebilir."],"destekleme":["Hac ve umre ibadetlerinin yapılışını gösteren görsel veya dijital materyallerden faydalanılarak öğrencilere görsel rehberlik yapılabilir. Bu ibadetlerin nasıl yapıldığı adım adım açıklanarak öğrencilerin konuyu anlamaları desteklenebilir. Hacla ilgili kavram ve mekânlara ait görsellerin, isimleriyle eşleştirilmesi istenebilir."],"ogretmenYansitmalari":[]},
{"no":3,"ad":"İslam Düşüncesinde Yorumlar","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/129","odak":"kavramlar ve erkânlar hakkında bilgi toplamaları amaçlanmaktadır.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.4. Çözümleme","KB2.5. Sınıflandırma","KB2.6. Bilgi Toplama","KB2.8. Sorgulama"],"egilimler":["E3.5. Açık Fikirlilik","E3.7. Sistematik Olma","E3.11. Özgün Düşünme"],"sdb":["SDB2.3. Sosyal Farkındalık"],"degerler":["D4. Dostluk","D14. Saygı","D20. Yardımseverlik"],"okuryazarlik":["OB4. Görsel Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.7.3.1","ad":"Din anlayışındaki yorum farklılıklarının sebeplerini sorgulayabilme","surec":["a) Din ve din anlayışı kavramlarını tanımlar.","b) Din ve din anlayışı arasındaki farklara dair sorular sorar.","c) Dinin farklı yorumlanma sebeplerine dair bilgi toplar.","ç) Dinin farklı yorumlanma sebeplerine dair topladığı bilgilerin doğruluğunu değerlendirir.","d) Dinin farklı yorumlanma sebeplerine ilişkin topladığı bilgilerden yola çıkarak dinin neden farklı yorumlandığına dair çıkarım yapar."]},{"kod":"DKAB.7.3.2","ad":"İslam düşüncesindeki yorum biçimlerini sınıflandırabilme","surec":["a) İslam düşüncesindeki yorum biçimlerini araştırır.","b) İslam düşüncesindeki yorum biçimlerini itikadi, fıkhi ve tasavvufi yorumlar olarak ayrıştırır.","c) İslam düşüncesindeki yorum biçimlerini itikadi, fıkhi ve tasavvufi yorumlar şeklinde tasnif eder.","ç) İslam düşüncesindeki yorum biçimlerini itikadi, fıkhi ve tasavvufi yorumlar şeklinde listeler."]},{"kod":"DKAB.7.3.3","ad":"Kültürümüzdeki tasavvufi yorumları çözümleyebilme","surec":["a) Kültürümüzdeki tasavvufi yorumları inceler.","b) Kültürümüzdeki tasavvufi yorumlar arasındaki ilişkileri bulur."]},{"kod":"DKAB.7.3.4","ad":"Alevilik Bektaşilik ile ilgili temel kavramlar ve cem erkânları hakkında bilgi toplayabilme","surec":["a) Alevilik Bektaşilik ile ilgili temel kavramlar ve cem erkânları konusunu araştırır.","b) Alevilik Bektaşilik ile ilgili temel kavramlar ve cem erkânları hakkında bilgileri bulur.","c) Alevilik Bektaşilik ile ilgili temel kavramlar ve cem erkânları hakkında ulaştığı bilgileri kontrol eder.","ç) Alevilik Bektaşilik ile ilgili temel kavram ve erkânlar hakkında ulaşılan bilgileri kaydeder."]}],"icerikCercevesi":["Din Anlayışındaki Yorum Farklılıkları","İslam Düşüncesinde Yorum Biçimleri","Kültürümüzdeki Tasavvufi Yorumlar","Alevilik Bektaşilik ile İlgili Temel Kavramlar ve Cem Erkânları"],"anahtarKavramlar":["erkân","itikat","mezhep","tasavvuf"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritaları, bulmacalar (anagram, çengel, sözcük avı vb.), yapılandırılmış grid ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Din ve din anlayışı arasındaki farkları içeren bir metin yazılabilir. İslam düşüncesindeki itikadi, fıkhi ve tasavvufi yorum biçimleriyle ilgili kavramların yer aldığı yapılandırılmış grid oluşturulabilir. Kültürümüzdeki tasavvufi yorum biçimlerini anlatan bilgi kartları hazırlanabilir. Alevilik Bektaşilik ile ilgili temel kavram ve erkânların tespit edilip birbirleriyle ilişkilendirildikleri bir kavram haritası hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin insanların farklı duygu, düşünce ve davranışlara sahip olabileceğini fark ettikleri kabul edilmektedir."],"onDegerlendirme":["Öğrencilerin konuyla ilgili ön bilgilerini kontrol etmek üzere öğrencilere mezhep ve tasavvuf kavramlarıyla ilgili neler bildikleri sorulur ve verdikleri cevaplara göre hazır bulunuşlukları kontrol edilir."],"kopruKurma":["Günlük hayatta insanların çeşitli konularda farklı bakış açılarına sahip olmaları ile din anlayışında farklı yorum biçimlerinin ortaya çıkması arasında ilişki kurulur."],"uygulamalar":[{"kod":"DKAB.7.3.1","metin":"Din ve din anlayışı kavramları açıklanır. Dinin farklı yorumlanabileceğini fark ettirmek üzere tahtaya daha önceden hazırlanmış uygun bir görsel yansıtılır. Öğrencilerden ilgili görseli incelemeleri ve görsele dair düşüncelerini not ederek paylaşmaları istenir (OB4). Öğrencilerin birbirlerinin paylaşımlarını dikkate alarak aynı görseli, her birinin farklı tarif edebildiği gibi dinin de bireyler tarafından özgün şekilde (E3.11) yorumlanabileceğini anlamaları ve böylelikle sosyal farkındalık kazanmaları sağlanır (SDB2.3). Öğrenciler din ve din anlayışı arasındaki farklara dair soru sormaya teşvik edilir. Bu farklar öğretmen tarafından açıklanarak din ve din anlayışı kategorileri altında listelenir. Toplumdaki farklı dinî anlayışlara dikkat çekilerek dinin farklı yorumlanma sebepleri açıklanır. Öğrencilerin içinde yaşadıkları toplumdaki farklı din anlayışlarını gözlemlemesi ve bunlar hakkında ön yargısız bir şekilde (E3.5) bilgi toplamaları istenir. Ulaştıkları bilgilerin doğruluğu öğretmenle birlikte değerlendirilir. Öğrencilerin dinin neden farklı yorumlandığına dair çıkarım yapmaları sağlanır. Öğrenciler edindikleri bilgilerden hareketle farklılıklara karşı anlayış geliştirerek saygı (D14.3) gösterir (SDB2.3). Din anlayışındaki farklılıkların kültürel bir zenginlik olduğunu fark eder."},{"kod":"DKAB.7.3.2","metin":"Mezhep kavramı ele alınır. İslam düşüncesindeki yorum biçimlerini sistematik biçimde (E3.7) sınıflandırmak üzere ölçüt olarak inanç, ibadet ve ahlak konuları belirlenir. Belirlenen ölçüte göre yorum biçimleri itikadi yorumlar, fıkhi yorumlar ve tasavvufi yorumlar olarak ayrıştırılır. İnançla ilgili yorum biçimleri itikadi yorumlar, ibadetle ilgili yorum biçimleri fıkhi yorumlar, ahlakla ilgili yorum biçimleri tasavvufi yorumlar olarak tasnif edilir. İtikadi yorumlar Matüridilik ve Eşarilik; fıkhi yorumlar Hanefilik, Malikilik, Şafiilik ve Hanbelilik; tasavvufi yorumlar Yesevilik, Kadirilik, Mevlevilik, Nakşibendilik ve Alevilik Bektaşilik şeklinde listelenir. Bu yorum biçimleri hakkında verilen bilgiler kurucuları, öğretileri ve etkin oldukları coğrafyalar ile sınırlandırılır."},{"kod":"DKAB.7.3.3","metin":"İnsanın ahlaki gelişimini konu edinen tasavvufi yorumları çözümlemek üzere tartışma yöntemi kullanılır. İyi bir kul ve iyi bir insan olmak için nelere dikkat edilmesi gerektiği sorularak öğrenciler düşünmeye teşvik edilir. İslam dininde ibadet ve inançla birlikte ahlaki esasların da önemli olduğu fark ettirilerek öğrencilerin toplumsal normlar hakkında bir anlayış geliştirmesi sağlanır (SDB2.3). İnsanların ahlaki gelişimini esas alan anlayışlardan olan Yesevilik, Kadirilik, Mevlevilik, Nakşibendilik ve Alevilik Bektaşilik kültürümüzde etkin olan tasavvufi yorumlar olarak incelenir. Konuyla ilgili olarak Mevlana Haftası’na değinilir. Her bir yorum biçiminin kurucuları ve öğretileri hakkında ayrıntıya girmeden genel bilgiler verilir. Ahlaki değerler bağlamında aralarındaki ilişki belirlenir."},{"kod":"DKAB.7.3.4","metin":"Alevilik Bektaşilikle ilgili temel kavramlar ve cem erkânları listelenir. Bu kavram ve erkânlar hakkında araştırma yapılır. Öğrenciler; cem, cemevi, musahiplik, razılık ve kul hakkının sorulması, cemde on iki hizmet, semah, gülbank, lokma duası, Hızır ve muharrem orucu, erkân, ikrar, dört kapı kırk makam kavramları ile uygulanma şekilleri hakkında bilgiler bulur. Bu bilgiler öğretmen rehberliğinde kontrol edilir ve afiş, broşür, pano, duvar gazetesi gibi yollarla kaydedilir. Cemevinin Alevilikte ayinicem erkânının yapıldığı yol, adap ve erkân yeri olduğu ifade edilir. Bunun için ayinicem ve cemevi ile ilgili görseller kullanılır. Cem çeşitleri olarak görgü cemi, ikrar cemi ve Abdal Musa cemine yer verilir. Alevilik Bektaşilikte gülbankların başında “bismişah”, sonunda ise “Allah Allah” lafzının söylendiği belirtilir. “Bismişah Allah Allah” ifadesinde yer alan “şah” kelimesinin evrenin mutlak ve yegâne yöneticisi Allah’ı işaret ettiğine değinilir. Gülbank konusunda lokma duasına değinilir. Alevilik Bektaşilikteki “ocak kültürü” ve “el ele, el hakka ikrarı” kavramları anlatılır. Bektaşilikte musahipliğe “ikrar verip nasip almak” da denildiği ifade edilir. Bu kavramın İslam tarihindeki muhacir-ensar kardeşliğine dayandırıldığına dikkat çekilir (D4.1, D20.2)."}],"zenginlestirme":["Hacı Bektaş Veli’nin Makalat’ından ve Mevlana’nın Mesnevi’sinden metinler seçilerek bu metinlerde geçen ahlaki öğütlerin listelenmesi istenebilir."],"destekleme":["Öğrenci düzeyine uygun kaynaklar seçilerek öğrencilerden İslam düşüncesindeki yorum biçimleriyle ilgili bilgi toplamaları istenebilir. Öğrencilerin edindikleri bilgileri listelemeleri ve sınıfta sunmaları sağlanabilir."],"ogretmenYansitmalari":[]},
{"no":4,"ad":"Peygamber Olarak Hz. Muhammed","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/130","odak":"Bu ünitenin teması Kur’an ve peygamberdir. Ünitede Hz. Muhammed’in (sav) vahiy aldıktan sonraki hayatı ele alınmaktadır. Öğrencilerin, Hz. Muhammed’in (sav) bir peygamber olarak Mekke’de yaşadıklarını yorumlamaları, Hicret sırasında gerçekleşen olayları kendi tarihsel şartları bağlamında değerlendirmeleri, Hz. Muhammed’in (sav) Medine’deki hayatını yapılandırmaları amaçlanmaktadır. Nasr suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":16,"alanBecerileri":["SBAB3. Tarihsel Empati (KB2.14. Yorumlama","SBAB3.1. Tarihsel Bağlamsallaştırma","KB2.13. Yapılandırma)"],"kavramsalBeceriler":["KB2.14. Yorumlama"],"egilimler":["E1.1. Merak","E1.5. Kendine Güvenme (Öz Güven)","E2.1. Empati","E3.2. Odaklanma","E3.11. Özgün Düşünme"],"sdb":["SDB2.3. Sosyal Farkındalık"],"degerler":["D14. Saygı","D15. Sevgi"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Sosyal Bilgiler","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.7.4.1","ad":"Hz. Muhammed’in (sav) Mekke’de yaşadıklarını yorumlayabilme","surec":["a) Hz. Muhammed’in (sav) Mekke’de yaşadıklarını inceler.","b) Hz. Muhammed’in (sav) Mekke’de yaşadıklarını kendi ifadeleriyle, doğru ve bilgiyi değiştirmeyecek şekilde özetler."]},{"kod":"DKAB.7.4.2","ad":"Hicret konusunu tarihsel bağlamda değerlendirebilme","surec":["a) Hz. Muhammed’in (sav) Hicret’te yaşadıklarını temel kaynaklardan hareketle fark eder.","b) Hicret’in yaşandığı dönemi koşulları içerisinde açıklar.","c) Hicret’in yaşandığı dönemi analiz eder.","ç) Hicret’in yaşandığı dönemi günümüz koşullarıyla karşılaştırır."]},{"kod":"DKAB.7.4.3","ad":"Hz. Muhammed’in (sav) Medine Dönemi konusunu yapılandırabilme","surec":["a) Hz. Muhammed’in (sav) Medine’de yaşadıklarını inceleyerek çıkarımda bulunur.","b) Hz. Muhammed’in (sav) Medine hayatı hakkında yaptığı çıkarımları ifade eder."]},{"kod":"DKAB.7.4.4","ad":"Nasr suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Nasr suresini ve bu surenin anlamını okur.","b) Nasr suresinin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Nasr suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Hz. Muhammed’in Daveti: Mekke Dönemi","Hicret","Hz. Muhammed’in Daveti: Medine Dönemi","Bir Sure Öğreniyorum: Nasr Suresi"],"anahtarKavramlar":["Ehlibeyt","ensar","Hicret","muhacir"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","İlk Müslümanlarla ilgili bilgilerin yer aldığı kimlik kartları hazırlanabilir. Mekke Dönemi’nde yaşanan olayları içeren tarih cetveli hazırlanabilir. Hicret’in sebep ve sonuçlarının değerlendirildiği neden-sonuç diyagramı (balık kılçığı) hazırlanabilir. Hz. Muhammed’in (sav) Medine hayatı ile ilgili panel düzenlenebilir. Sınıf ortamında Veda Hutbesi okunarak öğrencilerden hutbeden ilkeler çıkarmaları istenebilir. Nasr suresi ile bu surenin anlamı için eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin Hz. Muhammed’in (sav) peygamberlikten önceki hayatı hakkında bilgi sahibi olduğu kabul edilmektedir."],"onDegerlendirme":["Öğrencilerin Hz. Muhammed’in (sav) vahiy almadan önceki hayatı hakkında bilgi sahibi oldukları varsayılarak hazır bulunuşlukları değerlendirilmek üzere onlara sorular sorulur ve kısa hatırlatmalar yapılır."],"kopruKurma":["Hz. Muhammed’in (sav) hayatıyla ilgili öğrencilerin okul ve çevreden edindiği bilgilerle yeni öğrendiği bilgiler arasında bağlantı kurulur."],"uygulamalar":[{"kod":"DKAB.7.4.1","metin":"Öğrencilerin Hz. Muhammed’in (sav) vahiy almadan önceki hayatına odaklanması sağlanarak (E3.2) vahyin inişi öncesinde Hz. Muhammed’in (sav) yaşadıkları açıklanır. Bu bağlamda Hz. Muhammed’in (sav) toplumdaki haksızlıklara olan tepkisine ve yalnız kalma isteğine vurgu yapılır. İlk vahyin nerede ve ne zaman geldiğine, ilk ayetlerin neler olduğuna ve ilk ayetlerde ne gibi mesajlar verildiğine değinilir. Sınıfta bu süreci aktaran sunu, belgesel vb. materyallerden yararlanılabilir. Hz. Muhammed’in (sav) İslam’a davete, yakın çevresinden başladığı anlatılır. Bunun sebepleri konusunda öğrencilerin beyin fırtınası yapması için gerekli zemin oluşturulur. Böylece öğrencilerin farklı fikirler üreterek (E3.11) düşüncelerini ifade etmeleri sağlanır. Davet süreci, İsra ve Miraç olayı, Hz. Hamza ve Hz. Ömer’in Müslüman olmaları, boykot yılları, Hüzün Yılı, Taif yolculuğu, Habeşistan’a hicret, Akabe Biatleri hakkında öğrencilerde merak (E1.1) uyandıracak sorular sorulur. Öğrencilerin Hz. Muhammed’in (sav) peygamberlik dönemi hakkında bilgi ihtiyacını fark etmesi sağlanır. Bilgiye ulaşmada doğru kaynaklar kullanma konusunda öğrencilere rehberlik edilir ve öğrencilerin edindiği bilgilerin doğruluğu incelenir. Öğrencilerin edindikleri bilgiyi istendik davranışlara dönüştürmesi için özetlemesi ve ardından yorumlaması beklenir (OB1). Öğrencilerin Hz. Muhammed’in (sav) Mekke’de yaşadıklarını kendi döneminin şartları içinde anlaması ve sosyal farkındalığının gelişmesi (SDB2.3) hedeflenir. Öğrenciler edindikleri bilgilerden yola çıkarak davet süreci hakkında bazı ipuçları toplar. Böylece Hz. Muhammed’i (sav) ve ilk Müslümanları daha iyi anlayarak, onlara saygı (D14.3) ve sevgi (D15.1) duyar. Öğrenciler benzer durumlara uygun davranış biçimleri ve kuralları belirleyerek kompozisyon, şiir, resim vb. çalışmalarla duygu ve düşüncelerini özetler."},{"kod":"DKAB.7.4.2","metin":"Öğrencilere “Yaşadığınız yerden ayrılmak zorunda kalsanız neler hissedersiniz?” sorusu yöneltilir. Öğrencilerin verdikleri cevaplardan hareketle hicret etmenin insan üzerindeki etkileri hakkında beyin fırtınası yapılır. Hicret kavramı açıklanır. Öğrencilerin Hz. Muhammed’in (sav) Hicret’ini ele alırken sosyal bilgiler dersinde öğrendikleri hatırlatılarak temel kaynaklardan edindiği bilgiler doğrultusunda Hicret’i gerektiren şartları açıklaması sağlanır. Hz. Ebubekir ve Hz. Ali’nin Hicret’teki rollerine yer verilir. Öğrencilerin Hicret’in yaşandığı dönemin şartlarını fark etmesi için hikâye yazma, drama yapma vb. etkinlikler yapılır. Bu etkinliklerle öğrencilerin Hicret’in yaşandığı dönemi kendi koşulları içinde analiz etmesine ve günümüz koşullarıyla karşılaştırmasına fırsat tanınmış olur."},{"kod":"DKAB.7.4.3","metin":"Öğrencilere “Yaşadığınız yerden ayrıldıktan sonra gittiğiniz yerde ne gibi sorunlarla karşılaşırsınız?” sorusu yöneltilir. Verilen cevaplardan hareketle öğrencilerin Hz. Muhammed (sav) ve sahabilerin Hicret sonrasında yaşadıklarını değerlendirmesi sağlanır. Ensar-muhacir kardeşliği, Medine Sözleşmesi, Mescid-i Nebevi’nin inşası ve işlevi, Suffe ashabı, Bedir, Uhud ve Hendek savaşları, Hudeybiye Antlaşması ve Mekke’nin Fethi, İslam’a davet mektupları, Veda Haccı, Hz. Muhammed’in (sav) vefatı konularından ayrıntıya girilmeden bahsedilir. Veda Hutbesi’nde yer alan evrensel mesajlar açıklanır. Öğrencilerin Hz. Muhammed’in (sav) Medine’de yaşadıklarını inceleyerek çıkarımda bulunması sağlanır. Metin çalışması yapmaları ve bu çıkarımları kendi cümleleriyle ifade etmeleri istenir. Hz. Muhammed’in (sav) Veda Hutbesi’nde ümmete bıraktığı “iki emanet”e (farklı rivayetleriyle birlikte) yer verilir. Bu bağlamda Ehlibeyt kavramı açıklanır ve Ehlibeyt’in Müslümanlar açısından önemine dikkat çekilerek Hz. Muhammed’in (sav) torunları Hz. Hasan ve Hz. Hüseyin’den kısaca bahsedilir. Hz. Peygamber’in onlara olan sevgisine yer verilir."},{"kod":"DKAB.7.4.4","metin":"Öğrencilere “Nasr suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Nasr kelimesinin anlamı açıklanarak Nasr suresinin içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Nasr suresi hakkında bilgi verilirken surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Nasr suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir, Nasr suresi ile Hz. Muhammed’in (sav) Medine’de yaşadıkları arasında bağ kurulur. Buradan çıkarılacak mesajlarla ilgili etkinlikler yoluyla değerlendirme yapılabilir ve öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Nasr suresindeki tesbih, hamt ve istiğfar kavramları açıklanır. Öğrencilerin Nasr suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilerden Hz. Muhammed’in (sav) Mekke’de, Medine’de ve Hicret esnasında yaşadıklarıyla ilgili panel düzenlemeleri istenebilir. Hicret’in bugünün imkânlarıyla aktarıldığı bir haber programının hazırlanması istenebilir."],"destekleme":["Öğrencilerden Hz. Muhammed’in (sav) Mekke ve Medine’de yaşadığı olayları listelemesi istenebilir. Hz. Muhammed’in (sav) Mekke’de, Medine’de ve Hicret esnasında yaşadığı olayları somutlaştırmak için resim veya harita gibi görsel materyaller kullanılabilir."],"ogretmenYansitmalari":[]},
{"no":5,"ad":"Yaşayan Dünya Dinleri","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/131","odak":"Bu ünitenin teması kültürdür. Ünitede yaşayan dünya dinleri ele alınmaktadır. Öğrencilerin; Yahudilik, Hristiyanlık, Hinduizm ve Budizm dinleri hakkında bilgi toplamaları, edindiği bilgilerden hareketle dünyada farklı dinleri bir olgu olarak kabul etmeleri ve her dinin kendine has özellikleri olduğunu fark etmeleri amaçlanmaktadır.","dersSaati":10,"alanBecerileri":[],"kavramsalBeceriler":["KB2.6. Bilgi Toplama"],"egilimler":["E3.2. Odaklanma","E3.4. Gerçeği Arama"],"sdb":["SDB2.3. Sosyal Farkındalık"],"degerler":["D11. Özgürlük","D14. Saygı"],"okuryazarlik":["OB4. Görsel Okuryazarlığı"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.7.5.1","ad":"Yahudilik, Hristiyanlık, Hinduizm ve Budizm dinleri hakkında bilgi toplayabilme","surec":["a) Yahudilik, Hristiyanlık, Hinduizm ve Budizm dinlerini araştırır.","b) Yahudilik, Hristiyanlık, Hinduizm ve Budizm dinleri hakkında bilgiler bulur.","c) Yahudilik, Hristiyanlık, Hinduizm ve Budizm dinleri hakkında edindiği bilgileri doğrular.","ç) Yahudilik, Hristiyanlık, Hinduizm ve Budizm dinleri hakkında edindiği bilgileri kaydeder."]}],"icerikCercevesi":["Yahudilik","Hristiyanlık","Hinduizm","Budizm"],"anahtarKavramlar":["Budizm","Hinduizm","Hristiyanlık","Yahudilik"],"olcmeDegerlendirme":["Bu ünitede ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası, görsel inceleme formu ve öz değerlendirme formu kullanılabilir.","Performans görevi:","Yahudilik, Hristiyanlık, Hinduizm ve Budizm dinleriyle ilgili afiş, sunu vb. hazırlanabilir. Bu dinlerin yaşandığı coğrafyalar, tanrı tasavvurları, inanç esasları, kurucuları, kutsal metinleri, ritüelleri, kutsal mekânları, mabetleri, sembolleri vb. bilgileri içeren bilgi kartları hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin farklı dinlerin varlığını bir olgu olarak kabul ettiği, bu dinlere mensup olanların farklı inanç ve ritüelleri olduğunu bildiği kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Dünyada hangi dinler var?” sorusu sorularak bir liste oluşturulur. Listede yer alan dinler hakkında öğrencilerin neler bildiği sorularak hazır bulunuşlukları kontrol edilir."],"kopruKurma":["Öğrencilerin farklı dinlerin varlığını bildiğinden hareketle bu dinler hakkında yeni edindiği bilgiler arasında bağlantı kurulur."],"uygulamalar":[{"kod":"DKAB.7.5.1","metin":"Öğrencilere “Yaşayan dünya dinleri hakkında neler biliyorsunuz?” sorusu sorulur. Verilen cevaplardan hareketle bir kavram haritası oluşturulur. Her din hakkında öğrencilerin neler bildiği ve ne düşündüklerine dair tartışma ortamı hazırlanarak öğrencilerin kendilerini özgür bir şekilde (D11.2) ifade etmeleri sağlanır. Böylece öğrencilerin dünya üzerinde farklı dinlerin varlığını bir olgu olarak kabul etmesi ve sosyal farkındalığının gelişmesi (SDB2.3) hedeflenir. Bu bilgilerden yola çıkılarak öğrencilerin bu dinlerin mensuplarını anlayabilmesi, onlara saygı duyabilmesi (D14.3) ve toplum kurallarıyla ilgili bir anlayış geliştirmesi sağlanır (D11.2). Öğrencilerin bu dinlerin kültürel unsurlarını fark etmelerini sağlayacak görsel, belgesel, film vb. materyallerden yararlanılır. Öğrencilerin yaşayan dünya dinlerinden Yahudilik, Hristiyanlık, Hinduizm ve Budizm dinlerine odaklanması (E3.2) istenir. Bu dinlerin kutsal metinleri, dinin ibadet ve ritüellerinin aktarıldığı eserler temel bilgi kaynakları olarak belirlenir. Bu dinlerin tarihçelerine değinilir. Dünyanın hangi bölgelerinde yaygın olduğu, tanrı tasavvurları, inanç esasları, kutsal metinleri, ritüelleri, kutsal mekânları, mabetleri, sembolleri konularında öğrencilerin yazılı ve görsel kaynaklardan bilgi bulmaları istenir. Yahudilik, Hristiyanlık, Hinduizm ve Budizm dinleri hakkında bilgiler verilerek konu edilen din ile ilgili genel bir çerçeve çizilir. Öğrencilerin edindiği bilgileri söz konusu dinin temel kaynaklarından elde edilen bilgileri öğretmen rehberliğinde doğrulaması sağlanır. Böylece öğrencilerin doğruya ulaşma konusundaki kararlılığından (E3.4) hareketle edindikleri bilgileri sorgulamaları istenir. Öğrencilere bu dinlerle ilgili resim, sunu, belgesel vb. materyaller gösterilerek öğrencilerin dinler hakkındaki bilgilerini pekiştirmeleri sağlanır. Öğrencilerden inceledikleri bu materyaller hakkında düşüncelerini ifade ettikleri bir kompozisyon yazmaları veya dinler hakkında buldukları görsellerden bir pano, afiş veya sunu çalışması yapmaları (OB4) istenerek bilgilerini kaydetmeleri sağlanır."}],"zenginlestirme":["Öğrenciler; Yahudilik, Hristiyanlık, Hinduizm ve Budizm hakkında panel düzenleyebilir."],"destekleme":["Yahudilik, Hristiyanlık, Hinduizm ve Budizm hakkında bilgi toplanırken dijital içerikler kullanılabilir. Öğrencilerden şematik haritalar kullanılarak bu dinlerle ilgili sunu hazırlamaları istenebilir."],"ogretmenYansitmalari":[]}],"s8":[{"no":1,"ad":"Kader İnancı","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/132","odak":"davranışlarına etkisine dair bir bakış açısı kazanmaları amaçlanmaktadır. Tebbet suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":14,"alanBecerileri":["SBAB16. Eleştirel Sosyolojik Düşünme (KB3.3. Eleştirel Düşünme)"],"kavramsalBeceriler":["KB2.14. Yorumlama","KB2.16.2. Tümdengelime Dayalı Akıl Yürütme"],"egilimler":["E1.5. Kendine Güvenme (Öz Güven)","E2.2. Sorumluluk","E3.3. Özgün Düşünme","E3.8. Soru Sorma","E3.10. Eleştirel Bakma"],"sdb":["SDB3.2. Esneklik"],"degerler":["D1. Adalet","D5. Duyarlılık","D12. Sabır","D14. Saygı","D16. Sorumluluk","D17. Tasarruf"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Fen Bilimleri, Sosyal Bilgiler","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.8.1.1","ad":"Allah’ın (cc) her şeyi bir ölçü ve düzene göre yarattığını kader ve kaza inancı bağlamında özetleyebilme","surec":["a) Allah’ın (cc) her şeyi bir ölçü ve düzene göre yarattığını kader ve kaza inancı bağlamında inceler.","b) Evrenin işleyişindeki ölçü ve düzeni gösteren örnekleri kader ve kaza bağlamında kendi hayatı için anlamlı hâle getirir.","c) Kader ve kaza inancını doğru ve bilgiyi değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade eder."]},{"kod":"DKAB.8.1.2","ad":"Kaderle ilgili kavramları açıklayabilme","surec":["a) Kaderle ilgili kavramları öğretmen rehberliğinde araştırır.","b) Kaderle ilgili kavramlar ve kader arasında parça-bütün ilişkisi kurar.","c) Kaderle ilgili kavramlar hakkında çıkarım yapar."]},{"kod":"DKAB.8.1.3","ad":"Kader inancının insan davranışına etkisi hakkında düşünebilme","surec":["a) Kader inancının insan davranışına etkisini inceler.","b) Kader inancının insan davranışına etkisiyle ilgili sonuç çıkarır.","c) Kader inancının insan davranışına etkisiyle ilgili ulaştığı çıkarımları davranışlarına yansıtır."]},{"kod":"DKAB.8.1.4","ad":"Tebbet suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Tebbet suresini ve bu surenin anlamını okur.","b) Tebbet suresinin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Tebbet suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Allah’ın Ölçüsü: Kader ve Kaza","Kaderle İlgili Kavramlar","Kader İnancının İnsan Davranışına Etkisi","Bir Sure Öğreniyorum: Tebbet Suresi"],"anahtarKavramlar":["emek","kader","kaza","rızık","sünnetullah","tevekkül"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, öğrenme günlüğü, tanılayıcı dallanmış ağaç ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Evrendeki ölçü ve düzenle ilgili olay, olgu ve ayetlerin evrendeki ilahi yasalarla eşleştirildiği bir çalışma yaprağı hazırlanabilir. Kaderle ilgili kavramların tespit edilip birbirleriyle ilişkilendirildikleri bir kavram haritası hazırlanabilir. Kader inancının insan davranışlarına etkisiyle ilgili panel hazırlanabilir. Tebbet suresi ve bu surenin anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin İslam’ın inanç esasları hakkında bilgi sahibi oldukları, Kur’an-ı Kerim’de ve hadislerde inanç konusuyla ilgili bilgilerin yer aldığını bildikleri kabul edilmektedir."],"onDegerlendirme":["Öğrencilerin kader inancıyla ilgili ön bilgilerini tespit etmek üzere “alın yazısı”, “kara talih”, “kader mahkûmu” gibi ifadeler tahtaya yazılarak öğrencilerden bu ifadelerin ne anlama geldiğini yorumlamaları istenir. Söz konusu ifadelere katılıp katılmadıkları sorularak tartışma ortamı oluşturulur."],"kopruKurma":["Eğitim Bilişim Ağı’ndan (EBA) yararlanılarak gece-gündüzün ve mevsimlerin oluşumu, suyun kaldırma kuvveti, besin zinciri gibi doğa yasalarının işleyişiyle ilgili öğrencinin seviyesine uygun kısa film veya belgesel izletilir. 5. sınıf “Allah İnancı” ünitesinde öğrendikleri ile mevcut hazır bulunuşlukları arasında bağlantı kurulur.","Öğrencilere hayatlarında değiştirmeyi istedikleri şeylerin neler olduğu sorulur ve onlardan bunları değiştirmeye güçlerinin yetip yetmediği üzerinde düşünmeleri istenir. Her şeyi kontrol etmelerinin mümkün olmadığı fark ettirilerek kader inancıyla günlük hayat arasında köprü kurulur."],"uygulamalar":[{"kod":"DKAB.8.1.1","metin":"Öğrencilerden çevrelerini gözlemleyerek evrendeki düzen ve uyumu gösteren farklı örnekler vermeleri istenir. Bu örnekler çerçevesinde öğrencilerin Allah’ın (cc) evreni bir ölçü ve düzene göre yarattığı çıkarımını yapmaları sağlanır. Kader ve kaza kavramlarının anlamları incelenir. Öğrencilerin, Allah’ın (cc) her şeyi bir ölçü ve düzene göre yaratmasını kaza ve kader inancı ile ilişki kurarak incelemeleri sağlanır ve öğrenciler özgürce sorgulama yapmaları (E3.8) için teşvik edilir. Kuran’ı Kerim’den konuyla ilgili ayetlere başvurularak Allah’ın (cc) evrenin işleyişi için yasalar koyduğu fark ettirilir. Öğrencilerin, evrenin yaratılışındaki ölçü ve düzeni gösteren örnekleri evrendeki ilahi yasalarla ilişkilendirilerek sünnetullah kavramını öğrenmeleri sağlanır. Evrendeki ilahi yasalar çözümlenerek fiziksel, biyolojik ve toplumsal yasalar olarak sınıflandırılır. Konuyla ilgili olarak öğrencilerin fen bilimleri dersinde edindiği bilgilerden faydalanılır. Fiziksel yasaların günümüzdeki teknolojik gelişmelere nasıl ilham olabileceği örnekler üzerinden açıklanır (E3.3). Ekosistemin işleyişinde biyolojik yasaların rolü fark ettirilir (D5.2). Toplumsal yasalar, toplumların sağlıklı bir şekilde varlıklarını sürdürebilmek için ihtiyaç duydukları kurallar ve değerler bağlamında ele alınır (D1.2, D14.1). Konuyla ilgili olarak öğrencilerin sosyal bilgiler dersinde öğrendiği bilgilerden yararlanılır. Öğrencilere “Günümüzde yaşanan küresel ısınma, iklim krizi gibi problemler nelerden kaynaklanmış olabilir?” sorusu yöneltilerek tartışma ortamı hazırlanır. Öğrencilerin yaşadıkları zamanın koşullarının ve toplumun yaşantısının söz konusu krizlerdeki rollerini sorgulamaları (D16.2, D17.2) sağlanır. Öğrenciler, evrenin işleyişindeki ölçü ve düzeni gösteren örnekleri kader ve kaza inancı bağlamında kendi hayatı için anlamlı hâle getirir. Kader ve kaza inancını nesnel, doğru ve anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade eder ve kaydeder. Bunun için öğrencilerden öğrenme günlüğü hazırlamaları istenebilir."},{"kod":"DKAB.8.1.2","metin":"Kaderle ilgili kavramlar araştırılır ve irade, külli irade, cüzi irade, sorumluluk, ecel, ömür, rızık, tevekkül olarak belirlenir. Kavramların tanımları yapılarak günlük hayattan örnekler verilir. Kavramlar, kader inancı bağlamında ele alınarak aralarında ilişki kurulur. Hz. Yusuf kıssası, Yusuf suresi çerçevesinde işlenir. Hz. Yusuf’un yaşadığı zorluklar karşısında gösterdiği sabra dikkat çekilir (D12.1). Kıssanın olay örgüsünde yer alan hadiseler, kaderle ilgili kavramlar kapsamında değerlendirilir. Öğrencilerin kaderle ilgili kavramlar hakkında çıkarım yapması sağlanır."},{"kod":"DKAB.8.1.3","metin":"Toplumun dikkatini çeken güncel bir olay sınıfta paylaşılarak öğrencilerin olayı kader inancı bağlamında incelemeleri istenir. Örnek olaydan hareketle toplumda kader ve kazayla ilgili yaygın olan yanlış anlayışlar, öğrencilerin eleştirel bakmasına (E3.10) imkân verecek şekilde incelenir. Öğrencilerden kader inancını doğru anlayan ve yorumlayan birinin içinde bulunduğu durumu nasıl değerlendirebileceğine dair akıl yürütmeleri istenir. Öğrencilerin kader inancına, zor durumlara alternatif çözümler bulma ve yeni durumlara uyum sağlamada bir araç olarak yaklaşmaları sağlanır (SDB3.2). Akıl yürütmeyle ulaştıkları çıkarımları sorumluluk bilinciyle (E2.2) davranışlarına yansıtmaları beklenir."},{"kod":"DKAB.8.1.4","metin":"Öğrencilere “Tebbet suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Tebbet suresinin içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Tebbet suresi hakkında bilgi verilirken surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Tebbet suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Tebbet suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Ahlaki ikilem içeren örnek olaylar tasarlanarak öğrencilere kader inancı konulu münazara yaptırılabilir."],"destekleme":["Kaderle ilgili kavramlardan oluşan sözcük avı hazırlanabilir. Grafik, resim veya video gibi görsel materyaller kullanılarak öğrencilerin konuyu daha iyi kavraması desteklenebilir."],"ogretmenYansitmalari":[]},
{"no":2,"ad":"Zekât ve Sadaka","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/133","odak":"Ünitenin teması ibadettir. Bu ünitede zekât ve sadaka konusu ele alınmaktadır. Öğrencilerin; zekât ibadetini paylaşma ve yardımlaşma bağlamında gözlemlemeleri, sadaka kapsamında düşünülebilecek davranışları kendi hayatına yansıtmaları, zekât ve sadaka ibadetinin kültürümüze yansımalarını gözleme dayalı tahmin etmeleri amaçlanmaktadır. Maun suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.2. Gözlemleme","KB2.11. Gözlemleme Dayalı Tahmin Etme","KB2.14. Yorumlama","KB2.15. Yansıtma"],"egilimler":["E1.4.Kendine İnanma (Öz Yeterlilik)","E1.5. Kendine Güvenme (Öz Güven)","E2.3. Girişkenlik"],"sdb":[],"degerler":["D1. Adalet","D9. Merhamet","D20. Yardımseverlik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık","OB4. Görsel Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.8.2.1","ad":"Zekât ibadetini gözlemleyebilme","surec":["a) Paylaşma ve yardımlaşma bağlamında zekât ibadetine ilişkin ölçütleri açıklar.","b) Zekât ibadeti hakkında bilgi toplar.","c) Zekât ibadeti hakkında topladığı bilgileri sınıflandırır ve kaydeder."]},{"kod":"DKAB.8.2.2","ad":"Sadaka kapsamında değerlendirilen davranışları kendi hayatına yansıtabilme","surec":["a) Sadaka ibadeti kapsamındaki tecrübelerini gözden geçirir.","b) Sadaka ibadeti kapsamındaki tecrübelerine dayalı çıkarımlar yapar.","c) Sadaka ibadeti kapsamındaki tecrübelerinden ulaştığı çıkarımları öğretmen rehberliğinde değerlendirir."]},{"kod":"DKAB.8.2.3","ad":"Zekât ve sadaka ibadetinin kültürümüze yansımalarını gözleme dayalı tahmin edebilme","surec":["a) Zekât ve sadaka ibadetlerinin kültürümüze yansımalarına ilişkin ön gözlem veya tecrübelerini ilişkilendirir.","b) Zekât ve sadaka ibadetlerinin kültürümüze yansımalarına ilişkin çıkarım yapar.","c) Zekât ve sadaka ibadetlerinin kültürümüze yansımalarına ilişkin sonuç çıkarır."]},{"kod":"DKAB.8.2.4","ad":"Maun suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Maun suresini ve bu surenin anlamını okur.","b) Maun suresinin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Maun suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Paylaşma ve Yardımlaşma İbadeti: Zekât","Allah’ın Sevgisini ve Hoşnutluğunu Kazanmanın Yolu: Sadaka","Zekât ve Sadaka İbadetinin Kültürümüze Yansımaları","Bir Sure Öğreniyorum: Maun Suresi"],"anahtarKavramlar":["nisap","sadaka","zekât"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritaları, bulmacalar (anagram, çengel, sözcük avı vb.) ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","Zekât ibadeti hakkında broşür hazırlanabilir. Sadaka ibadeti hakkında bir gözlem formu hazırlanabilir. Zekât ve sadaka ibadetinin kültürümüze yansımaları hakkında sunu yapılabilir. Maun suresi ve bu surenin anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrenciler zekâtın İslam’ın temel ibadetlerinden biri olduğunu bildiği, çevresindeki yardımlaşma ve paylaşma davranışlarını gözlemlediği kabul edilmektedir."],"onDegerlendirme":["Tahtaya “Bir elin nesi var, iki elin sesi var.” atasözü yazılarak bu sözün hangi mesajı içerdiği sorulur ve öğrencilerin ön bilgileri harekete geçirilir. Öğrencilerin bu soruya verdikleri cevaplara göre hazır bulunuşlukları kontrol edilir."],"kopruKurma":["Öğrencilere “Başkalarına yardım ettiğinizde neler hissedersiniz?” sorusu sorulur. Bu soru ekseninde öğrencilerden paylaşma ve yardımlaşma duygusunu fark ederek bu duyguların kendi hayatlarına yansımalarını değerlendirmeleri istenir. Böylece zekât ve sadaka ibadeti ile gerçek hayat arasında köprü kurulur."],"uygulamalar":[{"kod":"DKAB.8.2.1","metin":"Öğrencilerin zekât ibadetini paylaşma ve yardımlaşma bağlamında öz yeterlilikle (E1.4) değerlendirmeleri için onlara “İslam dininde başkalarına yardım ederek yapılan ibadetler nelerdir?” sorusu yöneltilir. Öğrencilerin dinî bilgi türü arasında sayılan zekât ibadetiyle paylaşma ve yardımlaşma ihtiyacını fark etmeleri beklenir (OB1). Öğrencilerin ayet ve hadislerden yararlanarak zekât ibadetiyle ilgili bilgileri bulması ve zekât ibadetini genel hatlarıyla açıklaması sağlanır. Öğrenciler, zekât ibadetiyle ilgili elde ettikleri bilgileri öğretmenleriyle birlikte değerlendirerek doğrular ve sınıflandırır. Afiş, broşür, pano, duvar gazetesi gibi yollarla kaydeder (OB1). Öğrencilerin paylaşma ve yardımlaşma bağlamında zekât ibadetinin kimlere farz olduğunu belirlemesi sağlanır. Zekât verilecek malların dijital içerikleri gösterilir. Öğrencilerden görselleri incelemesi, bağlamından koparmadan nisap miktarlarına dönüştürmesi ve görsellerden hareketle ulaştığı nisap miktarlarını, anlamı değiştirmeden nesnel ve doğru bir şekilde kendi cümleleriyle yeniden ifade etmesi istenir (OB4). Ayrıntılı ilmihal bilgilerinden kaçınılarak zekâtın kimlere verildiği ve toplumsal dayanışmaya etkisi açıklanır. Böylece öğrenciler, yaşadığı toplumdaki ihtiyaç sahibi bireylerin varlığını keşfederek zekâtın toplumsal adalet ve dayanışmayı sağlayan bir ibadet olduğu yargısında bulunur."},{"kod":"DKAB.8.2.2","metin":"Öğrencilerin sadaka kapsamında değerlendirilen davranışları kendi hayatlarına girişkenlikle (E2.3) yansıtabilmeleri için sadaka kavramı açıklanır. Herkesin imkânı nispetinde sadaka ibadetini yerine getirebileceği bilgisi verilir. Sadaka kapsamındaki davranışlar belirlenir ve bu davranışların Allah’ın (cc) rızasını kazanmak için yapıldığı açıklanır (OB1). Sadakayıcariye hakkında bilgi verilir. Öğrencilere “Birisi size yardım ederken neler hissedersiniz?” sorusu yöneltilir ve öğrencilerin sadaka kapsamındaki tecrübelerini gözden geçirmesi beklenir. Öğrencilerin güzel söz söylemek, insanlara karşı güler yüzlü olmak gibi davranışların da sadaka kapsamında değerlendirildiği çıkarımında bulunması sağlanır. Öğrenciler, öğrendiklerinden hareketle sadaka ibadetiyle ilgili özgün bir bütün oluşturur (OB4), sadakanın bireysel ve toplumsal katkıları hakkında ulaştığı sonuçları değerlendirir."},{"kod":"DKAB.8.2.3","metin":"Öğrencilerin zekât ve sadaka ibadetinin kültürümüze yansımaları hakkında gözlemlerinden hareketle tahminde bulunmaları için onlara “Sizce İslam dininde yardımlaşmaya niçin önem verilmiştir?” sorusu yöneltilir. Öğrencilerden zekât ve sadaka ibadetinin bireysel ve toplumsal katkılarını fark ederek kendi gözlem ve tecrübeleriyle ilişkilendirmeleri istenir. Öğrencilere çevrelerinde bulunan bazı okul, hastane, cami gibi çeşitli kurumların sadaka kültürü sayesinde inşa edildiği bilgisi verilir. Sadaka taşı, itimat bakkaliyesi ve vakıf gibi örnekler üzerinden zekât ve sadakanın kültürümüze yansımasına ilişkin çıkarım yapılır. Öğrencilerden zekât ve sadaka ibadetinin kültürümüzün ve yaşantımızın ayrılmaz bir parçası olduğu sonucuna ulaşmaları beklenir. Zekât ve sadaka ibadeti hakkında elde ettiği bilgilerden hareketle öğrencilerin hakkaniyetli davranmaları (D1.2), vicdanlı (D9.1) ve yardımsever olmaları (D20.1) sağlanır."},{"kod":"DKAB.8.2.4","metin":"Öğrencilere “Maun suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Öğrencilere Maun suresinin anlamı, içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Ancak surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Maun suresinin doğru telaffuzunu öğretmek için öğrencilerin genel ağ araçlarını tanımaları ve kullanmaları sağlanır. Maun suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Maun suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Zekât ve sadakanın bireysel ve toplumsal hayata katkıları hakkında belgesel hazırlanabilir. Öğrencilerden zekât ve sadakanın sosyolojik etkilerini konu edinen bilimsel makaleleri inceleyerek yorumlaması istenebilir."],"destekleme":["Zekât ve sadaka ibadetiyle ilgili kavramlardan oluşan sözcük avı hazırlanabilir. Zekât ve sadaka ibadetleriyle ilgili eğitici ve dijital içerikler kullanılabilir. İki gruba ayrılan öğrencilere bilgi notları verilerek onlardan afiş hazırlamaları istenebilir."],"ogretmenYansitmalari":[]},
{"no":3,"ad":"Din ve Sosyal Hayat","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/134","odak":"Ünitenin teması din ve hayattır. Bu ünitede, dinin gayesi ve sosyal hayattaki işlevi ele alınmaktadır. Öğrencilerin dinin temel gayesini sentezlemeleri ve sosyal hayattaki işlevini yapılandırmaları amaçlanmaktadır. Asr suresini ve bu surenin anlamını okuyarak yorumlamaları amaçlanmaktadır.","dersSaati":12,"alanBecerileri":["SBAB3. Tarihsel Empati (KB2.13. Yapılandırma)","SBAB16. Eleştirel Sosyolojik Düşünme (KB2.20. Sentezleme)"],"kavramsalBeceriler":["KB2.14. Yorumlama"],"egilimler":["E1.2. Bağımsızlık","E1.5. Kendine Güvenme (Öz Güven)","E3.11. Özgün Düşünme"],"sdb":[],"degerler":["D1. Adalet","D2. Aile Bütünlüğü","D5. Duyarlılık","D9. Merhamet","D13. Sağlıklı Yaşam","D17. Tasarruf","D18. Temizlik","D20. Yardımseverlik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.8.3.1","ad":"Dinin temel gayesi konusunu sentezleyebilme","surec":["a) Dinin korunmasını amaçladığı temel hakları inceler.","b) Dinin korunmasını amaçladığı temel haklar arasında ilişki kurar.","c) Dinin korunmasını amaçladığı temel hakların korunmasının dinin gayesi olduğunu anlayarak özgün bir bütün oluşturur."]},{"kod":"DKAB.8.3.2","ad":"Dinin sosyal hayattaki işlevini yapılandırabilme","surec":["a) Dinin sosyal hayattaki işlevini inceleyerek nedensel ilişkiler ortaya koyar.","b) Dinin sosyal hayattaki işleviyle ilgili kendi mevcut bilgisiyle elde ettiği ilişkilere dayalı unsurlardan hareketle uyumlu bir bakış açısı geliştirir."]},{"kod":"DKAB.8.3.3","ad":"Asr suresini ve bu surenin anlamını okuyarak yorumlayabilme","surec":["a) Asr suresini ve bu surenin anlamını okur.","b) Asr suresinin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Asr suresinin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Dinin Temel Gayesi","Dinin Sosyal Hayattaki İşlevi","Bir Sure Öğreniyorum: Asr Suresi"],"anahtarKavramlar":["hak","zaruratıdiniye"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritaları, bulmacalar (anagram, çengel, sözcük avı vb.), öz değerlendirme formu, örnek olay incelemesi ve sınıflandırma tablosu kullanılabilir.","Performans Görevi:","Dinin temel gayesi ve bu kapsamda korunan temel haklar ile ilgili hikâye yazmaları istenebilir. Dinin sosyal hayattaki işlevi ile ilgili duvar gazetesi hazırlanabilir. Asr suresi ve bu surenin anlamını içeren eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulabilir.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin İslam’ın insana önem verdiği bilgisine sahip oldukları kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Dinin amacı ne olabilir?” sorusu yöneltilerek dinin gayesine yönelik ön bilgi düzeyleri belirlenir."],"kopruKurma":["Öğrencilere günlük hayatlarında karşılaştıkları haberler hakkında sorular sorulur. Bu haberler ile temel hakların korunması arasında bağlantı kurulur."],"uygulamalar":[{"kod":"DKAB.8.3.1","metin":"Din kavramı hakkında bilgi verilir. Öğrencilere “Sizce dinin amacı ne olabilir?” sorusu sorulur. Öğrencilerin özgürce (E1.2) cevap verebilecekleri bir ortam oluşturulur. Dinin temel gayesi ele alınır. Öğrencilerden hak kavramını araştırmaları ve bu kavramın anlamını defterlerine kaydetmeleri istenir (OB1). Hak kavramı ele alınarak öğrencilerin haklarını ve özgürlüklerinibilmeleri (D1.1) gerektiğine değinilir. Öğrencilerden insanların doğuştan sahip olması gereken hakları belirlemeleri istenir. Öğrencilere İslam’ın koruduğu hakların neler olabileceğine dair fikirleri sorularak beş temel hakkın belirlenmesi sağlanır. İslam’ın temel haklar olarak saydığı can, nesil, akıl, mal ve dinin korunması konusuna giriş yapılır. Canın kutsal olduğu vurgulanır. Hayat hakkının hem din kuralları hem de hukuk kuralları ile korunduğu belirtilir. Sağlığı korumanın, kişisel bakımın (D18.1) ve tedavi olmanın canın korunması kapsamında olduğu bilgisi öğrencilere aktarılır. İş güvenliğinin ve tedbir almanın öneminden bahsedilerek canın korunmasının İslam dininde en çok önem verilen hak olduğunun kavranması sağlanır. Neslin korunmasında aile birliğinin ve aile içi iletişimin önemi vurgulanır (D2.1, D2.3). İslam dininin aile ilişkisine verdiği öneme ilaveten aile kurumunun toplumun temeli olduğundan, sağlıklı bir aile hayatı için nikah bağının olması gerektiğinden, eşler arasında sevgi ve saygı bağı olmasının öneminden ve çocuğa sağlıklı bir yetişme ortamı hazırlamanın ehemmiyetinden bahsedilir. Aklın öneminin fark edilmesi için öğrencilerin özgün düşünebilecekleri (E3.11) sorular sorulur. Cevaplar değerlendirilerek İslam’ın akıl sağlığına verdiği önem açıklanır. İslam’a göre akıl sağlığı yerinde olan insanların sorumluluk sahibi olduğu bilgisi aktarılır. Konu, bağımlılıklarla (D13.3) ilişkilendirilerek akıl sağlığına zarar veren tüm bağımlılıklardan uzak durulması gerektiği vurgulanır. Malın korunmasının mülkiyet, ekonomik haklar, üretim, alım, satım gibi hakları kapsadığı belirtilir. Mülk edinme hakkı, çalışmak ve emek vermek, emeğini helal yollarla kazanmak ve harcamak gibi konulara kısaca değinilir. Malın korunması ile ilgili hırsızlık, hile, rüşvet, kumar ve faiz kavramları tahtaya yazılarak açıklanır. Öğrencilerden bu kavramları defterlerine kaydetmeleri istenir (OB1). Öğrencilere sahip olduklarının değerini bilmenin (D17.3) ve israftan kaçınmanın (D17.2) önemi anlatılarak bilinçli harcama konusunda bilgi verilir. Öğrencilerin bu haklar arasında ilişki kurarak onlardan bu ilişkiyi kendi cümleleriyle yorumlamaları istenir. Dinin korunmasını istediği temel haklarla ilgili özgün bir bütün oluşturmaları amacıyla öğrencilere yazma etkinliği yaptırılabilir (OB1). Dini korumaya ilişkin bidat, hurafe ve tahrif kavramları açıklanır; öğrencilerden bu kavramları defterlerine kaydetmeleri istenir (OB1). Öğrencilerin farkındalığını arttırmak için batıl inançlardan örnekler verilir."},{"kod":"DKAB.8.3.2","metin":"Öğrencilere “Dinin toplumsal hayata katkıları nelerdir?” sorusu sorulur. Verilen cevaplar listelenir. İslam dininin sosyal hayata katkıda bulunan yönleri öğretmen rehberliğinde belirlenir. Dinin temel inanç, ibadet ve ahlaki esaslarının bireysel, sosyal ve iktisadi hayata etkileri ele alınır. Öğrencilerin bununla ilgili nedensel ilişkiler ortaya koyması sağlanır. Bu bağlamda namazın kılınışına ve cemaatle namaz konusuna değinilir. Öğrencilerden dinin sosyal hayata katkılarına ve toplumsal hayattaki işlevine dair çıkarımda bulunmaları istenir. Bu çıkarımlardan hareketle uyumlu bir bakış açısı geliştirmesi sağlanır. Bu çıkarımlarından hareketle öğrencilerin sosyal hayatta hakkaniyetli davranmanın (D1.2), insana ve topluma değer vermenin (D5.1), çevrelerindeki insanlara şefkat göstermenin (D9.2), dayanışma ve fedakarlığın (D20.2) önemini fark etmeleri beklenir (OB1)."},{"kod":"DKAB.8.3.3","metin":"Öğrencilere “Asr suresi hakkında neler biliyorsunuz?” sorusu yöneltilir. Asr kelimesinin anlamı açıklanarak Asr suresinin içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Asr suresi hakkında bilgi verilirken surenin Mekki-Medeni ayrımı, ayet sayısı ve Kur’an-ı Kerim’deki sıralaması gibi konulara değinilmez. Asr suresini dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) surenin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu sureyi kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Surenin anlamı incelenir. Surenin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak sure değerlendirilebilir. Öğrencilerin surenin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Asr suresinin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilere günlük hayatta karşılaşılan haberlerin hangi haklarla ilgili olduğu tespit ettirilerek bir makale yazdırılabilir veya gazete/dergi hazırlatılabilir. İslam’ın koruma altına aldığı temel hakların özellikleri ile ilgili bulmaca hazırlanabilir."],"destekleme":["Öğrencilerden dinin korunmasını amaçladığı temel haklarla ilgili bir kavram haritası oluşturması istenebilir."],"ogretmenYansitmalari":[]},
{"no":4,"ad":"Kur’an ve İnsan","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/135","odak":"Yazdır","dersSaati":14,"alanBecerileri":["SBAB16. Eleştirel Sosyolojik Düşünme (KB2.4. Çözümleme","KB2.20. Sentezleme)"],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.14. Yorumlama","KB2.15. Yansıtma"],"egilimler":["E1.5. Kendine Güvenme (Öz Güven)","E3.2. Odaklanma","E3.7. Sistematik Olma"],"sdb":["SDB1.3. Kendine Uyarlama (Öz Yansıtma)"],"degerler":["D1. Adalet","D5. Duyarlılık","D6. Dürüstlük","D9. Merhamet","D15. Sevgi","D16. Sorumluluk"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.8.4.1","ad":"İnsanın Kur’an-ı Kerim’de anlatılan özelliklerini sentezleyebilme","surec":["a) İnsanın Kur’an-ı Kerim’de anlatılan özelliklerini öğretmen rehberliğinde bulur.","b) İnsanın Kur’an-ı Kerim’de anlatılan özellikleri arasında ilişki kurar.","c) İnsanın Kur’an-ı Kerim’de anlatılan özellikleri hakkında özgün bir bütün oluşturur."]},{"kod":"DKAB.8.4.2","ad":"Kur’an-ı Kerim’in rehberliğini özetleyebilme","surec":["a) İnsanlığa rehber olarak Kur’an-ı Kerim’in dindeki yeri hakkında çözümleme yapar.","b) İnsanlığa rehber olarak Kur’an-ı Kerim’in ana konularını sınıflandırır.","c) Kur’an-ı Kerim’in rehberliğini kendi cümleleriyle anlatır."]},{"kod":"DKAB.8.4.3","ad":"Kur’an-ı Kerim’e göre Hz. Muhammed’in (sav) örnekliğini çözümleyebilme","surec":["a) Kur’an-ı Kerim’e göre Hz. Muhammed’in (sav) güzel ahlakını inceler.","b) Kur’an-ı Kerim’e göre Hz. Muhammed’in (sav) güzel ahlakıyla örnek davranışları arasındaki ilişkiyi inceler."]},{"kod":"DKAB.8.4.4","ad":"Hz. Lokman’ın öğütlerini kendi hayatına yansıtabilme","surec":["a) Lokman suresi, 12-19. ayetlerde tavsiye edilen davranışları gözden geçirir.","b) Hz. Lokman’ın öğütleri hakkında çıkarım yapar.","c) Hz. Lokman’ın öğütlerini Kur’an-ı Kerim’in insanlara örnek olması ve doğru yolu göstermesi bağlamında değerlendirir."]},{"kod":"DKAB.8.4.5","ad":"Ayetelkürsi’yi ve bu ayetin anlamını okuyarak yorumlayabilme","surec":["a) Ayetelkürsi’yi ve bu ayetin anlamını okur.","b) Ayetelkürsi’nin anlamını kendi hayatı için anlamlı bir hâle getirir.","c) Ayetelkürsi’nin anlamını değiştirmeyecek şekilde özetler."]}],"icerikCercevesi":["Kur’an-ı Kerim’de İnsanın Özellikleri","Kur’an-ı Kerim’in Rehberliği","Kur’an’ın Örnek Gösterdiği İnsan: Hz. Muhammed (sav)","Hz. Lokman’dan Öğütler","Bir Ayet Öğreniyorum: Ayetelkürsi"],"anahtarKavramlar":["hidayet","muamelat","sünnet","üsveihasene"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritaları, bulmacalar (anagram, çengel, sözcük avı vb.) ve öz değerlendirme formu kullanılabilir.","Performans Görevi:","İnsanın Kur’an-ı Kerim’de anlatılan özellikleri hakkında münazara yapılabilir. Kur’an-ı Kerim’in rehberliği hakkında sosyal sorumluluk projesi hazırlanabilir. Günümüzdeki toplumsal sorunlar tespit edilerek bu sorunlara Hz. Muhammed’in (sav) güzel ahlakından hareketle çözümlerin önerildiği bir metin hazırlanabilir. Hz. Lokman’ın öğütleri hakkında sunu hazırlanabilir. Ayetelkürsi ve bu ayetin anlamıyla ilgili eşleştirme etkinliği hazırlanabilir. Performans görevleri, ölçütlere göre oluşturulan puanlama anahtarıyla değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin Kur’an-ı Kerim’i Müslümanların ilahi kitabı olarak tanıdığı ve onun özellikleri hakkında bilgi sahibi olduğu kabul edilmektedir."],"onDegerlendirme":["Kur’an-ı Kerim hakkında sorular yöneltilerek öğrencilerin ön bilgileri harekete geçirilir ve sorulara verdikleri cevaplara göre hazır bulunuşlukları kontrol edilir."],"kopruKurma":["Öğrencilere “Kur’an-ı Kerim’in temel özellikleri nelerdir?” sorusu sorulur. Mevcut hazır bulunuşlukları ile 5. sınıf “Kur’an-ı Kerim” ünitesinde öğrendikleri arasında ilişki kurulur."],"uygulamalar":[{"kod":"DKAB.8.4.1","metin":"İnsanın Kur’an-ı Kerim’de anlatılan özelliklerini sistematik olarak (E3.7) sentezlemeleri için öğrencilere sorular yöneltilir. Ayet ve hadislerden yararlanılarak insanın Kur’an-ı Kerim’de anlatılan özellikleri belirlenir. Bu özellikler arasında ilişki kurularak insanda iyi ve kötü tarafların bulunduğu açıklanır. Öğrencilerin insanın Kur’an-ı Kerim’de anlatılan özellikleri hakkında özgün bir bütün oluşturarak güzel özellikleri kendi hayatında uygulaması sağlanır. Öğrenciler; insanın Kur’an-ı Kerim’de anlatılan özellikleriyle ilgili elde ettikleri bilgileri öğretmenleriyle birlikte değerlendirerek doğrular ve afiş, broşür, pano, duvar gazetesi gibi yollarla kaydeder (OB1)."},{"kod":"DKAB.8.4.2","metin":"Öğrencilerin Kur’an-ı Kerim’in rehberliğini odaklanarak (E3.2) özetlemeleri için İslam’ın ana kaynaklarının Kur’an-ı Kerim ve sünnet olduğu hakkında çözümleme yapılır. Öğrencilere “Kur’an-ı Kerim’de yer alan konular hakkında neler biliyorsunuz?” sorusu yöneltilerek Kur’an’ın ana konuları inanç, ibadet, ahlak, sosyal hayat ve kıssalar olarak sınıflandırılır. Bu konular ekseninde öğrencilerin Kur’an-ı Kerim’in rehberliğini fark etmeleri ve elde ettikleri bilgileri kendi cümleleriyle yorumlamaları sağlanır. Böylece öğrencilerin ölçülü ve dengeli olmaları (D1.3), insana ve topluma değer vermeleri (D5.1) ve görev bilincine sahip olmaları (D16.3) beklenir."},{"kod":"DKAB.8.4.3","metin":"Kur’an-ı Kerim’e göre Hz. Muhammed’in (sav) insani ve peygamberlik yönü açıklanır. Üsveihasene kavramı Ahzab suresinin 21. ayeti bağlamında ele alınır. Hz. Muhammed’in (sav) güzel ahlakı Kalem suresi 4. ayetten yola çıkılarak incelenir. Günlük hayattaki davranışlarından ve hadislerden verilen örneklerle, Hz. Muhammed’in (sav) doğruluğu ve güvenilir kişiliği (D6.2), merhametli ve affedici oluşu (D9.2), istişareye önem vermesi, davasındaki cesaret ve kararlılığı, hakkı gözetmedeki hassasiyeti (D1.2) ve insanlara değer vermesi (D15.1) açıklanır. Böylelikle güzel ahlakı ve örnek davranışları arasında ilişki kurulur. Öğrendiklerinden hareketle Hz. Muhammed’in (sav) neden örnek alınması gerektiğine dair öğrencilerin düşüncelerini ifade edebileceği bir etkinlik yapılır."},{"kod":"DKAB.8.4.4","metin":"Öğrencilerin Hz. Lokman’ın öğütlerini kendi hayatlarıa yansıtması için Lokman suresi, 12-19. ayetlerde tavsiye edilen davranışlar listelenir ve bu davranışları gözden geçirmeleri istenir. Öğrencilerin Hz. Lokman’ın öğütleri hakkında çıkarımda bulunmaları sağlanır. Böylece öğrenciler, Kur’an-ı Kerim’in insanlara örnek olması ve doğru yolu göstermesi bağlamında Hz. Lokman’ın öğütlerini değerlendirir ve bu öğütleri davranışlarına yansıtmaları hedeflenir (SDB1.3)."},{"kod":"DKAB.8.4.5","metin":"Öğrencilere “Ayetelkürsi hakkında neler biliyorsunuz?” sorusu yöneltilir. Ayetelkürsi’nin anlamı, içerdiği mesajlar ve nerelerde okunduğu hakkında bilgi verilir. Ayetelkürsi’nin doğru telaffuzunu öğretmek için öğrencilerin genel ağ araçlarını tanımaları ve kullanmaları sağlanır. Ayetelkürsi’yi dinlemek üzere Diyanet İşleri Başkanlığına bağlı genel ağ adresleri belirlenir. Öğrencilerin bu adresleri kullanmaları sağlanarak (OB2) ayetin doğru telaffuzunu öğrenmeleri için dinleme etkinliği yapılır. Öğrencilerin bu ayeti kendine güvenerek (E1.5) okuması için sesli okuma etkinliği yapılabilir. Ayetin anlamı incelenir. Ayetin anlamından çıkarılacak mesajlarla ilgili etkinlikler yapılarak ayet değerlendirilebilir. Öğrencilerin ayetin anlamını kendi hayatı için anlamlı hâle getirmesi sağlanır. Öğrencilerin Ayetelkürsi’nin anlamını değiştirmeyecek şekilde kendi cümleleriyle yeniden ifade etmeleri için yazma etkinliği yapılabilir."}],"zenginlestirme":["Öğrencilerden Kur’an-ı Kerim’in ana konuları hakkında bilgi grafiği hazırlaması istenebilir. Ünitede öğrenilen konular bağlamında “Kur’an’ı Tanıyalım” bülteni veya panosu hazırlanabilir."],"destekleme":["Konuyla ilgili yazılmış hikâyeler, görsel materyaller ve etkileşimli dijital uygulamalar kullanılabilir."],"ogretmenYansitmalari":[]},
{"no":5,"ad":"Müslümanların Bilim ve Kültüre Katkısı","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/136","odak":"değerlendirmeleri amaçlanmaktadır.","dersSaati":12,"alanBecerileri":["SBAB3. Tarihsel Empati (SBAB3.1. Tarihsel Bağlamsallaştırma)","SBAB16. Eleştirel Sosyolojik Düşünme (KB2.8. Sorgulama)"],"kavramsalBeceriler":["KB2.20. Sentezleme"],"egilimler":["E3.7. Sistematik Olma","E3.8. Soru Sorma"],"sdb":[],"degerler":["D3. Çalışkanlık"],"okuryazarlik":[],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.8.5.1","ad":"İslam kültür ve medeniyetinin esasları konusunu sentezleyebilme","surec":["a) İslam kültür ve medeniyetinin esaslarını inceler.","b) İslam kültür ve medeniyetinin esasları arasında ilişki kurar.","c) İslam kültür ve medeniyetinin esaslarını birleştirerek özgün bir bütün oluşturur."]},{"kod":"DKAB.8.5.2","ad":"İslam’ın bilime verdiği önemi ve katkıyı sorgulayabilme","surec":["a) Bilim kavramını tanımlar.","b) İslam’ın bilime verdiği önem hakkında sorular sorar.","c) İslam’ın bilime verdiği önemle ilgili bilgi toplar.","ç) İslam’ın bilime verdiği önemle ilgili toplanan bilgilerin doğruluğunu öğretmen rehberliğinde değerlendirir.","d) İslam’ın bilime verdiği önemle ilgili toplanan bilgiler üzerinde çıkarım yapar."]},{"kod":"DKAB.8.5.3","ad":"Müslüman bilim insanlarının bilim ve kültüre katkısını tarihsel bağlamda","surec":["değerlendirebilme","a) Müslüman bilim insanlarının bilim ve kültüre katkısını farkeder.","b) Müslüman bilim insanlarının bilim ve kültüre katkısını, yaşadıkları dönemlerin koşulları içerisinde açıklar.","c) Müslüman bilim insanlarının katkılarını analiz eder.","ç) Müslüman bilim insanlarının kendi koşullarını günümüz koşullarıyla karşılaştırır."]}],"icerikCercevesi":["İslam Kültür ve Medeniyetinin Esasları","İslam’da Bilimin Önemi","Müslüman Bilim İnsanları"],"anahtarKavramlar":["bilim","kültür","medeniyet"],"olcmeDegerlendirme":["Bu ünitenin ölçme değerlendirme sürecinde açık uçlu soru, kısa cevaplı soru, çalışma yaprağı, kavram haritası, bulmacalar ve öz değerlendirme formu, kullanılabilir.","Performans Görevi:","İslam kültür ve medeniyetinin esasları konulu panel etkinliği hazırlanabilir. İslam’da bilimin yerini ve önemini anlatan bir sunu hazırlanabilir. Bilim insanlarının hayatlarını ve çalışmalarını araştırarak okul panosu, afiş veya dergi hazırlanabilir. Performans görevleri ölçütlere göre oluşturulan puanlama anahtarı ile değerlendirilir. Öğrencinin ünite süresince yaptığı ürün çıktıları bir araya getirilerek öğrenci ürün dosyası oluşturulur.","Sonuç değerlendirmede performans görevlerine yer verilebileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin, Müslüman bilim insanlarının varlığı hakkında bilgi sahibi olduğu kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Müslüman bilim insanlarından kimleri tanıyorsunuz?” ve “Bu bilim insanlarının öncü çalışmaları nelerdir?” soruları sorularak konuya dair bilgi düzeyleri kontrol edilir."],"kopruKurma":["İslam kültür ve medeniyetine ait unsurlar örneklendirilerek bunlar ile ünite arasında bağlantı kurulur."],"uygulamalar":[{"kod":"DKAB.8.5.1","metin":"İslam kültür ve medeniyetinin esasları hakkında öğrencilere farkındalık kazandırmak ve konuya ilgilerini çekmek için sorular yöneltilir (E3.8). Kültür ve medeniyet kavramları açıklanır. İslam kültür ve medeniyetine ait örnekler verilerek öğrencilere kültürel mirasın önemi fark ettirilir. İslam kültür ve medeniyetinin esasları bütünsellik, özgünlük, evrensellik ve bilimsellik olarak belirlenir. Bu esaslar arasında parça-bütün ilişkisi kurulur. Öğrencilerin bu esasları birleştirerek İslam kültür ve medeniyeti hakkında bir metin yazması veya afiş, pano vs. hazırlaması sağlanır."},{"kod":"DKAB.8.5.2","metin":"Öğrenciler bilim kavramını tanımlar. Öğrencilerin, İslam’ın bilime verdiği önem hakkında merak ettikleri soruları sormaları (E3.8) için sınıfta uygun bir ortam oluşturulur ve sorulan sorular cevaplanır. Öğrencilerin konuyla ilgili bilgi toplaması sağlanır. İslam dininin akla, düşünmeye, eğitime verdiği önem ayet ve hadislerin ışığında açıklanır. İslam biliminde Hz. Ali’nin önemi vurgulanır. Öğrenciler elde ettikleri bilgileri öğretmen rehberliğinde doğrulayarak değerlendirir. Öğrenciler bu bilgiler üzerinden çıkarım yapar. Konuyla ilgili olarak Bilim ve Teknoloji Haftası’na değinilir."},{"kod":"DKAB.8.5.3","metin":"Öğrencilerden Müslüman bilim insanlarının hayat hikâyeleriyle ilgili kaynaklara dayanarak sistematik (E3.7) bir şekilde araştırma yapması ve onların bilim ve kültüre katkısını farketmesi sağlanır. Çalışmaların değerinin ve özgünlüğünün öneminin anlaşılması için Müslüman bilim insanlarının bilim ve kültüre katkısı, yaşadıkları dönemlerin koşulları içerisinde açıklanır. Konu içerisinde Cabir bin Hayyan, Harizmi, Fatıma el-Fihrî, İbni Sina, İbnülheysem, Cezeri, İbni Haldun, Ali Kuşçu, Mimar Sinan ve Fuat Sezgin isimlerine yer verilir. Bu bilim insanlarının içinde yaşadıkları dönemin zorluklarına rağmen çalışmalarını azim ve kararlılıkla (D3.1) sürdürdüklerinin üzerinde durulur. Öğrenciler bu bilim insanlarının çalışkanlıklarını örnek almaları konusunda teşvik edilir. Öğrencilerin, Müslüman bilim insanlarının bilim dünyasına katkıları ve bu katkıların günümüze kadar devam eden etkilerini analiz etmeleri sağlanır. Müslüman bilim insanlarının koşulları günümüz koşullarıyla karşılaştırılır ve değerleri açıklanır. Çalışmalarının günümüzdeki yansımaları hakkında farkındalık kazandırılır."}],"zenginlestirme":["Öğrencilere merak ettikleri bir bilim insanının hayatını araştırarak sunu hazırlama görevi verilebilir. (Farabi, Uluğ Bey vb.)"],"destekleme":["Öğrencilere, ünitede bilgi verilen bilim insanlarının isimlerinden ve bu insanların öne çıktığı bilim alanlarından oluşan eşleştirme etkinliği yaptırılabilir. Bu bilim insanlarının isimlerini içeren bir bulmaca veya kelime avı hazırlanabilir."],"ogretmenYansitmalari":[]}],"s9":[{"no":1,"ad":"Allah-İnsan İlişkisi","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/139","odak":"ele alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.8. Sorgulama","KB2.15. Yansıtma","KB3.3. Eleştirel Düşünme"],"egilimler":["E3.2. Odaklanma","E3.6. Analitik Düşünme","E3.8. Soru Sorma"],"sdb":["SDB1.3. Kendine Uyarlama (Öz Yansıtma)","SDB2.1. İletişim"],"degerler":["D12. Sabır","D16. Sorumluluk"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.9.1.1","ad":"İnsanın yaratılışını ve özelliklerini ayetlerden hareketle tefekkür ederek sorgulayabilme","surec":["a) İnsanın yaratılışı ve özellikleri ile ilgili merak ettiklerini tanımlar.","b) İnsanın yaratılışına ve özelliklerine dair sorular sorar.","c) İnsanın yaratılışına ve özelliklerine dair İslam’ın temel kaynaklarından bilgiler toplar.","ç) İnsanın yaratılışına ve özelliklerine dair topladığı bilgileri değerlendirir.","d) İnsanın yaratılışına ve özelliklerine dair çıkarımlarda bulunur."]},{"kod":"DKAB.9.1.2","ad":"İnsanın doğruyu arayan bir varlık olarak bilgiye ulaşma yolları hakkında eleştirel düşünebilme","surec":["a) İnsanın hakikate ulaşma konusunda vahiy ve peygamberlere olan ihtiyacını fark eder.","b) Vahyin ve peygamberin gönderiliş amacına dair akıl yürütür.","c) Akıl yürütmeyle ulaştığı çıkarımları yansıtır."]},{"kod":"DKAB.9.1.3","ad":"Allah (cc) ile iletişimin ibadet ve dua ile sağlandığını yansıtabilme","surec":["a) İbadet ve dua deneyimlerini gözden geçirir.","b) İbadet ve dua deneyimlerine dayalı çıkarım yapar.","c) İbadet ve dua deneyimlerine dayalı yaptığı çıkarımları değerlendirir."]},{"kod":"DKAB.9.1.4","ad":"Rum suresi 17-27. ayetlerin mesajlarını özetleyebilme","surec":["a) Ayetlerde verilen mesajlarla ilgili çözümleme yapar.","b) Ayetlerde geçen konuları sınıflandırır.","c) Ayetlerde verilen mesajları açıklar."]}],"icerikCercevesi":["İnsan ve İnsanın Yaratılışı","Doğruyu Arayan Bir Varlık Olarak İnsan","İbadet ve Dua Eden Bir Varlık Olarak İnsan","Kur’an’dan Mesajlar"],"anahtarKavramlar":["dua","fıtrat","hamt","marifet","mükellef","tövbe"],"olcmeDegerlendirme":["Öğrenme çıktıları; açık uçlu sorular, evet-hayır kartları, çalışma yaprağı, dereceleme ölçeği, öz değerlendirme formu ve dereceli puanlama anahtarı kullanılarak değerlendirilebilir.","Allah’ın (cc) güzel isimlerinin yer aldığı dua örneklerinden bir sınıf panosu hazırlama, performans","görevi olarak verilebilir. Bu performans görevi “bilgi toplama, çıkarım yapma, içerik ve sunma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin evrenin tesadüfen oluşmadığını ve bir yaratıcıya ihtiyaç olduğunu bildikleri kabul edilmektedir."],"onDegerlendirme":["İnsanın yaratılış amacının ne olduğuyla ilgili sorular sorularak öğrencilerin verdikleri cevaplara göre ön bilgileri belirlenmeye çalışılır. Öğrencilere hangi peygamberleri ve ilahi kitapları bildikleri sorulur. Ardından Allah’ın (cc) neden ilahi kitap ve peygamber gönderdiğini tartışmaları istenir. Bu süreçte öğrencilerin hazır bulunuşlukları kontrol edilmiş olur."],"kopruKurma":["Öğrencilere çevrelerindeki herhangi bir varlığın yaratılış amacı sorulur. Gelen cevaplardan hareketle insanın yaratılış amacının ne olabileceğine dair tartışma ortamı oluşturulur. Dünyadaki diğer varlıkların yaratılış amacının ne olduğu üzerine konuşmalar yapılır. Öğrencilerin görüşleri alınarak konuyla ilişki kurulur."],"uygulamalar":[{"kod":"DKAB.9.1.1","metin":"Öğrencilere çevrelerindeki varlıkların yaratılış amacı sorularak konuya dikkat çekilir (E3.2). İnsanın yaratılışı ve özelliklerine dair öğrencilerin merak ettiklerini tanımlaması sağlanır (OB1, E3.8). İnsanın yaratılışı ve özellikleriyle ilgili soru sormalarına imkân tanınır. Bu konuda soru turu tekniği kullanılabilir. Öğrencilerden İslam’ın temel kaynaklarından konuyla ilgili bilgi toplaması istenir ve konuyu öğretmen rehberliğinde değerlendirmeleri beklenir. Yüce Allah’ın, insanı mükemmel bir varlık olarak yarattığına ilişkin öğrencilerin çıkarımlarda bulunması sağlanır. Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir. Öğrencilerin insanın yaratılış amacının farkına vararak kendisine, ailesine, topluma ve Allah’a (cc) karşı sorumluluk bilinci kazanması beklenir (D16.2)."},{"kod":"DKAB.9.1.2","metin":"İnsanın hakikate ulaşma konusunda kullandığı bilgi kaynakları değerlendirilir. Bunun için beyin fırtınası tekniği kullanılabilir. Öğrenciler, bazı bilgilere duyu organları ve akıl yoluyla ulaşılamayacağını öğretmen rehberliğinde verilen örnekler üzerinden fark eder. İnsanın vahiy ve peygambere olan ihtiyacı vurgulanır. Konuyla ilgili ayetler incelenir. Öğrenciler ilgili ayetlerden hareketle vahyin ve peygamberin gönderiliş amacına dair akıl yürüterek çıkarımda bulunur (E3.6). Öğrenciler hakikati arayan bir varlık olarak doğru bilgiye ulaşmada akıl ve duyularla birlikte vahiyden faydalanır. Allah’ın (cc) Hâdi ismine konu ile bağlantı kurularak vurgu yapılır. Ölçme ve değerlendirme uygulamalarında öğrencilerden bir değerlendirme metni yazmaları istenebilir. Yazılan metinler dereceleme ölçeği ile değerlendirilebilir."},{"kod":"DKAB.9.1.3","metin":"Allah (cc) ile bağ kurmanın ibadet, dua, tövbe etmek ve Kur’an okumakla sağlandığına vurgu yapılır. Kur’an-ı Kerim ve hadislerde geçen dua örnekleri incelenir. Öğrencilerden birer dua örneği yazmaları istenir. Bu yolla dua konusundaki deneyimlerini öğrenciler gözden geçirirler. İbadet ve duanın insana katkılarının neler olacağına dair öğrencilerin kendi deneyimlerinden hareketle çıkarım yapmaları beklenir (SDB1.3). Yapılan çıkarımlar evet-hayır kartları ile değerlendirilebilir. Öğrenci dua ve ibadetlerin zorluklarla mücadelede kendisine güç ve moral verebileceğini fark eder. İradesiyle değiştirebileceği ve değiştiremeyeceği olayları ve durumları ayırt eder (D12.1). İbadet ve dua konusu Allah’ın (cc) Mucib, Tevvab, Gaffar, Settar ve Afüv isimleri çerçevesinde değerlendirilir. Ölçme ve değerlendirme uygulamalarında eşleştirme, boşluk doldurma ve kısa cevaplı sorulardan oluşan çalışma yaprağı kullanılabilir."},{"kod":"DKAB.9.1.4","metin":"Rum suresinin 17-27. ayetleri, Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetlerin nüzul sebeplerine, ayetlerde geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayetlerde verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler, ayetlerde ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında boşluk doldurma, doğru-yanlış, kısa cevaplı ve açık uçlu soru türlerinden oluşan çalışma yaprağı kullanılabilir."}],"zenginlestirme":["Öğrencilerden Kur’an-ı Kerim’de geçen peygamber dualarından oluşan fanzin (küçük ölçekli dergi) hazırlamaları istenebilir. Görsel sanatlara ilgisi olan öğrencilerin ünitede verilen esmayıhüsna ile ilgili hat levhalarını incelemelerine ve bu alanda ürün oluşturmalarına imkân sağlanabilir."],"destekleme":["Öğrencilerin öğrenme süreçlerine katılımlarını artırmak için gerekli araç gereçler hazırlanır ve ortam düzenlemesi yapılır. Öğrenciler sesli metin, video, soru cevap etkinlikleri ile desteklenebilir."],"ogretmenYansitmalari":[]},
{"no":2,"ad":"İslam’da İnanç Esasları","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/140","odak":"Bu ünitenin odak noktasını İslam’da inanç esasları oluşturmaktadır. Öğrencilerin iman ve imanın mahiyetiyle ilgili konuları sorgulayabilmesi, iman esaslarını ayet ve hadislerden hareketle özetleyebilmesi, imanın bireye ve topluma kazandırdıklarını yansıtabilmesi amaçlanır. İnancın hayatı nasıl etkilediği ve şekillendirdiğine yer verilerek bu konuda bir farkındalık oluşturulması hedeflenir. Kur’an’dan mesajlar bölümünde Bakara suresinin 177. ayeti ele alınır. Öğrencilerin bu ayette verilen mesajları özetleyebilmesi beklenir.","dersSaati":16,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.8. Sorgulama","KB2.15. Yansıtma"],"egilimler":["E1.1. Merak","E3.4. Gerçeği Arama","E3.7. Sistematik Olma"],"sdb":["SDB2.1. İletişim","SDB2.3. Sosyal Farkındalık","SDB3.3. Sorumlu Karar Verme"],"degerler":["D5. Duyarlılık","D20. Yardımseverlik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.9.2.1","ad":"İman ve imanın mahiyetiyle ilgili konuları sorgulayabilme","surec":["a) İman ve imanın mahiyetiyle ilgili merak ettiği konuları tanımlar.","b) İman ve imanın mahiyetini anlayabilmek için sorular sorar.","c) İman ve imanın mahiyeti hakkında bilgi toplar.","ç) İman ve imanın mahiyeti hakkında toplanan bilgileri değerlendirir.","d) İman ve imanın mahiyeti hakkında toplanan bilgiler üzerinde çıkarım yapar."]},{"kod":"DKAB.9.2.2","ad":"İslam’ın iman esaslarını ayet ve hadisler bağlamında özetleyebilme","surec":["a) Ayet ve hadislerden hareketle İslam’ın iman esaslarına ilişkin çözümleme yapar.","b) Ayet ve hadislerden hareketle iman esaslarını sınıflandırır.","c) Ayet ve hadislerden hareketle iman esaslarını açıklar."]},{"kod":"DKAB.9.2.3","ad":"İmanın bireye ve topluma kazandırdıklarını yansıtabilme","surec":["a) İmanın bireye ve topluma kazandırdıkları ile ilgili izlenim veya deneyimlerini gözden geçirir.","b) İmanın bireye ve topluma kazandırdıkları ile ilgili izlenim ve deneyimlerine dayalı çıkarımlar yapar.","c) İmanın bireye ve topluma kazandırdıkları ile ilgili ulaştığı çıkarımları değerlendirir."]},{"kod":"DKAB.9.2.4","ad":"Bakara suresinin 177. ayetindeki mesajları özetleyebilme","surec":["a) Ayette verilen mesajlarla ilgili çözümleme yapar.","b) Ayette geçen konuları sınıflandırır.","c) Ayette verilen mesajları açıklar."]}],"icerikCercevesi":["İman ve İmanın mahiyeti","İslam’da İman Esasları","İmanın Bireye ve Topluma Kazandırdıkları","Kur’an’dan Mesajlar"],"anahtarKavramlar":["ahiret","iman","kutsal kitap","melek","tevhit"],"olcmeDegerlendirme":["Öğrenme çıktıları; açık uçlu sorular, çıkış kartları, 3-2-1 kartı, kavram haritası, öz değerlendirme formu ve dereceli puanlama anahtarı kullanılarak değerlendirilebilir.","İmanla ilgili temel kavramlar, iman esasları, imanın birey ve topluma katkılarıyla ilgili bilgi haritası hazırlama, performans görevi olarak verilebilir. Bu performans görevi, “konu hakkında bilgi toplama, ilişkilendirme, çözümleme, çıkarım yapma ve sunma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formuyla değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["İmanın şartları konusunda öğrencilerin temel bilgilere sahip oldukları kabul edilmektedir."],"onDegerlendirme":["Öğrencilerin “İman nedir, imanın şartları nelerdir, imanın bireye ve topluma kazandırdıkları nelerdir?” sorularına verdikleri cevaplara göre ön bilgileri belirlenir. İnsanın duygu, düşünce ve davranışları üzerinde Allah’a (cc), meleklere, kitaplara, peygamberlere, ahirete, kadere ve kazaya inanmanın nasıl ve ne tür etkilerinin olabileceğiyle ilgili bir tartışma ortamı oluşturularak öğrencilerin hazır bulunuşlukları kontrol edilir."],"kopruKurma":["Geçmişteki her toplumun yüce bir varlık inancına sahip olduğuna değinilir. Bu konuyla ilgili belgesellerden çeşitli bölümler izletilerek bütün insanların doğasında inanma duygusunun var olduğuna dikkat çekilebilir. İnancın hayatı anlamlandırmaya katkı sağladığı, huzur ve güven duygusunu geliştirdiği, güzel ahlaka yönlendirdiği örneklerle ele alınarak gerçek hayatla köprü kurulur."],"uygulamalar":[{"kod":"DKAB.9.2.1","metin":"İnsanın inanma duygusuna doğuştan sahip olduğu vurgulanır, bu olgu geçmiş toplumlardan verilen örneklerle açıklanır. Öğrenciler imanın mahiyetiyle ilgili merak ettiklerini tanımlar (E1.1). Konuyla ilgili sorular sorar ve bu soruları listeler. Bu süreçte beyin fırtınası tekniği kullanılabilir. İman kavramı tanımlanarak imanın kalp ile tasdik dil ile ikrar olduğuna değinilir. Öğretmen konuyla ilgili yapılandırılmış bir metni öğrencilerle paylaşır. Bu metinden hareketle öğrenciler, ayet ve hadislerden imanın mahiyetine dair bilgi toplar ve arkadaşlarıyla paylaşır (E3.4, OB1). Öğrenciler bu bilgileri öğretmen rehberliğinde değerlendirir ve değerlendirmelerine dayalı çıkarımlar yapar. Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."},{"kod":"DKAB.9.2.2","metin":"İman esasları ile ilgili ayet ve hadisler öğrencilerle paylaşılır. Öğrenciler tarafından ayet ve hadisler doğrultusunda iman esaslarına ilişkin çözümlemeler yapılır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayet ve hadisleri konularına göre sınıflandırır. Bu aşamada yapılandırılmış grid tekniği kullanılabilir. Öğrencilerin ayet ve hadislerden hareketle sistematik bir bakış açısıyla iman esaslarının ayrılmaz bir bütün olduğunu açıklamalarına imkân tanınır (E3.7). Öğrencilerden iman esaslarıyla ilgili görüş ve yorumlarını birbirleriyle paylaşmaları istenir (SDB2.1). Ölçme ve değerlendirme uygulamalarında çıkış kartları kullanılabilir."},{"kod":"DKAB.9.2.3","metin":"Öğrencilere imanın bireye ve topluma kazandırdıklarının neler olduğu sorulur ve öğrenciler konuyla ilgili izlenim ve deneyimlerini paylaşır. İmanın insanı güzel ahlaka yönlendirdiği, kaygıdan uzak tuttuğu, yalnızlıktan kurtardığı, insana huzur ve güven verdiğine vurgu yapılır. Bununla birlikte toplumda birlik, düzen ve istikrarı sağladığı, iyilik ve merhamet duygularını canlı tuttuğu, yardımlaşma ve dayanışma ruhu kazandırdığı belirtilir. Öğrenciler izlenim ve deneyimlerine dayalı çıkarımlar yapar. Bu süreçte görüş geliştirme tekniği kullanılabilir. Öğrenciler imanın bireye ve topluma kazandırdıklarına yönelik ulaştığı çıkarımları kendi ifadeleriyle değerlendirir (SDB2.3, SDB3.3). Ölçme ve değerlendirme uygulamalarında 3-2-1 kartı kullanılabilir. Öğrenci, imanın insana ve topluma kazandırdıklarının farkında olarak kendisinin ve başkalarının istekleri arasında denge kurar ve çevresindekilere duyarlı, sabırlı, anlayışlı ve nazik davranır. Bu süreçte ahlaki muhakeme yöntemi kullanılabilir (D5.2)."},{"kod":"DKAB.9.2.4","metin":"Bakara suresi 177. ayetin meali, Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetin nüzul sebebine, ayette geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayette verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayette ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında kavram haritası kullanılabilir. Bakara suresi 177. ayetin mesajı çerçevesinde öğrencilerin sahip olduklarını (para, mal, bilgi vb.) başkalarıyla paylaşması gerektiğinin farkına varması ve insanlara yardım etmekten mutluluk duyacağı bir anlayışa ulaşması hedeflenir. Bu değerin kazandırılma sürecinde yaparak yaşayarak öğrenme modeli tercih edilebilir (D20.1)."}],"zenginlestirme":["Konuyla ilgili güvenilir kaynaklardan çeşitli belgeseller önerilir. Öğrencilerden inancın hayata yansımasıyla ilgili kısa bir film hazırlamaları istenebilir."],"destekleme":["Öğrencilerin öğrenme süreçlerine katılımlarını artırmak için gerekli görsel-işitsel araç gereçler hazırlanır ve ortam düzenlemesi yapılır. Öğrenciler sesli metin, video, soru cevap etkinlikleri ile desteklenebilir. Öğrencilerin gruplar hâlinde çalışmaya yönlendirilmesi ve daha fazla rehberlik ve destek sunulmasıyla öğrenme süreçleri desteklenir."],"ogretmenYansitmalari":[]},
{"no":3,"ad":"İslam’da İbadetler","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/141","odak":"Bu ünitenin odak noktasını İslam’da ibadetler oluşturmaktadır. Öğrencilerin İslam’da ibadet ve ibadetin temel ilkeleri hakkında bilgi toplayabilmesi, öğretmen rehberliğinde temel ibadetleri sınıflandırabilmesi, insan ve ibadet ilişkisini yorumlayabilmesi amaçlanır. Kur’an’dan mesajlar bölümünde Bakara suresi 21, Zariyat suresi 56 ve Hicr suresi 99. ayetler ele alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.5. Sınıflandırma","KB2.6. Bilgi toplama","KB2.14. Yorumlama"],"egilimler":["E3.7. Sistematik Olma"],"sdb":["SDB1.3. Kendine Uyarlama (Öz Yansıtma)","SDB2.1. İletişim","SDB2.2. İş Birliği","SDB2.3. Sosyal Farkındalık"],"degerler":["D3. Çalışkanlık","D4. Dostluk","D6. Dürüstlük","D20. Yardımseverlik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.9.3.1","ad":"İslam’da ibadet ve ibadetin temel ilkeleri hakkında bilgi toplayabilme","surec":["a) İslam’da ibadet ve ibadetin temel ilkeleri hakkında bilgiye ulaşmak için kullanacağı kaynakları araştırır.","b) Kaynakları kullanarak İslam’da ibadet ve ibadetin temel ilkelerine dair bilgileri bilgi toplar.","c) İslam’da ibadet ve ibadetin temel ilkeleri hakkında ulaştığı bilgileri temel kaynaklardan faydalanarak doğrular.","ç) İslam’da ibadet ve ibadetin temel ilkeleri hakkında ulaştığı bilgileri kaydeder."]},{"kod":"DKAB.9.3.2","ad":"İslam’da temel ibadetleri sınıflandırabilme","surec":["a) Dinin temel kaynaklarından ibadetlerin sınıflandırılmasında kullanılan ölçütleri açıklar.","b) Sınıflandırma ölçütlerine göre İslam’da temel ibadetleri ayırt eder.","c) İslam’da temel ibadetleri tasnif eder.","ç) İslam’da temel ibadetlerin neler olduğunu isimlendirir."]},{"kod":"DKAB.9.3.3","ad":"İnsan ve ibadet ilişkisini yorumlayabilme","surec":["a) İnsan ve ibadet ilişkisini inceler.","b) İnsan ve ibadet ilişkisini kendi hayatı için anlamlı hâle getirir.","c) İnsan ve ibadet ilişkisini nesnel ve doğru bir şekilde ifade eder."]},{"kod":"DKAB.9.3.4","ad":"Bakara suresi 21, Zariyat suresi 56 ve Hicr suresi 99. ayetlerin mesajlarını özetleyebilme","surec":["a) Ayetlerde verilen mesajlarla ilgili çözümleme yapar.","b) Ayetlerde geçen konuları sınıflandırır.","c) Ayetlerde verilen mesajları açıklar."]}],"icerikCercevesi":["İslam’da İbadetin Kapsamı","İslam’da Temel İbadetler","İnsan ve İbadet","Kur’an’dan Mesajlar"],"anahtarKavramlar":["ibadet","ihlas","ihsan ","itidal","tefekkür","tesettür","tevazu","yardımlaşma"],"olcmeDegerlendirme":["Öğrenme çıktıları; çıkış kartı, bilgi kartı, açık uçlu sorular, boşluk doldurma, doğru-yanlış, kısa cevaplı sorular, öz değerlendirme formu ve dereceli puanlama anahtarı kullanılarak değerlendirilebilir.","İbadetin bireye ve topluma kazandırdıklarıyla ilgili sunum hazırlama, performans görevi olarak verilebilir. Bu performans görevi “ibadetin bireye ve topluma kazandırdıkları hakkında bilgi toplama, bilgileri işleme, sınıflandırma ve sunma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin namaz, oruç, zekât, hac ve kurban gibi ibadetler konusunda ön bilgilere sahip oldukları, ibadetlerle ilgili bazı tecrübe ve izlenimlerinin olduğu kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “İbadet nedir, ibadet etmenin insana kazandırdıkları nelerdir?” sorularak verdikleri cevaplara göre öğrencilerin ön bilgileri belirlenir. Bunun için kum saati tekniği kullanılabilir."],"kopruKurma":["Öğrencilerden namaz, oruç, zekât, hac gibi ibadetler hakkındaki izlenimlerini aktarmaları istenir. Bu izlenimlerinden hareketle ibadetlerin birey ve toplum hayatında ne gibi etkilerinin olduğu ele alınarak gerçek yaşamla köprü kurulur."],"uygulamalar":[{"kod":"DKAB.9.3.1","metin":"Öğrencilerin ibadet konusuyla ilgili merak ettiklerini sormaları sağlanır. Öğrenciler öğretmen rehberliğinde konuyla ilgili detaylı bilgilere ulaşmak için kullanacakları kaynakları araştırır (E3.7). Öğrencilerin yararlandığı kaynaklardan ibadetin tanımı, kapsamı, amacı ve temel ilkeleriyle ilgili bilgi toplamaları sağlanır (OB1). Bu süreçte grup çalışması tekniği kullanılabilir (SDB2.2). Öğrenciler topladıkları bilgilerin doğruluğunu öğretmen rehberliğinde kontrol eder ve bu bilgileri kaydeder. Ayrıca ibadetin temel ilkelerinden Kur’an-ı Kerim ve sünnete uygunluk, niyet, ihlas, süreklilik, itidal konularına vurgu yapılır. Ölçme ve değerlendirme uygulamalarında çıkış kartı kullanılabilir. Öğrenciler düzenli çalışmanın başarı üzerindeki etkisini ibadetlerdeki süreklilik anlayışıyla ilişkilendirerek çalışkanlık değerinin önemini fark eder (D3.2)."},{"kod":"DKAB.9.3.2","metin":"İslam’ın temel ibadetleriyle ilgili öğrencilere neler bildikleri sorulur. Beyin fırtınası tekniği bu aşamada kullanılabilir. İslam’ın temel ibadetleri olan namaz, oruç, zekât, hac ve kurban hakkında kısaca bilgi verilir. Bu ibadetlerle ilgili ayet ve hadisler vurgulanır. Ayrıca abdest ve guslün nasıl alınacağı ile namazın kılınışı kısaca ele alınır. Allah’ın (cc) rızasının gözetildiği tüm davranışların ibadet olduğuna ve salih amel kavramına değinilir. Bu bağlamda tesettür kavramı da ele alınır. İslam dinine göre tesettürün önemine değinilir. Tesettürün bazı ibadetlerin şartlarından biri olduğu açıklanır. Öğrenciler, dinin temel kaynaklarında yer alan ibadetlere dair sınıflandırma ölçütlerinin hükümleri ve yapılış şekilleri olduğunu öğretmen rehberliğinde açıklar. Bu ölçütlere göre öğrenciler ibadetleri birbirinden ayırt ederek tasnif eder. Öğrencilerin temel ibadetlerin isimlerini söylemesi beklenir. Bu süreçte eşleştirme tekniği kullanılabilir. Ölçme ve değerlendirme uygulamalarında bilgi kartı kullanılabilir."},{"kod":"DKAB.9.3.3","metin":"İbadetlerin insanı Allah’a (cc) yakınlaştırması, güzel ahlaka yönlendirmesi, insanda yardımlaşma duygusunu, sabır ve disiplini geliştirmesi vurgulanır. İbadetin hikmetine, tefekkür boyutuna ve yapılış amacına değinilir. Öğrenciler zekât ve kurban ibadetlerinden hareketle sahip olduklarını (para, mal, bilgi vb.) paylaşmanın önemini yaparak yaşayarak öğrenir (D20.1, SDB1.3, SDB2.3). Öğrenciler insan-ibadet ilişkisi bağlamında ibadetlerin bireysel ve toplumsal hayata yansımalarını inceler (SDB2.3). İbadetlerin bireysel ve toplumsal yansımalarını kendi hayatı için anlamlı hâle getirir. Bunun için örnek olay tekniği kullanılabilir. Öğrenciler insan ve ibadet ilişkisini ayet ve hadislerden hareketle doğru bir şekilde ifade eder. Öğrencilerin, beraber yapılan ibadetlerin inananlar arasındaki dostluğu artırdığını fark etmelerine imkân tanınır (D4.3). Öğrenciler ihlasın insanı dürüstlüğe yönlendireceğini fark eder (D6.2). Bu değerin kazandırılmasına yönelik soru cevap ve drama teknikleri kullanılabilir. Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."},{"kod":"DKAB.9.3.4","metin":"Bakara suresi 21, Zariyat suresi 56 ve Hicr suresi 99. ayetler, Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetlerin nüzul sebeplerine, ayetlerde geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayetlerde verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayetlerde ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında boşluk doldurma, doğru-yanlış, kısa cevaplı ve açık uçlu soru türleri kullanılabilir."}],"zenginlestirme":["Öğrencilerin ilmihâlden ibadetlerin ayrıntılarını incelemeleri sağlanabilir. Farz, vacip, sünnet, müstehap ibadetlerin yer aldığı bir sunum hazırlamaları istenebilir. Hazırladıkları sunumun (afiş vb.) bir dokümana dönüştürülerek sınıf veya okul panosunda sergilemesi sağlanır.","Öğrencilerden namazda okunan kısa dua ve sureleri anlamlarıyla birlikte içeren bir sunu hazırlamaları istenebilir."],"destekleme":["Öğrencilerin öğrenme süreçlerine katılımlarını artırmak için gerekli görsel-işitsel araç gereçler hazırlanır ve ortam düzenlemesi yapılır. Öğrenciler İslam’ın temel ibadetleri konusunda dijital içerik (sesli metin, video vb.), soru cevap etkinlikleriyle desteklenebilir. Öğrencilerin gruplar hâlinde çalışmaya yönlendirilmesi ve daha fazla rehberlik ve destek sunulmasıyla öğrenme süreçleri desteklenir."],"ogretmenYansitmalari":[]},
{"no":4,"ad":"İslam’da Ahlak İlkeleri","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/142","odak":"Bu ünitenin odak noktasını İslam’da ahlak konusu oluşturmaktadır. Öğrencilerin İslam’da ahlakın mahiyetini sorgulayabilmesi, ahlakın temel unsurlarını sentezleyebilmesi, İslam’ın emrettiği bazı ahlaki davranışları örneklendirebilmesi, ahlaki tutum ve davranışlara olan ihtiyaçla ilgili eleştirel düşünebilmesi amaçlanır. Kur’an’dan mesajlar bölümünde İsra suresinin 23-29. ayetleri ele alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":12,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.8. Sorgulama","KB2.20. Sentezleme","KB3.3. Eleştirel Düşünme"],"egilimler":["E3.4. Gerçeği Arama","E3.6. Analitik Düşünme","E3.11. Özgün Düşünme"],"sdb":["SDB1.2. Kendini Düzenleme (Öz Düzenleme)","SDB2.1. İletişim"],"degerler":["D1. Adalet","D6. Dürüstlük","D12. Sabır","D20. Yardımseverlik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık","OB6. Vatandaşlık Okuryazarlığı"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.9.4.1","ad":"İslam’da ahlakın mahiyetini sorgulayabilme","surec":["a) İslam’da ahlakın mahiyetine yönelik merak ettiklerini ifade eder.","b) İslam’da ahlakın mahiyeti hakkında sorular sorar.","c) İslam’da ahlakın mahiyetiyle ilgili bilgi toplar.","ç) İslam’da ahlakın mahiyetiyle ilgili topladığı bilgilerin doğruluğunu değerlendirir.","d) İslam’da ahlakın mahiyetiyle ilgili topladığı bilgiler üzerinden çıkarım yapar."]},{"kod":"DKAB.9.4.2","ad":"Ahlakın temel unsurlarını sentezleyebilme","surec":["a) Ahlakın temel unsurlarının neler olduğunu ifade eder.","b) Ahlakın temel unsurları arasında ilişki kurar.","c) Bu unsurlar arasında özgün bir bakış açısı oluşturur."]},{"kod":"DKAB.9.4.3","ad":"Ahlaki tutum ve davranışlarla ilgili eleştirel düşünebilme","surec":["a) Ahlaki tutum ve davranışlara olan ihtiyacı sorgular.","b) Ahlaki tutum ve davranışların toplumsal düzene etkisiyle ilgili akıl yürütür.","c) Ahlaki tutum ve davranışla ilgili ulaştığı çıkarımları yansıtır."]},{"kod":"DKAB.9.4.4","ad":"İsra suresi 23-29. ayetlerdeki mesajları özetleyebilme","surec":["a) Ayetlerde verilen mesajlarla ilgili çözümleme yapar.","b) Ayetlerde geçen konuları sınıflandırır.","c) Ayetlerde verilen mesajları açıklar."]}],"icerikCercevesi":["İslam’da Ahlakın Mahiyeti","Ahlakın Temel Unsurları","Ahlaki Tutum ve Davranışlar","Kur’an’dan Mesajlar"],"anahtarKavramlar":["adalet","ahilik","ahlak","şecaat","hikmet","iffet","vicdan","terbiye"],"olcmeDegerlendirme":["Öğrenme çıktıları; açık uçlu sorular, çalışma yaprağı, dereceli puanlama anahtarı, tanılayıcı dallanmış ağaç, 3-2-1 kartı, öz değerlendirme formu kullanılarak değerlendirilebilir.","Belirlenen bir ahlaki değerle ilgili kısa film hazırlama, performans görevi olarak istenebilir. Bu performans görevi “değere ilişkin bilgi toplama, senaryo yazma, görüntü ve ses tekniklerine uygun çekim yapma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Ahlaki ilkelerin çoğunun evrensel özellik taşıdığını, İslam’da ahlak ilkelerinin önemli bir yer tuttuğunu, ahlakın birey ve toplum hayatında önemli bir yere sahip olduğunu öğrencilerin bildiği kabul edilir."],"onDegerlendirme":["Öğrencilerin ahlaki değerlerle ilgili ön bilgilerini belirlemeye yönelik sorular sorulabilir. Öğrencilerden, ahlaki tutum ve davranışların bireyin hayatına etkileri bağlamında akıl yürütmeleri istenebilir. Bu şekilde değerlerle ilgili ön bilgileri belirlenir."],"kopruKurma":["Ahlakın temel unsurları ile ahlaki değerlere uygun ticaret yapılması arasında köprü kurulabileceği gibi öğrencilerden küresel ısınma ve iklim krizi sorunlarının ortaya çıkış süreci ve çözümünü ahlak ilkeleri ile ilişkilendirmeleri istenerek gerçek yaşam ile köprü kurulabilir."],"uygulamalar":[{"kod":"DKAB.9.4.1","metin":"Öğrencilerin İslam’da ahlakın mahiyetine yönelik merak ettikleri soruları soru kutusuna atması istenir (SDB2.1, E3.4). Ahlakın mahiyeti konusunda bilgilendirici metinler okunur (TDV İslam Ansiklopedisi gibi temel kaynaklardan ahlakla ilgili maddeler) öğrencilerden not tutmaları istenir. Bu aşamada Cornell tekniği kullanılabilir. İslam’da ahlakın mahiyeti konusunda öğrenciler elde ettiği bilgilerin doğruluğunu öğretmen rehberliğinde değerlendirir. Ahlakın kaynaklarının neler olduğu belirtilir. Ahlakın kaynaklarından aklın önemine de vurgu yapılır. Ahlakın din ile temellendirilmesi bağlamında ayet ve sünnet ışığında İslam’ın bakış açısı sunulur. Öğrenciler İslam ahlakının temelinde, insanların hem Allah’a (cc) hem de diğer canlılara karşı sorumluluklarına uygun davranışlar sergilemesi gerektiğini bilir. İslam’da ahlakın mahiyetine yönelik soru kutusuna atılan sorular cevaplanır. Bu aşamada soru turu tekniği kullanılabilir. İnsanın kendisiyle, çevresiyle ve Rabb’iyle doğru ilişkiler kurmasında ahlakın önemine dair öğrencilerden çıkarım yapmaları beklenir (E3.6). Ölçme ve değerlendirme uygulamalarında tanılayıcı dallanmış ağaç tekniği ve açık uçlu sorular kullanılabilir."},{"kod":"DKAB.9.4.2","metin":"Ahlakı oluşturan temel unsurların neler olabileceğine dair sorularla öğrenciler konu hakkında düşünmeye sevk edilir. Alınan cevaplar çerçevesinde öğrencilerin ahlakın temel unsurlarının adalet, şecaat, iffet ve hikmet olduğunu ifade etmeleri sağlanır. İnsanın düşünme, arzu ve gazap gibi konularda ölçülü olması, itidal üzere hareket etmesi, bedenî ve maddi hazlara aşırı düşkünlükten korunması konuları ilgili kavramlar bağlamında ele alınır. Bu süreçte köşeleme tekniği kullanılabilir. Öğrenciler ahlakla ilgili kavramları dikkate alarak bunlar arasında bütüncül bir bakış açısı oluşturur (OB1, E3.11). Öğrenciler adaletin doğruluk, denge, gerçeğe uygun hükmetme, doğru yolu izleme, dürüstlük, tarafsızlık anlamlarına geldiğini bilerek sosyal hayatta adaletli olmaya özen gösterir. Bu değerin kazandırılması için ahlaki muhakeme yaklaşımı kullanılabilir (D1.2). Ölçme ve değerlendirme uygulamalarında öğrencilerden değerlendirme metni yazmaları istenebilir. Bu metinler dereceli puanlama anahtarıyla değerlendirilebilir."},{"kod":"DKAB.9.4.3","metin":"Ahlaki tutum ve davranışların neler olduğu, bu tutum ve davranışlara niçin ihtiyaç duyulduğu öğrencilere sorularak alınan cevaplar değerlendirilir. Ahlaki tutum ve davranışlardan dürüstlük, yardımseverlik, sabır konuları ayet ve hadisler bağlamında ele alınır. Dürüstlüğün hayatın tüm yönlerini kapsaması bakımından ahilik kavramına değinilir. Bu kapsamda ahilik haftasında yapılan etkinliklere de dikkat çekilir. Toplumsal düzen için adabımuaşeretin önemine vurgu yapılır (SDB3.3, OB6). Bu bağlamda öğrencilerin söz ve davranışlarında tutarlı, tarafsız, doğru ve güvenilir olması hedeflenir (D6.2). Öğrencilerin gösterişten uzak bir şekilde karşılıksız iyilik yapması amaçlanır (D20.4). Öğrenciler, günlük hayatlarında etkilendikleri içsel ve dışsal faktörleri fark edip süreci sabırla doğru bir şekilde yönetmenin önemini fark eder. Bu değerlerin kazandırılmasında yaparak yaşayarak öğrenme yöntemi uygulanabilir (D12.2). Ahlaki tutum ve davranışlara olan ihtiyacın öğrenciler tarafından sorgulanması sağlanır (E3.4). Bu süreçte tartışma tekniği kullanılabilir (SDB2.1). Ahlaki tutum ve davranışların toplumsal düzene etkisiyle ilgili akıl yürütmeleri istenir. Öğrencilerden ulaşılan çıkarımları duvar gazetesi, hikâye tamamlama gibi etkinliklerle yansıtmalarına imkân verilir (SDB1.2). Ölçme ve değerlendirme uygulamalarında 3-2-1 kartı kullanılabilir."},{"kod":"DKAB.9.4.4","metin":"İsra suresinin 23-29. ayetleri, Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetlerin nüzul sebeplerine, ayetlerde geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayetlerde verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayetlerde ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında boşluk doldurma, doğru-yanlış, kısa cevaplı ve açık uçlu soru türlerinden oluşan çalışma yaprağı kullanılabilir."}],"zenginlestirme":["Belirlenen bir kitabın veya bir filmin ahlaki erdemler bakımından incelenmesine ve sunulmasına imkân sağlanabilir. Öğrencilere uygulamalı etik konularında araştırma görevleri verilebilir ve öğrencilerin söz konusu araştırma görevlerini tercih edecekleri tarzlarda sunmalarına (rol oynama, dijital içerik hazırlama, eylem planı hazırlama, sözlü sunum, görsel sunum vb.) imkân verilir."],"destekleme":["Ünite konularına dair temel kavramları kapsayan sade ve anlaşılır özetler hazırlanarak öğrencilere sunulur. Öğrencilere birebir veya küçük gruplar hâlinde bireysel ihtiyaçlarına göre daha yoğun bir destek sağlanır. Öğretim sürecinde görsel ve işitsel materyaller arasından çeşitli öğretim araçları kullanılır. Öğrencilerin öğrenme sürecinde aktif rol almalarını teşvik eden etkileşimli ve uygulamalı etkinlikler düzenlenir."],"ogretmenYansitmalari":[]},
{"no":5,"ad":"Kur’an’a Göre Hz. Muhammed","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/143","odak":"ele alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":12,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.13. Yapılandırma","KB2.14. Yorumlama"],"egilimler":["E3.4. Gerçeği Arama","E3.6. Analitik Düşünme","E3.11. Özgün Düşünme"],"sdb":["SDB2.1. İletişim","SDB2.3. Sosyal Farkındalık"],"degerler":["D4. Dostluk","D5. Duyarlılık","D14. Saygı","D15. Sevgi"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık","OB5. Kültür Okuryazarlığı"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.9.5.1","ad":"Hz. Muhammed’in (sav) beşerî ve peygamberlik yönünü özetleyebilme","surec":["a) Hz. Muhammed’in (sav) beşerî ve peygamberlik yönünü temel kaynaklardan yararlanarak inceler.","b) Hz. Muhammed’in (sav) özelliklerini beşerî ve peygamberlik yönü açısından sınıflandırır.","c) Hz. Muhammed’in (sav) beşerî ve peygamberlik yönünü öğrendiklerinden hareketle ifade eder."]},{"kod":"DKAB.9.5.2","ad":"Hz. Muhammed’in (sav) örnekliğini esas alarak kendi bakış açısını yapılandırabilme","surec":["a) Hz. Muhammed’in (sav) neden örnek alınması gerektiğiyle ilgili çıkarımlarda bulunur.","b) Hz. Muhammed’in (sav) neden örnek alınması gerektiğiyle ilgili kendi bilgisi ile elde ettiği bilgiler arasında ilişki kurar."]},{"kod":"DKAB.9.5.3","ad":"Kültürümüzde Hz. Muhammed (sav) ve Ehlibeyt sevgisini yorumlayabilme","surec":["a) Kültürümüzde Hz. Muhammed (sav) ve Ehlibeyt sevgisini inceler.","b) Kültürümüzde oluşan Hz. Muhammed (sav) ve Ehlibeyt sevgisini bağlamından koparmadan hayatı için anlamlı hale getirir.","c) Kültürümüzde Hz. Muhammed (sav) ve Ehlibeyt sevgisini doğru bir şekilde ifade eder."]},{"kod":"DKAB.9.5.4","ad":"Ahzab suresinin 45-46 ve Nahl suresinin 43-44. ayetlerindeki mesajları özetleyebilme","surec":["a) Ayetlerde verilen mesajlarla ilgili çözümleme yapar.","b) Ayetlerde geçen konuları sınıflandırır.","c) Ayetlerde verilen mesajları açıklar."]}],"icerikCercevesi":["Hz. Muhammed’in Beşerî ve Peygamberlik Yönü","Hz. Muhammed’in Örnekliği","Kültürümüzde Hz. Muhammed ve Ehlibeyt Sevgisi","Kur’an’dan Mesajlar"],"anahtarKavramlar":["Ehlibeyt","hadis","hatemülenbiya","nübüvvet","peygamber","sünnet","tebliğ","tebyin","temsil","teşri","üsveihasene"],"olcmeDegerlendirme":["Öğrenme çıktıları; 3-2-1 kartı, çalışma yaprağı, çıkış kartları, dereceli puanlama anahtarı, tanılayıcı dallanmış ağaç ve öz değerlendirme formu kullanılarak değerlendirilebilir.","Edebi metinlerden de yararlanarak Hz. Muhammed (sav) ve Ehlibeyt sevgisiyle ilgili bir fanzin hazırlama, performans görevi olarak verilebilir. Bu performans görevi “bilgi toplama, inceleme, yorumlama, dil ve anlatım kurallarına uyma, tasarım yapma ve sunma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin Hz. Muhammed’in (sav) peygamberlerin sonuncusu olduğunu ve kendisine indirilen kutsal kitabın Kur ’an-ı Kerim olduğunu bildiği kabul edilir."],"onDegerlendirme":["Soru-cevap tekniği kullanılarak Hz. Muhammed’in (sav) örnek oluşu ile ilgili öğrencilerin neler bildikleri ve ne öğrenmek istedikleri belirlenir."],"kopruKurma":["Öğrencilere kimleri rol model aldıkları, bu kişileri seçme nedenleri ve bu kişilerden nasıl etkilendikleri sorulur. İnsan yaşamında “rol model” olgusunun önemi üzerinde durulur. Kur’an-ı Kerim'de Hz. Muhammed (sav) için üsveihasene ifadesi kullanıldığı vurgulanır. Bu şekilde Hz. Muhammed’in (sav) örnek şahsiyeti ile kendi yaşamlarını ilişkilendirmeleri amaçlanır."],"uygulamalar":[{"kod":"DKAB.9.5.1","metin":"Öğrenciler “Hz. Muhammed (sav) kimdir?” sorusuna cevap bulmaya yönlendirilir. Hz. Muhammed’e (sav) peygamberlik görevi verilmeden önceki dönem coğrafi, sosyo-kültürel, ekonomik ve dinî açılardan ele alınır (E3.4). Dönemi yansıtan tarihi eserlerden, siyer kitaplarından, haritalardan, bilgi grafiğinden, belgesel ve filmlerden yararlanılabilir. Öğrenciler Hz. Muhammed’in (sav) beşerî ve peygamberlik yönünü temel kaynaklardan yararlanarak inceler. Hz. Muhammed’in (sav) beşerî ve peygamberlik özelliklerini ayetler ve hadisler çerçevesinde sınıflandırır. Hz. Muhammed’in (sav) tebliğ, tebyin, teşri, temsil görevlerine değinilir. Bu süreçte kavram haritaları kullanılabilir. Hz. Muhammed’in (sav) nasıl bir şahsiyete sahip olduğu onun hayatından örneklerle incelenir. Öğrencilerin Hz. Muhammed’in (sav) beşerî ve peygamberlik yönünü öğrendiklerinden hareketle ifade etmelerine imkân tanınır (OB1). Bu süreçte öğrencilerden “Bir beşer ve bir peygamber olarak Hz. Muhammed (sav) nasıl bir insandı?” konulu bir söyleşi yapmaları istenebilir (SDB2.1). Mevlid-i Nebî Haftası’nda yapılan etkinliklerden kısaca bahsedilebilir. Ölçme ve değerlendirme uygulamalarında çalışma yaprağı kullanılabilir."},{"kod":"DKAB.9.5.2","metin":"Kur’an-ı Kerim’e göre ‘’Hz. Muhammed (sav) nasıl bir insandır, neden üsveihasene olarak nitelendirilmiştir?’’ sorularını yanıtlamak ve ilgili ayetleri tespit etmek amacıyla öğrenciler Kur’an-ı Kerim mealinden araştırma yapmaya yönlendirilir. Hz. Muhammed’in (sav) örnekliğini ilgili ayet ve hadisler üzerinden inceler. Bu aşamada üsveihasene kavramı analiz edilir. Öğrenciler ayetlerden hareketle Hz. Muhammed’in (sav) neden örnek alınması gerektiğiyle ilgili çıkarımlarda bulunur (E3.6). Bu süreçte kar topu (piramit) tekniği kullanılabilir. Hz. Muhammed’in (sav) neden örnek alınması gerektiğiyle ilgili kendi bilgisi ile elde ettiği bilgiler arasında ilişki kurmaları sağlanır (E3.11). Hz. Muhammed’in (sav) gençlerle olan iletişiminde onlarla olan dostluğuna ve dayanışmasına dair örnekler verilir (D4.2). Ölçme ve değerlendirme uygulamalarında 3-2-1 kartı kullanılabilir."},{"kod":"DKAB.9.5.3","metin":"Kültürümüzde yer alan Hz. Peygamber ve Ehlibeyt sevgisi ile ilgili şiir, naat, mevlit gibi eserler okunarak veya dinletilerek konuya ilgi çekilebilir. Öğrenciler Ali, Hasan, Hüseyin, Fatma ve Zeynep gibi isimlerin çokça kullanılmasının Hz. Peygamber ve Ehlibeyt sevgisinin göstergelerinden olduğunu örnekler üzerinden inceler (SDB2.3). Konuyla ilgili izlenimlerini bağlamından koparmadan doğru bir şekilde ifade eder. Öğrencilerin toplumumuzda Hz. Muhammed (sav) ve Ehlibeyti’ne duyulan bağlılık ve sevgi üstüne oluşmuş kültürel birikimi tanımalarına, ona saygı duymalarına, kültürel birikimden yararlanmalarına, onu korumalarına ve geliştirmelerine imkân sağlanarak onlara kültürel mirasa değer verme bilincinin kazandırılması amaçlanır (D5.3). Öğrencilerin kültürümüzdeki Hz. Peygamber ve Ehlibeyt sevgisine ilişkin duygu, düşü nce ve bakış açılarına saygılı bir tutum geliştirmeleri hedeflenir (OB5). Bu süreçte farklı duygu, düşünce ve inançlara karşı empati ile yaklaşarak kendisine, çevresine, içinde yaşadığı toplumun sahip olduğu millî ve manevi değerlere önem verir (D14.4, D15.1). Ölçme ve değerlendirme uygulamalarında tanılayıcı dallanmış ağaç kullanılabilir."},{"kod":"DKAB.9.5.4","metin":"Ahzab suresinin 45-46 ve Nahl suresinin 43-44. ayetleri Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetlerin nüzul sebeplerine, ayetlerde geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayetlerde verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayetlerde ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında çıkış kartı kullanılabilir."}],"zenginlestirme":["Öğrencilerin Hz. Muhammed’in (sav) örnekliği ve şahsiyeti ile ilgili hilyeişerif örneklerini araştırmaları, incelemeleri ve bunu bir sunu ile arkadaşlarıyla paylaşmaları sağlanabilir. Öğrencilerin öğrenme özelliklerine göre ürün oluşturmalarına (afiş, duvar gazetesi, rapor, vb.) fırsat verilebilir."],"destekleme":["Ünite konularına dair temel kavramları kapsayan sade ve anlaşılır özetler hazırlanarak öğrencilere sunulur. Öğrencilere birebir veya küçük gruplar hâlinde bireysel ihtiyaçlarına göre daha yoğun bir destek sağlanır. Öğretim sürecinde görsel ve işitsel materyaller gibi çeşitli öğretim araçları kullanılır. Öğrencilerin öğrenme sürecinde aktif rol almalarını teşvik eden etkileşimli ve uygulamalı etkinlikler düzenlenir."],"ogretmenYansitmalari":[]}],"s10":[{"no":1,"ad":"İslam’da Varlık ve Bilgi","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/144","odak":"Bu ünitenin odak noktasını İslam’da varlık ve bilgi konusu oluşturmaktadır. Öğrencilerin İslam’da bilginin yerini ve kaynaklarını çözümleyebilmesi, Allah-âlem ilişkisini tefekkür ederek sorgulayabilmesi amaçlanır. Kur’an’dan mesajlar bölümünde İsra suresi 36 ve Mülk suresinin 23. ayetleri ele alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.4. Çözümleme","KB2.8. Sorgulama"],"egilimler":["E3.4. Gerçeği Arama","E3.6. Analitik Düşünme","E3.8. Soru Sorma"],"sdb":["SDB1.2. Kendini Düzenleme (Öz Düzenleme)","SDB2.1. İletişim"],"degerler":["D10. Mütevazılık","D16. Sorumluluk"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Kelam","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.10.1.1","ad":"İslam’da bilginin yerini ve kaynaklarını çözümleyebilme","surec":["a) İslam düşüncesinde bilginin yerini ve kaynaklarını inceler.","b) İslam düşüncesinde bilginin yeri ve kaynakları arasındaki ilişkiyi belirler."]},{"kod":"DKAB.10.1.2","ad":"Allah-âlem ilişkisini tefekkür ederek sorgulayabilme","surec":["a) Allah-âlem ilişkisiyle ilgili merak ettiklerini tanımlar.","b) Allah-âlem ilişkisini anlayabilmek için sorular sorar.","c) Allah-âlem ilişkisi hakkında İslam’ın temel kaynaklarından bilgi toplar.","ç) Allah-âlem ilişkisi hakkında topladığı bilgileri değerlendirir.","d) Allah-âlem ilişkisi hakkında topladığı bilgilerden çıkarım yapar."]},{"kod":"DKAB.10.1.3","ad":"İsra suresi 36 ve Mülk suresi 23. ayetlerin mesajlarını özetleyebilme","surec":["a) Ayetlerde verilen mesajlarla ilgili çözümleme yapar.","b) Ayetlerde geçen konuları sınıflandırır.","c) Ayetlerde verilen mesajları açıklar."]}],"icerikCercevesi":["İslam’da Bilgi ve Bilginin Kaynakları","Allah-Âlem İlişkisi","Kur’an’dan Mesajlar"],"anahtarKavramlar":["akıl","bilgi","gayb","mütevatir","sadık haber","şehadet","varlık"],"olcmeDegerlendirme":["Öğrenme çıktıları; açık uçlu sorular, kavram haritası, çalışma yaprağı, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir.","Allah-âlem ilişkisiyle ilgili bir deneme yazma, performans görevi olarak verilebilir. Bu performans görevi “bilgi toplama, inceleme, yorumlama, dil ve anlatım kurallarına uyma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin, ilahi kitapların insanlara yol göstermek amacıyla Allah (cc) tarafından gönderildiğini bildikleri, görülen ve görülemeyen varlıklar hakkında bilgi sahibi oldukları kabul edilmektedir."],"onDegerlendirme":["Öğrencilerin İslam’da varlık ve bilgi alanında merak ettiği konular tespit edilerek hazır bulunuşluk düzeyleri kontrol edilir."],"kopruKurma":["Salim duyular, selim akıl ve sadık haberle elde edilebilecek bilgiler sınıflandırılır. Bu sınıflandırmaya uygun örnekler bulunarak konuyla köprü kurulur."],"uygulamalar":[{"kod":"DKAB.10.1.1","metin":"Öğrencilere varlık, nesne, olay ve olgular hakkındaki bilgileri nasıl elde ettikleri sorulur. Öğrencilerin verdikleri cevaplar dikkate alınarak bilgi kaynaklarının neler olduğu incelenir (SDB2.1). Öğrenciler bu kaynaklardan yararlanarak bilgi ve bilginin kaynakları arasındaki ilişkileri öğretmen rehberliğinde belirler (E3.4). Bu süreçte zihin haritası kullanılabilir. Doğru bilgi, doğru inanç ve doğru davranış arasındaki ilişkiden yola çıkılarak doğru bilginin önemine değinilir. İslam düşüncesinde bilgi ve kaynakları, bilginin değeri ve önemi farklı disiplinler dikkate alınarak açıklanır (OB1). Bilgi kaynaklarının öznel ve nesnel gibi farklı sınıflandırmaları ele alınır. İslam’da nesnel bilgi kaynakları sadık haber, selim akıl ve salim duyular olarak belirlenir. Doğru bilgiyi elde etmeye yönlendirilerek duygu, düşünce ve davranışlarından sorumlu olduğu öğrenciye fark ettirilir (D16.1, SDB1.2). Ölçme ve değerlendirme uygulamalarında kavram haritası kullanılabilir."},{"kod":"DKAB.10.1.2","metin":"Öğrenciler Allah-âlem ilişkisiyle ilgili merak ettiklerini tanımlar. Öğrenciler Allah-âlem ilişkisini anlayabilmek için sorular sorar (E3.8). Bu süreçte bilgi kutusu tekniği kullanılabilir. Zihin haritaları oluşturularak görülen (şehadet) ve görülemeyen (gayb) âlem, varlık türleri (insan, hayvan, bitki, melek, cin, şeytan) hakkında öğrencilerin görüşlerini paylaşmaları istenir. Öğrenciler, gözlem yoluyla edindiği bilgiler çerçevesinde insanın âlemdeki yerini bilir ve Allah (cc) karşısındaki konumunun farkına varır (D10.1). Öğrencilerin konuyla ilgili İslam’ın temel kaynaklarından bilgi toplamalarına imkân tanınır. Kelam ilminin Allah-âlem ilişkisine dair yaklaşımı dikkate alınarak konu aktarılır. Öğrenciler edindikleri bilgileri öğretmen rehberliğinde değerlendirerek çıkarımda bulunur (E3.6). Düşün-eşleş-paylaş tekniği bu süreçte kullanılabilir. Ölçme ve değerlendirme uygulamalarında açık uçlu sorulara yer verilebilir."},{"kod":"DKAB.10.1.3","metin":"İsra suresi 36 ve Mülk suresi 23. ayetleri Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetlerin nüzul sebeplerine, ayetlerde geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayetlerde verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayetlerde ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında çalışma yaprağı kullanılabilir."}],"zenginlestirme":["Allah-âlem ilişkisini inceleyen bazı makalelerin okunması sağlanıp bu makalelerin özetlenmesi istenebilir. Özetlenen makalelerden elde edilen veriler afiş şeklinde tasarlanıp öğrenciler tarafından sınıfta sergilenebilir."],"destekleme":["Görsel ve interaktif materyaller kullanılarak İslam düşüncesinde bilgi kuramı ve bilginin kaynaklarının anlaşılması kolaylaştırılır. Örneğin vahiy, akıl ve beş duyunun nasıl bilgi kaynağı olduğunu açıklayan animasyonlar veya şemalar hazırlanır.","Allah-âlem ilişkisini ve Kur’an-ı Kerim’deki mesajları anlamalarını sağlamak için öğrencilere kısa, öz ve anlaşılır açıklamalar yapılır. Bu konularda örnek olay incelemeleri veya hikâye anlatımı gibi yöntemler kullanılır. Derste grup çalışmaları ve tartışmalar düzenlenerek öğrencilerin birbirlerinden öğrenmeleri teşvik edilir ve sınıf içi etkileşim artırılır."],"ogretmenYansitmalari":[]},
{"no":2,"ad":"Allah’ı Tanımak","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/145","odak":"Bu ünitenin odak noktasını Allah’ı (cc) tanımak konusu oluşturmaktadır. Öğrencilerin Allah’ın (cc) varlığının delilleri üzerine akıl yürütebilmesi, Allah’ı (cc) gereği gibi tanıyabilmek için Allah’ın (cc) isim ve sıfatlarını hayata yansıması bakımından sentezleyebilmesi amaçlanır. Kur’an’dan mesajlar bölümünde Haşr suresinin 22-24. ayetleri ele alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":16,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.16.1. Tümevarıma Dayalı Akıl Yürütme","KB2.20. Sentezleme"],"egilimler":["E1.1. Merak","E3.4. Gerçeği Arama"],"sdb":["SDB2.1. İletişim"],"degerler":["D11. Özgürlük","D14. Saygı","D15. Sevgi"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Felsefe","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.10.2.1","ad":"Allah’ın (cc) varlığının delilleri üzerine akıl yürütebilme","surec":["a) Allah’ın (cc) varlığının delilleriyle ilgili öğrendiklerinden hareketle gözlemler yapar.","b) Varlıklar arasındaki örüntüleri bulur.","c) Varlıklar hakkında yaptığı gözlemler ve bulduğu örüntüler üzerinden genellemeler yapar."]},{"kod":"DKAB.10.2.2","ad":"Allah’ı (cc) gereği gibi tanıyabilmek için O’nun isim ve sıfatlarını hayata yansıması bakımından sentezleyebilme","surec":["a) Ayet ve hadislerden hareketle Allah’ın (cc) isim ve sıfatlarını inceler.","b) Allah’ın (cc) isimleri ve sıfatları arasında ilişki kurar.","c) Allah’ın (cc) isimlerinden ve sıfatlarından hareketle Allah (cc) hakkında bütüncül bir bakış açısı oluşturur."]},{"kod":"DKAB.10.2.3","ad":"Haşr suresi 22-24. ayetlerin mesajlarını özetleyebilme","surec":["a) Ayetlerde verilen mesajlarla ilgili çözümleme yapar.","b) Ayetlerde geçen konuları sınıflandırır.","c) Ayetlerde verilen mesajları açıklar."]}],"icerikCercevesi":["Allah’ın Varlığının Delilleri","Allah’ı İsim ve Sıfatlarıyla Tanımak","Kur’an’dan Mesajlar"],"anahtarKavramlar":["delil","evren","gaye","marifetullah","nizam","teleoloji"],"olcmeDegerlendirme":["Öğrenme çıktıları; öğrenme günlüğü, fanzin, 3-2-1 kartı, çalışma yaprağı, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir.","Allah’ın (cc) varlığının delilleri, esma ve sıfatları konusunda sınıf içerisinde öğrenilen bilgilerden oluşan bir sunum hazırlama, performans görevi olarak verilebilir. Bu performans görevi “kaynakları kullanma, bilgi toplama, dil ve anlatım kurallarına uygunluk” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin İslam’a göre Allah’ın (cc) tek ilah ve mutlak yaratıcı olduğu bilgisine sahip oldukları kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Allah’ın (cc) varlığının kanıtlanması noktasında neler biliyorsunuz, yaratılanlar Allah’ın (cc) varlığına işaret eder mi, Allah’ın (cc) isim ve sıfatları denilince aklınıza gelenler nelerdir?” soruları yöneltilerek verdikleri cevaplarla öğrencilerin ön bilgileri kontrol edilir."],"kopruKurma":["Gökyüzü, bitkiler, hayvanlar, insanlar gibi Allah’ın (cc) yarattığı varlıklarla ilgili belgeseller izletilerek O’nun ilmi, iradesi ve kudretine dikkat çekilir. Yaratılan her şeyin Allah’a (cc) muhtaç olduğu gerçeği üzerinden konuyla köprü kurulur."],"uygulamalar":[{"kod":"DKAB.10.2.1","metin":"Öğrencilerin yaratılan varlıkları düşünerek gözlemler yapması ve bu gözlemler üzerinden varlıklar arasındaki örüntüleri bulması sağlanır (E1.1, E3.4). Evrendeki düzenle ve tabiat olaylarıyla ilgili gözlemlerini arkadaşlarıyla paylaşmaları istenir (SDB2.1). Bu süreçte düşün-eşleş-paylaş tekniği kullanılabilir. Öğrenciler varlıklarla ilgili yaptığı gözlemler ve bulduğu örüntüler üzerinden genellemelere ulaşır. Öğrenciler, Allah’ın (cc) varlığı konusunda duygu, düşünce ve genellemelerini etki altında kalmadan beyin fırtınası tekniğiyle özgürce ifade ederler (D11.1). Allah’ın (cc) varlığını ispatlamak için kozmolojik, teleolojik (gaye ve nizam), ontolojik ve dinî tecrübe delilleri detaya girilmeden anlatılır. Bu deliller sunulurken ayet ve hadislerden faydalanılır. Bu bağlamda Hz. İbrahim kıssasına yer verilir. Ölçme ve değerlendirme uygulamalarında öğrenme günlüğü kullanılabilir."},{"kod":"DKAB.10.2.2","metin":"Öğrenciler öğretmen rehberliğinde ayet ve hadislerden faydalanarak Allah’ın (cc) isim ve sıfatlarını inceler (OB1). Öğrenciler esmayıhüsnadan hareketle Allah’ın (cc) aşkın bir varlık olarak insana ve kâinata karşı ilgisiz olmadığı konusunda çıkarımda bulunur. Bu kapsamda Allah’ın (cc) isimleri üç farklı açıdan ele alınır. Bunların kendisine mahsus olan, kâinatı ve insanı ilgilendiren isimler olduğu vurgulanır. Kendisine mahsus olanlar zatî isimler şeklinde ifade edilir. Kâinatla ilgili isimler tabiatın yaratılış ve işleyişi ile ilgilidir. İnsanı ilgilendirenler ise Allah-insan ilişkisinde insanı muhatap alan ve mükellef kılan ilahî isimlerdir. Buradan hareketle Allah’ın (cc) isimlerinin (Rahman, Rahim, Melik, Rezzak, Halık gibi) ve sıfatlarının (Kelam, İlim, İrade, Kudret ve Tekvin gibi) anlamları açıklanır. Bu isim ve sıfatların varoluşa yansıması öğrenciler tarafından örneklendirilir. Süreçte grafik düzenleyiciler kullanılabilir. Öğrenciler bu isim ve sıfatları birbiriyle ilişkilendirir. Allah’ın (cc) isimleri ve sıfatları hakkında öğrenciler bütüncül bir bakış açısı oluşturur. Bunun için çeşitli tartışma teknikleri (panel, zıt panel, kollegyum, münazara, sokratik çember) kullanılabilir (OB1). Ölçme ve değerlendirme uygulamalarında öğrencilerden fanzin hazırlamaları istenebilir. Yapılan çalışmalar dereceli puanlama anahtarı ile değerlendirilebilir. Öğrenciler, Allah’ın (cc) yarattığı canlı ve cansız her varlığın değerli olduğunu düşünerek varlıklara karşı saygılı olur (D14.4). Allah’ın (cc) Rahman isminin yansımalarını gözlemleyerek bütün canlılara karşı şefkat gösterir (D15.1)."},{"kod":"DKAB.10.2.3","metin":"Haşr suresinin 22-24. ayetleri Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetlerin nüzul sebeplerine, ayetlerde geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayetlerde verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayetlerde ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında 3-2-1 kartı kullanılabilir."}],"zenginlestirme":["Öğrencilere alanın önemli isimlerinden İbni Sina ve İbni Tufeyl’in Hay bin Yakzan isimli eserleri tavsiye edilebilir.","Öğrencilerden varlıklar arasındaki uyumu anlatan kısa videolar hazırlamaları istenebilir.","Allah’ın (cc) varlığının delillerine yönelik yapılmış akademik çalışmalar, makale ve kitapları araştırması, incelemesi elde ettiği bulgulardan en önemli gördüklerini afiş şeklinde tasarlayıp sınıf panosunda sergilemesi istenebilir.","Öğrencilerden kozmolojik ve teleolojik deliller hakkında araştırma yapmaları ve elde ettikleri sonuçları sunmaları istenebilir.","Haşr suresinin 22-24. ayetlerinde geçen Allah’ın (cc) isimleri ile ilgili esmayıhüsna sözlüğü hazırlamaları istenebilir."],"destekleme":["Allah’ın (cc) yarattığı varlıklar ve onların arasındaki ilişkileri gözlemlemek için etkileşimli sanal dış mekân etkinlikleri düzenlenir. Bu sayede öğrencilerin doğrudan gözlem yaparak kavramları daha iyi anlayabilmeleri sağlanır. Öğrencilerin metinleri daha iyi anlamaları ve yorumlamaları için görsel ve işitsel materyaller kullanılır. Öğrencilere Kur’an ayetlerinin mesajlarını özetlemeleri ve sınıflandırmaları için adım adım izlenebilecek çalışma yaprakları veya interaktif dijital araçlar sunularak öğrenme desteklenir."],"ogretmenYansitmalari":[]},
{"no":3,"ad":"İslam’ın Evrensel Mesajları","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/146","odak":"Bu ünitenin odak noktasını İslam’ın evrensel mesajları oluşturmaktadır. Öğrencilerin İslam’ın evrensel mesajlarından birinin tevhit olduğu hakkında bilgi toplayabilmesi, İslam, adalet ve eşitlik arasındaki ilişkiyi sentezleyebilmesi, İslam ve barış ilişkisini yorumlayabilmesi amaçlanır. Kur’an’dan mesajlar bölümünde ise Nahl suresi 90, Nisa suresi 58 ve Bakara suresinin 208. ayetleri ele alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.6. Bilgi Toplama","KB2.14. Yorumlama","KB2.20. Sentezleme"],"egilimler":["E2.2. Sorumluluk","E3.7. Sistematik Olma"],"sdb":["SDB1.1 Kendini Tanıma (Öz Farkındalık)","SDB2.1. İletişim","SDB2.3. Sosyal Farkındalık"],"degerler":["D1. Adalet","D11. Özgürlük","D16. Sorumluluk","D19. Vatanseverlik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Felsefe, Sosyoloji, Türk Dili ve Edebiyatı","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.10.3.1","ad":"İslam’ın evrensel mesajlarından biri olan tevhit ilkesi hakkında bilgi toplayabilme","surec":["a) İslam’da tevhit ilkesi hakkında bilgiye ulaşmak için kullanacağı kaynakları araştırır.","b) Belirlediği kaynaklardan İslam’da tevhit ilkesi hakkında bilgileri bulur.","c) İslam’da tevhit ilkesi hakkında elde ettiği bilgileri ayet ve hadisler ışığında doğrular.","ç) İslam’da tevhit ilkesi hakkında elde ettiği bilgileri kaydeder."]},{"kod":"DKAB.10.3.2","ad":"İslam’ın adalet ve eşitlik ilkeleri arasındaki ilişkiyi sentezleyebilme","surec":["a) İslam’ın adalet ve eşitlik kavramlarını araştırır.","b) İslam’ın adalet ve eşitlik kavramları arasında ilişki kurar.","c) İslam’ın adalet ve eşitlik kavramlarını birleştirerek özgün bir bütün oluşturur."]},{"kod":"DKAB.10.3.3","ad":"İslam ve barış ilişkisini yorumlayabilme","surec":["a) İslam ve barış ilişkisini inceler.","b) İslam ve barış ilişkisini bağlamı içerisinde kendisi için anlamlı hâle getirir.","c) İslam ve barış ilişkisini nesnel ve doğru bir şekilde ifade eder."]},{"kod":"DKAB.10.3.4","ad":"Nahl suresi 90, Nisa suresi 58 ve Bakara suresi 208. ayetlerin mesajlarını özetleyebilme","surec":["a) Ayetlerde verilen mesajlarla ilgili çözümleme yapar.","b) Ayetlerde geçen konuları sınıflandırır.","c) Ayetlerde verilen mesajları açıklar."]}],"icerikCercevesi":["İslam’ın Tevhit İlkesi","İslam’da Adalet ve Eşitlik","İslam ve Barış","Kur’an’dan Mesajlar"],"anahtarKavramlar":["cihat","emanet","emniyet","güven","hak","hukuk","liyakat"],"olcmeDegerlendirme":["Öğrenme çıktıları; özet metin, açık uçlu sorular, boşluk doldurma, doğru yanlış, çalışma yaprağı, küçürek hikaye, dereceleme ölçeği, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir.","Adalet konusuyla ilgili bir roman, şiir ya da hikâyenin okunup tahlilini yapma ve raporlaştırma, performans görevi olarak verilebilir. Bu performans görevi “tahlilin yeterliliği, dil ve anlatım kurallarına uyma, raporlaştırma” ölçütlerine göre öz değerlendirme formu ve dereceli puanlama anahtarı ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Eşitlik, adalet ve barış kavramlarının evrensel değerler arasında olduğunu öğrencilerin bildiği kabul edilir."],"onDegerlendirme":["İslam’da evrensel mesajların neler olduğu hakkında beyin fırtınası tekniğiyle öğrencilerin görüşlerini ifade etmeleri sağlanır. Verilen cevaplara göre öğrencilerin hazır bulunuşlukları kontrol edilir."],"kopruKurma":["Dünyadaki sorunlar (savaş, göç, açlık gibi) gündeme getirilerek bir tartışma ortamı oluşturulur. Bu tür sorunların çözümü İslam’ın adalet, barış ve eşitlik anlayışıyla ilişkilendirilir."],"uygulamalar":[{"kod":"DKAB.10.3.1","metin":"Öğrenciler tevhit kavramının tanımı hakkında bilgi elde edeceği kaynakları araştırır. Öğretmen rehberliğinde hangi kaynaklardan faydalanacağını belirler. Belirlediği kaynaklardan tevhit ilkesiyle ilgili bilgilere ulaşır. Ulaştığı bilgileri ayet ve hadisler ışığında doğrular. Tevhidin İslam’ın evrensel mesajlarından biri olduğunu öğrencinin fark etmesi sağlanır. Bu bağlamda Hz. Nuh kıssasından yola çıkılarak bütün peygamberlerin ortak mesajının tevhit olduğu vurgulanır. Elde ettiği bilgileri düşün-eşleş-paylaş tekniğiyle arkadaşlarıyla paylaşır (SDB2.1). Ölçme değerlendirme uygulamalarında öğrencilerden özet metin hazırlamaları istenebilir. Yazılan metinler dereceleme ölçeği ile değerlendirilebilir."},{"kod":"DKAB.10.3.2","metin":"Adaletin İslam’ın evrensel mesajlarından biri olduğu ayet ve hadisler bağlamında ele alınır. Allah’ın (cc) Adl ismine vurgu yapılır. İslam’da adaletin ilkelerini ve önemini araştırır. Adalet kavramı çerçevesinde öğrenciler; eşitlik, hakkaniyet (D1.1), dürüstlük, şeffaflık, tarafsızlık, emanet, liyakat, ahde vefa, insanın saygınlığı ve hesap verebilirlik ilkeleri arasındaki ilişkiyi tespit eder (OB1). Örnek olay inceleme tekniği bu süreçte kullanılabilir. İslam dininin adalet ve eşitlik konusundaki yaklaşımına ilişkin açıklamalar yapılır. Bütün insanların Allah (cc) katında eşit oluşu; kadın-erkek, işveren-işçi, amir-memur, zengin-fakir gibi ayrımların İslam’a göre insanlara bir üstünlük sağlamadığına vurgu yapılır, insanı değerli kılan özelliğin takva olduğu belirtilir (SDB2.3, E3.7). Bu kapsamda Veda Hutbesi’ne de değinilir. Öğrenciler konuyla ilgili ayet ve hadislerden hareketle, İslam’da, adalet ve eşitlik kavramları arasında ilişki kurar. Altıgen düşünme tekniği bu süreçte kullanılabilir. Öğrenciler adalet ve eşitlik konularında İslam’ın bakış açısını anlayarak özgün bir bütün oluşturur. Ölçme ve değerlendirme uygulamalarında öğrencilere adalet ve eşitlik konusu hakkında küçürek hikâye yazma görevi verilebilir. Yapılan çalışmalar dereceli puanlama anahtarıyla değerlendirilebilir."},{"kod":"DKAB.10.3.3","metin":"İslam kelimesinin anlamı sulh, selam, emniyet ve güven kavramlarıyla verilir. İslam kavramı kişinin kendisiyle ve diğerleriyle barış içinde yaşaması bağlamında ele alınır. Öğrenciler, Medine Dönemi’nde toplumsal barışın tesisi amacıyla Hz. Peygamber’in uygulamalarından hareketle İslam ve barış ilişkisini inceler. Öğrenciler Medine’de yaşanmış bir örnek olay üzerinden İslam ve barış ilişkisini kendisi için anlamlı hâle getirir (SDB1.1). İslam ve barış konusu ele alınırken cihat kavramına yer verilir. Cihadın; İslam tarihindeki bazı örneklerine, Anadolu ve Balkanlar’ın İslamlaşmasındaki rolüne, yakın tarihimizdeki Çanakkale Muharebeleri, Millî Mücadele süreci ve 15 Temmuz’da olduğu gibi barışı sağlama ve vatanı savunmadaki rolüne vurgu yapılır (D11.1). Cihat kavramı anlam genişliği göz önünde bulundurularak salt savaş ile sınırlandırılmadan tüm boyutlarıyla ele alınır. Cihadın farzıayn ve farzıkifaye olduğu durumlara değinilir. Bu kapsamda ceht, mücahede, davet, tebliğ, irşat, emir bilmaruf ve nehiy anilmünker, kıtal/mukatele ve şehadet kavramlarına yer verilir. Cihat kavramının öncelikle kişinin nefsiyle mücadelesi anlamında kullanıldığı belirtilir (E2.2). Güncel sorunlara (savaşlar, ekonomik ve sosyal problemler vb.) atıf yapılır. Öğrenciler, İslam’ın barış konusundaki yaklaşımını tarihten günümüze bir arada yaşama deneyimlerinden hareketle nesnel, doğru ve anlamını değiştirmeyecek bir şekilde ifade eder. Bu süreçte öğrencilerin her durumda vatanını sevme ve koruma bilincini kazanmaları sağlanır (D19.1). Bu bağlamda Gaziler Haftası ve 15 Temmuz Demokrasi ve Millî Birlik Günü etkinliklerine dikkat çekilir. Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."},{"kod":"DKAB.10.3.4","metin":"Nahl suresi 90. ayet, Nisa suresi 58. ayet ve Bakara suresinin 208. ayetleri Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetlerin nüzul sebeplerine, ayetlerde geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayetlerde verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayetlerde ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında boşluk doldurma, doğru-yanlış, kısa cevaplı ve açık uçlu soru türlerinden oluşan çalışma yaprağı kullanılabilir."}],"zenginlestirme":["İslam’ın evrensel mesajlarının günlük hayattaki uygulamalarına örnek olarak Veda Hutbesi sınıfta okutularak adalet, eşitlik ve barış kavramları üzerinden tahlil edilebilir.","Öğrencilerden adalet, barış ve eşitlik konularında bir poster, sunu veya bilgi grafiği hazırlamaları istenebilir.","Birleşmiş Milletler İnsan Hakları Sözleşmeleri’nde yer alan barışa yönelik ifadelerle Kur’an ve hadislerde yer alan barış ifadelerindeki benzerliklerin raporlanması ve sınıfa sunulması istenebilir."],"destekleme":["Öğrenciler dijital içerik (sesli metin, video vb.), soru cevap etkinlikleri ile desteklenebilir.","Öğrencilerden İslam’ın evrensel mesajlarına dair kavramların anlamlarını sözlükten bularak not etmeleri ve arkadaşlarıyla paylaşmaları istenebilir."],"ogretmenYansitmalari":[]},
{"no":4,"ad":"Din, Çevre ve Teknoloji","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/147","odak":"Bu ünitenin odak noktasını din, çevre ve teknoloji oluşturmaktadır. Öğrencilerin insan, çevre ve ahlak arasındaki ilişkiyi yorumlayabilmesi, teknoloji ve ahlak ilişkisini çözümleyebilmesi, çevre ve teknoloji tartışmalarını özetleyebilmesi amaçlanır. Kur’an’dan mesajlar bölümünde ise Rum suresinin 41. ayeti ele alınır. Öğrencilerin bu ayette verilen mesajları özetleyebilmesi beklenir.","dersSaati":12,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.4. Çözümleme","KB2.14. Yorumlama"],"egilimler":["E1.1. Merak","E2.1. Empati","E2.2. Sorumluluk"],"sdb":["SDB1.1. Kendini Tanıma (Öz Farkındalık)","SDB2.3. Sosyal Farkındalık"],"degerler":["D5. Duyarlılık","D8. Mahremiyet","D14. Saygı","D16. Sorumluluk","D17. Tasarruf","D18. Temizlik"],"okuryazarlik":["OB2. Dijital Okuryazarlık","OB8. Sürdürülebilirlik Okuryazarlığı"],"disiplinlerArasi":"Bilişim Teknolojileri, Coğrafya, Felsefe","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.10.4.1","ad":"İnsan, çevre ve ahlak arasındaki ilişkiyi yorumlayabilme","surec":["a) İnsan, çevre ve ahlak arasındaki ilişkiyi inceler.","b) Çevreye karşı ahlaki sorumluluklarını bağlamından koparmadan kendi yaşantısı için anlamlı hâle getirir.","c) İnsan ve çevre arasındaki ilişkiyi nesnel bir biçimde ifade eder."]},{"kod":"DKAB.10.4.2","ad":"Teknoloji ve ahlak ilişkisini çözümleyebilme","surec":["a) Teknoloji ve ahlakla ilgili unsurları araştırır.","b) Teknoloji ve ahlakla ilgili unsurlar arasındaki ilişkileri belirler."]},{"kod":"DKAB.10.4.3","ad":"Çevre ve teknoloji ilişkisini özetleyebilme","surec":["a) Çevre ve teknoloji ilişkisi ile ilgili çözümleme yapar.","b) Çevre ve teknoloji arasındaki ilişkileri sınıflandırır.","c) Çevre ve teknoloji ilişkisini açıklar."]},{"kod":"DKAB.10.4.4","ad":"Rum suresi 41. ayetin mesajlarını özetleyebilme","surec":["a) Ayette verilen mesajlarla ilgili çözümleme yapar.","b) Ayette geçen konuları sınıflandırır.","c) Ayette verilen mesajları açıklar."]}],"icerikCercevesi":["İnsan, Çevre ve Ahlak","Teknoloji ve Ahlak","Çevre ve Teknoloji","Kur’an’dan Mesajlar"],"anahtarKavramlar":["çevre","teknoloji"],"olcmeDegerlendirme":["Öğrenme çıktıları; balık kılçığı diyagramı, 3-2-1 kartı, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir.","Çevre ve teknoloji ilişkisiyle ilgili düzenlenecek bir konferans için konuşma metni hazırlama, performans görevi olarak verilebilir. Bu performans görevi “konuyu araştırma, kaynak kullanma, metnin konuyu kapsaması, dil ve anlatım kurallarına uygunluk” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin çevreyi korumak ve teknolojiyi verimli kullanmak konusunda temel bilgilere sahip oldukları kabul edilmektedir."],"onDegerlendirme":["“Yarın kıyametin kopacağını bilseniz bile elinizdeki fidanı dikiniz.” (İbn Hanbel, III, 184.) hadisinden hareketle öğrencilerin din ve çevre konusundaki görüşleri alınarak hazır bulunuşlukları kontrol edilir."],"kopruKurma":["İslam’ın temel ilkeleri çerçevesinde, çevre ve teknolojiyle ilgili güncel problemler ele alınarak gerçek yaşamla köprü kurulur."],"uygulamalar":[{"kod":"DKAB.10.4.1","metin":"Öğrencilerin insan, çevre ve ahlak arasındaki ilişkiyi fıtrat, denge, ölçü ve bütünlük kavramları ekseninde incelemesi sağlanır. Konuyla ilgili belgesel veya görsellerden yararlanılarak çevresel sorunların hayata etkileri üzerinde durulur (OB8). Öğrenciler çevreye karşı ahlaki sorumluluklarını kendi yaşantısı için anlamlandırır. Yer altı ve yer üstü kaynaklarını amacına uygun kullanır. İsrafın olası zararlarını fark eder (D17.2). İnsan ve çevre arasındaki ilişkiyi İslam’ın çevreye dair temel ahlaki ilkelerini dikkate alarak ifade etmelerine imkân verilir (SDB2.3). Bu süreçte arkadaşa öğret tekniği kullanılabilir. Güncel çevre sorunlarına değinilerek öğrencilerin çevreye karşı sorumluluklarının farkına varmaları konuşma halkası tekniğiyle sağlanabilir (E2.2, D16.2). Çevre sorunlarını (biyoçeşitliliğin kaybı, çevre kirliliği ve bilinçsiz su tüketimi vb.) merak etmeleri sağlanarak ve gelecek yıllarda bu sorunların ne düzeyde küresel sorunlara dönüşebileceğine dair görüşlerini beyin fırtınası tekniği ile belirtmelerine imkân verilir (E1.1, D18.3, SDB2.3). Bu şekilde öğrenciler farklı açılardan olaylara bakarak problemlere çözümler bulur. Ölçme ve değerlendirme uygulamalarında balık kılçığı diyagramı kullanılabilir."},{"kod":"DKAB.10.4.2","metin":"Teknoloji ve ahlak arasındaki ilişki güncel teknolojik gelişmelerle bağlantı kurularak incelenir. Öğrenciler teknoloji ve ahlakla ilgili unsurları araştırır. Bu süreçte çift sütun tekniği kullanılabilir. Teknolojinin geliştirilmesinde ve kullanılmasında ahlaki kurallara dikkat edilmesi gerektiği vurgulanır. Teknoloji ve ahlak arasındaki ilişkinin belirlenmesinde örnek olay incelemesi tekniği kullanılabilir (OB2, SDB1.1). Öğrencilerin sosyal medya, genetik, biyoteknoloji, yapay zekâ, savaş teknolojisi, sanal gerçeklik, dijital oyunlar gibi teknolojik alanlarda sorumluluk bilincine sahip olması, kişisel hakların ve verilerin korunması ile mahremiyet ilkelerine uygun davranışlar geliştirmesi hedeflenir. Bu süreçte Kişisel Verileri Koruma Günü ile ilgili etkinlikler hakkında bilgi verilebilir. Öğrenciler, kendisinin, ailesinin ve başkalarının özel alanını ve bilgilerini korur; başkalarının özgürlüklerini ihlal etmez ve kişisel sınırlara saygı duyar (D8.1, D14.2). Drama tekniği bu süreçte kullanılabilir. Ölçme ve değerlendirme uygulamalarında dijital öykü yazılması istenebilir ve hazırlanan öyküler dereceli puanlama anahtarıyla değerlendirilebilir."},{"kod":"DKAB.10.4.3","metin":"Teknolojik gelişmelerin sebep olduğu çevre problemleri ile ilgili (iklim değişikliği, ormanların yok edilmesi, nesli tükenme tehlikesi altında olan hayvanlar, çarpık kentleşme, tüketim bağımlılığı vb.) belgesel veya kısa film izletilerek öğrencilerin çevreye ve canlılara ilişkin duyarlılık kazanmaları sağlanabilir (D5.4). Çevre ve teknoloji ilişkisi incelenir. Öğrencilerin bu ilişkileri çözümlemesi çember tekniği kullanılarak sağlanabilir. Mevcut sorunların sınıflandırılmasında 5N1K tekniği kullanılabilir (SDB2.3). Öğrenciler “Ben Olsam Ne Yapardım?” etkinliği ile çevre sorunlarına dair açıklama yaparak çözüm üretirler (SDB1.1, E2.1, OB8). Konu kapsamında Çevre ve İklim Değişikliği Haftası ile Dünya Su Günü etkinlikleri hakkında bilgi verilebilir. Ölçme ve değerlendirme uygulamalarında 3-2-1 kartları kullanılabilir."},{"kod":"DKAB.10.4.4","metin":"Rum suresinin 41. ayeti Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetin nüzul sebebine, ayette geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayette verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayette ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında öz değerlendirme formu kullanılabilir."}],"zenginlestirme":["Günümüzdeki çevre ve teknoloji sorunlarını konu edinen fotoğraf ve kısa film yarışmaları düzenlenerek öğrencilerin mevcut potansiyellerini keşfetmeleri sağlanır. Teknolojik bağımlılıklar hakkında Yeşilay’ın Türkiye Bağımlılıkla Mücadele Eğitim Programı’ndaki materyallerinden faydalanılabilir."],"destekleme":["Özel öğretim yöntemleri kullanılarak öğrencinin çevre ve teknoloji hakkında merak ettikleri soruları sormaları ve cevap bulmaları anlamında etkinlikler planlanabilir. Öğrenciler gruplara ayrılarak akran öğretimi uygulanabilir."],"ogretmenYansitmalari":[]},
{"no":5,"ad":"İslam Düşüncesinde İtikadi-Siyasi ve Fıkhi Yorumlar","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/148","odak":"Bu ünitenin odak noktasını İslam düşüncesinde itikadi-siyasi ve fıkhi yorumlar oluşturmaktadır. Öğrencilerin dinî yorumların ortaya çıkış sebeplerini sorgulayabilmesi, İslam düşüncesindeki itikadi-siyasi ve fıkhi yorumları karşılaştırabilmesi amaçlanır. Kur’an’dan mesajlar bölümünde Hucurat suresinin 13. ayeti ele alınır. Öğrencilerin bu ayette verilen mesajları özetleyebilmesi beklenir.","dersSaati":12,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.7. Karşılaştırma","KB2.20. Sentezleme"],"egilimler":["E3.5. Açık Fikirlilik","E3.7. Sistematik Olma","E3.8. Soru Sorma","E3.10. Eleştirel Bakma"],"sdb":["SDB2.1. İletişim","SDB2.3. Sosyal Farkındalık"],"degerler":["D14. Saygı"],"okuryazarlik":["OB2. Dijital Okuryazarlık","OB5. Kültür Okuryazarlığı"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.10.5.1","ad":"Dinî yorum farklılıklarının ortaya çıkış sebeplerini sentezleyebilme","surec":["a) Dinî yorum farklılıklarının ortaya çıkış sebeplerinin neler olduğunu belirler.","b) Dinî yorum farklılıklarının ortaya çıkış sebepleri arasında ilişki kurar.","c) Dinî yorum farklılıklarının ortaya çıkış sebepleriyle ilgili bütünsel bakış açısına ulaşır."]},{"kod":"DKAB.10.5.2","ad":"İslam düşüncesindeki itikadi-siyasi ve fıkhi yorumları karşılaştırabilme","surec":["a) İslam düşüncesindeki itikadi-siyasi ve fıkhi yorumların özelliklerini ve konu ile ilgili temel kavramları açıklar.","b) İslam düşüncesindeki itikadi-siyasi ve fıkhi yorumların özelliklerine ilişkin benzerlikleri listeler.","c) İslam düşüncesindeki itikadi-siyasi ve fıkhi yorumların özelliklerine ilişkin farklılıkları listeler."]},{"kod":"DKAB.10.5.3","ad":"Hucurat suresi 13. ayetin mesajını özetleyebilme","surec":["a) Ayette verilen mesajlarla ilgili çözümleme yapar.","b) Ayette geçen konuları sınıflandırır.","c) Ayette verilen mesajları açıklar."]}],"icerikCercevesi":["Dinî Yorum Farklılıklarının Sebepleri","İslam Düşüncesinde İtikadi-Siyasi ve Fıkhi Yorumlar","Kur’an’dan Mesajlar"],"anahtarKavramlar":["Ehlisünnet","fıkıh","itikat","mezhep","tevil"],"olcmeDegerlendirme":["Öğrenme çıktıları; bilgi haritası, yapılandırılmış grid, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir.","İslam düşüncesindeki yorum farklılıkları konusunda bilgi grafiği hazırlama, performans görevi olarak verilebilir. Bu performans görevi “bilgi toplama, dil ve anlatım kurallarına uygunluk, uygun görsel kullanma, kaynak kullanma, metnin konuyu kapsaması” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Farklı dinî yorumların var olduğunu bildikleri ve Hanefilik, Şafiilik hakkında bilgi sahibi oldukları kabul edilir."],"onDegerlendirme":["Öğrencilere daha önce duydukları bir mezhep olup olmadığı sorusu sorulur. Öğrencilerden konuyla ilgili geçmiş bilgilerinden faydalanmaları istenir. Dijital öğrenme platformları kullanılarak uygun videolar izletilir ve insanların yorum farklılıklarının nelerden kaynaklandığı ve bunların sebeplerinin neler olabileceği soruları öğrencilere yöneltilir. Böylece öğrencilerin din ve dinî yorum hakkında hazır bulunuşlukları kontrol edilir."],"kopruKurma":["İnsanların karşılaştıkları olaylar hakkında farklı yorumlarda bulunmalarının birçok sebebi vardır. İnsanın karakteri, yetiştiği coğrafya, aldığı eğitim gibi sebepler farklı yorumları ortaya çıkarır. İslam düşüncesindeki itikadi-siyasi ve fıkhi yorumlar da bu bağlamda değerlendirilir. Öğrencilerin herhangi bir konuda farklı fikirler ortaya koymasıyla İslam düşüncesinde ortaya çıkan yorum farklılıklarının sebepleri arasında köprü kurulur."],"uygulamalar":[{"kod":"DKAB.10.5.1","metin":"Öğrenciler dinî yorum farklılıkları hakkında merak ettiklerini sorar (E3.8). Dinî yorum farklılıklarının sebepleri ile ilgili bir metin paylaşılır ve bu metinden hareketle öğrencilerin dinî yorum farklılıklarının sebeplerini belirlemelerine imkân tanınır (OB5). Bu sebepler arasında ilişki kurmaları sağlanır. Beyin fırtınası tekniği bu süreçte kullanılabilir. Öğrencilerin dinî yorum farklılıklarının zenginlik olduğunu, böylece İslam’ın tüm çağ ve coğrafyalarda yaşanabilir hâle geldiğini fark etmeleri ve bütünsel bir bakış açısına ulaşmaları amaçlanır. Bu süreçte zıt panel tekniği uygulanabilir (E3.5). Dinin yanlış yorumlanmasından doğan sorunların, dinin kendisinden kaynaklanmadığı vurgulanır. Ölçme ve değerlendirme uygulamalarında bilgi haritası kullanılabilir."},{"kod":"DKAB.10.5.2","metin":"Dinî yorum farklılıklarının itikadi-siyasi, fıkhi konular bağlamında ortaya çıktığı belirtilir. Mezhep, fıkıh, fırka ve tevil kavramları hakkında bilgi verilir. Öğrencilere “Mezhepler hakkında neler biliyorsunuz?” sorusu yöneltilerek soru-cevap tekniği uygulanabilir. Ehlisünnet başlığı altında itikadi yorumlardan Eşarilik ve Matüridilik; fıkhi yorumlardan Hanefilik, Malikilik, Şafilik ve Hanbelilik; Şia başlığı altında Caferilik hakkında bilgi verilir; Caferiliğin Şia’nın fıkhi yorumu olduğuna vurgu yapılır (E3.7). Öğrenciler, itikadi-siyasi ve fıkhi yorum türleri arasındaki benzerlikler ve farklılıkları listeler. Bu süreçte istasyon tekniği kullanılabilir (E3.10, SDB2.3). İslam düşüncesindeki farklı yorumların zenginlik olduğuna, İslam’ın fikir özgürlüğüne verdiği öneme ve farklı fikirlere saygı duymanın gerekliliğine değinilir (D14.1). Ölçme ve değerlendirme uygulamalarında yapılandırılmış grid kullanılabilir."},{"kod":"DKAB.10.5.3","metin":"Hucurat suresinin 13. ayeti Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetin nüzul sebebine, ayette geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayette verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayette ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında öz değerlendirme formu kullanılabilir."}],"zenginlestirme":["Öğrencilerden iktisadi, siyasi ve fıkhi mezhepler ve bu mezheplerin hangi olay veya durumlardan dolayı ortaya çıktığını akademik makalelerden araştırması ve bulgularını özetleyerek arkadaşlarına sunması istenebilir.","Öğrencilerden namaz ibadetinin uygulanışındaki mezhepler arası farklılıkları araştırması istenebilir."],"destekleme":["Öğrenciler dijital içerikler (sesli metin, video vb.) ve soru cevap etkinlikleri ile desteklenebilir. Doğru yanlış, boşluk doldurma, eşleştirme, sözcük avı gibi etkinliklerin yanında EBA’da yer alan dijital içerikler de kullanılabilir."],"ogretmenYansitmalari":[]}],"s11":[{"no":1,"ad":"Kader, İrade ve Sorumluluk","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/149","odak":"Bu ünitenin odak noktasını kader, irade ve sorumluluk konuları oluşturmaktadır. Öğrencilerin kader ve kaderle ilgili kavramları yapılandırabilmesi, insan, akıl, irade ve sorumluluk arasındaki ilişki hakkında eleştirel düşünebilmesi amaçlanır. Kur’an’dan mesajlar bölümünde Bakara suresinin 286. ayeti ele alınır. Öğrencilerin bu ayette verilen mesajları özetleyebilmesi beklenir.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.13. Yapılandırma","KB3.3. Eleştirel Düşünme"],"egilimler":["E1.2. Bağımsızlık","E2.2. Sorumluluk","E3.8. Soru Sorma"],"sdb":["SDB2.1. İletişim","SDB3.3. Sorumlu Karar Verme"],"degerler":["D11. Özgürlük","D5. Duyarlılık","D16. Sorumluluk"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Felsefe","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.11.1.1","ad":"Kader ve kaderle ilgili kavramları yapılandırabilme","surec":["a) Kader ve kaderle ilgili kavramları inceleyerek nedensel ilişkiler ortaya koyar.","b) Kader ve kaderle ilgili kavramlara dair elde ettiği bilgilere dayalı olarak bütüncül bir bakış açısı ortaya koyar."]},{"kod":"DKAB.11.1.2","ad":"İnsan, akıl, irade ve sorumluluk kavramları arasındaki ilişki hakkında eleştirel düşünebilme","surec":["a) İnsan, akıl, irade ve sorumluluk arasındaki ilişkiyi sorgular.","b) İnsan, akıl, irade ilişkisi bağlamında insanın özgür ve sorumlu bir varlık olduğu ile ilgili akıl yürütür.","c) İnsanın özgürlüğü ve sorumluluğu konusunda akıl yürütmeyle ulaştığı çıkarımları yansıtır."]},{"kod":"DKAB.11.1.3","ad":"Bakara suresi 286. ayetin mesajlarını özetleyebilme","surec":["a) Ayette verilen mesajlarla ilgili çözümleme yapar.","b) Ayette geçen konuları sınıflandırır.","c) Ayette verilen mesajları açıklar"]}],"icerikCercevesi":["İnsan ve Kader","Akıl, İrade ve Sorumluluk Sahibi Bir Varlık Olarak İnsan","Kur’an’dan Mesajlar"],"anahtarKavramlar":["insan","irade","kader","kaza","özgürlük","sorumluluk"],"olcmeDegerlendirme":["Öğrenme çıktıları; bilgi kartı, 3-2-1 kartı, dereceli puanlama anahtarı, öz değerlendirme formu ve açık uçlu sorular kullanılarak değerlendirilebilir.","Öğrencilerden performans görevi olarak kaderle ilişkili olarak başarı-başarısızlık hakkında köşe yazısı yazmaları istenebilir. Bu performans görevi “bilgiyi kullanma, dil ve anlatım kurallarına uygunluk, kaynak kullanma, metnin kapsam geçerliliği” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin kadere imanın İslam inanç esasları arasında yer aldığını bildikleri kabul edilir."],"onDegerlendirme":["Öğrencilere kader, akıl, irade ve sorumluluk kavramlarıyla ilgili sorular sorularak öğrencilerin verdikleri cevaplara göre ön bilgileri kontrol edilir."],"kopruKurma":["“İnsanların kendi elleriyle yapıp ettikleri yüzünden karada ve denizde düzen bozuldu…” (Rum suresi, 41. ayet.) ayet mealinde verilen mesajla insan iradesi arasında öğrencilerin köprü kurması sağlanır."],"uygulamalar":[{"kod":"DKAB.11.1.1","metin":"Öğrencilerin kaderle ilgili merak ettiklerini sormalarına imkân verilir (E3.8). Soru kutusu tekniği bu süreçte kullanılabilir. Kader ve kaza kavramları hakkında bilgi verilir. “Sünnetullah, afet, rızık, sabır, ömür, ecel, hastalık, sağlık, başarı, başarısızlık, hidayet, dalalet, hayır, şer, dua, tevekkül, teslimiyet, rıza ve imtihan” kavramları açıklanır. Bu bağlamda Hz. Eyyüb kıssasına vurgu yapılır. Rızık kavramı açıklanırken helal kazancın önemine değinilir. Öğrencilerin bu kavramların kaderle bağlantısını dikkate alarak nedensel ilişkiler kurmaları ve elde ettiği bilgilerle bütüncül bir bakış açısı ortaya koymaları sağlanır. Toplumda yaygın olan yanlış kader anlayışlarına dikkat çekilir. Öğrencilerin kaderin yanlış yorumlanmasından doğan sorunların, insanın iradesinden kaynaklandığı çıkarımında bulunmalarına rehberlik edilir. Fay hatları ya da dere yatakları üzerine ev yapmanın ortaya çıkarabileceği olumsuz durumlarla ilgili farkındalığı artırmak için tartışma tekniklerinden yararlanılabilir (D5.2, D16.2). Bu süreçte Dünya Afet Risklerini Azaltma Günü’ne dikkat çekilebilir ve bu konuda etkinlikler yaptırılabilir. Ölçme ve değerlendirme uygulamalarında bilgi kartı kullanılabilir."},{"kod":"DKAB.11.1.2","metin":"İnsanın aklı sayesinde nesne, olay ve olgulara dair doğru-yanlış, iyi-kötü, güzel-çirkin, hayır-şer ayrımı yapabilen (temyiz ve tefrik kabiliyeti olan) bir varlık olduğu üzerinde durulur. Öğrenciler insan, akıl, irade ve sorumluluk arasındaki ilişkiyi sorgular. Bu bağlamda insanın özgürlüğü ve özgürlüğünün sınırları ele alınır (E1.2). İnsan için mutlak özgürlüğün olmadığı ifade edilir ancak insanın, davranışlarında özgürce karar verebildiği sürece sorumlu olduğu vurgulanır (D11.1). Bu süreçte rol oynama ve drama teknikleri kullanılabilir. Allah’ın (cc) bilgisi ve insanın iradesi arasındaki ilişkinin insanın akıllı, özgür ve sorumlu bir varlık olmasıyla çelişmediği belirtilir. Öğrenciler, insanın özgür ve sorumlu bir varlık olduğu ile ilgili akıl yürütür. Öğrenciler, mükellefiyet kavramıyla insanın özgürce karar vermesi ve kararlarının sorumluluğunu üstlenmesi arasında ilişki kurar (SDB3.3). Bu bağlamda insanın Allah’a (cc), kendisine ve çevresine karşı sorumlulukları belirlenir (E2.2). Bu süreçte İş Sağlığı ve Güvenliği Haftası ile ilgili bilgi verilebilir. Ölçme ve değerlendirme uygulamalarında 3-2-1 kartı kullanılabilir."},{"kod":"DKAB.11.1.3","metin":"Bakara suresinin 286. ayeti Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetin nüzul sebebine, ayette geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayette verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayette ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."}],"zenginlestirme":["Öğrencilerden insanın Allah’a (cc), kendisine ve çevresine karşı sorumluluklarıyla ilgili bilgi grafiği hazırlamaları istenebilir.","Üniversite sınavına hazırlanan bir öğrencinin hedefe ulaşması sürecinde kader ve sorumluk arasındaki ilişki incelenebilir."],"destekleme":["Kader ve insan ilişkisi konusunda, kavramları açıklamak için günlük hayattan örnekler ve hikâyeler kullanılabilir.","Aklıselim sahibi insan ve aklın hüküm verme kabiliyeti üzerine düşünmeleri için öğrencilere senaryo tabanlı örnek olaylar sunulabilir. Kur’an-ı Kerim ayetlerinin okunması ve yorumlanmasında, öğrencilere ayetlerin anlamını ve önemini daha iyi kavrayabilmeleri için görsel ve işitsel destekler sağlanabilir."],"ogretmenYansitmalari":[]},
{"no":2,"ad":"Din, Felsefe, Bilim ve Sanat","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/150","odak":"Bu ünitenin odak noktasını dinin felsefe, bilim ve sanatla olan ilişkisi oluşturmaktadır. Öğrencilerin din tanımlarını ve din ile ilgili yaklaşımları genelleyebilmesi, din, felsefe ve bilim arasındaki ilişkiyi sorgulayabilmesi, din ve sanat arasındaki ilişkiyi çözümleyebilmesi amaçlanır. Kur’an’dan mesajlar bölümünde Al-i İmran suresinin 190-191. ayetleri ele alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.4. Çözümleme","KB2.8. Sorgulama","KB2.9. Genelleme"],"egilimler":["E1.1. Merak","E3.5. Açık Fikirlilik","E3.8. Soru Sorma","E3.11. Özgün Düşünme"],"sdb":["SDB2.1. İletişim","SDB2.2. İş Birliği"],"degerler":["D3. Çalışkanlık","D7. Estetik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık","OB9. Sanat Okuryazarlığı"],"disiplinlerArasi":"Tarih, Türk Dili ve Edebiyatı, Felsefe","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.11.2.1","ad":"Din tanımlarını ve din ile ilgili yaklaşımları genelleyebilme","surec":["a) Din tanımları ve farklı disiplinlerin dine yaklaşımları hakkında bilgi toplar.","b) Din tanımlarının ve farklı disiplinlerin dine yaklaşımları hakkında ortak özelliklerini belirler.","c) Din tanımlarının ve farklı disiplinlerin dine yaklaşımları hakkında ortak olmayan özelliklerini belirler.","ç) Din tanımları ve farklı disiplinlerin dine yaklaşımları hakkındaki örüntüler üzerinden önermede bulunur."]},{"kod":"DKAB.11.2.2","ad":"Dinin felsefe ve bilimle ilişkisini sorgulayabilme","surec":["a) Dinin felsefe ve bilimle ilişkisi hakkında merak ettiklerini tanımlar.","b) Dinin felsefe ve bilimle ilişkisi hakkında sorular sorar.","c) Dinin felsefe ve bilimle ilişkisi hakkında bilgi toplar.","ç) Dinin felsefe ve bilimle ilişkisine yönelik elde ettiği bilgilerin doğruluğunu değerlendirir.","d) Felsefe ve bilimin İslam kültüründeki yerine ve İslam düşüncesine katkılarına dair çıkarımda bulunur."]},{"kod":"DKAB.11.2.3","ad":"Din ve sanat arasındaki ilişkiyi çözümleyebilme","surec":["a) Din ve sanat ilişkisinin temel unsurlarını araştırır.","b) Belirlediği unsurlar arasındaki ilişkileri tespit eder."]},{"kod":"DKAB.11.2.4","ad":"Al-i İmran suresi 190-191. ayetlerin mesajlarını özetleyebilme","surec":["a) Ayetlerde verilen mesajlarla ilgili çözümleme yapar.","b) Ayetlerde geçen konuları sınıflandırır.","c) Ayetlerde verilen mesajları açıklar."]}],"icerikCercevesi":["Din","Din, Felsefe ve Bilim","Din ve Sanat","Kur’an’dan Mesajlar"],"anahtarKavramlar":["âlim","Beytülhikme","darülhadis","darülkurra","filozof","ilim","medrese","rasathane"],"olcmeDegerlendirme":["Öğrenme çıktıları; açık uçlu sorular, kavram haritası, 3-2-1 kartı, çalışma yaprağı, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir.","Dinin felsefe, bilim ve sanatla ilişkisiyle ilgili bir blog yazısı yazma, performans görevi olarak verilebilir (Türk Dili ve Edebiyatı). Bu performans görevi, “bilgi toplama, yorumlama, içerik, özgünlük, dil ve anlatıma uygunluk” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin bu ünitede din, felsefe, bilim ve sanat kavramlarına aşina oldukları ve bu kavramlarla ilgili deneyim ve gözleme dayalı fikirlerinin olduğu kabul edilmektedir."],"onDegerlendirme":["“Din nedir, felsefe nedir, bilim nedir ve sanat nedir?” soruları sırayla yöneltilir. Verilen cevaplardan yola çıkılarak öğrencilerin hazır bulunuşlukları tespit edilir."],"kopruKurma":["Öğrencilere felsefe, bilim, sanat alanında eserler vermiş Müslüman âlimlerin biyografilerinin ele alındığı belgeseller izletilir. Okul çevresine yakın, konuyla ilgili müze, kütüphane ve mimari eserlere gezi düzenlenerek yukarıda geçen kurum veya eserler ziyaret edilebilir. 3D gösterimi yapan sitelerden ilgili eserler çevrimiçi olarak sınıfta incelenebilir. Bu etkinliklerin ardından öğrencilere gözlemleri, dinin bu eserlerdeki etkisi sorularak derste işlenen konularla köprü kurulması sağlanır."],"uygulamalar":[{"kod":"DKAB.11.2.1","metin":"İslam âlimlerinin din tanımlarının yanında felsefe, psikoloji, sosyoloji ve antropolojinin dine yaklaşımları açıklanır. Din anlayışının dinden farkına vurgu yapılarak örnekler verilir. Öğrenciler, bu yaklaşımlarla ilgili bilgi toplar. Bu tanım ve yaklaşımların benzer ve farklı yönlerini tespit eder. Çift sütun tekniği bu süreçte kullanılabilir. Öğrenciler din tanımları ve farklı disiplinlerin dine yaklaşımları hakkında önermelerde bulunur (E3.11). Evet-hayır kartlarıyla paylaşılan önermeler değerlendirebilir. Ölçme ve değerlendirme uygulamalarında 3-2-1 kartı kullanılabilir."},{"kod":"DKAB.11.2.2","metin":"Öğrenciler din, felsefe ve bilime dair merak ettiklerini tanımlar ve konuya dair öğrencilerin sorular sormaları sağlanır (E1.1, E3.8). Kum saati tekniği bu süreçte kullanılabilir. Felsefi bilgiden bahsedilerek öğrencilerin felsefenin sınırlılıklarını tartışma tekniğiyle değerlendirmeleri istenir (SDB2.1). Felsefi düşüncenin İslam kültüründeki yerine ve İslam düşüncesine olan katkılarına değinilir. İlgili konu bağlamında ilim, âlim ve filozof kavramlarına yer verilir. Öğrencilere, İslam medeniyetinde bilim ve düşüncenin gelişim süreci hakkında bilgi verilir. Öğrenciler, İslam medeniyetinde öne çıkan eğitim ve bilim kurumları (Cami, mescit, mektep, medrese, darulkurra, darulhadis, Beytülhikme, kütüphane, rasathane ve şifahane ile sınırlandırılır.) örneklerinden yola çıkarak İslam ve bilim arasında ilişki kurar. Öğrenciler dinin felsefe ve bilimle olan ilişkisine dair bilgi toplar (OB1). Din, bilim ve felsefe arasındaki ilişki ele alınır. Bu süreçte münazara tekniği kullanılabilir (SDB2.1, SDB2.2). Bu sayede öğrenciler, düşüncelerini açık fikirlilikle ele almanın önemini fark ederek çalışmalarını kararlılıkla yürütürler (E3.5, D3.1). Toplanan bilgiler öğretmen rehberliğinde değerlendirilir. Din, felsefe ve bilimin etkileşim hâlinde oldukları ve birbirleriyle çelişmedikleri çıkarımında bulunmaları sağlanır. Konu ile ilişkilendirilerek Kütüphaneler Haftası ile ilgili etkinlikler hakkında bilgilendirme yapılabilir. Ölçme ve değerlendirme uygulamalarında kısa cevaplı ve açık uçlu sorular ile doğru-yanlış sorularından oluşan bir çalışma yaprağı kullanılabilir."},{"kod":"DKAB.11.2.3","metin":"Sanat ve estetik kavramları hakkında bilgi verilir. Allah’ın (cc) “Cemal” ve “Muhsin” isimleriyle kainattaki güzellikler arasında ilişki kurulur. Öğrenciler bu bağlamda din ve sanat arasındaki ilişkinin unsurlarını araştırır (OB9). Öğrenciler Allah’ın (cc) esmasından sanata yansıyan boyutlarına dair çeşitli örneklerden din ve sanatın unsurları arasındaki ilişkiyi belirler. Öğrenciler yaşadığı çevredeki sanat eserlerini ve doğal güzellikleri tanır. Öğrencilerin sanat eserlerini din ve sanat ilişkisi bağlamında öğrendikleriyle ve toplumsal değerlerle ilişkilendirerek yorumlamaları sağlanır (D7.1). Bu süreçte gezi gözlem veya görsel yorumlama yöntemleri kullanılabilir. Bu konudaki ölçme ve değerlendirme uygulamalarında kavram haritası kullanılabilir."},{"kod":"DKAB.11.2.4","metin":"Al-i İmran suresinin 190-191. ayetleri Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetlerin nüzul sebeplerine, ayetlerde geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayetlerde verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayetlerde ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."}],"zenginlestirme":["Öğrencilerden kültürümüze ait somut ve somut olmayan mirası tespit etmeleri ve bu eserlerle ilgili çeşitli araştırmalar yapmaları istenebilir."],"destekleme":["Öğrencilere din tanımları ve yaklaşımları sunulurken görsel ve işitsel malzemelerden yararlanmak, farklı öğrenme stillerine hitap eder. Felsefe ve bilim kavramları tanıtılırken, öğrencilere farklı düşünce sistemlerini keşfetmeleri için interaktif etkinlikler ve tartışma ortamları sunulabilir. Din ve sanat arasındaki ilişkiyi inceleyen etkinliklerde, çeşitli sanat eserleri ve mimari örneklerini içeren görsel materyaller kullanılabilir. Kur’an-ı Kerim ayetlerinin analizi sırasında, öğrencilere metinlerin derinlemesine anlaşılmasına yardımcı olacak görsel ve işitsel destekler sunulabilir. Ayetlerin günlük hayatla ilişkilendirilmesi için öğrencilerin kendi deneyimlerini tartışmaları teşvik edilebilir."],"ogretmenYansitmalari":[]},
{"no":3,"ad":"İslam Medeniyeti ve Gönül Coğrafyamız","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/151","odak":"Bu ünitenin odak noktasını İslam medeniyeti ve gönül coğrafyamız oluşturmaktadır. Öğrencilerin medeniyetin oluşumuna etki eden unsurları çözümleyebilmesi, İslam medeniyetinin izlerini özetleyebilmesi, İslam medeniyetinin bugünü ve geleceği hakkında akıl yürütebilmesi amaçlanır. Kur’an’dan mesajlar bölümünde Rum suresinin 9. ayeti ele alınır. Öğrencilerin bu ayette verilen mesajları özetleyebilmesi beklenir.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.4. Çözümleme","KB2.16.3. Analojik Akıl Yürütme"],"egilimler":["E1.1. Merak","E2.5. Oyunseverlik","E3.2. Odaklanma"],"sdb":["SDB2.1. İletişim","SDB2.2. İş Birliği"],"degerler":["D16. Sorumluluk"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık","OB4. Görsel Okuryazarlık","OB5. Kültür Okuryazarlığı","OB9. Sanat Okuryazarlığı"],"disiplinlerArasi":"Tarih, Coğrafya, Türk Dili ve Edebiyatı","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.11.3.1","ad":"Medeniyetin oluşumuna etki eden unsurları çözümleyebilme","surec":["a) Medeniyetin oluşumuna ilişkin unsurları araştırır.","b) Medeniyetin oluşumuna etki eden unsurlar arasındaki ilişkileri belirler."]},{"kod":"DKAB.11.3.2","ad":"İslam medeniyetinin izlerini özetleyebilme","surec":["a) İslam medeniyetinin mimari, musiki, dil ve edebiyata olan etkisini çözümler.","b) İslam medeniyetinin izlerini bölgelere göre sınıflandırır.","c) İslam medeniyetinin Anadolu ve Balkanlara taşınmasında Horasan, Anadolu ve Rumeli erenlerinin rolünü açıklar."]},{"kod":"DKAB.11.3.3","ad":"İslam medeniyetinin bugünü ve geleceği hakkında akıl yürütebilme","surec":["a) Türk İşbirliği ve Koordinasyon Ajansı Başkanlığı (TİKA), Yurtdışı Türkler ve Akraba Topluluklar Başkanlığı (YTB), Yunus Emre Enstitüsü (YEE),Türkiye Maarif Vakfı (TMV), Türkiye Diyanet Vakfı (TDV) gibi kurumların gönül coğrafyamızda gerçekleştirdiği çalışmaları gözlemler.","b) Bu kurumların gönül coğrafyamızda yaptıkları çalışmaların niteliklerini tespit eder.","c) Gönül coğrafyamızda yapılan çalışmaların birliğe, beraberliğe, yardımlaşma ve dayanışmaya olan katkısıyla ilgili çıkarım yapar."]},{"kod":"DKAB.11.3.4","ad":"Rum suresi 9. ayetin mesajlarını özetleyebilme","surec":["a) Ayette verilen mesajlarla ilgili çözümleme yapar.","b) Ayette geçen konuları sınıflandırır.","c) Ayette verilen mesajları açıklar."]}],"icerikCercevesi":["Medeniyetin Oluşumu","İslam Medeniyetinin İzleri","İslam Medeniyetinin Bugünü ve Geleceği","Kur’an’dan Mesajlar"],"anahtarKavramlar":["medeniyet","mimari","musiki","vakıf"],"olcmeDegerlendirme":["Öğrenme çıktıları; açık uçlu sorular, kısa cevaplı sorular, 3-2-1 kartları, bilgi grafiği, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir.","İslam kültür ve medeniyetine katkı sağlayan öncü isimler ve onların çalışmaları performans görevi olarak verilebilir. Bu performans görevi “bilgi toplama, inceleme, yorumlama, dil ve anlatım kurallarına uyma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin medeniyet kavramı hakkında bilgi sahibi olduğu, İslam medeniyetinin farklı zamanlarda ve bölgelerde dünya üzerinde etkili olduğuna dair ön bilgilerinin bulunduğu kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “İslam medeniyeti ve gönül coğrafyamız” ifadelerinin ne anlama geldiği sorularak beyin fırtınası tekniği uygulanır. Alınan cevaplara göre öğrencilerin hazır bulunuşlukları kontrol edilir."],"kopruKurma":["İslam medeniyetinin mimari, musiki, dil ve edebiyat alanlarına etkisi göz önünde bulundurularak ülkemizin gönül coğrafyamızda Türk İşbirliği ve Koordinasyon Ajansı Başkanlığı (TİKA), Yurtdışı Türkler ve Akraba Topluluklar Başkanlığı (YTB), Yunus Emre Enstitüsü (YEE), Türkiye Maarif Vakfı (TMV), Türkiye Diyanet Vakfı (TDV) gibi kurumlar aracılığı ile yaptığı çalışmalar arasında köprü kurulur."],"uygulamalar":[{"kod":"DKAB.11.3.1","metin":"Medeniyetin tanımı, gelişimi ve unsurları hakkında bilgi verilir. Kültür ve medeniyet arasındaki farka kısaca değinilir. Buradan hareketle öğrenciler, İslam medeniyetini oluşturan unsurları araştırır (E3.2). Soru-cevap tekniği bu süreçte kullanılabilir (E1.1). Medeniyetin maddi ve manevi unsurları açıklanır. Medeniyet ile medeniyetin unsurları arasındaki ilişkiyi belirler. Ölçme ve değerlendirme uygulamalarında açık uçlu ve kısa cevaplı sorular kullanılabilir."},{"kod":"DKAB.11.3.2","metin":"Mimari, musiki, dil ve edebiyat alanlarından hareketle İslam medeniyetinin sanat üzerindeki etkisi anlatılır. Görsel ve işitsel materyallerle öğrencilerin İslam medeniyetinin bu alanlara etkisini çözümlemesi sağlanır. Mimari, musiki, dil ve edebiyat alanlarından çeşitli örneklerle dinin medeniyet üzerindeki etkisine dair farkındalık oluşturulur (OB4, OB9). Öğrencilerin, toplumun millî ve manevi değerlerini koruyup yaşatmaya istekli olmaları amaçlanır (D16.2). Bu süreçte görsel yorumlama yöntemi kullanılabilir. İslam medeniyetinin gelişmesinde etkili olan merkezlere ve özelliklerine yer verilir (OB5). Hicaz Bölgesi, Kudüs ve çevresi, Şam ve Bağdat Bölgesi; İran, Horasan, Türkistan ve Maveraünnehir Bölgesi; Hint Alt Kıtası, Anadolu ve Balkanlar, Kuzey Afrika (Mısır ve Mağrip) ve Endülüs gibi İslam medeniyetinin tarihî süreçte hayat bulduğu ilim ve kültür havzaları ele alınır (OB1). Gönül coğrafyamız konusu ele alınırken Kıbrıs’ın İslam kültür ve medeniyet tarihindeki yerine ve önemine değinilir. Kuzey Kıbrıs Türk Cumhuriyeti’nin bu kültür ve medeniyeti yaşatmadaki önemine vurgu yapılır. İslam’ın yayıldığı coğrafyalardan hareketle öğrenciler, İslam medeniyetinin izlerini bölgelerine göre sınıflandırır. Bu süreçte görsel özetleyicilerden yararlanılabilir. Horasan, Anadolu ve Rumeli erenlerinden (Ahmet Yesevi, Hacı Bektaş Veli, Ahi Evran, Yunus Emre, Sarı Saltuk, Mevlâna Celaleddin Rumi, Hacı Bayram Veli) bahsedilir. Öğrencilere önemli bazı şahsiyetlerden bahsedilirken Ben Kimim? oyunu oynatılabilir (E2.5). Bu şahsiyetlerin İslam medeniyetinin Anadolu ve Balkanlara taşınmasındaki rolünü öğrenciler açıklar. Konu ile bağlamı bakımından Türk Dünyası ve Toplulukları Haftası ile ilgili bilgilendirme yapılabilir. Ölçme ve değerlendirme uygulamalarında öğrencilerden bilgi grafiği hazırlamaları istenebilir."},{"kod":"DKAB.11.3.3","metin":"İslam medeniyeti ve değerlerimize katkı sağlayan Türk İşbirliği ve Koordinasyon Ajansı Başkanlığı (TİKA), Yurtdışı Türkler ve Akraba Topluluklar Başkanlığı (YTB), Yunus Emre Enstitüsü (YEE), Türkiye Maarif Vakfı (TMV), Türkiye Diyanet Vakfı (TDV) gibi kurumların çalışmalarına değinilir. Bu kurumların yaptığı çalışmalarla ilgili örnekler sunularak (belgesel, video, fotoğraflar) öğrencilerin gözlem yapmasına imkân tanınır. Bu gözlemler neticesinde yapılan çalışmaların nitelikleri tespit edilir. Öğrenciler gönül coğrafyamızda yapılan çalışmaların birliğe, beraberliğe, yardımlaşma ve dayanışmaya olan katkısıyla ilgili çıkarım yapar. Öğrencilere vakıf kavramıyla ilgili neler bildikleri sorulur ve kavramla ilgili bilgi verilir. Bu süreçte düşün-eşleş-paylaş tekniği kullanılabilir (SDB2.1, SDB2.2). Öğrencilerin medeniyetimize katkı sağlayabilecek yeni önerilerde bulunmaları beyin fırtınası tekniği ile sağlanabilir (SDB2.1). Bu süreçte Vakıflar Haftası ile ilgili bilgilendirme yapılabilir. Ölçme ve değerlendirme uygulamalarında 3-2-1 kartı kullanılabilir."},{"kod":"DKAB.11.3.4","metin":"Rum suresinin 9. ayeti Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetin nüzul sebebine, ayette geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayette verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayette ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."}],"zenginlestirme":["İslam medeniyetinin geleceği için bir kurum tasarlamaları ve bu kurumun ne tür çalışmalar gerçekleştirmesi, hangi niteliklere sahip olması gerektiğini araştırmaları ve bu araştırma sonuçlarını raporlaştırmaları istenebilir."],"destekleme":["Öğrenciler farklı medeniyetler hakkında bilgiler içeren grafik düzenleyiciler ve şemalar kullanarak karşılaştırmalı analizler yapabilirler. Bu sürecin değerlendirilmesinde, öğrencilere kendilerini değerlendirebilmeleri için kontrol listeleri sunulabilir.","Öğrencilere İslam medeniyetinin etkilerini farklı bakış açılarından incelemek için basamaklandırılmış içerikler sunulurken bu içeriklerin sunumunda çeşitli multimedya araçlarından yararlanılabilir.","Ülkemizdeki çeşitli kurumların İslam medeniyetine katkıları hakkında genelleme yapabilmeleri için öğrencilere şemalar, kavram haritaları ve farklı veri sunum yöntemleri sağlanabilir."],"ogretmenYansitmalari":[]},
{"no":4,"ad":"İnançla İlgili Meseleler","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/152","odak":"alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":16,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.8. Sorgulama","KB3.3. Eleştirel Düşünme"],"egilimler":["E3.4. Gerçeği Arama","E3.8. Soru Sorma","E3.9. Şüphe Duyma","E3.10. Eleştirel Bakma"],"sdb":["SDB1.3. Kendine Uyarlama (Öz Yansıtma)","SDB2.1. İletişim","SDB2.3. Sosyal Farkındalık","SDB3.3. Sorumlu Karar Verme"],"degerler":["D16. Sorumluluk"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"Felsefe, Kelam","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.11.4.1","ad":"İnançla ilgili felsefi yaklaşımları sorgulayabilme","surec":["a) İnançla ilgili felsefi yaklaşımlar hakkında merak ettiklerini tanımlar.","b) İnançla ilgili felsefi yaklaşımlar hakkında soru sorar.","c) İnançla ilgili felsefi yaklaşımlar hakkında bilgi toplar.","ç) Topladığı bilgilerin doğruluğunu değerlendirir.","d) Toplanan bilgiler üzerinde çıkarım yapar."]},{"kod":"DKAB.11.4.2","ad":"Kötülük problemi hakkında eleştirel düşünebilme","surec":["a) Kötülük problemini sorgular.","b) Kötülük problemi ve tanrı inancıyla ilgili akıl yürütür.","c) Akıl yürütmeyle ulaştığı çıkarımları yansıtır."]},{"kod":"DKAB.11.4.3","ad":"Din istismarının ve yeni dinî hareketlerin ortaya çıkış sebeplerinisonuçlarını sorgulayabilme","surec":["a) Din istismarı ve yeni dinî hareketlerle ilgili merak ettiklerini tanımlar.","b) Din istismarı ve yeni dinî hareketlerle ilgili sorular sorar.","c) Din istismarı ve yeni dinî hareketlerle ilgili bilgi toplar.","ç) Toplanan bilgilerin doğruluğunu temel kaynakları dikkate alarak değerlendirir.","d) Toplanan bilgiler üzerinde çıkarım yapar."]},{"kod":"DKAB.11.4.4","ad":"Hadid suresi 1-5. ayetlerin mesajlarını özetleyebilme","surec":["a) Ayetlerde verilen mesajlarla ilgili çözümleme yapar.","b) Ayetlerde geçen konuları sınıflandırır.","c) Ayetlerde verilen mesajları açıklar."]}],"icerikCercevesi":["İnançla İlgili Felsefi Yaklaşımlar","Kötülük Problemi","Yeni Dinî Hareketler ve Din İstismarı","Kur’an’dan Mesajlar"],"anahtarKavramlar":["din istismarı","İslamofobi","iyilik","kötülük"],"olcmeDegerlendirme":["Öğrenme çıktıları; açık uçlu sorular, öğrenme günlükleri, dereceleme ölçeği, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir.","İnançla ilgili felsefi yaklaşımlarla ilgili araştırma yaparak bir deneme yazma, performans görevi olarak verilebilir. Bu performans görevi “dil ve anlatım kurallarına uyma, kaynaklardan yararlanabilme, araştırmayı derinleştirme, raporlaştırma ve sunma” gibi ölçütlere göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin İslam inanç esasları hakkında bilgi sahibi oldukları kabul edilmektedir."],"onDegerlendirme":["Öğrencilere teizm, ateizm ve deizm kavramları hakkında neler bildikleri sorulur. Verilen cevaplar çerçevesinde öğrencilerin hazır bulunuşluk seviyeleri kontrol edilir."],"kopruKurma":["Öğrencilerin felsefe dersinde öğrenmiş olduğu tanrının varlığına ilişkin görüşlerden hareketle teizm, deizm, ateizm, nihilizm, agnostisizm, materyalizm, pozitivizm, sekülarizm gibi inanç ve felsefi yaklaşımlar arasında köprü kurulur."],"uygulamalar":[{"kod":"DKAB.11.4.1","metin":"İnançla ilgili felsefi yaklaşımlar hakkında bilgi verilir. Öğrenciler konuyla ilgili merak ettiklerini ifade eder ve sorular sorar (E3.8). Beyin fırtınası tekniği bu süreçte kullanılabilir. Teizm, deizm, materyalizm, pozitivizm, sekülarizm, agnostisizm, ateizm, nihilizm ve transhümanizm yaklaşımları öğretmen rehberliğinde açıklanır (OB1). Yapılandırılmış bir metinden hareketle öğrencilerin konu hakkında bilgi toplamaları sağlanır. Öğrenciler topladıkları bilgileri öğretmen rehberliğinde değerlendirir. Öğrencilerin bu yaklaşımların ortaya koyduğu meseleleri İslam’ın temel kaynaklarından hareketle ve eleştirel bir bakış açısıyla değerlendirerek çıkarımda bulunmaları sağlanır (E3.10). Ayrıca bu felsefi yaklaşımlar İslam’ın ahiret inancı açısından da ele alınır. Ölçme ve değerlendirme uygulamalarında öğrencilerden konuyla ilgili özet bir metin yazmaları ve hazırladıkları metinleri arkadaşlarıyla paylaşmaları istenebilir (SDB2.1). Yazılan metinler dereceleme ölçeği ile değerlendirilebilir."},{"kod":"DKAB.11.4.2","metin":"Öğrencilere iyilik ve kötülük kavramlarıyla ilgili neler bildikleri sorulur. Kelam disiplinine göre iyilik ve kötülük kavramları açıklanır. Öğrencilerin, kötülük problemine dair merak ettiklerini sormaları sağlanır (E3.8). Bu süreçte soru kutusu tekniği kullanılabilir. Yapılandırılmış bir metinden hareketle öğrencilerin konu hakkında akıl yürütmeleri sağlanır. Örnek olay incelemesi tekniğinden faydalanılabilir. Kötülük problemiyle ilgili görüşlerde tanrı inancına dair öne sürülen iddialar öğretmen rehberliğinde ele alınır. Kötülüğün ortaya çıkmasında insan iradesine ve sorumluluğuna vurgu yapılarak öğrencilerin eleştirel düşünmeleri ve çıkarım yapmaları sağlanır (E3.4, E3.10). Buradan hareketle öğrenciler kötülük problemine dair çıkarım yapar. Öğrenciler çıkarımlarını görüş geliştirme tekniğiyle yansıtabilir (SDB1.3). Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."},{"kod":"DKAB.11.4.3","metin":"Öğrencilerin din istismarıyla ilgili bildikleri yoklanır ve din istismarı konu bağlamında açıklanır. Yeni dinî hareketler ve FETÖ, DAEŞ gibi din istismarında bulunan oluşumlarla ilgili öğrencilerin merak ettiklerini dile getirmeleri sağlanır. Bunların ortaya çıkma ve yaygınlaşma sebeplerine, ortak yönlerine, ülkemize olan olumsuz yansımalarına güncel örneklerle yer verilir. Konu ile ilgili yapılandırılmış bir metin üzerinden öğrenciler merak ettikleri sorulara dair bilgi toplar. Toplanan bilgilerin doğruluğu öğretmen rehberliğinde değerlendirilir. Bu süreçte balık kılçığı diyagramı kullanılabilir. Terörist, illegal, çıkarcı yapı ve gruplara değinilir. Batı’da ortaya çıkan “İslamofobi/İslam karşıtlığı” sebebiyle başta Müslümanlar olmak üzere dünya üzerinde yaşayan pek çok insana zarar veren söylem ve eylemlere dikkat çekilir. Bu hareketlerin bireysel, toplumsal, ekonomik ve siyasal etkenleri ile ilgili çıkarım yapmalarına imkân tanınır. Ülkemize verdiği zararların farkında olarak yeni dinî hareketlere ve din istismarına karşı mücadelede bireysel ve toplumsal sorumluluklar vurgulanır. Öğrencilerden bu ve benzeri toplumsal sorunların çözümü için öneriler sunmaları istenir (SDB3.3, SDB2.3, D16.2). Öğrencilerin dinî konularda alanında uzman olmayan kişilerin verdiği bilgilere şüpheyle yaklaşmaları ve doğru bilgiye ulaşmak için araştırma yapmaları sağlanır. (E3.9). Ölçme ve değerlendirme uygulamalarında öğrenme günlükleri kullanılabilir."},{"kod":"DKAB.11.4.4","metin":"Hadid suresi 1-5. ayetleri Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetlerin nüzul sebeplerine, ayetlerde geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayetlerde verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayetlerde ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."}],"zenginlestirme":["Öğrencilerden kötülük problemini İmam Matüridi’nin nasıl yorumlandığını araştırmaları istenebilir.","Öğrencilerden 15 Temmuz gazileriyle din istismarının bireye ve topluma verdiği zararlara dair röportaj yapmaları veya konuyla ilgili hazırlanmış röportajlardan faydalanarak bir metin hazırlamaları istenebilir."],"destekleme":["Öğrenmeyi desteklemek için dijital uygulamalardan, eşleştirme, soru cevap ve görsel yorumlama tekniklerinden kullanılabilir."],"ogretmenYansitmalari":[]},
{"no":5,"ad":"Yahudilik ve Hristiyanlık","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/153","odak":"dinlerin bazı mezheplerine yer verilir.","dersSaati":10,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme"],"egilimler":["E3.7. Sistematik Olma","E3.10. Eleştirel Bakma"],"sdb":["SDB2.3. Sosyal Farkındalık"],"degerler":["D5. Duyarlılık","D14. Saygı"],"okuryazarlik":["OB5. Kültür Okuryazarlığı"],"disiplinlerArasi":"Tarih, Coğrafya","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.11.5.1","ad":"Yahudilik ve Hristiyanlık dinlerinin tarihini ve temel özelliklerini özetleyebilme","surec":["a) Yahudilik ve Hristiyanlığın tarihi ve temel özellikleriyle ilgili çözümleme yapar.","b) Yahudilik ve Hristiyanlığın tarihi ve temel özellikleriyle ilgili sınıflandırma yapar.","c) Yahudilik ve Hristiyanlığın tarihini ve temel özelliklerini açıklar."]}],"icerikCercevesi":["Yahudilik","Hristiyanlık"],"anahtarKavramlar":["Ahd-i Atik","Ahd-i Cedit","Elohim","haç","havra","İncil","katedral","kilise","Kitab-ı Mukaddes","Musevi","ritüel","sakrament","sinagog","şapel","Tanah","teslis","Tevrat","vaftiz","Yahve"],"olcmeDegerlendirme":["Öğrenme çıktıları; çalışma yaprağı, öz değerlendirme formu ve dereceli puanlama anahtarı kullanılarak değerlendirilebilir.","Yahudilik ve Hristiyanlık ritüelleri, kutsal mekân ve sembolleriyle ilgili bir sunu hazırlama, performans görevi verilebilir. Bu performans görevi “kavram ve ritüelleri tespit etme, kutsal mekân ve sembollerle ilgili bilgi toplama, bilgileri sınıflandırma, ilgili bölümlere görsel ekleme, hazırlanan içeriği sunma ve zamanı verimli kullanma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin Yahudilik ve Hristiyanlık ile bu dinlerin kutsal kitapları ve bazı sembolleri hakkında bilgi sahibi oldukları kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Yahudilik ve Hristiyanlık hakkında neler biliyorsunuz?” sorusu sorularak öğrencilerin ön bilgileri kontrol edilir."],"kopruKurma":["Yahudilik ve Hristiyanlığın tarihsel gelişimi ve dağılımı ile ilgili bir harita gösterilerek öğrencilere bu dinlerin yaygın olarak yaşandığı yerler hakkında bilgilendirme yapılır. Böylelikle öğrencilerin tarih ve coğrafya dersinde öğrendikleriyle köprü kurması sağlanır."],"uygulamalar":[{"kod":"DKAB.11.5.1","metin":"Yahudiliğin tarihçesine; Elohim, Yahve, İbrani, İsrail, Yahudi ve Musevi kavramlarına değinilir. Öğrencilerin Yahudilik hakkında neler bildikleri beyin fırtınası tekniğiyle tespit edilebilir. Alınan cevaplardan hareketle öğretmen rehberliğinde inanç esasları, ritüelleri, sembolleri, kutsal mekânları, kitap ve peygamber anlayışlarına yer verilir (OB5, SDB2.3). Öğrenciler Yahudiliğin tarihine ve kavramlarına ilişkin çözümleme yapar. Yahudi mezheplerine yer verilir ve siyonizm konusuna değinilir (E3.10). Kitab-ı Mukaddes, Tanah, Tevrat, sinagog, havra kavramları çerçevesinde öğrencilerin Yahudilik tarihi ve kavramları arasında sınıflandırma yapması ve açıklaması sağlanır (E3.7). Bu süreçte zihin haritaları ve yapılandırılmış grid kullanılabilir. Öğrenci yaşadığı toplumda insanların farklı kültür ve inançlara sahip olabileceğini fark ederek çevresindekilere saygılı ve duyarlı olur (D5.3, D14.4). Bu değerlerin kazandırılmasında tartışma tekniğinden yararlanılabilir. Ölçme ve değerlendirme uygulamalarında eşleştirme, boşluk doldurma ve kısa cevaplı ve açık uçlu sorulardan oluşan çalışma yaprağı kullanılabilir. Hristiyanlığın tarihçesine; inanç esaslarına, ritüellerine, sembollerine ve kutsal mekânlarına değinilir. Öğrencilerin Hristiyanlık hakkında neler bildikleri beyin fırtınası tekniğiyle tespit edilebilir. Alınan cevaplardan hareketle öğretmen rehberliğinde Hristiyanlığın kurumsallaşmasında ve inanç esaslarının oluşmasında Pavlus’un rolüne, Hristiyanların vahiy ve peygamberlik anlayışına yer verilir (OB5, SDB2.3). Öğrenciler Hristiyanlığın tarihine ve kavramlarına (Kitab-ı Mukaddes, Ahd-i Atik, Ahd-i Cedit, İncil, teslis, haç, kilise, katedral, şapel, vaftiz, sakrament) ilişkin çözümleme yapar. Katoliklik, Ortodoksluk ve Protestanlık gibi Hristiyan mezheplerinden ve evanjelik akımlardan kısaca bahsedilir (E3.10). Bu çerçevede öğrencilerin Hristiyanlık tarihi ve kavramları arasında sınıflandırma yapması ve öğrendiklerini açıklaması sağlanır (E3.7). Bu süreçte zihin haritaları ve yapılandırılmış grid kullanılabilir. Öğrenci yaşadığı toplumda insanların farklı kültür ve inançlara sahip olabileceğini fark ederek çevresindekilere saygılı ve duyarlı olur (D5.3, D14.4). Bu değerlerin kazandırılmasında tartışma tekniğinden yararlanılabilir. Ölçme ve değerlendirme uygulamalarında eşleştirme, boşluk doldurma ve kısa cevaplı ve açık uçlu sorulardan oluşan çalışma yaprağı kullanılabilir."}],"zenginlestirme":["Öğrencilerin ilgi alanlarına göre farklı ürünler oluşturmalarına (afiş, duvar gazetesi, rapor, vb.) fırsat verilebilir.","Türkiye’de yer alan dinî gruplardan Musevi Hahambaşılığına ve Ermeni, Süryani, Ortodoks kiliselerine dair araştırma yapmaları istenebilir."],"destekleme":["Öğrencilerin öğrenme süreçlerine katılımlarını artırmak için gerekli araç gereçler hazırlanır ve ortam düzenlemesi yapılır. Öğrenciler dijital içerik (sesli metin, video vb.), soru cevap etkinlikleri ile desteklenebilir."],"ogretmenYansitmalari":[]}],"s12":[{"no":1,"ad":"Kur’an-ı Kerim","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/154","odak":"Bu ünitenin odak noktasını Kur’an-ı Kerim oluşturmaktadır. Öğrencilerin Kur’an-ı Kerim’in tarihi süreci hakkında bilgi toplayabilmesi, ana konularını ve temel özelliklerini sentezleyebilmesi, Kur’an’ın anlaşılmasında temel ilkeleri özetleyebilmesi ve kültürümüze etkisini yorumlayabilmesi amaçlanır. Kur’an’dan mesajlar bölümünde İsra suresinin 9. ayeti ele alınır. Öğrencilerin bu ayette verilen mesajları özetleyebilmesi beklenir.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.6. Bilgi Toplama","KB2.14. Yorumlama","KB2.20. Sentezleme"],"egilimler":["E1.1. Merak","E3.6. Analitik Düşünme"],"sdb":["SDB1.2. Kendini Düzenleme (Öz Düzenleme)","SDB2.1. İletişim","SDB2.3. Sosyal Farkındalık"],"degerler":["D3. Çalışkanlık","D5. Duyarlılık","D6. Dürüstlük","D7. Estetik"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık","OB5. Kültür Okuryazarlığı"],"disiplinlerArasi":"Tarih, Türk Dili ve Edebiyatı","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.12.1.1","ad":"Kur’an-ı Kerim’in tarihî süreci hakkında bilgi toplayabilme","surec":["a) Kur’an-ı Kerim’in tarihî süreciyle ilgili kaynakları araştırır.","b) Kaynakları kullanarak Kur’an-ı Kerim’in tarihî süreci hakkındaki bilgileri bulur.","c) Kur’an-ı Kerim’in tarihî süreci hakkında ulaştığı bilgileri temel kaynaklara dayanarak doğrular.","ç) Kur’an-ı Kerim’in tarihî süreci hakkında ulaştığı bilgileri kaydeder."]},{"kod":"DKAB.12.1.2","ad":"Kur’an-ı Kerim’in ana konularını ve temel özelliklerini sentezleyebilme","surec":["a) Kur’an-ı Kerim’in ana konularını ve temel özelliklerini inceler.","b) Kur’an-ı Kerim’in ana konuları ve temel özellikleri arasındaki ilişkiyi belirler.","c) Kur’an-ı Kerim’in ana konuları ve temel özellikleriyle özgün bir bütün oluşturduğunun farkına varır."]},{"kod":"DKAB.12.1.3","ad":"Kur’an-ı Kerim’in anlaşılmasında temel ilkeleri özetleyebilme","surec":["a) Kur’an-ı Kerim’in anlaşılmasındaki temel ilkeleri çözümler.","b) Kur’an-ı Kerim’in anlaşılmasındaki temel ilkeleri sınıflandırır.","c) Kur’an-ı Kerim’in anlaşılmasındaki temel ilkeleri açıklar."]},{"kod":"DKAB.12.1.4","ad":"Kur’an-ı Kerim’in kültürümüze etkisini yorumlayabilme","surec":["a) Kur’an-ı Kerim’in kültürümüz üzerindeki etkisini inceler.","b) Kur’an-ı Kerim’in kültürümüz üzerindeki etkisini bağlamından koparmadan hayatı için anlamlı hâle getirir.","c) Kur’an-ı Kerim’in kültürümüz üzerindeki etkisini ifade eder."]},{"kod":"DKAB.12.1.5","ad":"İsra suresi 9. ayetin mesajlarını özetleyebilme","surec":["a) Ayette verilen mesajlarla ilgili çözümleme yapar.","b) Ayetin mealinde geçen konuları sınıflandırır.","c) Ayette verilen mesajları açıklar."]}],"icerikCercevesi":["Kur’an-ı Kerim’in Tarihi","Kur’an-ı Kerim’in Ana Konuları ve Temel Özellikleri","Kur’an-ı Kerim’in Anlaşılmasında Temel İlkeler","Kur’an-ı Kerim ve Kültürümüz","Kur’an’dan Mesajlar"],"anahtarKavramlar":["Mushaf","nüzul","vahiy"],"olcmeDegerlendirme":["Öğrenme çıktıları; 3-2-1 kartı, yapılandırılmış grid, bilgi kartları, blog yazısı, boşluk doldurma, doğru-yanlış, kısa cevaplı ve açık uçlu soru türleri, çalışma yaprağı, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir.","Kur’an-ı Kerim’in ana konuları ile ilgili bilgi grafiği hazırlama, performans görevi olarak verilebilir. Bu performans görevi “dil ve anlatım kurallarına uyma, konu hakkında yeterli bilgi toplama, konuya uygun görseller kullanma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencinin peygamber, ilahi kitap ve vahiy kavramları ile ilgili temel bilgilere sahip olduğu kabul edilmektedir."],"onDegerlendirme":["Allah’ın (cc) vahiy göndermesinin nedenleri ile ilgili beyin fırtınası yaptırılır. Etkinlik sırasında peygamberler ve ilahi kitaplarla ilgili sorular sorulur. Öğrencilerin görüşleri not edilerek ön bilgileri kontrol edilir."],"kopruKurma":["Kur’an ayetlerinin sanat, edebiyat, mimari, musiki gibi alanlardaki yansımaları üzerinden köprü kurulur."],"uygulamalar":[{"kod":"DKAB.12.1.1","metin":"Kur’an-ı Kerim’in tanımına yer verilerek Hz. Peygamber döneminde Kur’an’ın hangi materyallere yazıldığına değinilir. Öğrenciler konuyla ilgili merak ettiklerini sorar (E1.1). Bu süreçte soru kutusu tekniği kullanılabilir. Öğrenciler öğretmen rehberliğinde Kur’an-ı Kerim’in tarihî süreci hakkında bilgi toplayabilmeleri için ilgili kaynakları belirler (OB1). Öğrencilerin temel kaynaklardan Kur’an-ı Kerim’in indirilişi, Mushaf hâline getirilişi, çoğaltılması, harekelenmesi ve noktalanması hakkında bilgi toplaması sağlanır (OB1, SDB1.2). Toplanan bilgilerden hareketle öğrenciler öğretmen rehberliğinde Kur’an-ı Kerim’in tahriften korunmuş olması ve son ilahi kitap oluşu ile ilgili bilgileri temel kaynaklara dayanarak doğrular ve kaydeder. Öğrenciler, öğrendiklerini düşün-eşleş-paylaş tekniğiyle arkadaşlarıyla paylaşabilir (SDB2.1). Öğrencilere sahabenin, Kur’an-ı Kerim’in Mushaf hâline getirilmesinde gösterdikleri özverili, azimli ve planlı çalışmalardan bahsedilir. Bu örnekten yola çıkarak disiplinli ve istikrarlı çalışma alışkanlıkları geliştirmeleri, doğru ve güvenilir bilgiyi ayırt edebilmeleri ve çalışmalarını planlayarak ertelemeden yürütmeye gayret etmeleri gerektiği vurgusu yapılır (D3.2). Ölçme ve değerlendirme uygulamalarında öğrencilerden bilgi kartları hazırlamaları istenebilir."},{"kod":"DKAB.12.1.2","metin":"Kur’an-ı Kerim’in ana konuları olan tevhit, nübüvvet, ahiret, ibadetler, ahlaki ilkeler, sosyal hayat ve kıssalar ayetler çerçevesinde aktarılır. Bu süreçte kum saati tekniği kullanılabilir. Ayrıca ahiret konusu aşamalarıyla birlikte ayetler ışığında ele alınır. Öğrenciler, ayetlerden hareketle Kur’an-ı Kerim’in mucize oluşunu, ana konularını ve temel özelliklerini inceler. Kur’an’ın iyiye, doğruya ve güzele yönlendirmesi, kötülüklerden sakındırması, yol göstermesi, açıklayıcı olması, insanları düşünmeye ve aklını kullanmaya yöneltmesi gibi temel özellikleriyle Kur’an-ı Kerim’in ana konuları arasındaki ilişkiyi öğrenciler tespit eder. Öğrencilere ahlaki ilkelerin yer aldığı ayet ve hadislerden örnekler verilerek sosyal ilişkilerinde duyarlı ve dürüst olmaya gayret etmeleri telkin edilir (D5.2, D6.1). Bu bağlamda Hz. Yusuf kıssasına değinilir. Öğrenciler, Kur’an-ı Kerim’in ana konuları ve temel özellikleriyle özgün bir bütün oluşturduğunun farkına varır. Ölçme ve değerlendirme uygulamalarında yapılandırılmış grid kullanılabilir."},{"kod":"DKAB.12.1.3","metin":"Öğrenciler, Kur’an-ı Kerim’in anlaşılmasındaki temel ilkeleri tespit ederek bunlar arasındaki ilişkiyi çözümler. Öğrencilerin, Kur’an-ı Kerim’in anlaşılmasındaki temel ilkeleri, Hz. Peygamber’in açıklamaları, ayetlere bütüncül bakma, ayetleri bağlamlarıyla değerlendirme ve ayetlerin nüzul sebepleri şeklinde sınıflandırabilmelerine imkân tanınır (E3.6). Anlam çözümleme tablosu bu süreçte kullanılabilir. Öğrenciler, meal ve tefsir kullanarak Kur’an-ı Kerim’in anlaşılmasındaki temel ilkeleri açıklar. Ölçme ve değerlendirme uygulamalarında 3-2-1 kartı kullanılabilir."},{"kod":"DKAB.12.1.4","metin":"Öğrenciler, Kur’an-ı Kerim’in dil, edebiyat, mimari, sanat ve musiki gibi alanlar üzerindeki etkisini görsel ve işitsel materyaller üzerinden inceler (OB5, E1.1). Öğrencilerin Kur’an-ı Kerim’in kültürümüz üzerindeki etkisini kendi hayatları için anlamlı hâle getirmelerine imkân sağlanır (SDB2.3). Öğrenciler Kur’an-ı Kerim’in kültürümüz üzerindeki etkisini hüsnühat, tezhip gibi sanatlar bağlamında ifade eder. Öğrencilerin gezi gözlem yoluyla geleneksel sanatlara ait etkinliklere katılmaları, sanat eseri oluşturmanın emek, zaman ve maliyet gerektirdiğini fark etmeleri (D7.2), yaşamını estetik unsurlarla zenginleştirmeleri beklenir (D7.4). Ölçme ve değerlendirme uygulamalarında öğrencilerden bir sanat eserini inceleyerek blog yazısı oluşturmaları istenebilir."},{"kod":"DKAB.12.1.5","metin":"İsra suresi 9. ayet, Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetin nüzul sebebine, ayette geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayette verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayette ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında boşluk doldurma, doğru-yanlış, kısa cevaplı ve açık uçlu soru türlerinden oluşan çalışma yaprağı kullanılabilir."}],"zenginlestirme":["Kur’an-ı Kerim’in sanata, dil ve edebiyata yansımalarını inceleyebilmek için Kültür ve Turizm Bakanlığına ait sanal müzeleri öğrencilerin ziyaret etmeleri teşvik edilebilir.","Kur’an-ı Kerim’in musikiye etkisine dair sanat eserleri dinletilebilir.","Kur’an-ı Kerim’in anlaşılmasına katkı sağlayabilecek özgün önerilerin sunulması ve bu önerilerin sınıf veya okul panosunda sergilenmesi istenebilir."],"destekleme":["Öğrenciler dijital içerik (sesli metin, video vb.), soru cevap etkinlikleri ile desteklenebilir."],"ogretmenYansitmalari":[]},
{"no":2,"ad":"Din ve Aile","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/155","odak":"Bu ünitenin odak noktasını dinin aile kurumuna verdiği değer oluşturmaktadır. Öğrencilerin İslam’ın aile kurumuna verdiği önemi yorumlayabilmesi, aile içi iletişim ve etkileşim sürecini çözümleyebilmesi, aile hayatında dikkat edilmesi gereken ahlaki değerleri özetleyebilmesi amaçlanır. Kur’an’dan mesajlar bölümünde Ahkaf suresinin 15. ayeti ele alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":12,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.4. Çözümleme","KB2.14. Yorumlama"],"egilimler":["E2.1. Empati","E2.2. Sorumluluk","E3.5. Açık fikirlilik"],"sdb":["SDB1.1. Kendini Tanıma (Öz Farkındalık)","SDB1.2. Kendini Düzenleme (Öz Düzenleme)","SDB2.1. İletişim","SDB2.3. Sosyal Farkındalık"],"degerler":["D2. Aile bütünlüğü","D6. Dürüstlük","D8. Mahremiyet","D9. Merhamet","D14. Saygı","D15. Sevgi"],"okuryazarlik":["OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.12.2.1","ad":"İslam’ın aile kurumuna verdiği önemi yorumlayabilme","surec":["a) İslam’ın aile kurumuna verdiği önemi inceler.","b) İslam’ın aile kurumuna ve akrabalık ilişkilerine verdiği önemi kendi hayatı için anlamlı hâle getirir.","c) Neslin devamı ve korunmasında İslam’ın aile kurumuna verdiği önemi doğru bir şekilde ifade eder."]},{"kod":"DKAB.12.2.2","ad":"Aile içi iletişim ve etkileşim sürecini çözümleyebilme","surec":["a) Aile içi iletişim ve etkileşim sürecine dâhil olan unsurları açıklar.","b) Aile içi iletişim ve etkileşim sürecine dâhil olan unsurlar arasındaki ilişkileri belirler."]},{"kod":"DKAB.12.2.3","ad":"Aile hayatında dikkat edilmesi gereken ahlaki değerleri özetleyebilme","surec":["a) Aile hayatının üzerine inşa edildiği ahlaki değerlele ilgili çözümleme yapar.","b) Aile hayatında önemli olan ahlaki değerleri sınıflandırır.","c) Aile hayatında önemli olan ahlaki değerleri açıklar."]},{"kod":"DKAB.12.2.4","ad":"Ahkaf suresi 15. ayetin mesajlarını özetleyebilme","surec":["a) Ayette verilen mesajlarla ilgili çözümleme yapar.","b) Ayetin mealinde geçen konuları sınıflandırır.","c) Ayette verilen mesajları açıklar."]}],"icerikCercevesi":["İslam’da Aile","Aile İçi İletişim","Aile ve Ahlaki Değerler","Kur’an’dan Mesajlar"],"anahtarKavramlar":["aile","Ehlibeyt","fedakârlık","mahremiyet","merhamet","nesil","sadakat","vefa"],"olcmeDegerlendirme":["Öğrenme çıktıları; açık uçlu ve kısa cevaplı sorular, kavram haritası, çalışma yaprağı, dereceli puanlama anahtarı, dereceleme ölçeği ve öz değerlendirme formu kullanılarak değerlendirilebilir.","Aile temalı kısa bir film hazırlama, performans görevi olarak verilebilir. Bu performans görevi “değerlere yer verme, bilgi toplama, senaryo yazma, görüntü ve ses tekniklerine uygun çekim yapma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin aile kavramının tanımını bildikleri ve aile içi sorumlulukların farkında oldukları kabul edilmektedir."],"onDegerlendirme":["Aile kurumunun bireysel ve toplumsal önemi hakkında sorular sorularak öğrencilerin ön bilgileri değerlendirilir."],"kopruKurma":["Ailenin değer ve kültür aktarımındaki rolü ile gerçek yaşam arasında köprü kurması sağlanır."],"uygulamalar":[{"kod":"DKAB.12.2.1","metin":"Aile kurumunun toplumun temeli olduğu vurgulanır. Dinlerin aile kurumuna bakış açısına kısaca yer verilir. Öğrenciler temel kaynaklardan İslam’da ailenin yeri ve önemini inceler. İslam’ın aile kurumuna verdiği değer ayet ve hadisler ışığında açıklanır. Allah’ın (cc) aile üyeleri arasında sevgi ve merhamet bağı yarattığı, Hz. Muhammed’in (sav) evliliği teşvik ettiği, eşlerin birbirlerine olan sorumluluğu gibi hususlara değinilir. Hz. Peygamber’in örnekliğinden hareketle aile fertlerinin sevgilerini samimi ve istekli bir şekilde göstermeleri, sevdikleri için fedakârlık yapmaları, birbirlerinin sevincine ve üzüntüsüne ortak olmaları gerektiği yönünde açıklamalarda bulunulur (D15.1, E2.2). Aile bağlarının boşanma ile sona ermesi durumunda tarafların hakları olduğundan, boşanmanın birey ve toplum üzerindeki etkilerinden bahsedilir (SDB2.3). Öğrencilerin ülkemizin geleceği için neslin korunması ve aile bütünlüğünün önemini grup çalışması etkinliğiyle fark etmeleri sağlanır (D2.1, E3.5). Akrabalar arası ilişkilerin birey ve toplum hayatı için önemine vurgu yapılır. Bu bağlamda sılayırahim kavramına dikkat çekilir. Öğrencilerin İslam’ın aile kurumuna ve akrabalık ilişkilerine verdiği önemi kendisi için anlamlı hâle getirmesi amaçlanır. Öğrencilerin neslin devamı ve korunmasında İslam’ın aile kurumuna verdiği önemi doğru bir şekilde ifade etmelerine imkân verilir. Bu süreçte RAFT tekniği kullanılarak öğrencilerden bir metin oluşturmaları istenebilir. Yazılan metinler öz değerlendirme formu ile değerlendirilebilir. ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."},{"kod":"DKAB.12.2.2","metin":"Aile içi iletişim süreçleri, iletişim kanalları, aile ortamı ve aile değerleri hakkında sınıfta tartışma ortamı oluşturulur. Öğrenciler aile içi iletişim ve etkileşim sürecine dâhil olan unsurları belirler. Bu süreçte konuşma halkası tekniği kullanılabilir. Öğrenciler aile bireylerinin birbirlerine karşı sorumluluklarına ilişkin unsurları açıklar (SDB1.2). Aile üyelerinin birbirleri ile iletişimlerinde dürüst olmalarının ve birbirlerini saygıyla dinlemesinin kişiye ve topluma olumlu katkılar sağlayacağı vurgulanır (E2.1, D14.2). Hz. Peygamber’in aile fertlerine olan sevgi ve merhametini anlatan rivayetlere yer verilir. Ehlibeyt sevgisi ile ilgili öğrencilerin öz farkındalık kazanması hedeflenir (SDB1.1). Konu kapsamında Yaşlılar Haftası etkinlikleri hakında bilgi verilebilir. Ölçme ve değerlendirme uygulamalarında kavram haritası kullanılabilir."},{"kod":"DKAB.12.2.3","metin":"Öğrencilere aile kurumunun güçlü ve sağlam olmasında hangi değerlerin ön plana çıktığı sorulur. Bu süreçte beyin fırtınası tekniği kullanılabilir. Öğrencilerin ayet ve hadislerden hareketle aile hayatının üzerine inşa edildiği ahlaki değerlerin neler olduğu üzerine çözümleme yapmaları sağlanır. Bu bağlamda mahremiyet, sadakat, iffet, vefa, fedakârlık, merhamet, adalet ve eşitlik kavramlarına değinilir (D6.2, D8.3, D9.2, D15.2, 3). Örnek olay incelemesi tekniği bu süreçte uygulanabilir (SDB1.1). Öğrenciler aile bireylerinin hak ve sorumlulukları doğrultusunda ahlaki değerleri sınıflandırır ve açıklar. Bu bağlamda Hz. Lokman’ın oğluna verdiği öğütlere vurgu yapılır. Ölçme ve değerlendirme uygulamalarında öğrencilerden küçürek hikâye yazmaları istenebilir. Bu hikâye dereceleme ölçeği ile değerlendirilebilir."},{"kod":"DKAB.12.2.4","metin":"Ahkaf suresi 15. ayet, Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetin nüzul sebebine, ayette geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayette verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayette ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında boşluk doldurma, doğru-yanlış, kısa cevaplı ve açık uçlu soru türlerinden oluşan çalışma yaprağı kullanılabilir."}],"zenginlestirme":["Peygamberlerin aile kavramına vurgu yapan kıssalarının derlenmesi istenebilir.","Öğrencilerden TÜİK’in aile kurumunu çeşitli yönleri ile ele alan istatistiklerinin analizi istenebilir."],"destekleme":["Çoklu görsel ve işitsel materyaller (çizimler, grafikler, ses kayıtları vb.) kullanarak aile ve toplumsal değerlerle ilgili konuları her öğrencinin erişebileceği şekilde sunulabilir.","Aile içi iletişim ve ahlaki değerler hakkında interaktif oyunlar ve uygulamalar kullanılarak öğrencilerin aktif katılımı teşvik edilebilir.","Dinî metinlerin anlaşılmasını sağlamak için görsel destekli anlatımlar yapılabilir."],"ogretmenYansitmalari":[]},
{"no":3,"ad":"Güncel Dinî Meseleler","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/156","odak":"Bu ünitenin odak noktasını güncel dinî meseleler oluşturmaktadır. Öğrencilerin dinî meselelerin çözümünde temel ilke ve yöntemleri özetleyebilmesi, gıda maddeleriyle ilgili meseleleri yorumlayabilmesi, bağımlılık ve günlük hayatla ilgili meseleleri ayet ve hadislerden hareketle sorgulayabilmesi amaçlanır. Kur’an’dan mesajlar bölümünde En'am suresinin 151-152. ayetleri ele alınır. Öğrencilerin bu ayetlerde verilen mesajları özetleyebilmesi beklenir.","dersSaati":14,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.8. Sorgulama","KB2.14. Yorumlama"],"egilimler":["E1.3. Azim ve Kararlılık","E3.4. Gerçeği Arama","E3.5. Açık Fikirlilik","E3.8. Soru Sorma","E3.11. Özgün Düşünme"],"sdb":["SDB2.1. İletişim","SDB2.2. İş Birliği","SDB2.3. Sosyal Farkındalık"],"degerler":["D11. Özgürlük","D13. Sağlıklı Yaşam"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB2. Dijital Okuryazarlık"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.12.3.1","ad":"Güncel dinî meselelerin çözümünde temel ilke ve yöntemleri özetleyebilme","surec":["a) Güncel dinî meselelerin çözümünde kullanılan temel ilke ve yöntemlerle ilgili çözümleme yapar.","b) Güncel dinî meselelerin çözümünde kullanılan temel ilke ve yöntemlerle ilgili sınıflandırma yapar.","c) Güncel dinî meselelerin çözümünde kullanılan ilke ve yöntemleri açıklar."]},{"kod":"DKAB.12.3.2","ad":"Gıda maddeleriyle ilgili meseleleri yorumlayabilme","surec":["a) Gıda maddeleriyle ilgili meseleleri inceler.","b) Gıda maddeleriyle ilgili meselelerin hükümlerini kendisi için anlamlı hâle getirir.","c) Gıda maddeleriyle ilgili meseleleri doğru bir şekilde ifade eder."]},{"kod":"DKAB.12.3.3","ad":"Bağımlılıkla ilgili meseleleri sorgulayabilme","surec":["a) Bağımlılıkla ilgili meseleleri tanımlar.","b) Bağımlılıkla ilgili meseleler hakkında sorular sorar.","c) Bağımlılıkla ilgili meseleler hakkında bilgi toplar.","ç) Bağımlılıkla ilgili meseleler hakkında toplanan bilgilerin doğruluğunu değerlendirir.","d) Bağımlılıkla ilgili meseleler hakkında toplanan bilgiler üzerinde çıkarım yapar."]},{"kod":"DKAB.12.3.4","ad":"Günlük hayatla ilgili meseleleri sorgulayabilme","surec":["a) Günlük hayatla ilgili meselelerden merak ettiklerini tanımlar.","b) Günlük hayatla ilgili meseleler hakkında sorular sorar.","c) Günlük hayatla ilgili meseleler hakkında bilgi toplar.","ç) Günlük hayatla ilgili meseleler hakkında topladığı bilgilerin doğruluğunu değerlendirir.","d) Günlük hayatla ilgili meseleler hakkında topladığı bilgilerden çıkarımlar yapar."]},{"kod":"DKAB.12.3.5","ad":"Enam suresi 151-152. ayetlerinin mesajlarını özetleyebilme","surec":["a) Ayetlerde verilen mesajlarla ilgili çözümleme yapar.","b) Ayetlerin mealinde geçen konuları sınıflandırır.","c) Ayetlerde verilen mesajları açıklar."]}],"icerikCercevesi":["Dinî Meselelerin Çözümünde Temel İlke ve Yöntemler","Gıda Maddeleriyle İlgili Meseleler","Bağımlılıkla İlgili Meseleler","Günlük Hayatla İlgili Meseleler","Kur’an’dan Mesajlar"],"anahtarKavramlar":["bidat","haram","helal","hurafe","icma","içtihat","kul hakkı","mekruh","zaruratıdiniye","zaruratıhamse"],"olcmeDegerlendirme":["Öğrenme çıktıları; 3-2-1 kartı, açık uçlu sorular, öğrenme günlüğü, tekzip metni / gazete","yazısı, çalışma yaprağı, dereceli puanlama anahtarı ve öz değerlendirme formu kullanılarak değerlendirilebilir.","Dinî meselelerin çözümünde belirlenen temel ilke ve yöntemlerle ilgili deneme yazısı oluşturma, performans görevi olarak verilebilir. Bu performans görevi “konuyla ilgili bilgi toplama, bilgileri sınıflandırma, dil ve anlatım kurallarına uyma, kaynak kullanma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da","kullanılabilir."],"temelKabuller":["Öğrencilerin helal, haram, caiz gibi dinî hükümler ve kavramları bildikleri kabul edilmektedir."],"onDegerlendirme":["Öğrencilerden helal ve haram diye nitelendirilen davranışlara örnek vermeleri istenir. Bu","davranışların helal ve haram olarak nitelendirilmelerinin sebepleri sorularak ön bilgileri","kontrol edilmiş olur."],"kopruKurma":["Güncel meselelerin bireyin hayatına yansımalarından hareketle dinin bu meselelerin çözümündeki yaklaşımını göz önünde bulundurarak değişim ve süreklilik bağlamında hayatla köprü kurulur."],"uygulamalar":[{"kod":"DKAB.12.3.1","metin":"Güncel dinî meselelerin çözümünde kullanılan ilke ve yöntemlerin, İslam âlimlerinin üzerinde icma ettiği temel esas ve hükümlere ters düşmemesi, bu önerilerin “zaruratıdiniye” adı verilen ilkelere aykırı olmaması gerektiğine vurgu yapılır. İslam’ın ortaya koyduğu çözümlerin temel amacının, insanların can, nesil, akıl, mal ve din emniyetini (zaruratıhamse) güvence altına almak olduğuna dikkat çekilir. Ayrıca dinî mesellerin çözümünde “Defi mefasit celbi menafiden evladır.” ve “seddizerai” ilkelerinin önemine değinilir. Bu ilkelerden hareketle öğrenciler dinî meselelerin çözümünde kullanacağı temel ilke ve yöntemleri içtihat kavramı çerçevesinde inceler (E3.4). Öğrenciler ilke ve yöntemleri sınıflandırır ve açıklar. Bu süreçte anlam çözümleme tablosu ve düşün-eşleş-paylaş tekniği kullanılabilir (E3.5). Bu teknikle öğrenciler arasındaki iletişim geliştirilir (SDB2.1). Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."},{"kod":"DKAB.12.3.2","metin":"Öğrencilere yiyecek ve içecekler konusunda “Eşyada asıl olan ibahadır.” ilkesi kapsamında “yasakların sınırlı, helaller alanının ise geniş olduğu” vurgulanır. Bu süreçte mekruh kavramına da yer verilir. İslam’a göre yenilmesi ve içilmesi yasaklanmış gıdalar, beyin fırtınası tekniğiyle örneklendirilir. Yiyecek ve içeceklerle ilgili yasakların delillerine ve hikmetlerine yer verilir. Genetiği ve öz niteliği değiştirilmiş yiyecek ve içeceklerin insan sağlığı üzerindeki etkilerine değinilir. Öğrenciler verilen bu bilgiler doğrultusunda gıda maddeleri ilgili meseleleri bireysel olarak inceler. Öğrencilerin gıda maddeleri ile ilgili meseleleri anlamlı hâle getirmelerine rehberlik edilir ve doğru bir şekilde ifade etmeleri sağlanır. Bu süreçte örnek olay incelemesi yöntemi uygulanarak sağlıklı ve sağlıksız besinleri ayırt etmeleri ve dengeli beslenmenin önemini fark etmeleri sağlanır (E3.11, D13.1). Ölçme ve değerlendirme uygulamalarında 3-2-1 kartı kullanılabilir."},{"kod":"DKAB.12.3.3","metin":"“Bağımlılık konusunda merak ettikleriniz nelerdir?” sorusundan hareketle öğrenciler merak ettikleri konuları tanımlar ve sorular sorarlar (E3.8). Bu aşamada soru kutusu tekniği kullanılabilir. Uyuşturucu madde, alkol ve sigara kullanımı ile kumar oynamak gibi bağımlılığa neden olan zararlı alışkanlıklar ve teknoloji bağımlılığı hakkında bilgi verilir (SDB2.3). Öğrencilere uyuşturucu madde, alkol ve sigara kullanımı ile kumar oynamak gibi bağımlılığa neden olan zararlı alışkanlıkların İslam’da yasaklandığı vurgulanır. Konuyla ilgili ayet ve hadisler üzerinde durulur. Örnek olay yöntemiyle öğrencilerin uyuşturucu madde, alkol ve sigara kullanımı ile kumar oynamak gibi bağımlılığa neden olan zararlı alışkanlıkların olumsuz etkilerini fark etmeleri ve bu zararlı alışkanlıklarla azim ve kararlılıkla mücadele etme bilinci kazanmaları sağlanır (D13.3, E1.3). Bu meselelerle ilgili yapılandırılmış bir metin öğrencilerle paylaşılarak konu hakkında bilgi toplamaları sağlanır (OB1, SDB2.3). Öğrenciler topladıkları bilgilerin doğruluğunu öğretmen rehberliğinde değerlendirir ve elde ettiği bilgilerden çıkarım yapar. Bu süreçte zihin haritası tekniği kullanılabilir. Ölçme ve değerlendirme uygulamalarında tekzip metni / gazete yazısı yazma teknikleri kullanılabilir."},{"kod":"DKAB.12.3.4","metin":"“Günlük hayatta dinî hükmünü merak ettiğiniz konular nelerdir?” sorusundan hareketle öğrenciler merak ettikleri konuları tanımlar ve sorular sorar (E3.8). Bu aşamada soru kutusu tekniği kullanılabilir. Sağlık ve tıpla ilgili meseleler (otopsi, ötenazi, organ nakli, kan bağışı, haram maddelerle tedavi, dövme, estetik ameliyat ve intihar) ; toplumsal hayatla ilgili meseleler (akran zorbalığı, mobbing, telif hakkı ihlali ve kul hakkı kapsamındaki diğer konular), çalışma hayatıyla ilgili meseleler (işçi ve işveren hakları, iş sağlığı ve güvenliği, iş ve meslek ahlakı), yanlış inanışlar (ruh çağırmak, falcılık ve büyücülük gibi bidat ve hurafeler) hakkında bilgi verilir (SDB2.3). Bu meselelerle ilgili yapılandırılmış bir metin öğrencilerle paylaşılarak bilgi toplamaları sağlanır (OB1, SDB2.3). Öğrenciler, topladıkları bilgilerin doğruluğunu öğretmen rehberliğinde değerlendirir ve elde ettiği bilgilerden çıkarım yapar. Bu süreçte Philips 66 tekniği kullanılabilir (SDB2.2). Ahlaki muhakeme yaklaşımıyla öğrencilerin kişisel haklara ve fikri mülkiyet haklarına saygı göstermeleri sağlanır (D11.3, OB2). Ölçme ve değerlendirme uygulamalarında öğrenme günlüğü kullanılabilir."},{"kod":"DKAB.12.3.5","metin":"Enam suresi 151-152. ayetleri, Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetlerin nüzul sebeplerine, ayetlerde geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayetlerde verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayetlerde ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında boşluk doldurma, doğru-yanlış, kısa cevaplı ve açık uçlu soru türlerinden oluşan çalışma yaprağı kullanılabilir."}],"zenginlestirme":["Öğrencilerin güncel dinî meselelerle ilgili İslam Araştırmaları Merkezinde yayınlanan bir","makaleyi okuyarak sunum yapmaları istenebilir."],"destekleme":["Öğrencilere dinî meselelerin çözümünde temel ilke ve yöntemlerini anlatmak için görsel","ve işitsel materyallerle desteklenmiş dersler yapılabilir.","İslam’ın yiyecek ve içeceklerle ilgili hükümleri konusunda, görsel materyaller ve interaktif tartışmalar kullanılarak öğrencilerin konuyu derinlemesine anlamaları sağlanabilir.","Sağlık ve tıpla ilgili konuları araştırırken, öğrencilere çeşitli kaynaklar ve araştırma yöntemleri sunulur. Günlük hayatla ilgili meselelerin tartışılmasında öğrencilerin kendi deneyimlerini paylaşmaları teşvik edilebilir."],"ogretmenYansitmalari":[]},
{"no":4,"ad":"İslam Düşüncesinde Tasavvufi Yorumlar","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/157","odak":"Bu ünitenin odak noktasını İslam düşüncesinde tasavvufi yorumlar oluşturmaktadır. Öğrencilerin tasavvufi düşüncenin oluşum sürecini çözümleyebilmesi ve tasavvufi düşüncenin ahlaki boyutunu özetleyebilmesi, kültürümüzde etkin olan tasavvufi yorumlar hakkında ilgi toplayabilmesi amaçlanır. Ayrıca Alevilik Bektaşilikte erkân ve temel kavramları öğrenmeleri hedeflenir. Kur’an’dan mesajlar bölümünde Hucurat suresinin 10. ayeti ele alınır. Öğrencilerin bu ayette verilen mesajları özetleyebilmesi beklenir.","dersSaati":16,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme","KB2.4. Çözümleme","KB2.6. Bilgi Toplama","KB2.20. Sentezleme"],"egilimler":["E3.2. Odaklanma","E3.6. Analitik Düşünme"],"sdb":["SDB2.1. İletişim","SDB2.3. Sosyal Farkındalık"],"degerler":["D5. Duyarlılık","D14. Saygı"],"okuryazarlik":["OB2. Dijital Okuryazarlık","OB5. Kültür Okuryazarlığı"],"disiplinlerArasi":"","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.12.4.1","ad":"Tasavvufi düşüncenin oluşum sürecini çözümleyebilme","surec":["a) Tasavvufi düşüncenin oluşum sürecindeki unsurları inceler.","b) Tasavvufi düşüncenin oluşum sürecindeki unsurlar arasındaki ilişkileri belirler."]},{"kod":"DKAB.12.4.2","ad":"Tasavvufi düşüncenin ahlaki boyutunu özetleyebilme","surec":["a) Tasavvufi düşüncenin ahlaki boyutuyla ilgili çözümleme yapar.","b) Tasavvufi düşüncenin ahlaki boyutuyla ilgili sınıflandırma yapar.","c) Tasavvufi düşüncenin ahlaki boyutunu açıklar."]},{"kod":"DKAB.12.4.3","ad":"Kültürümüzde etkin olan tasavvufi yorumlar hakkında bilgi toplayabilme","surec":["a) Tasavvufi yorumlar hakkında bilgiye ulaşmak için kullanacağı kaynakları araştırır.","b) Tasavvufi yorumlar hakkında bilgileri bulur.","c) Tasavvufi yorumlar hakkında ulaştığı bilgileri doğrular.","ç) Tasavvufi yorumlar hakkında ulaştığı bilgileri kaydeder."]},{"kod":"DKAB.12.4.4","ad":"Alevilik Bektaşilikte temel kavramlar ve cem erkânını sentezleyebilme","surec":["a) Alevilik Bektaşilikte temel kavramlar ve cem erkânını açıklar.","b) Alevilik Bektaşilikte temel kavramlar ve cem erkânı arasında ilişki kurar.","c) Alevilik Bektaşilikte temel kavramlar ve cem erkânıyla ilgili bütüncül bir bakış açısı oluşturur."]},{"kod":"DKAB.12.4.5","ad":"Hucurat suresi 10. ayetin mesajlarını özetleyebilme","surec":["a) Ayette verilen mesajlarla ilgili çözümleme yapar.","b) Ayetin mealinde geçen konuları sınıflandırır.","c) Ayette verilen mesajları açıklar."]}],"icerikCercevesi":["Tasavvufi Düşüncenin Oluşumu","Tasavvufi Düşüncenin Ahlaki Boyutu","Kültürümüzde Etkin Olan Tasavvufi Yorumlar","Alevilik Bektaşilikte Temel Kavramlar ve Cem Erkânı","Kur’an’dan Mesajlar"],"anahtarKavramlar":["edep","erkân","insanıkâmil","semah","tasavvuf","veli"],"olcmeDegerlendirme":["Öğrenme çıktıları; açık uçlu sorular, kavram haritası, yapılandırılmış grid, çalışma yaprağı, dereceli puanlama anahtarı, öz ve akran değerlendirme formu kullanılarak değerlendirilebilir. Kültürümüzde yer alan tasavvufi yorumlarla ilgili bilgi grafiği oluşturma, performans görevi olarak verilebilir. Bu performans görevi “bilgi toplama, bilgileri sınıflandırma, uygun görsel kullanma, dil ve anlatım kurallarına uyma” ölçütlerine göre dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["İslam düşüncesi içerisinde tasavvufi yorumların yer aldığını ve bu yorumlardan bazılarının isimlerini bildikleri kabul edilir."],"onDegerlendirme":["Ön bilgilerini ölçmek amacıyla öğrencilere “tasavvuf” kavramıyla ilgili neler bildikleri sorulur. Tasavvuf kavramının öğrencilerde yaptığı çağrışımlardan yola çıkarak ön bilgileri kontrol edilir."],"kopruKurma":["Öğrencilere ilgili tasavvufi yorumların erkân ve uygulanışlarıyla ilgili videolar veya belgeseller izletilir. Bu video veya belgesellerdeki dikkat çeken hususların toplumdaki yansımaları üzerinde durulur ve konuyla gerçek hayat arasında köprü kurulur."],"uygulamalar":[{"kod":"DKAB.12.4.1","metin":"Tasavvufi düşünceyi ortaya çıkaran sebeplerle ilgili bilgiler öğrencilerle paylaşılır. Öğrenciler bu bilgilerden hareketle tasavvufi düşüncenin oluşum sürecinde etkili olan unsurları ve bunlar arasındaki ilişkileri inceler (E3.2). Zihin haritası bu süreçte kullanılabilir. Ölçme ve değerlendirme uygulamalarında açık uçlu sorulara yer verilebilir."},{"kod":"DKAB.12.4.2","metin":"Tasavvufi düşüncenin ahlaki boyutu açıklanır. Tasavvufi düşüncenin gelişmesinde etkili olan önemli şahsiyetlere dair bilgilere yer verilir. Buradan hareketle öğrenciler, tasavvufi düşüncenin ahlaki boyutu ile ilgili çözümleme yapar. Öğrenciler, tasavvufi düşünceyi, birey ve toplum hayatına etkilerini ele alarak sınıflandırır (SDB2.1). Bu süreçte anlam çözümleme tablosu kullanılabilir. Öğrenciler tasavvufi düşüncenin ahlaki boyutunu edep ve insanıkâmil kavramları bağlamında açıklar. Konuşma halkası tekniği kullanılarak yorumlarını saygı içerisinde arkadaşları ile paylaşmaları sağlanabilir (D14.2, SDB2.1). Ölçme ve değerlendirme uygulamalarında kavram haritası kullanılabilir."},{"kod":"DKAB.12.4.3","metin":"Kültürümüzde etkin olan tasavvufi yorumlardan Yesevilik, Kadirilik, Rifailik, Mevlevilik, Nakşibendilik ve Alevilik Bektaşilik konuları açıklanır (SDB2.3). Öğrenciler bu yorumlardan birini seçerek grup hâlinde bilgi toplamakla görevlendirilir (E1.2). Öğrencilerden araştırma için kullanacakları kaynakları tespit ederek seçtikleri tasavvufi yorum hakkında bilgi toplamaları, bu bilgileri doğrulamaları, kaydetmeleri ve sunmaları istenir (SDB2.3). Yapılan sunumlar öz ve akran değerlendirme formları ile değerlendirilebilir. Öğrenci tasavvufi düşüncenin topluma yansımalarının somut olmayan kültürel mirasımız olduğunu bilerek bu mirası tanımak, tanıtmak, korumak ve geliştirmek için duyarlı olması sağlanır (D5.3, OB5). Bu değeri kazandırmak için görsel-film yorumlama yöntemi kullanılabilir. Ölçme ve değerlendirme uygulamalarında yapılandırılmış grid kullanılabilir."},{"kod":"DKAB.12.4.4","metin":"Öğrencilerden bir araştırma yaparak Alevilik Bektaşilikte yer alan temel kavramları (cem ve cemevi, musahiplik, erkân, ikrar, razılık ve kul hakkının sorulması, cemde on iki hizmet, semah, gülbank, Hızır ve muharrem orucu) açıklamaları istenir (OB5). Bu süreçte bilgi kartı kullanılabilir. Bu kapsamda; Hacı Bektaş Veli’nin, Bektaşiliğin oluşumu ve Aleviliğin gelişimindeki rolüne, Alevilik Bektaşilikteki “ocak kültürü”nden, “el ele, el hakka ikrarı”ndan ve “dört kapı kırk makam”dan bahsedilir. Bektaşilikte musahipliğe “ikrar verip nasip almak” da denildiğine ve bu kavramın İslam tarihindeki muhacir ensar kardeşliğine dayandırıldığına değinilir. Cemevi; âyin-i cem erkânının yapıldığı, “yol, âdap ve erkân yeri” olarak nitelendirilir. “Düşkünlükten kaldırma cemi”, “dardan indirme cemi” ile “Abdal Musa cemi”nden bahsedilir. Âyin-i cem ve cemevi ile ilgili görsellere yer verilir. Alevilik Bektaşilikte gülbankların başında, “Bismişah”, sonunda ise “Allah Allah” lafzı söylenir. Burada, “Bismişah” lafzında yer alan “şah” kelimesinin evrenin mutlak ve yegâne yöneticisi olarak Allah’ı ifade ettiği, “Allah Allah” lafzının ise amin anlamına geldiği belirtilir. Ayrıca lokma duasına da yer verilir. Öğrenciler Alevilik Bektaşiliği anlamak için erkân ve kavramlar arasında ilişki kurar (E3.6). Kavram haritaları bu süreçte kullanılabilir. Öğrenciler Alevilik Bektaşilikte erkân ve temel kavramlara dair bütüncül bir bakış açısı oluşturur (SDB2.3, OB5.). Ölçme ve değerlendirme uygulamalarında eşleştirme, boşluk doldurma ve kısa cevaplı sorulardan oluşan çalışma yaprağı kullanılabilir. Öğrencilerin gözlemlerinden hareketle toplumun farklı kültür ve anlayışlara sahip olabileceğini ve bu farlılıklara saygılı olunması gerektiğini bilmeleri amaçlanır (D14.4, OB5)."},{"kod":"DKAB.12.4.5","metin":"Hucurat suresi 10. ayet, Diyanet İşleri Başkanlığı tarafından yayımlanan matbu ve dijital meallerden bulunarak incelenir (OB2). Ayetin nüzul sebebine, ayette geçen şahıslara, yerlere, konulara ve kavramlara yer verilir. Öğrenciler bu ayette verilen mesajları çözümler ve sınıflandırır. Bu süreçte bilgi kartları kullanılabilir. Öğrenciler ayette ele alınan konuları açıklar (SDB2.1). Ölçme ve değerlendirme uygulamalarında açık uçlu sorular kullanılabilir."}],"zenginlestirme":["Mevlana Celaleddin Rumi ve Hacı Bektaş Veli’nin özlü sözlerinin derlenmesi, benzer anlamda olanlarının tablo üzerinde bir araya getirilerek afiş hazırlanması istenebilir."],"destekleme":["Tasavvufi düşüncenin oluşum sürecinin grup çalışması ile incelenmesi önerilebilir, bu süreçte öğrencileri desteklemek için çeşitli materyaller ve etkinlikler sunulabilir.","Kültürümüzde etkin olan tasavvufi yorumların araştırılmasında öğrencilere çeşitli kaynaklardan yararlanma imkânı sunulabilir. Alevilik Bektaşilikteki temel kavramların araştırılması sırasında öğrencilere görsel ve işitsel materyallerle destek verilebilir.","Hucurat suresi 10. ayetin mealinin incelenmesi sırasında öğrencilere metni farklı formatlarda sunarak (sesli kitap, görsel sunumlar vb.) ayetin mesajlarını çeşitli yollarla keşfetmeleri teşvik edilebilir."],"ogretmenYansitmalari":[]},
{"no":5,"ad":"Hint ve Çin Dinleri","kaynak":"https://tymm.meb.gov.tr/din-kulturu-ve-ahlak-bilgisi-dersi/unite/158","odak":"özetleyebilmesi amaçlanır.","dersSaati":10,"alanBecerileri":[],"kavramsalBeceriler":["KB2.3. Özetleme"],"egilimler":["E3.8. Soru Sorma"],"sdb":["SDB2.3. Sosyal Farkındalık"],"degerler":["D14. Saygı"],"okuryazarlik":["OB1. Bilgi Okuryazarlığı","OB4. Görsel Okuryazarlık","OB5. Kültür Okuryazarlığı"],"disiplinlerArasi":"Coğrafya, Tarih","becerilerArasi":"","ogrenmeCiktilari":[{"kod":"DKAB.12.5.1","ad":"Hinduizm, Budizm, Sihizm, Konfüçyanizm, Taoizm dinlerinin tarihini ve temel özelliklerini özetleyebilme","surec":["a) Hinduizm, Budizm, Sihizm, Konfüçyanizm, Taoizm dinlerinin tarihi ve temel özellikleri ile ilgili çözümleme yapar.","b) Hinduizm, Budizm, Sihizm, Konfüçyanizm, Taoizm dinlerinin tarihi ve temel özellikleri ile ilgili sınıflandırma yapar.","c) Hinduizm, Budizm, Sihizm, Konfüçyanizm, Taoizm dinlerinin tarihi ve temel özelliklerini açıklar."]}],"icerikCercevesi":["Hinduizm","Budizm","Sihizm","Konfüçyanizm","Taoizm"],"anahtarKavramlar":["guru","karma","kast","nirvana","pagoda","reenkarnasyon","tenasüh","tien","ying-yang","yoga"],"olcmeDegerlendirme":["Öğrenme çıktıları; çalışma yaprağı, öz değerlendirme formu ve dereceli puanlama anahtarı kullanılarak değerlendirilebilir.","Hint ve Çin dinleri ile ilgili (ritüeller, kutsal mekân ve semboller) bilgi grafiği hazırlama, performans görevi verilebilir. Bu performans görevi “ritüeller, kutsal mekân ve sembollerle ilgili bilgi toplama, bilgileri sınıflandırma, görsel kullanma, tasarım yapma” ölçütlerine göre","dereceli puanlama anahtarı ve öz değerlendirme formu ile değerlendirilebilir.","Sonuç değerlendirmede performans görevleri kullanılabileceği gibi yazılı yoklamalar da kullanılabilir."],"temelKabuller":["Öğrencilerin dünya genelinde farklı dinlerin var olduğunu bildikleri kabul edilmektedir."],"onDegerlendirme":["Öğrencilere “Hint ve Çin dinlerinden hangilerini biliyorsunuz?” sorusuyla hazır bulunuşlukları kontrol edilir."],"kopruKurma":["Hint ve Çin dinlerinin dağılımı ile ilgili bir harita gösterilerek öğrencilere bu dinlerin yaygın olarak yaşandığı yerler hakkında bilgilendirme yapılır. Böylelikle öğrencilerin tarih ve coğrafya dersinde öğrendikleriyle köprü kurması sağlanır."],"uygulamalar":[{"kod":"DKAB.12.5.1","metin":"Öğrencilere Hinduizm’in uzun bir tarihî süreç içerisinde, farklı inanç ve kültürlerin birleşmesi neticesinde oluştuğu ifade edilir. Hinduizm’in tarihsel gelişimi ve dağılımı ile ilgili bir harita gösterilerek öğrencilere bu dinin yaygın olarak yaşandığı yerler hakkında bilgi verilir. Öğrencilere kast, karma- tenasüh, reenkarnasyon, nirvana ve yoga gibi kavramlar hakkında neler bildikleri sorulur (E3.8). Öğrencilerden alınan cevaplar çerçevesinde konuyla ilgili bilgi verilir. Öğrenciler Hinduizm’in inanç ve ritüellerine ilişkin çözümleme yapar. Bu süreçte yapılandırılmış grid kullanılabilir. Özellikle kast sisteminin toplumsal yapıyı nasıl etkilediğini yorumlamaları; Hinduizm’de karma-tenasüh anlayışı ile tek tanrılı dinlerdeki ahiret inancını karşılaştırmaları istenir (SDB2.3). Öğrenciler, Hinduizm’in kutsalmetinlerini, mekânlarını, ritüellerini ve sembollerini sınıflandırır (OB1, OB4). Bu sınıflandırmanın anlam çözümleme tablosu üzerinde gösterilmesi istenebilir. Öğrenciler Hinduizm’in tarihini ve temel özelliklerini açıklar (OB5). Budizm’in tarihçesi ve özellikleri hakkında genel bilgi verilir. Öğrencilere “Budizm’in kurucusu kimdir, Budizm ne zaman ve nasıl ortaya çıkmıştır?” soruları sorulur ve öğrencilerden alınan cevaplar değerlendirilerek konu anlatılır. Öğrencilere Budizm’le ilgili Tripitika, sekiz dilimli yol, dört yüce hakikat, pagoda gibi kavramlar hakkında bilgi verilir. Öğrenciler bu kavramlar bağlamında Budizm’in inanç, ibadet, ahlak ilkeleri ve kutsal kitap anlayışına ilişkin çözümleme yapar. Bu süreçte yapılandırılmış grid kullanılabilir. Verilen bu bilgiler çerçevesinde öğrenciler Budizm’in inanç, ibadet ve ahlak ilkelerini; kutsal metinlerini, mekânlarını, ritüellerini ve sembollerini sınıflandırır (OB1, OB4). Bu süreçte zihin haritası tekniği kullanılabilir. Öğrenciler Budizm’in tarihini ve temel özelliklerini açıklar (OB5). Sihizm’in tarihçesi ve özellikleri hakkında genel bilgi verilir. Öğrencilere “Sihizm’in kurucusu kimdir, Sihizm ne zaman ve nasıl ortaya çıkmıştır?” soruları sorulur ve öğrencilerden alınan cevaplar değerlendirilerek konu anlatılır. Öğrencilere Sihizm’le ilgili guru, karma, tenasüh, kakkas (5 K), khalsa teşkilatı gibi kavramlar hakkında bilgi verilir. Öğrenciler bu kavramlar bağlamında Sihizm’in inanç esasları ve ahlak ilkelerine ilişkin çözümleme yapar. Bu süreçte yapılandırılmış grid kullanılabilir. Verilen bilgiler çerçevesinde öğrenciler, Sihizm’in kutsal metinlerini, mekânlarını, ritüellerini ve sembollerini sınıflandırır (OB1, OB4). Öğrenciler “beş hırsız” (kibir, öfke, hırs, tutku ve şehvet) “beş silah” (kanaat, hayırseverlik, şefkat, iyi davranış, alçak gönüllülük) anlayışını açıklar. Bu süreçte kavram haritaları kullanılabilir. Öğrenciler Sihizm’in tarihini ve temel özelliklerini kendi cümleleriyle ifade eder (OB5). Konfüçyanizm’in tarihçesi ve özellikleri hakkında genel bilgi verilir. Öğrencilere “Konfüçyanizm’in kurucusu kimdir, Konfüçyanizm ne zaman ve nasıl ortaya çıkmıştır?” soruları sorulur ve öğrencilerden alınan cevaplar değerlendirilerek konu anlatılır. Öğrencilere Konfüçyanizm’le ilgili tien, şangti, junzi gibi kavramlar hakkında bilgi verilir. Öğrenciler bu kavramlar bağlamında Konfüçyanizm’in inanç esasları ve ahlak ilkelerine ilişkin çözümleme yapar. Bu süreçte yapılandırılmış grid kullanılabilir. Verilen bu bilgiler çerçevesinde öğrenciler Konfüçyanizm’in inanç, ibadet ve ahlak ilkelerini; kutsal metinlerini, mekânlarını, ritüellerini ve sembollerini sınıflandırır (OB1, OB4). Öğrenciler “beş erdem”, “beş insani ilişki” gibi ahlak esaslarını açıklar. Bu süreçte anlam çözümleme tablosu kullanılabilir. Öğrenciler Konfüçyanizm’in tarihini ve temel özelliklerini kendi cümleleriyle ifade eder (OB5). Taoizm’in tarihçesi ve özellikleri hakkında genel bilgi verilir. Öğrencilere “Taoizm’in kurucusu kimdir, Taoizm ne zaman ve nasıl ortaya çıkmıştır?” soruları sorulur ve öğrencilerden alınan cevaplar değerlendirilerek konu anlatılır. Öğrencilere Taoizm’le ilgili tao, yin-yang ve wue-wei kavramları hakkında bilgi verilir. Öğrenciler, verilen bu bilgiler çerçevesinde Taoizm’in inanç, ibadet ve ahlak ilkelerini çözümleme yapar. Bu süreçte yapılandırılmış grid kullanılabilir. Verilen bilgiler doğrultusunda öğrenciler Taoizm’in kutsal metinlerini, mekânlarını, ritüellerini ve sembollerini sınıflandırır (OB1, OB4). Öğrenciler Taoizm’de “üç insani özellik” anlayışını açıklar. Bu süreçte zihin haritası kullanılabilir. Öğrenciler Taoizm’in tarihini ve temel özelliklerini kendi cümleleriyle ifade eder (OB5). Öğrenciler tartışarak farklı fikirlere ve inançlara saygı duymanın önemini fark eder (D14.4). Ölçme ve değerlendirme uygulamalarında Hinduizm, Budizm, Sihizm, Konfüçyanizm, Taoizm dinlerinin tarihini ve temel özelliklerini ile ilgili açık uçlu sorular, kısa cevaplı sorular, doğru yanlış soruları ve eşleştirme soru türlerinden oluşturulan çalışma yaprağı kullanılabilir."}],"zenginlestirme":["Hinduizm, Budizm, Sihizm, Konfüçyanizm, Taoizm dinlerinin inanç ve ahlak esasları, kutsal metinleri, mekânları, ritüelleri ve sembolleri ile ilgili karşılaştırmalı bir tablo hazırlamaları istenebilir."],"destekleme":["Farklı dinlerin temel kavramları ve öğretilerini açıklayan görsel ve işitsel materyaller kullanarak Hinduizm, Budizm, Sihizm, Konfüçyanizm ve Taoizm hakkında temel bilgileri erişilebilir kılarak bu bilgiler öğrencilere sunulabilir."],"ogretmenYansitmalari":[]}]}};

