/* window.ACADEMIC'i resmî veriyle doldurur (portal: ogrenmeCercevesiHtml). */
(function(){
  var P = window.MEB_PROGRAM.siniflar, E = window.MEB_ESLESTIRME;
  var A = window.ACADEMIC = window.ACADEMIC || {};
  Object.keys(E).forEach(function(sid){
    var e = E[sid], liste = P[sid] || [];
    function isle(portalNo, mebNo, ek){
      var anahtar = sid+'-u'+portalNo, u = null;
      for(var i=0;i<liste.length;i++){ if(liste[i].no===mebNo){ u = liste[i]; break; } }
      if(!u) return;
      A[anahtar] = { meb:u, sinifNo:sid.slice(1), ek:!!ek, not:e.notlar[anahtar]||'' };
    }
    e.sira.forEach(function(g){ g.portal.forEach(function(p){ isle(p, g.meb, false); }); });
    e.ek.forEach(function(p){ var k = sid+'-u'+p; A[k] = { meb:null, sinifNo:sid.slice(1), ek:true, not:e.notlar[k]||'' }; });
  });
})();
